// The __madc_eval_*_runtime / __madc_context_set_*_runtime extern-C
// exports and the namespace madc publics live in src/ns_madc.cpp; both
// delegate to the internals above. Only the compiler-machinery scope
// setters stay here (cpp-first-api.md: they are CIR-builder-emitted
// symbols, not user-resolved functions).

extern "C" {

// cstr-key scope setters — the CIR builder's TokenScopeContext lowering
// fills the captured-scope context array with these (a string literal key
// avoids materializing a std::string temp per captured variable).
void *__madc_scope_set_int_runtime(void *ctx, const char *key, int64_t value)
{
    DBG(std::cerr << "scope_set_int ctx=" << ctx << " " << key << "=" << value << std::endl);
    ns_common::value_object_for_write(*(madc::value *)ctx,
				      "__madc_scope_set_int")
	[std::string(key)] = madc::value(value);
    return ctx;
}

void *__madc_scope_set_real_runtime(void *ctx, const char *key, double value)
{
    ns_common::value_object_for_write(*(madc::value *)ctx,
				      "__madc_scope_set_real")
	[std::string(key)] = madc::value(value);
    return ctx;
}

void *__madc_scope_set_array_runtime(void *ctx, const char *key, void *value)
{
    ns_common::value_object_for_write(*(madc::value *)ctx,
				      "__madc_scope_set_array")
	[std::string(key)] = *(const madc::value *)value;
    return ctx;
}

// `str` is the captured local's address; the host reads the std::string
// by pointer and copies it into the context (read-only snapshot).
void *__madc_scope_set_string_runtime(void *ctx, const char *key, void *str)
{
    ns_common::value_object_for_write(*(madc::value *)ctx,
				      "__madc_scope_set_string")
	[std::string(key)] = madc::value(*(const std::string *)str);
    return ctx;
}

}

static bool is_restrict_token(TokenBase *tb)
{
    return tb && tb->type() == TokenType::ttKeyword && tb->id() == TokenID::tkRESTRICT;
}

static bool is_post_pointer_qualifier_token(TokenBase *tb)
{
    return tb && tb->type() == TokenType::ttKeyword
        && (tb->id() == TokenID::tkRESTRICT
	 || tb->id() == TokenID::tkCONST
	 || tb->id() == TokenID::tkVOLATILE);
}

// Shared declarator pointer-star consumer. See the header for the contract.
// Replaces the copy-pasted `while (tkMul) { ... if (!fnptr_base) getPointerType }`
// loops so the explicit `*` count is handled the SAME way everywhere.
int Program::consume_declarator_stars(DataDef *&dd, bool *out_const_after_star)
{
    int stars = 0;
    bool fnptr_base = (dynamic_cast<DataDefFPTR *>(dd) != NULL);
    bool const_after = false;
    while ( peekToken() && (peekToken()->id() == TokenID::tkMul
			 || is_post_pointer_qualifier_token(peekToken())) )
    {
	if ( peekToken()->id() == TokenID::tkMul )
	{
	    nextToken();		// consume '*'
	    ++stars;
	    const_after = false;	// any const before this star was low-level
	    if ( !fnptr_base )
		dd = getPointerType(dd);
	}
	else
	{
	    if ( stars > 0 && peekToken()->id() == TokenID::tkCONST )
		const_after = true;	// const after the last '*' = top-level const ptr
	    nextToken();		// consume const/volatile/restrict
	}
    }
    if ( out_const_after_star )
	*out_const_after_star = const_after;
    return stars;
}

static bool is_type_qualifier_token(TokenBase *tb)
{
    return tb && tb->type() == TokenType::ttKeyword
	&& (tb->id() == TokenID::tkCONST
	 || tb->id() == TokenID::tkRESTRICT
	 || tb->id() == TokenID::tkVOLATILE
	 || tb->id() == TokenID::tkSTATIC
	 || tb->id() == TokenID::tkEXTERN);
}

static bool is_attribute_identifier_token(TokenBase *tb)
{
    if ( !tb || tb->type() != TokenType::ttIdentifier )
	return false;
    const std::string &name = ((TokenIdent *)tb)->spelling();
    return name == "__attribute__" || name == "__attribute";
}

// Ignored C++ declaration-specifier keywords. constexpr/consteval/constinit
// carry no madc codegen (like const) but ARE reserved tokens — so they
// must be consumed in declaration-specifier position rather than mistaken for
// a type name. `inline` (un-erased, C++ modes) is consumed on the same paths
// but is NOT a no-op: TokenCppKeyword::parse records it (parsing_inline_decl)
// so the declaration it qualifies gets vague linkage.
static bool is_ignored_cpp_specifier_token(TokenBase *tb)
{
    if ( !tb || tb->id() != TokenID::tkCPPKEYWORD )
	return false;
    const std::string &s = ((TokenIdent *)tb)->spelling();
    return s == "constexpr" || s == "consteval" || s == "constinit"
	|| s == "inline";
}

TokenBase *Program::consume_gnu_attributes(TokenBase *nt,
					 std::set<std::string> *attrs,
					 std::string *alias_target,
					 size_t *explicit_align,
					 size_t *vector_bytes)
{
    while ( nt && is_attribute_identifier_token(nt) )
    {
	if ( peekToken() && peekToken()->id() == TokenID::tkOpBrk )
	{
	    int adepth = 0;
	    bool saw_alias = false;
	    bool saw_aligned = false;
	    bool saw_vector_size = false;
	    bool saw_optimize = false;
	    do {
		TokenBase *at = nextToken();
		if ( !at ) break;
		if ( attrs && adepth >= 2 && at->type() == TokenType::ttIdentifier )
		    attrs->insert(((TokenIdent *)at)->spelling());
		if ( at->type() == TokenType::ttIdentifier
		  && (((TokenIdent *)at)->spelling_is("optimize")
		   || ((TokenIdent *)at)->spelling_is("__optimize__")) )
		    saw_optimize = true;
		else if ( saw_optimize && at->type() == TokenType::ttString )
		{
		    if ( std::string(((TokenStr *)at)->str).find("no-strict-aliasing") != std::string::npos )
			pending_no_strict_aliasing = true;
		    saw_optimize = false;
		}
		if ( at->type() == TokenType::ttIdentifier
		  && ((TokenIdent *)at)->spelling_is("alias") )
		    saw_alias = true;
		else if ( alias_target && saw_alias && at->type() == TokenType::ttString )
		{
		    *alias_target = ((TokenStr *)at)->str;
		    saw_alias = false;
		}
		else if ( at->type() == TokenType::ttIdentifier
		  && (((TokenIdent *)at)->spelling_is("aligned")
		   || ((TokenIdent *)at)->spelling_is("__aligned__")) )
		    saw_aligned = true;
		else if ( explicit_align && saw_aligned && at->type() == TokenType::ttInteger )
		{
		    int64_t aval = static_cast<TokenInt *>(at)->ival();
		    if ( aval > 0 )
			*explicit_align = static_cast<size_t>(aval);
		    saw_aligned = false;
		}
		else if ( at->type() == TokenType::ttIdentifier
		  && (((TokenIdent *)at)->spelling_is("vector_size")
		   || ((TokenIdent *)at)->spelling_is("__vector_size__")) )
		    saw_vector_size = true;
		else if ( saw_vector_size && at->id() == TokenID::tkOpBrk )
		{
		    int64_t n = parse_constant_integer_expression();
		    if ( vector_bytes && n > 0 )
			*vector_bytes = (size_t)n;
		    TokenBase *cl = nextToken();
		    if ( cl && cl->id() == TokenID::tkClBrk )
			; // consumed vector_size(...) argument paren
		    else if ( cl )
			pushToken(cl);
		    saw_vector_size = false;
		    continue; // don't do depth tracking for this paren pair
		}
		if ( at->id() == TokenID::tkOpBrk ) ++adepth;
		else if ( at->id() == TokenID::tkClBrk ) --adepth;
	    } while ( adepth > 0 );
	}
	nt = nextToken();
    }
    return nt;
}

static bool is_gnu_asm_identifier_token(TokenBase *tb)
{
    TokenIdent *ident = dynamic_cast<TokenIdent *>(tb);
    if ( !ident )
	return false;
    std::string name = ident->spelling();
    return name == "asm" || name == "__asm" || name == "__asm__";
}

TokenBase *Program::consume_gnu_asm_label(TokenBase *nt,
					std::string *alias_target)
{
    while ( nt && is_gnu_asm_identifier_token(nt) )
    {
	TokenBase *open = nextToken();
	if ( !open || open->id() != TokenID::tkOpBrk )
	    Throw(open ? open : nt) << "Expecting '(' after asm label" << flush;
	TokenBase *label = nextToken();
	if ( alias_target && label && label->type() == TokenType::ttString )
	{
	    *alias_target = ((TokenStr *)label)->str;
#if MADC_TARGET_APPLE_P
	    // Mach-O asm labels carry the assembler-level leading underscore
	    // (`__asm("_open")`). madc's canonical symbol space is the C/dlsym
	    // name: darwin dlsym() takes it WITHOUT the underscore and the
	    // Mach-O writer re-prepends it at emit — so strip exactly one here,
	    // at the boundary where the label enters madc. (ELF targets keep
	    // labels verbatim: glibc's `__isoc99_scanf` IS the ELF symbol.)
	    if ( !alias_target->empty() && (*alias_target)[0] == '_' )
		alias_target->erase(0, 1);
#endif
	}
	TokenBase *close = nextToken();
	if ( !close || close->id() != TokenID::tkClBrk )
	    Throw(close ? close : label) << "Expecting ')' after asm label" << flush;
	nt = nextToken();
    }
    return nt;
}

// Skip (or lower the recognized copy shapes of) a GNU asm STATEMENT.
// `tb` is the asm introducer; shared by the ttIdentifier and ttKeyword
// arms of parseStatement so reserving `asm` as a keyword keeps the skip.
TokenBase *Program::skip_gnu_asm_statement(TokenBase *tb)
{
	    // optional volatile qualifier
	    if ( peekToken()
	      && peekToken()->type() == TokenType::ttKeyword
	      && peekToken()->id() == TokenID::tkVOLATILE )
		nextToken();
	    else if ( peekToken() && peekToken()->type() == TokenType::ttIdentifier )
	    {
		std::string q = ((TokenIdent *)peekToken())->spelling();
		if ( q == "volatile" || q == "__volatile__" )
		    nextToken();
	    }
	    TokenBase *ob = nextToken();
	    if ( ob && ob->id() == TokenID::tkOpBrk )
	    {
		TokenBase *tmpl = nextToken();
		bool parsed_simple_copy = false;
		if ( tmpl && tmpl->type() == TokenType::ttString
		  && ((TokenStr *)tmpl)->spelling_empty()
		  && peekToken() && peekToken()->id() == TokenID::tkColon )
		{
		    nextToken(); // ':'
		    TokenBase *out_c = nextToken();
		    TokenBase *out_ob = nextToken();
		    if ( out_c && out_c->type() == TokenType::ttString
		      && out_ob && out_ob->id() == TokenID::tkOpBrk )
		    {
			std::string out_constraint = ((TokenStr *)out_c)->str;
			if ( out_constraint == "+m" )
			{
			    int out_depth = 1;
			    while ( out_depth > 0 )
			    {
				TokenBase *t = nextToken();
				if ( !t ) break;
				if ( t->id() == TokenID::tkOpBrk ) ++out_depth;
				else if ( t->id() == TokenID::tkClBrk ) --out_depth;
			    }
			    int asm_depth = 1;
			    while ( asm_depth > 0 )
			    {
				TokenBase *t = nextToken();
				if ( !t ) break;
				if ( t->id() == TokenID::tkOpBrk ) ++asm_depth;
				else if ( t->id() == TokenID::tkClBrk ) --asm_depth;
			    }
			    if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
				return nextToken();
			    return tb;
			}
			TokenBase *out_tb = nextToken();
			TokenBase *out_expr = out_tb ? parseExpression(out_tb, true) : NULL;
			TokenBase *out_cb = nextToken();
			TokenBase *next_clause = nextToken();
			if ( out_expr
			  && out_cb && out_cb->id() == TokenID::tkClBrk
			  && next_clause && next_clause->id() == TokenID::tkClBrk )
			{
			    if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
				nextToken();
			    if ( out_constraint == "+r" )
				return out_expr;
			    return tb;
			}
			if ( out_expr
			  && out_cb && out_cb->id() == TokenID::tkClBrk
			  && next_clause && next_clause->id() == TokenID::tkSemi )
			{
			    if ( out_constraint == "+r" )
				return out_expr;
			    return next_clause;
			}
			TokenBase *in_c = nextToken();
			TokenBase *in_ob = nextToken();
			if ( out_expr
			  && out_cb && out_cb->id() == TokenID::tkClBrk
			  && next_clause && next_clause->id() == TokenID::tkColon
			  && in_c && in_c->type() == TokenType::ttString
			  && in_ob && in_ob->id() == TokenID::tkOpBrk )
			{
			    TokenBase *in_tb = nextToken();
			    TokenBase *in_expr = in_tb ? parseExpression(in_tb, true) : NULL;
			    TokenBase *in_cb = nextToken();
			    TokenBase *close = nextToken();
			    std::string in_constraint = ((TokenStr *)in_c)->str;
			    // If close is ':' (clobber list), consume
			    // remaining tokens up to outer ')'.
			    if ( close && close->id() == TokenID::tkColon )
			    {
				int rem = 1;
				while ( rem > 0 )
				{
				    TokenBase *t = nextToken();
				    if ( !t ) break;
				    if ( t->id() == TokenID::tkOpBrk ) ++rem;
				    else if ( t->id() == TokenID::tkClBrk ) --rem;
				}
				close = new TokenClBrk();
			    }
			    if ( in_expr
			      && in_cb && in_cb->id() == TokenID::tkClBrk
			      && close && close->id() == TokenID::tkClBrk
			      && out_constraint == "=r"
			      && in_constraint == "0" )
			    {
				TokenAssign *assign = new TokenAssign();
				assign->file = tb->file;
				assign->line = tb->line;
				assign->column = tb->column;
				assign->left = out_expr;
				assign->right = in_expr;
				if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
				    nextToken();
				return assign;
			    }
			    if ( in_expr
			      && in_cb && in_cb->id() == TokenID::tkClBrk
			      && close && close->id() == TokenID::tkClBrk
			      && out_constraint == "=m"
			      && in_constraint == "m" )
			    {
				if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
				    return nextToken();
				return tb;
			    }
			    // Unrecognized two-operand asm pattern — consume
			    // any remaining tokens until the outer asm ')' is
			    // found, then return as no-op. We track paren
			    // depth starting from `close` (which may be `,`,
			    // `:`, or a paren itself).
			    {
				int rem = 1; // 1 for the outer '(' consumed at asm entry
				if ( close && close->id() == TokenID::tkOpBrk ) ++rem;
				else if ( close && close->id() == TokenID::tkClBrk ) --rem;
				while ( rem > 0 )
				{
				    TokenBase *t = nextToken();
				    if ( !t ) break;
				    if ( t->id() == TokenID::tkOpBrk ) ++rem;
				    else if ( t->id() == TokenID::tkClBrk ) --rem;
				}
				parsed_simple_copy = true;
				if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
				    return nextToken();
				return tb;
			    }
			}
			// Unrecognized asm pattern — the output operand
			// was consumed but the remaining clauses don't match
			// a known shape. Consume any remaining tokens until
			// the outer asm ')' is balanced. The outer '(' was
			// consumed at asm entry; out_ob/out_cb cancel; so we
			// need 1 more ')' to close, adjusted by any parens
			// in in_c and in_ob.
			{
			    int rem = 1; // for the outer '('
			    if ( in_c && in_c->id() == TokenID::tkOpBrk ) ++rem;
			    else if ( in_c && in_c->id() == TokenID::tkClBrk ) --rem;
			    if ( in_ob && in_ob->id() == TokenID::tkOpBrk ) ++rem;
			    else if ( in_ob && in_ob->id() == TokenID::tkClBrk ) --rem;
			    while ( rem > 0 )
			    {
				TokenBase *t = nextToken();
				if ( !t ) break;
				if ( t->id() == TokenID::tkOpBrk ) ++rem;
				else if ( t->id() == TokenID::tkClBrk ) --rem;
			    }
			    parsed_simple_copy = true;
			    if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
				return nextToken();
			    return tb;
			}
		    }
		}
		if ( !parsed_simple_copy )
		{
		    int depth = 1;
		    while ( depth > 0 )
		    {
			TokenBase *t = nextToken();
			if ( !t ) break;
			if ( t->id() == TokenID::tkOpBrk ) ++depth;
			else if ( t->id() == TokenID::tkClBrk ) --depth;
		    }
		}
	    }
	    // Return the semicolon as the statement (no-op).
	    // If the asm is the body of `if (...) asm(...);`, the
	    // caller needs a non-NULL return.
	    if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
		return nextToken();
	    return tb;
}

// Skip C23 [[...]] attributes: [[gnu::noipa]], [[nodiscard]], etc.
// Returns the next meaningful token after any [[...]] sequences.
void Program::skip_c23_attributes()
{
    while ( peekToken()
	 && peekToken()->id() == TokenID::tkOpSqr )
    {
	// peek ahead: is the NEXT token also [ ?
	TokenBase *first_sq = nextToken(); // consume first [
	if ( !peekToken()
	  || peekToken()->id() != TokenID::tkOpSqr )
	{
	    pushToken(first_sq); // not [[, push back
	    return;
	}
	nextToken(); // consume second [
	// Skip until ]]
	int depth = 1;
	while ( depth > 0 )
	{
	    TokenBase *t = nextToken();
	    if ( !t )
		break;
	    if ( t->id() == TokenID::tkOpSqr )
	    {
		if ( peekToken()
		  && peekToken()->id() == TokenID::tkOpSqr )
		{
		    nextToken();
		    ++depth;
		}
	    }
	    else if ( t->id() == TokenID::tkClSqr )
	    {
		if ( peekToken()
		  && peekToken()->id() == TokenID::tkClSqr )
		{
		    nextToken();
		    --depth;
		}
	    }
	}
    }
}

size_t Program::parse_gnu_vector_size_attribute()
{
    if ( !is_attribute_identifier_token(peekToken()) )
	return 0;
    nextToken(); // consume __attribute__
    if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	return 0;
    int depth = 0;
    bool saw_vector_size = false;
    size_t vector_bytes = 0;
    do {
	TokenBase *at = nextToken();
	if ( !at ) break;
	if ( saw_vector_size && at->id() == TokenID::tkOpBrk )
	{
	    int64_t n = parse_constant_integer_expression();
	    if ( n > 0 )
		vector_bytes = (size_t)n;
	    TokenBase *cl = nextToken();
	    if ( !cl || cl->id() != TokenID::tkClBrk )
		Throw(cl ? cl : at) << "Expected ')' after vector_size argument" << flush;
	    saw_vector_size = false;
	}
	else if ( at->id() == TokenID::tkOpBrk ) ++depth;
	else if ( at->id() == TokenID::tkClBrk ) --depth;
	else if ( at->type() == TokenType::ttIdentifier
	       && (((TokenIdent *)at)->spelling_is("vector_size")
		|| ((TokenIdent *)at)->spelling_is("__vector_size__")) )
	    saw_vector_size = true;
	else if ( saw_vector_size && at->type() == TokenType::ttInteger )
	{
	    int64_t n = at->ival();
	    if ( n > 0 )
		vector_bytes = (size_t)n;
	}
    } while ( depth > 0 );
    return vector_bytes;
}

void Program::consume_typedef_gnu_attributes(std::string *mode_name,
					   size_t *vector_bytes)
{
    while ( is_attribute_identifier_token(peekToken()) )
    {
	nextToken(); // consume __attribute__
	if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	    continue;
	int depth = 0;
	bool saw_mode = false;
	bool saw_vector_size = false;
	do {
	    TokenBase *at = nextToken();
	    if ( !at ) break;
	    if ( saw_vector_size && at->id() == TokenID::tkOpBrk )
	    {
		int64_t n = parse_constant_integer_expression();
		if ( vector_bytes && n > 0 )
		    *vector_bytes = (size_t)n;
		TokenBase *cl = nextToken();
		if ( !cl || cl->id() != TokenID::tkClBrk )
		    Throw(cl ? cl : at) << "Expected ')' after vector_size argument" << flush;
		saw_vector_size = false;
	    }
	    else if ( at->id() == TokenID::tkOpBrk )
		++depth;
	    else if ( at->id() == TokenID::tkClBrk )
		--depth;
	    else if ( at->type() == TokenType::ttIdentifier
		   && ((TokenIdent *)at)->spelling_is("mode") )
		saw_mode = true;
	    else if ( at->type() == TokenType::ttIdentifier
		   && (((TokenIdent *)at)->spelling_is("vector_size")
		    || ((TokenIdent *)at)->spelling_is("__vector_size__")) )
		saw_vector_size = true;
	    else if ( mode_name && saw_mode && at->type() == TokenType::ttIdentifier )
	    {
		*mode_name = ((TokenIdent *)at)->spelling();
		saw_mode = false;
	    }
	    else if ( vector_bytes && saw_vector_size && at->type() == TokenType::ttInteger )
	    {
		int64_t n = at->ival();
		if ( n > 0 )
		    *vector_bytes = (size_t)n;
		saw_vector_size = false;
	    }
	} while ( depth > 0 );
    }
}

static DataDef *apply_gnu_mode_alias(DataDef *base_dd, const std::string &mode_name)
{
    if ( !base_dd || mode_name.empty() )
	return base_dd;

    bool is_unsigned = false;
    switch ( base_dd->rawtype() )
    {
	case DataType::dtUINT8:
	case DataType::dtUINT16:
	case DataType::dtUINT24:
	case DataType::dtUINT32:
	case DataType::dtUINT64:
	    is_unsigned = true;
	    break;
	default:
	    break;
    }

    if ( mode_name == "QI" )
	return is_unsigned ? static_cast<DataDef *>(&ddUINT8) : static_cast<DataDef *>(&ddINT8);
    if ( mode_name == "HI" )
	return is_unsigned ? static_cast<DataDef *>(&ddUINT16) : static_cast<DataDef *>(&ddINT16);
    if ( mode_name == "SI" )
	return is_unsigned ? static_cast<DataDef *>(&ddUINT32) : static_cast<DataDef *>(&ddINT32);
    if ( mode_name == "DI" )
	return is_unsigned ? static_cast<DataDef *>(&ddUINT64) : static_cast<DataDef *>(&ddINT64);

    return base_dd;
}

static bool host_is_little_endian()
{
#if defined(__BYTE_ORDER__) && defined(__ORDER_LITTLE_ENDIAN__)
    return __BYTE_ORDER__ == __ORDER_LITTLE_ENDIAN__;
#else
    const uint16_t probe = 0x0100;
    return *((const uint8_t *)&probe) == 0;
#endif
}

static bool reverse_scalar_storage_requested(const std::string &order_name)
{
    if ( order_name == "big-endian" )
	return host_is_little_endian();
    if ( order_name == "little-endian" )
	return !host_is_little_endian();
    return false;
}

static bool is_contextual_identifier_token(TokenBase *tb);
static std::string contextual_identifier_name(TokenBase *tb);
static void copy_token_location(TokenBase *dst, TokenBase *src);
// [expr.sizeof]/5 — `sizeof...(P)` yields the pack's ARITY, not a type size.
// Program::evaluate_type_query parses the sizeof/alignof OPERAND and implements
// no `...` arm, so the operator can only be honoured by FOLDING it during
// substitution. That makes every substitution path responsible for recognising
// the same seven-token shape by hand. ONE owner for the shape; each caller
// resolves the COUNT from its own binding state (the maps differ per path).
//
// A path that forgets produces NO diagnostic. `sizeof` is soft-reserved — a
// TokenCppKeyword (tkCPPKEYWORD, cpp_reserved @lexer.cpp, STD_CPP98) that
// is_contextual_identifier_token deliberately ADMITS, so identifier-position
// code keeps working while the staged hard-reservation lands. An unfolded
// `sizeof` therefore degrades to a VARIABLE lookup rather than a syntax error:
// the instantiation throws, the placeholder is kept silently, and the program
// dies much later as an undefined MIR import naming the template.
//
// This helper is a WORKAROUND, not the end state. The folds exist only because
// the operator is unimplemented; teaching evaluate_type_query a `...` arm (which
// needs the pack binding reachable at parse time) would retire all of them.
static bool sizeof_pack_operand_name(const std::vector<TokenBase *> &toks,
				     size_t i, std::string &pack_name)
{
    if ( i + 6 >= toks.size() )
	return false;
    if ( !toks[i] || !is_contextual_identifier_token(toks[i])
      || contextual_identifier_name(toks[i]) != "sizeof" )
	return false;
    if ( !toks[i+1] || toks[i+1]->id() != TokenID::tkDot
      || !toks[i+2] || toks[i+2]->id() != TokenID::tkDot
      || !toks[i+3] || toks[i+3]->id() != TokenID::tkDot
      || !toks[i+4] || toks[i+4]->id() != TokenID::tkOpBrk
      || !toks[i+5] || toks[i+5]->type() != TokenType::ttIdentifier
      || !toks[i+6] || toks[i+6]->id() != TokenID::tkClBrk )
	return false;
    pack_name = ((TokenIdent *)toks[i+5])->spelling();
    return true;
}

static bool token_origin_allows_c89_implicit_function(TokenBase *tb)
{
    if ( !tb || !tb->file )
	return false;
    std::string path(tb->file);
    return path.size() >= 2 && path.substr(path.size() - 2) == ".c";
}

static bool is_typeof_identifier(const std::string &name)
{
    return name == "typeof" || name == "typeof_unqual"
	|| name == "__typeof" || name == "__typeof__";
}

// The name position of a typedef declarator accepts more than a plain
// identifier. A real system header may re-typedef a name madc already
// registers as a base datatype — gcc's <stddef.h> carries
// `typedef struct {...} max_align_t;`, and madc pre-registers max_align_t
// (it holds a stable value-ABI type id) — and C++ keywords that are valid C
// identifiers arrive here the same way from C headers. TokenDataType and
// TokenKeyword both derive from TokenIdent, so one cast reaches the virtual
// spelling(). Returns NULL when the token cannot name a typedef alias.
static const char *typedef_alias_spelling(TokenBase *tb)
{
    if ( !tb )
	return NULL;
    switch ( tb->type() )
    {
	case TokenType::ttIdentifier:
	case TokenType::ttDataType:
	case TokenType::ttKeyword:
	    return ((TokenIdent *)tb)->spelling();
	default:
	    return NULL;
    }
}

static bool is_decltype_identifier(const std::string &name)
{
    return name == "decltype";
}

static bool is_alignof_identifier(const std::string &name)
{
    return name == "alignof" || name == "_Alignof" || name == "__alignof__";
}

static bool is_static_assert_identifier(const std::string &name)
{
    return name == "_Static_assert" || name == "static_assert";
}

static bool is_nullptr_identifier(const std::string &name)
{
    return name == "nullptr";
}

static bool is_bool_literal_identifier(const std::string &name, bool &value)
{
    if ( name == "true" )
    {
	value = true;
	return true;
    }
    if ( name == "false" )
    {
	value = false;
	return true;
    }
    return false;
}

// The dot-path reference normalizer (a reference head denotes its referent
// for member access). Defined later in this file.
static DataDef *referent_if_reference(DataDef *dd);

DataDef *Program::effective_pointer_type_for_member_access(TokenBase *tb)
{
    if ( !tb )
	return NULL;

    DataDef *dd = tb->datadef();
    // A REFERENCE head denotes its referent ([expr.ref]) — collapse it
    // BEFORE the pointer test when the referent is itself a pointer: a
    // reference-to-pointer receiver (`node*& begin_node();
    // begin_node()->v`) must expose the REFERENT pointer, or the single
    // arrow deref lands on the pointer type itself and the member check
    // rejects it (libc++ __tree:890, '__left_' on the __iter_pointer&
    // returned by __begin_node()). A reference-to-CLASS head keeps
    // today's ref-as-pointer behavior.
    if ( DataDef *ref = referent_if_reference(dd) )
	if ( ref->is_pointer() )
	    dd = ref;
    if ( dd && dd->is_pointer() )
	return dd;
    if ( DataDefCArray *add = dynamic_cast<DataDefCArray *>(dd) )
    {
	DataDef *elem = add->element_type ? add->element_type : &ddINT64;
	return getPointerType(elem);
    }

    if ( TokenVar *tv = dynamic_cast<TokenVar *>(tb) )
    {
	if ( tv->var.is_fixed_array() && tv->var.type )
	    return getPointerType(tv->var.type);
    }

    if ( TokenMember *tm = dynamic_cast<TokenMember *>(tb) )
    {
	if ( tm->is_fixed_array_member() && tm->var.type )
	    return getPointerType(tm->var.type);
    }

    if ( TokenOperator *op = dynamic_cast<TokenOperator *>(tb) )
    {
	if ( op->id() == TokenID::tkAdd || op->id() == TokenID::tkSub )
	{
	    DataDef *lptr = effective_pointer_type_for_member_access(op->left);
	    if ( lptr )
		return lptr;
	    return effective_pointer_type_for_member_access(op->right);
	}
    }

    return NULL;
}

TokenCallMethod *Program::arrow_operator_call(TokenBase *lhs, TokenBase *loc_tb)
{
    // type()-gated, not dynamic_cast alone: TokenMember/TokenCallMethod
    // IS-A TokenVar, and their .var is the member/method Variable. A BARE
    // object variable is the receiver identity itself; a MEMBER or
    // CALL-RESULT receiver (`r.first->m`, `t.emplace().first->m` — libc++
    // map::operator[]'s tree-iterator shape) rides parent_expr so the CIR
    // side (class_this_arg's parent lane) addresses the full expression —
    // the chained-receiver precedent of the arrow method-call arm.
    if ( !lhs )
	return NULL;
    TokenVar *otv = dynamic_cast<TokenVar *>(lhs);
    if ( !otv )
	return NULL;
    DataDef *rdd = NULL;
    bool parent_backed = false;
    // A FIXED-ARRAY receiver decays to a pointer ([expr.ref] applies the
    // built-in arrow to arr[0]) — never an operator-> rewrite, even when
    // the ELEMENT class declares one (var.type names the element type, so
    // the object test alone would mis-fire).
    if ( otv->var.is_fixed_array() )
	return NULL;
    if ( lhs->type() == TokenType::ttVariable )
	rdd = otv->var.type;
    else if ( lhs->type() == TokenType::ttMember
	   || lhs->type() == TokenType::ttCallMethod
	   || lhs->type() == TokenType::ttCallFunc )
    {
	if ( TokenMember *mtm = dynamic_cast<TokenMember *>(lhs) )
	    if ( mtm->is_fixed_array_member() )
		return NULL;
	rdd = lhs->datadef();
	parent_backed = true;
    }
    else
	return NULL;
    // A reference-returning receiver (a call yielding `it&`) denotes its
    // referent ([expr.ref]) — same normalizer the dot arm uses.
    rdd = referent_if_reference(rdd);
    if ( !rdd || !rdd->is_object() || rdd->is_pointer() )
	return NULL;
    DataDefCLASS *ocls = dynamic_cast<DataDefCLASS *>(rdd);
    std::string arrow_name("operator->");
    Variable *arrow_m = ocls ? ocls->findMethod(arrow_name) : NULL;
    if ( !arrow_m )
	return NULL;
    TokenCallMethod *opcall = new TokenCallMethod(otv->var, *arrow_m);
    if ( parent_backed )
	opcall->parent_expr = lhs;
    opcall->file = loc_tb->file;
    opcall->line = loc_tb->line;
    opcall->column = loc_tb->column;
    DataDef *ret = opcall->datadef();
    if ( !ret || !ret->is_pointer() )
    {
	// Env-gated probe (MADC_ARROW_PROBE): the receiver class and the
	// unresolved return DataDef at the failing rewrite.
	static const char *ap = ::getenv("MADC_ARROW_PROBE");
	if ( ap )
	    fprintf(stderr, "[arrow] recv=%s ret=%s obj=%d ref=%d\n",
		    ocls ? ocls->name.c_str() : "?",
		    ret ? ret->name.c_str() : "(null)",
		    ret ? (int)ret->is_object() : -1,
		    ret ? (int)ret->is_reference() : -1);
	Throw(loc_tb) << "operator-> must return a pointer" << flush;
    }
    return opcall;
}

static uint32_t member_proxy_flags(uint32_t owner_flags)
{
    return owner_flags & ~vfFIXEDARRAY;
}

static DataDef *deref_type_for_variable(Variable *var)
{
    if ( !var || !var->type )
	return NULL;

    if ( var->is_fixed_array() )
	return var->type;

    if ( var->type->is_pointer() )
    {
	DataDefPTR *dptr = dynamic_cast<DataDefPTR *>(var->type);
	return (dptr && dptr->base_type) ? dptr->base_type : &ddINT64;
    }

    return NULL;
}

TokenBase *Program::skip_expression_whitespace()
{
    while ( peekToken()
	&& (peekToken()->type() == TokenType::ttSpace
	  || peekToken()->type() == TokenType::ttTab
	  || peekToken()->type() == TokenType::ttEOL) )
	nextToken();
    return peekToken();
}

static bool is_realpart_identifier(const std::string &name)
{
    return name == "__real" || name == "__real__";
}

static bool is_imagpart_identifier(const std::string &name)
{
    return name == "__imag" || name == "__imag__";
}

static TokenBase *make_complex_component_token(TokenBase *expr, bool imag_part)
{
    return new TokenComplexPart(expr, imag_part);
}

// Parse the operand of a `__real__` / `__imag__` component op and wrap it in
// a TokenComplexPart. `anchor` is the component keyword's token (diagnostics).
// Shared by the main identifier-expression arm and the cast-operand dispatch
// (`(int)__real__ d`), which bypasses the main arm.
TokenBase *Program::parse_complex_component_operand(bool want_imag, TokenBase *anchor)
{
    TokenBase *next_tb = nextToken();
    if ( !next_tb )
	Throw(anchor) << "Expecting expression after "
		      << (want_imag ? "__imag__" : "__real__") << flush;
    TokenBase *component_expr = NULL;
    if ( next_tb->id() == TokenID::tkOpBrk )
    {
	TokenBase *inner_tb = nextToken();
	component_expr = parseExpression(inner_tb, true, false, true, 1);
    }
    else if ( is_contextual_identifier_token(next_tb) || next_tb->type() == TokenType::ttIdentifier )
    {
	bool has_postfix_chain = peekToken()
	    && (peekToken()->id() == TokenID::tkDot
	     || peekToken()->id() == TokenID::tkDeRef
	     || peekToken()->id() == TokenID::tkOpSqr);
	if ( has_postfix_chain )
	    component_expr = parsePostfixChain(next_tb);
	else
	{
	    std::string name = contextual_identifier_name(next_tb);
	    TokenIdent component_ident(name);
	    copy_token_location(&component_ident, next_tb);
	    Variable *component_var = findVariable(name);
	    if ( component_var )
	    {
		component_expr = new TokenVar(*component_var);
		copy_token_location(component_expr, next_tb);
	    }
	    else
		component_expr = resolve_expression_context_identifier(&component_ident);
	}
	TokenVar *tv = dynamic_cast<TokenVar *>(component_expr);
	if ( tv && peekToken() && peekToken()->id() == TokenID::tkOpBrk
	  && tv->var.type && tv->var.type->is_function() )
	{
	    Variable *call_var = runtime_eval_scope_target(&tv->var);
	    TokenCallFunc *tc = new TokenCallFunc(*call_var);
	    TokenBase *call_tb = nextToken();
	    tc->line = call_tb->line;
	    tc->column = call_tb->column;
	    parseCallFunc(tc);
	    component_expr = tc;
	}
    }
    if ( !component_expr )
	Throw(next_tb) << "Unsupported operand for "
		       << (want_imag ? "__imag__" : "__real__") << flush;
    return make_complex_component_token(component_expr, want_imag);
}

std::string Program::hoisted_decl_symbol(const std::string &owner_symbol,
					 const std::string &source_name,
					 size_t ordinal,
					 HoistedDeclKind kind)
{
    std::string marker;
    switch ( kind )
    {
    case HoistedDeclKind::LocalClass: marker = "__local_class_"; break;
    case HoistedDeclKind::NestedFunction: marker = "__nested_fn_"; break;
    case HoistedDeclKind::PatternFunction: marker = "__pattern_"; break;
    }
    return owner_symbol + marker + source_name + "__" + std::to_string(ordinal);
}

std::string Program::function_body_emission_symbol(const Variable &var) const
{
    FuncDef *fd = dynamic_cast<FuncDef *>(var.type);
    if ( fd && !fd->emit_symbol.empty() )
	return fd->emit_symbol;
    if ( var.type && var.type->is_function() && !var.storage_alias_name.empty() )
	return var.storage_alias_name;
    return var.name;
}

void Program::remember_hoisted_identity(const HoistedDeclIdentity &identity,
					TokenBase *origin)
{
    std::ostringstream key;
    key << static_cast<int>(identity.kind)
	<< ':' << identity.owner_symbol.size() << ':' << identity.owner_symbol
	<< ':' << identity.source_name.size() << ':' << identity.source_name
	<< ':' << identity.ordinal;
    std::map<std::string, std::string>::iterator it =
	hoisted_symbol_identity_keys.find(identity.symbol);
    if ( it != hoisted_symbol_identity_keys.end() && it->second != key.str() )
	Throw(origin) << "Hoisted declaration symbol collision for '"
		      << identity.symbol << "'" << flush;
    hoisted_symbol_identity_keys[identity.symbol] = key.str();
}

HoistedDeclIdentity Program::declare_hoisted_declaration(
	TokenCpnd *scope, HoistedDeclKind kind,
	const std::string &source_name, TokenBase *origin)
{
    if ( !scope || !scope->method || source_name.empty() )
	Throw(origin) << "Missing enclosing function identity for local declaration"
		      << flush;
    Method *method = scope->method;
    Method::hoisted_decl_key_t key(kind, source_name);
    std::map<Method::hoisted_decl_key_t, HoistedDeclIdentity> &decls =
	method->hoisted_decls[scope];
    std::map<Method::hoisted_decl_key_t, HoistedDeclIdentity>::iterator it =
	decls.find(key);
    if ( it != decls.end() )
	return it->second;

    HoistedDeclIdentity identity;
    identity.kind = kind;
    identity.owner_symbol = function_body_emission_symbol(method->returns);
    identity.source_name = source_name;
    identity.ordinal = ++method->next_hoisted_decl_ordinal;
    identity.symbol = hoisted_decl_symbol(identity.owner_symbol,
					  identity.source_name,
					  identity.ordinal, identity.kind);
    remember_hoisted_identity(identity, origin);
    decls[key] = identity;
    return identity;
}

bool Program::find_hoisted_declaration(TokenCpnd *scope,
	HoistedDeclKind kind, const std::string &source_name,
	HoistedDeclIdentity &out) const
{
    Method::hoisted_decl_key_t key(kind, source_name);
    for ( TokenCpnd *cur = scope; cur; cur = cur->parent )
    {
	if ( !cur->method )
	    continue;
	std::map<const TokenCpnd *,
		 std::map<Method::hoisted_decl_key_t,
			  HoistedDeclIdentity> >::const_iterator si =
	    cur->method->hoisted_decls.find(cur);
	if ( si == cur->method->hoisted_decls.end() )
	    continue;
	std::map<Method::hoisted_decl_key_t,
		 HoistedDeclIdentity>::const_iterator di = si->second.find(key);
	if ( di != si->second.end() )
	{
	    out = di->second;
	    return true;
	}
    }
    return false;
}

bool Program::function_local_class_identity(DataDefCLASS *cdd,
					    HoistedDeclIdentity &out) const
{
    std::map<DataDefCLASS *, HoistedDeclIdentity>::const_iterator it =
	function_local_class_identities.find(cdd);
    if ( it == function_local_class_identities.end() )
	return false;
    out = it->second;
    return true;
}

static std::string namespace_function_symbol(const std::string &ns_name,
					     const std::string &member_name)
{
    // GLOBAL scope has nothing to qualify with, and the invented `__ns__name`
    // was findable by nobody: the registration stored the Variable under it
    // while every unqualified call site looks up the PLAIN name, so
    // `ident(7)` reported "use of undeclared identifier 'ident'" even after
    // the template registered (confirmed with -v: "Added new function
    // declaration name: __ns__ident" followed by "findVariable(ident) not
    // found"). An unqualified name at global scope IS its own key.
    if ( ns_name.empty() )
	return member_name;
    std::string sym = "__ns_";
    for ( size_t i = 0; i < ns_name.size(); ++i )
    {
	char c = ns_name[i];
	sym += (isalnum((unsigned char)c) || c == '_') ? c : '_';
    }
    sym += "_";
    if ( member_name.compare(0, 8, "operator") == 0 )
    {
	sym += "operator";
	std::string op = member_name.substr(8);
	for ( size_t i = 0; i < op.size(); ++i )
	{
	    char c = op[i];
	    switch ( c )
	    {
	    case '<': sym += "_lt"; break;
	    case '>': sym += "_gt"; break;
	    case '+': sym += "_pl"; break;
	    case '-': sym += "_mi"; break;
	    case '*': sym += "_ml"; break;
	    case '/': sym += "_dv"; break;
	    case '%': sym += "_rm"; break;
	    case '=': sym += "_as"; break;
	    case '&': sym += "_ad"; break;
	    case '|': sym += "_or"; break;
	    case '^': sym += "_eo"; break;
	    case '!': sym += "_nt"; break;
	    case '[': sym += "_ix"; break;
	    case ']': break;
	    case '(': sym += "_cl"; break;
	    case ')': break;
	    // ~ and , previously fell to the bare-underscore default, so
	    // operator~ and operator, in ONE namespace produced an IDENTICAL
	    // key — the second declaration found the first via findVariable
	    // and re-parsed its parameters into the SHARED FuncDef (silent
	    // overload collapse). Mnemonics follow operator_code (co, cm).
	    case '~': sym += "_co"; break;
	    case ',': sym += "_cm"; break;
	    default:  sym += (isalnum((unsigned char)c) || c == '_') ? c : '_'; break;
	    }
	}
    }
    else
    {
	for ( size_t i = 0; i < member_name.size(); ++i )
	{
	    char c = member_name[i];
	    sym += (isalnum((unsigned char)c) || c == '_') ? c : '_';
	}
    }
    return sym;
}

// Deterministic, order-independent symbol suffix for a namespace-function
// TEMPLATE-INSTANTIATION product, derived from the instantiated parameter-list
// spelling (the overload's identity): live parse, pack drain, and bound
// consumers mint the SAME symbol no matter which binding instantiates first.
// The registration-order `__oN` bump made a packed body's callee symbol depend
// on drain order, diverging from a live parse of the same TU (forest
// LOADED == PARSED, vecbind gate). Head = sanitized spelling (human hint,
// capped); tail = FNV-1a 32 hash of the raw spelling (the identity).
static std::string overload_spelling_symbol_suffix(const std::string &spelling)
{
    std::string sfx = "__i";
    for ( size_t i = 0; i < spelling.size() && sfx.size() < 64; ++i )
    {
	char c = spelling[i];
	if ( isalnum((unsigned char)c) || c == '_' )
	    sfx += c;
	else if ( c == '*' )
	    sfx += 'P';
	else if ( c == '&' )
	    sfx += 'R';
	// other chars (spaces, <>, ::, commas) drop from the readable head
    }
    uint32_t h = 2166136261u;
    for ( size_t i = 0; i < spelling.size(); ++i )
    {
	h ^= (unsigned char)spelling[i];
	h *= 16777619u;
    }
    char buf[16];
    snprintf(buf, sizeof(buf), "_%08x", h);
    return sfx + buf;
}

static std::vector<std::string> namespace_qualifiers(const std::string &ns_name)
{
    std::vector<std::string> out;
    size_t start = 0;
    while ( start < ns_name.size() )
    {
	size_t sep = ns_name.find("::", start);
	std::string part = sep == std::string::npos
			 ? ns_name.substr(start)
			 : ns_name.substr(start, sep - start);
	if ( !part.empty() )
	    out.push_back(part);
	if ( sep == std::string::npos )
	    break;
	start = sep + 2;
    }
    return out;
}

static std::string cpp_spelling_for_mangle(DataDef *dd, bool as_ref)
{
    if ( !dd )
	return "";
    if ( as_ref )
    {
	DataDefPTR *ptr = dynamic_cast<DataDefPTR *>(dd);
	DataDef *base = ptr && ptr->base_type ? ptr->base_type : dd;
	std::string s = base->canonical_cpp_spelling().empty()
		      ? base->name : base->canonical_cpp_spelling();
	return s + "&";
    }
    return dd->canonical_cpp_spelling().empty() ? dd->name : dd->canonical_cpp_spelling();
}

// `carrier_param_mask` (task #69): positions whose spelling must be
// re-derived as the ACTIVE flavor's text carrier (std_string_type()) instead
// of the stored spelling. The stored spellings are flavor-baked at parse
// time, so a host-flavor remint has to swap them — the mask is computed by
// the caller BEFORE switching mangler state, because marshals_value_text()
// itself reads the active state.
static std::string namespace_cpp_function_symbol(const std::string &ns_name,
						 const std::string &member_name,
						 FuncDef *fd,
						 const std::vector<char> *carrier_param_mask = NULL)
{
    std::vector<std::string> params;
    if ( fd )
    {
	for ( size_t i = 0; i < fd->parameters.size(); ++i )
	{
	    if ( fd->is_varargs && i + 1 == fd->parameters.size() )
	    {
		// The parsed trailing `...` (pseudo-param slot) mangles as `z`.
		params.push_back("...");
		break;
	    }
	    std::string spelling = fd->mangle_param_spelling(i);
	    if ( spelling.empty() )
	    {
		bool refp = fd->is_ref_param(i);
		spelling = cpp_spelling_for_mangle(fd->parameters[i], refp);
	    }
	    if ( carrier_param_mask && i < carrier_param_mask->size()
	      && (*carrier_param_mask)[i] )
	    {
		bool refp = fd->is_ref_param(i);
		bool ptrp = !refp
		    && dynamic_cast<DataDefPTR *>(fd->parameters[i]) != NULL;
		spelling = std_string_type()
			 + (refp ? "&" : ptrp ? "*" : "");
	    }
	    params.push_back(spelling);
	}
    }
    return itanium_mangle_nested_sub(namespace_qualifiers(ns_name),
				     member_name, params);
}

static std::string namespace_cpp_variable_symbol(const std::string &ns_name,
						 const std::string &member_name)
{
    return itanium_mangle_nested_var(namespace_qualifiers(ns_name),
				    member_name);
}

// task #69 (flavor-ABI marshalling): the HOST-flavor twin of a namespace
// public's Itanium symbol. A host-implemented public (php::trim,
// madc::eval_int_ctx) exports only the symbol mangled under the stdlib madc
// itself was built against; when the SCRIPT flavor differs, the marshalling
// boundary needs that twin to bind (and dlsym-verify) the real host entry.
// The remint reuses the one mint (namespace_cpp_function_symbol) under a
// scoped host-flavor mangler state — never string surgery on the script
// symbol (Itanium substitution compression makes fragment swaps wrong).
std::string Program::host_flavor_fn_symbol(const std::string &ns_name,
					   const std::string &member_name,
					   FuncDef *fd)
{
    // Which params are the flavor string — decided under the SCRIPT state
    // (marshals_value_text reads the active mangler state; inside the host
    // scope below it would compare against the HOST carrier and never fire).
    std::vector<char> mask;
    if ( fd )
	for ( size_t i = 0; i < fd->parameters.size(); ++i )
	{
	    DataDef *p = fd->parameters[i];
	    if ( DataDefPTR *pp = dynamic_cast<DataDefPTR *>(p) )
		p = pp->base_type ? pp->base_type : p;
	    mask.push_back(p && p->marshals_value_text() ? 1 : 0);
	}
    MangleHostFlavorScope host_state;
    return namespace_cpp_function_symbol(ns_name, member_name, fd, &mask);
}

static DataDef *unwrap_subscript_element_type(DataDef *base_type)
{
    if ( !base_type )
	return &ddINT64;
    if ( DataDefPTR *pdd = dynamic_cast<DataDefPTR *>(base_type) )
	return pdd->base_type ? pdd->base_type : &ddINT64;
    if ( DataDefCArray *add = dynamic_cast<DataDefCArray *>(base_type) )
	return add->element_type ? add->element_type : &ddINT64;
    return base_type;
}

static DataDef *build_fixed_array_query_type(DataDef *base_type,
					     const std::vector<carray_dim_t> &dims,
					     size_t consumed_dims)
{
    if ( !base_type )
	return &ddINT64;
    if ( consumed_dims >= dims.size() )
	return base_type;

    DataDef *result = base_type;
    for ( size_t i = dims.size(); i-- > consumed_dims; )
	result = new DataDefCArray(*result, result->name, dims[i], NULL);
    return result;
}

static DataDef *type_query_chain_datadef(TokenBase *chain)
{
    if ( !chain )
	return NULL;
    if ( TokenSubscript *ts = dynamic_cast<TokenSubscript *>(chain) )
    {
	if ( ts->object.is_fixed_array() )
	    return build_fixed_array_query_type(ts->object.type, ts->object.dims,
						1 + ts->extra_indices.size());
    }
    if ( TokenSubscriptExpr *tse = dynamic_cast<TokenSubscriptExpr *>(chain) )
    {
	if ( TokenVar *tv = dynamic_cast<TokenVar *>(tse->base_expr) )
	    if ( tv->var.is_fixed_array() )
		return build_fixed_array_query_type(tv->var.type, tv->var.dims, 1);
    }
    return chain->datadef();
}

DataDef *Program::resolve_named_datadef(const std::string &name)
{
    datadef_map_citer dmi = struct_map.find(name);
    if ( dmi != struct_map.end() )
	return dmi->second;

    flat_datatype_map_iter bmi = datatype_map.find(name);
    if ( bmi != datatype_map.end() )
	return &(*bmi)->definition;

    if ( name == "__builtin_va_list" )
	return use_builtin_va_list();	// per-Program: registers the tag struct

    if ( DataDef *dd = resolve_builtin_type_spelling(name) )
	return dd;

    return lazy_resolve_type(name);
}

// The element type a madc `array` (madc::value) subscript READ produces.
// String-first — the Python/PHP element model (`sys.argv[1]`, `arr[i]` in
// string contexts): typed as the real std::string class when <string> has
// been seen. Falls back to the legacy long typing otherwise, which keeps
// numeric reads working in string-less TUs. Numeric reads under the string
// typing are a LOUD type error (never a silent raw-buffer word read); use
// range-for or the php:: getters for mixed numeric access.
DataDef *Program::madc_array_element_type()
{
    DataDef *dd = resolve_named_datadef("string");
    if ( dd && dd->basetype() == BaseType::btClass
      && dd->rawtype() == DataType::dtRESERVED && !dd->is_pointer() )
	return dd;
    return &ddINT64;
}

// The ONE builtin-spelling -> canonical-DataDef table. Every C/C++ source
// spelling of a builtin scalar resolves to the SAME canonical object the
// lexer's type-specifier path emits (`int` -> ddINT32), so identity-sensitive
// consumers (template instantiation keys) converge on one name regardless of
// how the type was spelled.
DataDef *Program::resolve_builtin_type_spelling(const std::string &name)
{
    if ( name == "void" ) return &ddVOID;
    if ( name == "bool" || name == "_Bool" ) return &ddBOOL;
    if ( name == "char" ) return &ddCHAR;
    if ( name == "signed char" ) return &ddINT8;
    if ( name == "unsigned char" ) return &ddUINT8;
    if ( name == "short" || name == "short int"
      || name == "signed short" || name == "signed short int" )
	return &ddINT16;
    if ( name == "unsigned short" || name == "unsigned short int" )
	return &ddUINT16;
    if ( name == "int" || name == "signed" || name == "signed int" )
	return &ddINT32;
    if ( name == "unsigned" || name == "unsigned int" )
	return &ddUINT32;
    if ( name == "long" || name == "long int"
      || name == "signed long" || name == "signed long int"
      || name == "long long" || name == "long long int"
      || name == "signed long long" || name == "signed long long int"
      || name == "__int128" || name == "signed __int128" )
	return &ddINT64;
    if ( name == "unsigned long" || name == "unsigned long int"
      || name == "unsigned long long" || name == "unsigned long long int"
      || name == "unsigned __int128" )
	return &ddUINT64;
    if ( name == "float" || name == "_Float16" || name == "_Float32" )
	return &ddFLOAT;
    if ( name == "double" || name == "long double"
      || name == "_Float64" || name == "_Float128"
      || name == "_Float32x" || name == "_Float64x" )
	return &ddDOUBLE;
    if ( name == "int8_t" ) return &ddINT8;
    if ( name == "int16_t" ) return &ddINT16;
    if ( name == "int32_t" ) return &ddINT32;
    if ( name == "int64_t" ) return &ddINT64;
    if ( name == "uint8_t" ) return &ddUINT8;
    if ( name == "uint16_t" ) return &ddUINT16;
    if ( name == "uint32_t" ) return &ddUINT32;
    if ( name == "uint64_t" ) return &ddUINT64;
    if ( name == "size_t" ) return &ddUINT64;
    if ( name == "ptrdiff_t" ) return &ddINT64;
    if ( name == "wchar_t" ) return &ddINT32;
    if ( name == "char16_t" ) return &ddUINT16;
    if ( name == "char32_t" ) return &ddUINT32;
    if ( name == "max_align_t" ) return &ddMAX_ALIGN_T;
    if ( name == "LPSTR" ) return &ddLPSTR;
    if ( name == "array" ) return &ddARRAY;
    if ( name == "auto" ) return &ddAUTO;
    if ( name == "__builtin_va_list" ) return builtin_va_list_type();

    return NULL;
}

// The compiler-owned x86-64 SysV va_list: struct __madc_va_list_tag[1] —
// the SAME shape gcc, glibc, and c2mir's own mirc_x86_64_linux.h use. ONE
// process singleton so `typedef __builtin_va_list va_list;` (bare, no
// include) and the embedded <stdarg.h> (which aliases this builtin) resolve
// to the identical type; the CIR emitter synthesizes the typedef's C when a
// module references it (no source declaration exists to emit).
DataDef *Program::builtin_va_list_type()
{
    static DataDefCArray *va_list_dd = NULL;
    if ( !va_list_dd )
    {
	DataDefSTRUCT *tag = new DataDefSTRUCT("__madc_va_list_tag", 0);
	tag->addMember("gp_offset", ddUINT32, 1);
	tag->addMember("fp_offset", ddUINT32, 1);
	tag->addMember("overflow_arg_area", ddVOIDptr, 1);
	tag->addMember("reg_save_area", ddVOIDptr, 1);
	tag->is_complete = true;
	va_list_dd = new DataDefCArray(*tag, "__builtin_va_list", 1);
    }
    return va_list_dd;
}

// The single DataDefCOMPLEX-per-element factory (lexer/parser/CIR builder all
// route here so complex types compare by pointer identity — the previous
// per-file static caches could mint two `_Complex double`s).
DataDef *Program::complex_type_of(DataDef *elem)
{
    static std::map<DataDef *, DataDefCOMPLEX *> cache;
    if ( !elem )
	elem = &ddDOUBLE;
    std::map<DataDef *, DataDefCOMPLEX *>::iterator it = cache.find(elem);
    if ( it != cache.end() )
	return it->second;
    DataDefCOMPLEX *complex_type = new DataDefCOMPLEX(*elem);
    cache[elem] = complex_type;
    return complex_type;
}

// Per-Program entry point for a USE of the builtin: registers the tag struct
// in struct_map so the CIR emitter's struct sweep (Pass 1.97) emits the
// definition — a bare `typedef __builtin_va_list va_list;` has no parsed
// struct declaration to emit otherwise.
DataDef *Program::use_builtin_va_list()
{
    DataDef *dd = builtin_va_list_type();
    DataDefCArray *ca = static_cast<DataDefCArray *>(dd);
    if ( ca->element_type && !struct_map.count(ca->element_type->name) )
	struct_map.set(ca->element_type->name, ca->element_type);
    return dd;
}

bool Program::typedef_alias_matches_datadef(const std::string &alias, DataDef *dd)
{
    if ( alias.empty() || !dd || !user_typedef_names.count(alias) )
	return false;
    if ( resolve_named_datadef(alias) == dd )
	return true;

    DataDef *top_level_alias = NULL;
    size_t top_level_matches = 0;
    for ( size_t i = 0; i < top_decls.size(); ++i )
	if ( top_decls[i].kind == DeclKind::dkTypedef
	  && top_decls[i].name == alias )
	{
	    ++top_level_matches;
	    top_level_alias = top_decls[i].dd;
	}
    return top_level_matches == 1 && top_level_alias == dd;
}

static DataDef *resolve_class_type_alias(DataDefCLASS *cls, const std::string &name)
{
    if ( !cls )
	return NULL;
    // The injected-class-name ([class.pre]/2): within class X, the name X refers
    // to X itself. A monomorphized class registers its SHORT injected name as a
    // type-alias, but its identity `name` is the FULL mangled spelling; resolve
    // that to the class too so a fully-qualified self-reference (e.g. a ctor
    // symbol `<full>__<full>`) is recognized as the class.
    if ( cls->name == name )
	return cls;
    std::map<std::string, DataDef *>::iterator ai = cls->type_aliases.find(name);
    if ( ai != cls->type_aliases.end() )
	return ai->second;
    for ( size_t i = 0; i < cls->bases.size(); ++i )
	if ( DataDef *bd = resolve_class_type_alias(cls->bases[i].base, name) )
	    return bd;
    if ( cls->base_class )
	return resolve_class_type_alias(cls->base_class, name);
    if ( cls->enclosing_class )
	return resolve_class_type_alias(cls->enclosing_class, name);
    return NULL;
}

// Resolve an UNQUALIFIED type name through the enclosing class scopes, innermost
// first. [basic.scope.class]/1 + [basic.lookup.unqual]: inside a member — its
// return type, its body, AND its PARAMETER LIST, whether declared in-class or
// defined out of line — a nested type of the class is nameable without
// qualification. class_scope_stack exists for precisely this ("active C++ class
// scopes for nested type lookup", madc.h). Class scopes WIN over the global
// tables, which is why callers consult this before resolve_named_datadef.
static DataDef *resolve_type_in_class_scopes(Program &pgm,
					    const std::string &name)
{
    for ( std::vector<DataDefCLASS *>::reverse_iterator it =
		pgm.class_scope_stack.rbegin();
	  it != pgm.class_scope_stack.rend(); ++it )
	if ( *it )
	    if ( DataDef *dd = resolve_class_type_alias(*it, name) )
		return dd;
    return NULL;
}

// Public wrapper over the file-static class-scope member-type lookup —
// consumed by the tsubst re-derivation of Owner__member dependent
// placeholders (cir_builder rebuild_dependent_derived).
DataDef *Program::class_member_type(DataDefCLASS *cls, const std::string &name)
{
    return resolve_class_type_alias(cls, name);
}

// Class-scope `using <Base>::<member>;` ([namespace.udecl]): import the base
// class's <member> overload(s) into THIS class's overload set so they compete
// with the class's own same-name overloads (a using-declaration defeats name
// hiding). Real `__gnu_cxx::__alloc_traits` does `using _Base_type::construct;`
// to expose std::allocator_traits<_Alloc>::construct alongside its own
// custom-pointer construct overload — overload resolution + [temp.func.order]
// then pick the right one. Handles the single-name-scope, single-member shape;
// returns false (caller falls back to skipping the declaration) for any other
// shape or an unresolved/non-class base. Peeks pgm.tokens; consumes ONLY on a
// successful import (so unhandled forms reach the existing skip unchanged).
static bool try_import_using_base_member(Program &pgm, DataDefCLASS *ddc)
{
    if ( !ddc )
	return false;
    // tokens: [0]=using [1]=scope-name [2]=:: [3]=member [4]=;
    if ( pgm.tokens.size() < 5 )
	return false;
    TokenBase *scope_tb = pgm.tokens[1], *ns_tb = pgm.tokens[2];
    TokenBase *mem_tb = pgm.tokens[3], *semi_tb = pgm.tokens[4];
    if ( !scope_tb || !ns_tb || !mem_tb || !semi_tb )
	return false;
    if ( ns_tb->id() != TokenID::tkNS || semi_tb->id() != TokenID::tkSemi )
	return false;
    if ( !is_contextual_identifier_token(scope_tb)
      || !is_contextual_identifier_token(mem_tb) )
	return false;
    std::string scope_name = contextual_identifier_name(scope_tb);
    std::string member = contextual_identifier_name(mem_tb);
    if ( scope_name.empty() || member.empty() )
	return false;
    DataDefCLASS *base =
	dynamic_cast<DataDefCLASS *>(resolve_class_type_alias(ddc, scope_name));
    if ( !base )
	return false;
    bool captured = false;
    if ( pgm.class_pattern_using_capture )
    {
	std::vector<std::pair<DataDefCLASS *, std::string> > &entries =
	    (*pgm.class_pattern_using_capture)[ddc];
	std::pair<DataDefCLASS *, std::string> entry(base, member);
	bool present = false;
	for ( size_t i = 0; i < entries.size(); ++i )
	    if ( entries[i] == entry ) { present = true; break; }
	if ( !present )
	    entries.push_back(entry);
	captured = true;
    }
    bool imported = false;
    for ( size_t i = 0; i < base->methods.size(); ++i )
    {
	Variable *bm = base->methods[i];
	if ( !bm )
	    continue;
	FuncDef *fd = dynamic_cast<FuncDef *>(bm->type);
	if ( !fd )
	    continue;
	const std::string &disp = fd->method_display_name.empty()
				? bm->name : fd->method_display_name;
	if ( disp != member )
	    continue;
	bool present = false;
	for ( size_t j = 0; j < ddc->methods.size(); ++j )
	    if ( ddc->methods[j] == bm ) { present = true; break; }
	if ( present )
	    continue;
	ddc->methods.push_back(bm);
	if ( ddc->method_map.find(member) == ddc->method_map.end() )
	    ddc->method_map[member] = bm;
	imported = true;
    }
    if ( !imported && !captured )
	return false;
    pgm.nextToken(); pgm.nextToken(); pgm.nextToken();	// using scope ::
    pgm.nextToken(); pgm.nextToken();			// member ;
    return true;
}

static DataDef *resolve_class_static_member_type(DataDefCLASS *cls, const std::string &name)
{
    if ( !cls )
	return NULL;
    std::map<std::string, DataDef *>::iterator si = cls->static_member_types.find(name);
    if ( si != cls->static_member_types.end() )
	return si->second;
    for ( size_t i = 0; i < cls->bases.size(); ++i )
	if ( DataDef *bd = resolve_class_static_member_type(cls->bases[i].base, name) )
	    return bd;
    if ( cls->base_class )
	return resolve_class_static_member_type(cls->base_class, name);
    if ( cls->enclosing_class )
	return resolve_class_static_member_type(cls->enclosing_class, name);
    return NULL;
}

static bool peek_class_member_type_chain(DataDefCLASS *owner,
					 const TokenStream &tokens,
					 size_t start_index,
					 DataDef *&out,
					 size_t &consume_count,
					 std::string &leaf_name)
{
    out = NULL;
    consume_count = 0;
    leaf_name.clear();
    if ( !owner || start_index >= tokens.size()
      || !tokens[start_index]
      || tokens[start_index]->id() != TokenID::tkNS )
	return false;

    DataDefCLASS *scope = owner;
    size_t i = start_index;
    while ( i < tokens.size()
	 && tokens[i] && tokens[i]->id() == TokenID::tkNS )
    {
	size_t member_index = i + 1;
	if ( member_index >= tokens.size() || !tokens[member_index] )
	    return false;
	if ( tokens[member_index]->id() == TokenID::tkTEMPLATE )
	{
	    ++member_index;
	    if ( member_index >= tokens.size() || !tokens[member_index] )
		return false;
	}
	if ( !is_contextual_identifier_token(tokens[member_index]) )
	    return false;

	std::string member_name =
	    contextual_identifier_name(tokens[member_index]);
	DataDef *alias_dd = resolve_class_type_alias(scope, member_name);
	if ( !alias_dd )
	    return false;

	size_t next_index = member_index + 1;
	if ( next_index < tokens.size()
	  && tokens[next_index]
	  && tokens[next_index]->id() == TokenID::tkLT )
	    return false;

	consume_count = next_index - start_index;
	leaf_name = member_name;
	out = alias_dd;

	if ( next_index >= tokens.size()
	  || !tokens[next_index]
	  || tokens[next_index]->id() != TokenID::tkNS )
	    return true;

	scope = dynamic_cast<DataDefCLASS *>(alias_dd);
	if ( !scope )
	    return false;
	i = next_index;
    }
    return out != NULL;
}

// Constant value of an integral static-const data member (captured at parse), or
// false if `name` has no captured constant. Walks the base chain like the type
// resolver, so an inherited `static const … value` is found.
static bool resolve_class_static_member_const_value(DataDefCLASS *cls,
						    const std::string &name,
						    int64_t &out)
{
    if ( !cls )
	return false;
    std::map<std::string, int64_t>::iterator vi =
	cls->static_member_const_values.find(name);
    if ( vi != cls->static_member_const_values.end() )
    {
	out = vi->second;
	return true;
    }
    for ( size_t i = 0; i < cls->bases.size(); ++i )
	if ( resolve_class_static_member_const_value(cls->bases[i].base, name, out) )
	    return true;
    if ( cls->base_class )
	return resolve_class_static_member_const_value(cls->base_class, name, out);
    if ( cls->enclosing_class )
	return resolve_class_static_member_const_value(cls->enclosing_class, name, out);
    return false;
}

// `Class::member` where member is a STATIC DATA MEMBER — resolve it to a value
// token. Two kinds of static live behind one syntax and they resolve
// differently, which is the whole reason this is a shared helper:
//
//   static const int n = 5;   an in-class integral constant -> fold to its value
//   static int n;  int S::n;  STORAGE -> the `Class__member` global that its
//                             out-of-class definition declared (parseDeclaration
//                             folds the `::` in `int S::n = 5;` to `S__n`)
//
// Getting that choice wrong is not a diagnostic-quality issue: folding a
// storage-backed member to its (absent) constant yields a silent 0 on every
// read and "lvalue required" on every write. A class-TYPED static is always an
// object, so it checks storage first and never folds.
//
// Returns NULL when `member` is not a static data member of `scope` at all,
// leaving the caller's own not-found path in charge.
// The global name an out-of-class definition of `C::m` registers — parseDeclaration
// folds the `::` into `__`. Written once because two callers need DIFFERENT answers
// about the same name: a VALUE may fold to an in-class constant, while an ADDRESS
// must be of real storage (there is nothing to point at otherwise).
static std::string class_static_member_storage_name(DataDefCLASS *scope,
						    const std::string &member)
{
    return scope->name + "__" + member;
}

// The REAL Itanium symbol for `Class::member` when the class is library-owned.
//
// Rule #1: g++ names a static data member by the Itanium ABI, so madc must too.
// The name above is a madc invention (`scope->name` is the INTERNAL TAG —
// `numpunct_char`, not the C++ spelling `numpunct<char>`), which is fine only
// while madc emits both the storage and every reference. For a class declared
// in a system header the storage lives in the LIBRARY: libstdc++ exports 51
// facet `id` objects and libc++ 32, and `std::use_facet<F>` odr-uses `F::id`.
// Emitting `numpunct_char__id` against those is a reference to a name nothing
// defines, while `_ZNSt10numpunctIcE2idE` is sitting right there.
//
// This is the integration point every OTHER entity category already had and
// static data members did not — ctors/dtors/methods/operators bind via
// bind_declared_cpp_symbol, namespace functions via namespace_cpp_function_symbol,
// namespace variables via namespace_cpp_variable_symbol. Returns "" when the
// class is madc's own, which keeps the invented name for the case where it is
// harmless (madc emits the definition too).
static std::string class_static_member_itanium_symbol(DataDefCLASS *scope,
						      const std::string &member)
{
    if ( !scope || !scope->from_system_header )
	return std::string();
    const std::string &cls = scope->canonical_cpp_spelling();
    if ( cls.empty() )
	return std::string();
    // split_scope_spelling() owns `::`-splitting that must not cut inside a
    // template argument list (`map<int,string>::x`) — never hand-rolled here,
    // that family is consolidated and ratchet-gated (spelling_delim.h).
    std::vector<std::string> quals = split_scope_spelling(cls);
    if ( quals.empty() )
	return std::string();
    return itanium_mangle_nested_var(quals, member);
}

static TokenBase *resolve_class_static_member_value(Program &pgm,
						    DataDefCLASS *scope,
						    const std::string &member,
						    TokenBase *at)
{
    DataDef *static_dd = resolve_class_static_member_type(scope, member);
    if ( !static_dd )
	return NULL;

    const std::string storage_name = class_static_member_storage_name(scope, member);
    int64_t cv = 0;
    const bool have_const =
	resolve_class_static_member_const_value(scope, member, cv);
    // Objects never fold; scalars prefer a real in-class constant and fall back
    // to storage. `static const int n = 5;` with a later `const int S::n;`
    // still reads 5, which is what both canons do.
    const bool storage_first = dynamic_cast<DataDefCLASS *>(static_dd) != NULL;
    if ( storage_first || !have_const )
    {
	if ( Variable *svar = pgm.findVariable(storage_name) )
	{
	    TokenVar *tv = new TokenVar(*svar);
	    copy_token_location(tv, at);
	    return tv;
	}
    }
    // No storage: an in-class constant, or a declared-but-never-defined static
    // (unchanged behaviour — cv stays 0).
    TokenInt *ti = new TokenInt(cv);
    ti->setDataType(static_dd);
    copy_token_location(ti, at);
    return ti;
}

// Public seam for the CIR lowering (declared on Program): the resolution
// itself is the file-static above — storage-backed TokenVar for object-typed
// statics, folded in-class constant for scalars.
TokenBase *Program::class_static_member_value_token(DataDefCLASS *scope,
						    const std::string &member,
						    TokenBase *at)
{
    return resolve_class_static_member_value(*this, scope, member, at);
}

// `Tmpl<args>::member` once the template-id has already been instantiated to a
// concrete type: resolve the trailing `::member` static data member to a value.
//
// Consumes the `::` and the member name ONLY when it can resolve them, so a
// caller that speculatively instantiated a template-id can fall through with the
// token stream intact. Shared by the unqualified (`Box<int>::value`) and
// namespace-qualified (`std::is_same<A,B>::value`) operand arms, which differ
// only in how they reach the instantiation.
static TokenBase *resolve_template_id_static_member(Program &pgm,
						    TokenDataType *inst)
{
    if ( !inst || !pgm.peekToken() || pgm.peekToken()->id() != TokenID::tkNS )
	return NULL;
    DataDefCLASS *cls = dynamic_cast<DataDefCLASS *>(&inst->definition);
    if ( !cls )
	return NULL;
    TokenBase *probe = pgm.tokens.size() > 1 ? pgm.tokens[1] : NULL;
    if ( !probe || !is_contextual_identifier_token(probe) )
	return NULL;
    const std::string member = contextual_identifier_name(probe);
    if ( !resolve_class_static_member_type(cls, member) )
	return NULL;
    pgm.nextToken();				// consume '::'
    TokenBase *member_tb = pgm.nextToken();	// consume the member name
    return resolve_class_static_member_value(pgm, cls, member, member_tb);
}

// get-or-create the placeholder DataDef for template parameter `name` at 0-based
// `index`. Pooled by (name, index) and owned by template_param_pool for the
// Program's lifetime (same never-freed convention as ptr_type_cache), so a Tree-1
// pattern that references it outlives the per-TU TemplateParamScope frame.
DataDefTemplateParam *Program::intern_template_param(const std::string &name,
						     unsigned index)
{
    for ( size_t i = 0; i < template_param_pool.size(); ++i )
	if ( template_param_pool[i]->param_index == index
	  && template_param_pool[i]->name == name )
	    return template_param_pool[i];
    DataDefTemplateParam *tp = new DataDefTemplateParam(name, index);
    template_param_pool.push_back(tp);
    return tp;
}

// resolve `name` to an active template-parameter placeholder (innermost frame
// first). Returns NULL — the common case — when no dependent-body frame is active,
// keeping the consult below O(1) on the non-template path.
DataDef *Program::resolve_template_param(const std::string &name)
{
    for ( std::vector<std::map<std::string, DataDef *> >::reverse_iterator it =
	      template_param_scopes.rbegin();
	  it != template_param_scopes.rend(); ++it )
    {
	std::map<std::string, DataDef *>::iterator mi = it->find(name);
	if ( mi != it->end() )
	    return mi->second;
    }
    return NULL;
}

DataDef *Program::resolve_current_class_type_alias(const std::string &name)
{
    // Two-tree Phase 2 / 2a: during a DEPENDENT template-body parse, the template's
    // own parameters (`T`) resolve to their placeholder FIRST, ahead of any class
    // scope. Inert (no active frame) in every other parse, so this is byte-identical
    // until 2a pushes a TemplateParamScope.
    if ( DataDef *tp = resolve_template_param(name) )
	return tp;
    // The CURRENT METHOD's owner class is the innermost class scope while its
    // body parses ([class.mfct]: member-function lookup reaches the class
    // scope before any enclosing/ambient one), so it must SHADOW the
    // class_scope_stack — which can hold unrelated classes when this parse
    // was triggered from inside another class's method (the dependent-pattern
    // parse of _Rb_tree::_M_insert_unique, triggered inside std::set::insert,
    // resolved `iterator` to std::set's instead of _Rb_tree's own). In a
    // normal in-class method parse the owner is also the stack's innermost
    // entry, so the reorder is a no-op there.
    if ( !compounds.empty() && compounds.top()
      && compounds.top()->method
      && compounds.top()->method->owner_class )
	if ( DataDef *dd =
		resolve_class_type_alias(compounds.top()->method->owner_class,
					 name) )
	    return dd;
    for ( std::vector<DataDefCLASS *>::reverse_iterator it =
	      class_scope_stack.rbegin();
	  it != class_scope_stack.rend(); ++it )
	if ( DataDef *dd = resolve_class_type_alias(*it, name) )
	    return dd;
    return NULL;
}

// Resolve an UNQUALIFIED identifier to the captured value of a static-const
// data member of a class currently being parsed (or a method's owner class).
// Lets an in-class constant initializer reference a sibling static-const
// member, e.g. `static const category all = (ctype | numeric);`.
bool Program::resolve_current_class_static_member_const_value(
	const std::string &name, int64_t &out)
{
    for ( std::vector<DataDefCLASS *>::reverse_iterator it =
	      class_scope_stack.rbegin();
	  it != class_scope_stack.rend(); ++it )
	if ( resolve_class_static_member_const_value(*it, name, out) )
	    return true;
    if ( !compounds.empty() && compounds.top()
      && compounds.top()->method
      && compounds.top()->method->owner_class )
	if ( resolve_class_static_member_const_value(
		 compounds.top()->method->owner_class, name, out) )
	    return true;
    return false;
}

Variable *Program::find_variable_for_contextual_type_name(const std::string &name)
{
    std::string lookup = name;
    Variable *var = findVariable(lookup);
    if ( var )
	return var;
    size_t sp = name.rfind(' ');
    if ( sp == std::string::npos || sp + 1 >= name.size() )
	return NULL;
    lookup = name.substr(sp + 1);
    return findVariable(lookup);
}

DataDefCLASS *Program::resolve_expression_class_scope(const std::string &name)
{
    DataDef *dd = resolve_current_class_type_alias(name);
    if ( !dd && !compounds.empty() && compounds.top()
      && compounds.top()->method && compounds.top()->method->owner_class )
	dd = resolve_class_type_alias(compounds.top()->method->owner_class, name);
    if ( !dd )
    {
	flat_datatype_map_iter dti = datatype_map.find(name);
	if ( dti != datatype_map.end() )
	    dd = &(*dti)->definition;
    }
    if ( !dd )
    {
	datadef_map_citer dmi = struct_map.find(name);
	if ( dmi != struct_map.end() )
	    dd = dmi->second;
    }
    if ( !dd )
	dd = lazy_resolve_type(name);
    return dynamic_cast<DataDefCLASS *>(dd);
}

// THE one classify policy for "what does this qualifier name before `::` in
// an expression". Three arms (postfix chain, address-of, identifier arm)
// each hand-rolled a slice of it and diverged three ways: one checked class
// before namespace while two checked namespace first, one skipped alias
// resolution entirely, and only one consulted namespace_datatype_map. The
// populations are disjoint today, so the order disagreements were latent
// coin-flips — and a name that genuinely resolves BOTH ways is diagnosed
// loudly (both canons reject the ambiguity; picking a winner silently is
// how the arms would drift apart again).
Program::QualifierScope Program::classify_qualifier_before_scope(
	const std::string &name, TokenBase *at)
{
    QualifierScope r;
    r.cls = resolve_expression_class_scope(name);
    r.ns_name = name;
    std::string resolved = resolve_namespace_name_in_scope(name);
    if ( !resolved.empty() )
	r.ns_name = resolved;
    r.has_variable_ns = namespace_map.find(r.ns_name) != namespace_map.end();
    r.has_datatype_ns =
	namespace_datatype_map.find(r.ns_name) != namespace_datatype_map.end();
    if ( r.cls && r.is_namespace() )
	Throw(at) << "'" << name
		  << "' names both a class and a namespace in this scope" << flush;
    return r;
}

static TokenDataType *make_alias_type_token(const std::string &name,
					    DataDef *dd, TokenBase *at)
{
    if ( !dd )
	return NULL;
    TokenDataType *tdt = new TokenDataType(name.c_str(), *dd);
    if ( at )
    {
	tdt->file = at->file;
	tdt->line = at->line;
	tdt->column = at->column;
    }
    return tdt;
}

TokenDataType *Program::resolve_namespaced_type_token(TokenBase *tb, bool consume_tokens)
{
    if ( !tb || tb->type() != TokenType::ttIdentifier || !peekToken() || peekToken()->id() != TokenID::tkNS )
	return NULL;

    // Scope-relative qualification: inside `namespace std`, `__cmp_cat::type`
    // names std::__cmp_cat::type (C++ searches the enclosing-namespace chain
    // before the global scope). resolve_namespace_name_in_scope falls back to
    // the absolute name itself, preserving the old absolute-only behavior.
    std::string ns_name = ((TokenIdent *)tb)->spelling();
    std::string resolved_ns = resolve_namespace_name_in_scope(ns_name);
    if ( !resolved_ns.empty() )
	ns_name = resolved_ns;

    // Extend through nested qualifiers (`a::b::member`): tokens[0] is the '::'
    // after tb; each ident+'::' pair deepens the namespace while the deeper
    // path names a known namespace. tokens[j] ends as the member candidate.
    size_t j = 1;
    while ( j + 1 < tokens.size()
	 && tokens[j] && is_contextual_identifier_token(tokens[j])
	 && tokens[j + 1] && tokens[j + 1]->id() == TokenID::tkNS )
    {
	std::string deeper = ns_name + "::"
			   + contextual_identifier_name(tokens[j]);
	if ( namespace_datatype_map.find(deeper) == namespace_datatype_map.end()
	  && namespace_map.find(deeper) == namespace_map.end() )
	    break;
	ns_name = deeper;
	j += 2;
    }

    namespace_datatype_map_t::iterator nti = namespace_datatype_map.find(ns_name);
    if ( nti == namespace_datatype_map.end() )
	return NULL;

    if ( j >= tokens.size() )
	return NULL;
    TokenBase *member_tb = tokens[j];
    if ( !member_tb )
	return NULL;
    std::string member_name;
    if ( member_tb->type() == TokenType::ttIdentifier )
	member_name = ((TokenIdent *)member_tb)->spelling();
    else if ( member_tb->type() == TokenType::ttDataType )
	member_name = ((TokenDataType *)member_tb)->spelling();
    else if ( is_contextual_identifier_token(member_tb) )
	member_name = contextual_identifier_name(member_tb);
    else
	return NULL;
    datatype_map_iter dti = nti->find(member_name);
    if ( dti == nti->end() )
	return NULL;

    if ( consume_tokens )
	for ( size_t k = 0; k <= j; ++k )
	    nextToken(); // each qualifier's '::' (+ ident) and the member
    return dti->second;
}

// Instantiate a captured template on use: `Name<ConcreteType>`. Clones the
// template's body tokens, substitutes the type parameter(s) with the concrete
// type token(s) and renames the class to a per-instantiation mangled name, then
// injects the synthesized `class Mangled { ... };` to the front of the parse
// deque and re-parses it via the existing class parser (which registers a normal
// DataDefCLASS). Returns a use-site TokenDataType for the instantiated class, or
// NULL if `tname` is not a template / the syntax doesn't match (caller falls
// through). Assumes `tb` (the template name) is already current; the next token
// must be '<'. See docs/plans/2026-05-30-template-instantiation.md.
static TokenDataType *use_site_type_token(TokenDataType *proto, TokenBase *at);
// Match `<`...`>` as a balanced delimiter pair, like `(`...`)` and `{`...`}`:
// each `<` opens one template level and is closed by exactly ONE `>`. The lexer,
// having no template context, emits `>>` as a single TokenBSR (right-shift), so a
// `>>` at a nested template-id close supplies the `>` for THIS level and leaves a
// `>` for the enclosing one (the C++11 rule). `tok` is the already-consumed
// candidate close token; on a `>`-class token this consumes the close (pushing
// back the leftover `>` for `>>`) and returns true, else returns false and
// consumes nothing extra. Applied at every template-angle close site.
// (The open side never needs splitting — `<<` cannot appear as two template
// opens in a well-formed template-id, since each level is introduced by a name.)
bool Program::consume_template_close(TokenBase *tok)
{
    if ( !tok )
	return false;
    if ( tok->id() == TokenID::tkGT )
	return true;                          // single '>'
    if ( tok->id() == TokenID::tkBSR )    // '>>' = this level's '>' + the outer one
    {
	pushToken(new TokenGT());
	return true;
    }
    return false;
}

// Operator-function-id helpers — shared by every <...> scanner so the operator
// symbol of `operator<` / `operator>>` / … is treated as part of a NAME, never
// as an angle-bracket delimiter. Free functions because some scanners walk a
// captured token vector and have no Program & in hand.
static bool token_is_operator_id_start(TokenBase *t)
{
    return t && is_contextual_identifier_token(t)
	&& contextual_identifier_name(t) == "operator";
}
// Number of tokens the operator-function-id at toks[i] spans (keyword + symbol
// [+ closing )/] for operator()/operator[]]), or 0 if toks[i] is not an
// operator-id start. For index-based scanners that walk a captured token
// sequence (templated so it serves both std::vector and the std::deque queue).
// A conversion-function-id names a TYPE where every other operator-id names a
// symbol: `operator _Tp()`, `operator const char *()` [class.conv.fct]. Its
// conversion-type-id runs to the `(` of the parameter list.
static bool token_starts_conversion_type_id(TokenBase *t)
{
    if ( !t )
	return false;
    if ( t->id() == TokenID::tkNEW || t->id() == TokenID::tkDELETE )
	return false;                   // operator new / operator delete
    return is_contextual_identifier_token(t)
	|| t->type() == TokenType::ttDataType
	|| t->type() == TokenType::ttKeyword;
}

// How many tokens FOLLOW the `operator` keyword. ONE decision, shared by the
// index form below and the stream form (Program::delimStepStream) — the two
// must never disagree about how far an operator-id reaches.
template<typename Seq>
static size_t operator_id_tail_span(const Seq &toks, size_t sym_idx)
{
    if ( sym_idx >= toks.size() )
	return 0;
    TokenBase *sym = toks[sym_idx];
    TokenBase *next = sym_idx + 1 < toks.size() ? toks[sym_idx + 1] : NULL;
    if ( !sym )
	return 1;
    if ( sym->type() == TokenType::ttString && next
      && is_contextual_identifier_token(next) )
	return 2;   // user-defined literal: operator "" suffix
    if ( (sym->id() == TokenID::tkOpBrk || sym->id() == TokenID::tkOpSqr) && next )
	return 2;   // operator() / operator[]
    if ( sym->id() == TokenID::tkNEW || sym->id() == TokenID::tkDELETE )
	return 1;   // a trailing `[]` balances under ordinary delimiter tracking
    if ( token_starts_conversion_type_id(sym) )
    {
	// Multi-token conversion-type-id: `const char *`, `unsigned long`,
	// `std::size_t`. Runs to the parameter list's `(`.
	size_t n = 0;
	while ( sym_idx + n < toks.size()
	     && toks[sym_idx + n]
	     && toks[sym_idx + n]->id() != TokenID::tkOpBrk )
	    ++n;
	// No `(` in view (truncated / malformed): fall back to one token rather
	// than swallowing the rest of the sequence.
	return (n && sym_idx + n < toks.size()) ? n : 1;
    }
    return 1;       // operator + single symbol token (<, <<, <=, >, >>, …)
}

template<typename Seq>
static size_t operator_id_token_span(const Seq &toks, size_t i)
{
    if ( i >= toks.size() || !token_is_operator_id_start(toks[i]) )
	return 0;
    if ( i + 1 >= toks.size() )
	return 1;
    return 1 + operator_id_tail_span(toks, i + 1);
}

// Balanced-delimiter depth for token scans: (), [], {}, <>. The hand-rolled
// "++paren … --angle … >>" if-else chain is copy-pasted across many scanners;
// this is the single shared bookkeeping (operator-ids consumed opaquely, never
// counted as a '<'). Callers layer their own logic (comma counts, terminators)
// on top using `top()` / the individual depths.
struct DelimDepth {
    int paren = 0, square = 0, brace = 0, angle = 0;
    std::vector<int> angle_paren;   // paren depth at each angle open
    TokenBase *prev = NULL;         // previous token seen by update()
    bool top() const { return !paren && !square && !brace && !angle; }
    // A `<` can only BEGIN a template-argument-list after a name (template-id
    // head: identifier / type name / the `template` keyword). After `)`, `]`,
    // a literal, etc. it is the less-than OPERATOR — real <type_traits> writes
    // `integral_constant<bool, _Tp(-1) < _Tp(0)>`, and counting that `<` as an
    // open desynced the scan by one level for the next ~1300 header lines.
    // NULL prev (scan starting mid-stream) keeps the legacy always-open rule.
    static bool angle_open_context(TokenBase *t)
    {
	if ( !t )
	    return true;
	if ( t->type() == TokenType::ttIdentifier
	  || t->type() == TokenType::ttDataType )
	    return true;
	return t->id() == TokenID::tkTEMPLATE;
    }
    // Pure delimiter bookkeeping for one token (NO operator-id handling — the
    // callers below own that, differing by index vs stream access).
    void update(TokenBase *t)
    {
	if ( !t )
	    return;
	switch ( t->id() )
	{
	    case TokenID::tkOpBrk: ++paren; break;
	    case TokenID::tkClBrk: if ( paren > 0 )  --paren;  break;
	    case TokenID::tkOpSqr: ++square; break;
	    case TokenID::tkClSqr: if ( square > 0 ) --square; break;
	    case TokenID::tkOpBrc: ++brace; break;
	    case TokenID::tkClBrc: if ( brace > 0 )  --brace;  break;
	    // Two independent tests, and BOTH are required — each catches a
	    // shape the other misses:
	    //   angle_open_context : `declval<T>() < declval<U>()` — prev is
	    //                        `)`, so this `<` cannot begin a template-id.
	    //   !paren && !square  : `decltype(a < b)` — prev IS an identifier,
	    //                        so the context test passes and only the
	    //                        nesting test rejects it. Without this the
	    //                        angle opened here never closes (its `>` is
	    //                        inside the parens too), the depth stays
	    //                        stuck past the `)`, and a scan looking for
	    //                        a top-level `;` or body `{` runs to EOF.
	    // Inside `(...)`/`[...]` the paren balancing alone locates the
	    // enclosing construct, so angles there are simply not tracked.
	    case TokenID::tkLT:
		if ( !paren && !square && angle_open_context(prev) )
		{
		    ++angle;
		    angle_paren.push_back(paren);
		}
		break;
	    // An UNPARENTHESIZED `>` closes the argument list ([temp.names]):
	    // a `>` inside parens opened WITHIN the list (`A<(B > C)>`) is the
	    // greater-than operator, not a close.
	    case TokenID::tkGT:    close_angle(); break;
	    case TokenID::tkBSR:   close_angle(); close_angle(); break;
	    default: break;
	}
	prev = t;
    }
private:
    void close_angle()
    {
	if ( angle <= 0 )
	    return;
	if ( !angle_paren.empty() && paren > angle_paren.back() )
	    return;             // operator-> comparison inside parens
	--angle;
	if ( !angle_paren.empty() )
	    angle_paren.pop_back();
    }
};
// Index form: update `d` for the token sequence at toks[i]; returns the number
// of tokens consumed (1, or an operator-id's span). Templated for both
// std::vector and the std::deque token queue.
template<typename Seq>
static size_t delim_scan_step(const Seq &toks, size_t i, DelimDepth &d)
{
    if ( size_t n = operator_id_token_span(toks, i) )
	return n;
    d.update(toks[i]);
    return 1;
}

static std::string template_token_fragment(TokenBase *tb)
{
    if ( !tb )
	return "";
    if ( tb->type() == TokenType::ttIdentifier )
	return ((TokenIdent *)tb)->spelling();
    if ( tb->type() == TokenType::ttKeyword )
	return ((TokenKeyword *)tb)->spelling();
    if ( tb->type() == TokenType::ttDataType )
	return ((TokenDataType *)tb)->spelling();
    if ( tb->type() == TokenType::ttInteger )
    {
	TokenInt *ti = static_cast<TokenInt *>(tb);
	if ( !ti->source_text.empty() )
	    return ti->source_text;
	return std::to_string(ti->ival());
    }
    if ( tb->type() == TokenType::ttString )
	return ((TokenStr *)tb)->str;
    if ( TokenMultiOp *mo = dynamic_cast<TokenMultiOp *>(tb) )
	return mo->str;
    char c = (char)tb->get();
    return c ? std::string(1, c) : std::string("_");
}

namespace {
class ClassPatternHash
{
    uint64_t value_;
public:
    ClassPatternHash() : value_(1469598103934665603ULL) {}
    void add_u64(uint64_t value)
    {
	for ( unsigned i = 0; i < 8; ++i )
	{
	    value_ ^= (uint8_t)(value & 0xffu);
	    value_ *= 1099511628211ULL;
	    value >>= 8;
	}
    }
    void add_bool(bool value) { add_u64(value ? 1 : 0); }
    void add_string(const std::string &value)
    {
	add_u64(value.size());
	for ( size_t i = 0; i < value.size(); ++i )
	{
	    value_ ^= (uint8_t)value[i];
	    value_ *= 1099511628211ULL;
	}
    }
    uint64_t value() const { return value_; }
};
}

uint64_t Program::class_pattern_fingerprint(const ClassPattern &pattern) const
{
    ClassPatternHash hash;
    auto add_tokens = [&](const std::vector<TokenBase *> &tokens) {
	hash.add_u64(tokens.size());
	for ( size_t i = 0; i < tokens.size(); ++i )
	{
	    TokenBase *token = tokens[i];
	    hash.add_bool(token != NULL);
	    if ( !token )
		continue;
	    hash.add_u64((uint64_t)token->id());
	    hash.add_u64((uint64_t)token->type());
	    hash.add_u64((uint64_t)token->datatype());
	    hash.add_bool(token->is_bracketed());
	    hash.add_bool(token->is_overloaded());
	    hash.add_string(template_token_fragment(token));
	    if ( token->type() == TokenType::ttChar )
		hash.add_u64((uint64_t)token->ival());
	    else if ( token->type() == TokenType::ttReal )
	    {
		TokenReal *real = static_cast<TokenReal *>(token);
		hash.add_string(real->source_text);
		uint64_t bits = 0;
		double value = real->dval();
		memcpy(&bits, &value, sizeof(bits));
		hash.add_u64(bits);
	    }
	    else if ( token->type() == TokenType::ttString )
		hash.add_bool(static_cast<TokenStr *>(token)->wide);
	}
    };

    hash.add_string(pattern.identity);
    hash.add_string(pattern.class_name);
    hash.add_string(pattern.defining_namespace);
    hash.add_bool(pattern.is_partial_specialization);
    hash.add_u64((uint64_t)pattern.capture_reason);
    hash.add_u64(pattern.types.size());
    for ( size_t i = 0; i < pattern.types.size(); ++i )
    {
	const ClassTypePattern &type = pattern.types[i];
	hash.add_u64((uint64_t)type.kind);
	hash.add_u64(type.flags);
	// Fingerprint the concrete type by its process-stable canonical
	// spelling, never by the raw id: runtime type ids are process-local
	// (the producer's id space), so a correctly-swizzled restore would
	// always mismatch an id-based hash. Presence still hashes (id==0 vs
	// resolved is a semantic difference).
	if ( type.concrete_type_id )
	{
	    DataDef *concrete = madc_type_from_id(type.concrete_type_id);
	    if ( concrete )
		hash.add_string(concrete->canonical_cpp_spelling().empty()
		    ? concrete->name : concrete->canonical_cpp_spelling());
	    else
		hash.add_u64(1);	// resolvable-at-capture marker
	}
	else
	    hash.add_u64(0);
	hash.add_u64(type.operand);
	hash.add_u64(type.secondary);
	hash.add_u64(type.template_param_index);
	hash.add_u64(type.nested_node_id);
	hash.add_u64(type.pack_param_index);
	hash.add_string(type.name);
	hash.add_u64(type.arguments.size());
	for ( size_t a = 0; a < type.arguments.size(); ++a )
	    hash.add_u64(type.arguments[a]);
	hash.add_u64(type.dimensions.size());
	for ( size_t d = 0; d < type.dimensions.size(); ++d )
	    hash.add_u64(type.dimensions[d]);
    }
    hash.add_u64(pattern.nodes.size());
    for ( size_t i = 0; i < pattern.nodes.size(); ++i )
    {
	const ClassAggregatePatternNode &node = pattern.nodes[i];
	hash.add_u64(node.local_id);
	hash.add_u64(node.parent_id);
	hash.add_u64((uint64_t)node.kind);
	hash.add_string(node.source_name);
	hash.add_string(node.canonical_spelling);
	hash.add_bool(node.complete);
	hash.add_bool(node.from_system_header);
	hash.add_u64(node.bases.size());
	for ( size_t b = 0; b < node.bases.size(); ++b )
	{
	    hash.add_u64(node.bases[b].type);
	    hash.add_u64(node.bases[b].access);
	    hash.add_bool(node.bases[b].is_virtual);
	}
	hash.add_u64(node.declarations.size());
	for ( size_t d = 0; d < node.declarations.size(); ++d )
	    hash.add_u64((uint64_t)node.declarations[d]);
	hash.add_u64(node.aliases.size());
	for ( size_t a = 0; a < node.aliases.size(); ++a )
	{
	    hash.add_string(node.aliases[a].name);
	    hash.add_u64(node.aliases[a].type);
	}
	hash.add_u64(node.members.size());
	for ( size_t m = 0; m < node.members.size(); ++m )
	{
	    const ClassMemberPattern &member = node.members[m];
	    hash.add_string(member.name);
	    hash.add_u64(member.type);
	    hash.add_u64(member.count);
	    hash.add_u64(member.access);
	    hash.add_bool(member.is_array);
	    hash.add_bool(member.is_bitfield);
	    hash.add_bool(member.is_anonymous);
	    hash.add_u64(member.bit_width);
	    hash.add_u64(member.dimensions.size());
	    for ( size_t d = 0; d < member.dimensions.size(); ++d )
		hash.add_u64(member.dimensions[d]);
	}
	hash.add_u64(node.methods.size());
	for ( size_t m = 0; m < node.methods.size(); ++m )
	{
	    const ClassMethodPattern &method = node.methods[m];
	    hash.add_u64((uint64_t)method.kind);
	    hash.add_string(method.variable_name);
	    hash.add_string(method.display_name);
	    hash.add_string(method.storage_alias_name);
	    hash.add_string(method.local_emit_name); // allowed-exception: fingerprint field, not symbol build
	    hash.add_string(method.emit_symbol);
	    hash.add_string(method.return_typedef_name);
	    hash.add_u64(method.return_type);
	    hash.add_u64(method.flags);
	    hash.add_bool(method.is_varargs);
	    hash.add_bool(method.is_void_params);
	    hash.add_bool(method.declaration_only);
	    hash.add_bool(method.defaulted_or_deleted);
	    hash.add_bool(method.is_deleted);
	    hash.add_u64(method.noexcept_spec);
	    hash.add_bool(method.pure_virtual);
	    hash.add_bool(method.is_const_method);
	    hash.add_bool(method.is_member_template);
	    hash.add_bool(method.has_eager_body);
	    hash.add_u64(method.parameters.size());
	    for ( size_t p = 0; p < method.parameters.size(); ++p )
	    {
		const ClassMethodParamPattern &param = method.parameters[p];
		hash.add_string(param.name);
		hash.add_u64(param.type);
		hash.add_u64(param.flags);
		hash.add_bool(param.is_const);
		hash.add_bool(param.template_param_spelled_directly);
		hash.add_string(param.cpp_spelling);
		hash.add_string(param.typedef_name);
		add_tokens(param.default_tokens);
	    }
	    hash.add_u64(method.template_param_names.size());
	    for ( size_t p = 0; p < method.template_param_names.size(); ++p )
		hash.add_string(method.template_param_names[p]);
	    hash.add_u64(method.template_param_is_type.size());
	    for ( size_t p = 0; p < method.template_param_is_type.size(); ++p )
		hash.add_bool(method.template_param_is_type[p]);
	    hash.add_u64(method.template_param_is_pack.size());
	    for ( size_t p = 0; p < method.template_param_is_pack.size(); ++p )
		hash.add_bool(method.template_param_is_pack[p]);
	    hash.add_string(method.template_return_spelling);
	    hash.add_u64(method.template_param_spellings.size());
	    for ( size_t p = 0; p < method.template_param_spellings.size(); ++p )
		hash.add_string(method.template_param_spellings[p]);
	    add_tokens(method.body_tokens);
	    add_tokens(method.definition_tokens);
	    add_tokens(method.trailing_ret_tokens);
	    add_tokens(method.ctor_init_tokens);
	    add_tokens(method.member_template_decl);
	    add_tokens(method.member_template_return_tokens);
	    hash.add_u64(method.template_param_defaults.size());
	    for ( size_t p = 0; p < method.template_param_defaults.size(); ++p )
		add_tokens(method.template_param_defaults[p]);
	    hash.add_u64(method.template_param_constraints.size());
	    for ( size_t p = 0; p < method.template_param_constraints.size(); ++p )
		add_tokens(method.template_param_constraints[p]);
	    hash.add_u64(method.param_type_token_runs.size());
	    for ( size_t p = 0; p < method.param_type_token_runs.size(); ++p )
		add_tokens(method.param_type_token_runs[p]);
	}
	hash.add_u64(node.using_members.size());
	for ( size_t u = 0; u < node.using_members.size(); ++u )
	{
	    hash.add_u64(node.using_members[u].owner_type);
	    hash.add_string(node.using_members[u].name);
	}
	hash.add_u64(node.nested_templates.size());
	for ( size_t t = 0; t < node.nested_templates.size(); ++t )
	{
	    const ClassNestedTemplatePattern &nested = node.nested_templates[t];
	    hash.add_u64((uint64_t)nested.kind);
	    hash.add_u64(nested.typeparams.size());
	    for ( size_t p = 0; p < nested.typeparams.size(); ++p )
		hash.add_string(nested.typeparams[p]);
	    hash.add_u64(nested.typeparam_defaults.size());
	    for ( size_t p = 0; p < nested.typeparam_defaults.size(); ++p )
		add_tokens(nested.typeparam_defaults[p]);
	    hash.add_u64(nested.typeparam_is_type.size());
	    for ( size_t p = 0; p < nested.typeparam_is_type.size(); ++p )
		hash.add_bool(nested.typeparam_is_type[p]);
	    hash.add_u64(nested.typeparam_is_pack.size());
	    for ( size_t p = 0; p < nested.typeparam_is_pack.size(); ++p )
		hash.add_bool(nested.typeparam_is_pack[p]);
	    hash.add_bool(nested.has_non_type_params);
	    hash.add_string(nested.class_name);
	    add_tokens(nested.body);
	    hash.add_string(nested.defining_namespace);
	    hash.add_bool(nested.is_partial_specialization);
	    hash.add_u64(nested.spec_pattern.size());
	    for ( size_t p = 0; p < nested.spec_pattern.size(); ++p )
		add_tokens(nested.spec_pattern[p]);
	    add_tokens(nested.constraint);
	    add_tokens(nested.target);
	}
	hash.add_u64(node.static_members.size());
	for ( size_t s = 0; s < node.static_members.size(); ++s )
	{
	    hash.add_string(node.static_members[s].first);
	    hash.add_u64(node.static_members[s].second);
	}
	hash.add_u64(node.static_values.size());
	for ( size_t s = 0; s < node.static_values.size(); ++s )
	{
	    hash.add_string(node.static_values[s].first);
	    hash.add_u64((uint64_t)node.static_values[s].second);
	}
	hash.add_u64(node.friend_classes.size());
	for ( size_t f = 0; f < node.friend_classes.size(); ++f )
	    hash.add_string(node.friend_classes[f]);
	hash.add_u64(node.friend_functions.size());
	for ( size_t f = 0; f < node.friend_functions.size(); ++f )
	    hash.add_string(node.friend_functions[f]);
    }
    return hash.value();
}

static std::string template_type_arg_spelling(TokenDataType *adt,
					      const std::string &cv_spelling)
{
    if ( !adt )
	return cv_spelling;
    // These are distinct C++ template argument spellings even though madc maps
    // their storage to integer DataDefs internally. Keep the source spelling so
    // explicit specializations such as `char_traits<wchar_t>` are found.
    if ( adt->spelling_is("wchar_t") || adt->spelling_is("char16_t")
      || adt->spelling_is("char32_t") )
	return cv_spelling + adt->spelling();
    // A REFERENCE template argument (`tuple<const int&>`) must render with `&`,
    // NOT the ref-as-pointer `*` form. madc lowers references to pointers
    // (DataDefREF IS-A DataDefPTR), so a reference's name/canonical spelling is
    // the `*`-form — which is IDENTICAL to a real pointer's. Baking that into an
    // instantiation's canonical_cpp_spelling() LOSES the reference identity: when
    // that spelling is later re-resolved during deduction
    // (split_template_id_spelling -> resolve_arg_spelling_datadef), `const int32_t*`
    // rebuilds a PLAIN POINTER, so the library's `_Head&` (std::get/__get_helper's
    // return, _Head = const int&) double-wraps to `const int**` -> c2mir "incompatible
    // return-expr type in function returning a pointer" -> undefined __ns_std_get
    // (map<int,int>'s `tuple<const key_type&>` get<0>). Render `referent&` so the
    // canonical spelling round-trips back to a DataDefREF, where getReferenceType's
    // reference collapsing ([dcl.ref]p6) then yields the single reference. The
    // referent keeps its own cv (`const int` -> `const int&`).
    if ( adt->definition.is_reference() )
	if ( DataDefPTR *r = dynamic_cast<DataDefPTR *>(&adt->definition) )
	    if ( r->base_type )
	    {
		const std::string &rs = r->base_type->canonical_cpp_spelling();
		return cv_spelling
		     + (rs.empty() ? r->base_type->name : rs) + "&";
	    }
    // [temp.type]: template-argument identity is the CANONICAL type. A
    // NAMESPACE-scope scalar typedef mints a distinct alias dd whose
    // canonical spelling is the ALIAS ("std::streamsize", @0f97958b's
    // despaced-canonical index) — keying an instantiation on it makes an
    // explicit specialization keyed on the underlying builtin invisible,
    // so the PRIMARY instantiates silently (libc++'s
    // __libcpp_is_integral<long> never matched streamsize;
    // numeric_limits<streamsize> picked the all-zeros non-arithmetic
    // primary and `cin >> string` extracted NOTHING). Desugar through the
    // alias chain the typedef arm records. ONLY through that explicit
    // link: a DataType-based desugar (mangle_scalar_spelling) also fired
    // on class-scope aliases minted inside templates, whose DataType is
    // not a reliable identity — it crossed basic_string<char>'s chain
    // with vector<int>'s (reverse_iterator_char_typeP / basic_string
    // <int32_t> in the emitted C).
    {
	DataDef *ud = adt->definition.scalar_alias_of;
	while ( ud && ud->scalar_alias_of )
	    ud = ud->scalar_alias_of;
	if ( ud )
	{
	    const std::string &us = ud->canonical_cpp_spelling();
	    return cv_spelling + (us.empty() ? ud->name : us);
	}
    }
    const std::string &cs = adt->definition.canonical_cpp_spelling();
    return cv_spelling + (cs.empty() ? adt->definition.name : cs);
}

static std::string sanitize_template_fragment(const std::string &s)
{
    std::string out;
    for ( size_t i = 0; i < s.size(); ++i )
    {
	unsigned char c = (unsigned char)s[i];
	out += (isalnum(c) || c == '_') ? (char)c : '_';
    }
    return out.empty() ? std::string("_") : out;
}

// Template-ARGUMENT fragment sanitizer: like sanitize_template_fragment, but
// '*' -> 'P' and '&' -> 'R' instead of '_'. Declarator suffixes are
// type-identity-bearing in a template argument — `X<int*>` and `X<int&>` are
// distinct instantiations — and the blanket '_' collapsed both fragments to
// one key, so whichever registered first served the other's lookups
// (std::move<int*>'s `remove_reference<int*>::type` read the earlier
// `remove_reference<int&>`'s int32_t: one pointer level lost in the return).
// Same letters as overload_spelling_symbol_suffix's readable head.
static std::string sanitize_template_arg_fragment(const std::string &s)
{
    // Env-gated trap (MADC_RRTRAP=<exact spelling>): abort at the moment a
    // specific template-arg spelling is flattened, so a gdb backtrace names
    // the route that built it (the #103 RR-shell hunt). Diagnostic only.
    {
	static const char *rrt = ::getenv("MADC_RRTRAP");
	if ( rrt && *rrt && s == rrt )
	    abort();
    }
    std::string out;
    for ( size_t i = 0; i < s.size(); ++i )
    {
	unsigned char c = (unsigned char)s[i];
	if ( isalnum(c) || c == '_' )
	    out += (char)c;
	else if ( c == '*' )
	    out += 'P';
	else if ( c == '&' )
	    out += 'R';
	else
	    out += '_';
    }
    return out.empty() ? std::string("_") : out;
}

// The datatype_map / struct_map key HEAD for a template instantiation: the
// bare name unless the same name is declared in 2+ namespaces (std::char_traits
// vs __gnu_cxx::char_traits), where the defining namespace must disambiguate.
// Every registration AND lookup of an instantiated template must use this one
// rule — an explicit specialization registered under a differently-formed key
// is invisible to use sites, which then instantiate the primary instead.
static std::string template_instantiation_key_head(
	Program &pgm, const std::string &tname,
	uint32_t name_id,
	const std::string &defining_namespace,
	DataDefCLASS *owner = NULL)
{
    const Program::template_registry_entry_t *entry =
	pgm.template_map.find_readonly(name_id);
    const std::vector<Program::TemplateDef> *g =
	entry ? entry->find(owner) : NULL;
    if ( g && g->size() > 1
      && !defining_namespace.empty() )
	return sanitize_template_fragment(defining_namespace) + "__" + tname;
    return tname;
}

TokenBase *Program::collect_template_argument_spelling(TokenBase *first,
						     std::string &spelling,
						     std::vector<TokenBase *> *tokens_out)
{
    DelimDepth d;
    TokenBase *t = first;
    while ( t )
    {
	if ( d.angle == 0 && d.paren == 0 && d.square == 0
	  && (t->id() == TokenID::tkComma || t->id() == TokenID::tkGT
	   || t->id() == TokenID::tkBSR) )
	    return t;
	if ( t->id() == TokenID::tkBSR && d.angle == 1 )
	{
	    spelling += ">";
	    if ( tokens_out )
		tokens_out->push_back(new TokenGT());
	    return new TokenGT();
	}
	// operator-function-id (`operator<`, `operator>>`, `operator()`, …):
	// the operator symbol is part of a NAME, never an angle/paren/bracket
	// delimiter. Consume `operator` + its symbol token(s) via the shared
	// primitive without touching any depth counter.
	if ( isOperatorIdStart(t) )
	{
	    std::vector<TokenBase *> opsyms;
	    std::string opname = parseOperatorId(t, tokens_out ? &opsyms : NULL);
	    spelling += opname;
	    if ( tokens_out )
	    {
		tokens_out->push_back(t->clone());
		for ( TokenBase *s : opsyms )
		    tokens_out->push_back(s->clone());
	    }
	    t = nextToken();
	    continue;
	}
	{
	    // Separate two adjacent WORD fragments (`const`+`int`, `unsigned`+`long`)
	    // with a space so a multi-word type argument spells `const int&`, not the
	    // unparseable `constint&`. Without it the canonical_cpp_spelling() of an
	    // opaque/variadic instantiation (e.g. `tuple<const int&>`, a pack template)
	    // does NOT round-trip through resolve_arg_spelling_datadef — `const ` can't
	    // be peeled off `constint`, so partial-spec deduction of the element type
	    // fails and the spec is wrongly rejected for the primary (map<int,int>'s
	    // `tuple_element<0, tuple<const int&>>::type`). Only inserted between two
	    // identifier/keyword chars; `::`, `<`, `&`, `*`, `,` keep tight (sanitize/
	    // despace normalize the space away for mangled keys and canonical compares).
	    std::string frag = template_token_fragment(t);
	    if ( !spelling.empty() && !frag.empty() )
	    {
		char prev = spelling.back(), cur = frag[0];
		bool prev_word = isalnum((unsigned char)prev) || prev == '_';
		bool cur_word = isalnum((unsigned char)cur) || cur == '_';
		if ( prev_word && cur_word )
		    spelling += ' ';
	    }
	    spelling += frag;
	}
	if ( tokens_out )
	    tokens_out->push_back(t->clone());
	d.update(t);
	t = nextToken();
    }
    Throw(first) << "Unexpected end of input in template argument list" << flush;
    return NULL;
}

static std::string single_contextual_token_name(const std::vector<TokenBase *> &toks)
{
    if ( toks.size() != 1 || !is_contextual_identifier_token(toks[0]) )
	return "";
    return contextual_identifier_name(toks[0]);
}

static TokenDataType *resolve_type_token_sequence(Program &pgm,
						  const std::vector<TokenBase *> &seq,
						  TokenBase *loc)
{
    if ( seq.empty() )
	return NULL;

    TokenSemi *sentinel = new TokenSemi();
    std::vector<TokenBase *> inj;
    for ( size_t i = 0; i < seq.size(); ++i )
	inj.push_back(seq[i]->clone());
    inj.push_back(sentinel);
    for ( std::vector<TokenBase *>::reverse_iterator it = inj.rbegin();
	  it != inj.rend(); ++it )
	pgm.pushToken(*it);

    TokenBase *head = pgm.nextToken();
    std::string cv_spelling;
    head = pgm.consume_template_type_arg_qualifiers(head, cv_spelling);
    (void)cv_spelling;
    TokenDataType *resolved = pgm.resolve_declared_type_token(head, true, true);
    if ( resolved )
    {
	while ( pgm.peekToken() && pgm.peekToken()->id() == TokenID::tkMul )
	{
	    pgm.nextToken();
	    DataDefPTR *ptr = pgm.getPointerType(&resolved->definition);
	    TokenDataType *pdt = new TokenDataType(ptr->name.c_str(), *ptr);
	    pdt->file = loc ? loc->file : resolved->file;
	    pdt->line = loc ? loc->line : resolved->line;
	    pdt->column = loc ? loc->column : resolved->column;
	    resolved = pdt;
	}
    }

    bool have_sentinel = false;
    for ( size_t si = 0; si < pgm.tokens.size(); ++si )
	if ( pgm.tokens[si] == sentinel )
	{
	    have_sentinel = true;
	    break;
	}
    if ( have_sentinel )
    {
	while ( pgm.peekToken() && pgm.peekToken() != sentinel )
	    pgm.nextToken();
	if ( pgm.peekToken() == sentinel )
	    pgm.nextToken();
    }
    else if ( pgm.peekToken() && pgm.peekToken()->id() == TokenID::tkSemi )
	pgm.nextToken();

    return resolved;
}

static const Program::TemplateAliasDef *find_template_alias_in_class_tree(
	Program &pgm, uint32_t name_id, DataDefCLASS *owner,
	DataDefCLASS **matched_owner, std::set<DataDefCLASS *> *seen = NULL)
{
    if ( !owner )
	return NULL;
    std::set<DataDefCLASS *> local_seen;
    if ( !seen )
	seen = &local_seen;
    if ( seen->find(owner) != seen->end() )
	return NULL;
    seen->insert(owner);

    if ( const Program::TemplateAliasDef *found =
	    pgm.find_template_alias(name_id, std::string(), owner) )
    {
	if ( matched_owner )
	    *matched_owner = owner;
	return found;
    }

    for ( size_t i = 0; i < owner->bases.size(); ++i )
	if ( const Program::TemplateAliasDef *td =
		find_template_alias_in_class_tree(pgm, name_id,
					  owner->bases[i].base,
					  matched_owner, seen) )
	    return td;
    if ( const Program::TemplateAliasDef *td =
	    find_template_alias_in_class_tree(pgm, name_id, owner->base_class,
				      matched_owner, seen) )
	return td;

    return find_template_alias_in_class_tree(pgm, name_id,
				     owner->enclosing_class,
				     matched_owner, seen);
}

static TokenDataType *resolve_simple_member_detection_alias(
	Program &pgm, const Program::TemplateAliasDef &op_alias,
	const std::vector<std::vector<TokenBase *> > &op_arg_tokens,
	TokenBase *loc)
{
    const std::vector<TokenBase *> &target = op_alias.target;
    if ( target.size() < 4 )
	return NULL;
    if ( !is_contextual_identifier_token(target[0])
      || contextual_identifier_name(target[0]) != "typename" )
	return NULL;
    if ( !is_contextual_identifier_token(target[1])
      || target[2]->id() != TokenID::tkNS
      || !is_contextual_identifier_token(target[3]) )
	return NULL;

    std::string param_name = contextual_identifier_name(target[1]);
    size_t param_index = op_alias.typeparams.size();
    for ( size_t i = 0; i < op_alias.typeparams.size(); ++i )
	if ( op_alias.typeparams[i] == param_name )
	{
	    param_index = i;
	    break;
	}
    if ( param_index >= op_arg_tokens.size() )
	return NULL;

    TokenDataType *arg_type =
	resolve_type_token_sequence(pgm, op_arg_tokens[param_index], loc);
    DataDefCLASS *arg_class = arg_type
	? dynamic_cast<DataDefCLASS *>(&arg_type->definition) : NULL;
    if ( !arg_class )
	return NULL;

    std::string member_name = contextual_identifier_name(target[3]);
    DataDef *member = resolve_class_type_alias(arg_class, member_name);
    return member ? make_alias_type_token(member_name, member, loc) : NULL;
}

static bool template_param_expects_type(const std::vector<bool> &kinds,
					size_t index)
{
    return index >= kinds.size() || kinds[index];
}

static size_t first_template_pack_index(const std::vector<bool> &packs)
{
    for ( size_t i = 0; i < packs.size(); ++i )
	if ( packs[i] )
	    return i;
    return packs.size();
}

static bool template_has_parameter_pack(const std::vector<bool> &packs)
{
    return first_template_pack_index(packs) < packs.size();
}

// True when the template's base-specifier is a DEPENDENT MEMBER TYPE — a
// template-id immediately followed by `::member` in the base clause, i.e.
// `struct X : public Base<...>::type { }`. This is the non-recursive
// trait-FORWARDING shape (`__invoke_result : __result_of_impl<...>::type`,
// `__is_invocable : __is_invocable_impl<...>::type`): the class's entire meaning
// is the type it inherits, which can only be computed by really instantiating the
// base template and taking its member. It is distinct from the RECURSIVE bases
// (`tuple : _Tuple_impl<0, Ts...>`, `__and_ : conditional_t<...>`) whose base is a
// plain template-id (or alias), NOT a `::member` — so this predicate cleanly
// selects the forwarding traits without admitting the unbounded recursion the
// flag-clear at instantiate_template_use guards against. Scans the base-clause
// region of td.body (everything before the class body's opening `{` at depth 0)
// for a `>`/`>>` (template-id close) immediately followed by `::`.
static bool template_base_is_dependent_member(const Program::TemplateDef &td)
{
    int depth = 0;
    for ( size_t i = 0; i + 1 < td.body.size(); ++i )
    {
	TokenBase *t = td.body[i];
	if ( !t )
	    continue;
	TokenID id = t->id();
	if ( id == TokenID::tkOpBrc )
	{
	    if ( depth == 0 )
		return false;          // reached the class body — no dependent-member base
	    ++depth;
	}
	else if ( id == TokenID::tkClBrc )
	    --depth;
	else if ( depth == 0
	       && (id == TokenID::tkGT || id == TokenID::tkBSR)
	       && td.body[i + 1] && td.body[i + 1]->id() == TokenID::tkNS )
	    return true;               // `...>::` in the base clause
    }
    return false;
}

// A class template whose BASE CLAUSE names a template-id base (`: public
// Base<...>`). When the template itself is being really instantiated, its base
// must instantiate too — and a variadic / partial-spec base (std::tuple's
// `_Tuple_impl<_Idx, _Elements...>`) only really instantiates while variadic
// real-instantiation is active. So a true result keeps real-instantiation
// STICKY through the body re-parse (the base resolves with the flag on),
// bounded by variadic_inst_in_progress. Detects a `<` after the base-intro `:`
// and before the class body `{` (depth 0).
static bool template_base_clause_has_template_id(const Program::TemplateDef &td)
{
    bool in_base_clause = false;
    for ( size_t i = 0; i < td.body.size(); ++i )
    {
	TokenBase *t = td.body[i];
	if ( !t )
	    continue;
	TokenID id = t->id();
	if ( id == TokenID::tkOpBrc )
	    return false;              // reached the class body — no template-id base
	if ( id == TokenID::tkColon )
	    in_base_clause = true;
	else if ( in_base_clause && id == TokenID::tkLT )
	    return true;               // `: ... Name< ...` template-id base
    }
    return false;
}

// A variadic class template is REALLY instantiable (body parse + member evaluation,
// not just an opaque dependent shell) for concrete args when its only pack is a
// TRAILING TYPE pack and it carries a parseable body with no non-type params. This is
// the shape of the SFINAE trait helpers that must fold for `vector<T*>` —
// `__construct_helper<_Tp, _Args...>` whose `using type = decltype(__test<_Alloc>(0))`
// member must evaluate. Other variadic shapes (non-type packs, body-less) stay on the
// opaque path. The actual concreteness of the args is decided AFTER parsing them (a
// dependent arg falls back to the opaque shell), so this predicate only gates SHAPE.
static bool template_pack_real_instantiable(const Program::TemplateDef &td,
					    bool allow_valuepack,
					    bool nontype_fixed_ok = false)
{
    if ( td.body.empty() )
	return false;
    size_t n = td.typeparams.size();
    if ( n == 0 )
	return false;
    size_t pack_index = first_template_pack_index(td.typeparam_is_pack);
    if ( pack_index != n - 1 )
	return false;	// no pack, or pack is not the LAST parameter
    // Every FIXED parameter must be a TYPE parameter — the arg loop binds them
    // into subst. The trailing pack itself may be a TYPE pack (the SFINAE
    // helper shape) OR — only under the value-pack demand flag (task #102) —
    // a NON-TYPE pack (libc++ __integer_sequence's `_IdxType... _Values`):
    // value elements accumulate into token_pack_subst and the legacy body
    // clone splices / replicates them. (td.has_non_type_params is a misnomer —
    // it is set true even for a pure TYPE pack — so test typeparam_is_type
    // directly.)
    // EXCEPTION (`nontype_fixed_ok`, the WON-partial-spec path): a spec's
    // non-type FIXED param (`tuple_element<_Ip, tuple<_Types...>>`'s _Ip)
    // is already bound via token_subst by the spec-win wiring — the arg
    // loop's subst limitation does not apply there.
    if ( n > td.typeparam_is_type.size() )
	return false;
    for ( size_t i = 0; i + 1 < n; ++i )
	if ( !td.typeparam_is_type[i] && !nontype_fixed_ok )
	    return false;
    if ( !td.typeparam_is_type[n - 1] )
	return allow_valuepack;	// NON-TYPE pack: demand-keyed (see madc.h)
    return true;
}

static std::vector<TokenBase *> clone_template_tokens_with_type_subst(
	const std::vector<TokenBase *> &src,
	const std::map<std::string, TokenDataType *> &subst)
{
    std::vector<TokenBase *> out;
    for ( TokenBase *bt : src )
    {
	if ( bt && bt->type() == TokenType::ttIdentifier )
	{
	    const std::string &s = ((TokenIdent *)bt)->spelling();
	    std::map<std::string, TokenDataType *>::const_iterator si =
		subst.find(s);
	    if ( si != subst.end() )
	    {
		out.push_back(si->second->clone());
		continue;
	    }
	}
	out.push_back(bt ? bt->clone() : NULL);
    }
    return out;
}

// Like clone_template_tokens_with_type_subst, but ALSO expands a trailing pack: a
// `pack_name` identifier immediately followed by `...` is replaced by the pack's
// element types comma-separated (an EMPTY pack drops the preceding `,` so
// `<_Fn, _Args...>` -> `<_Fn>`, never `<_Fn,>`). A bare `pack_name` not followed by
// `...` falls back to the ordinary 1:1 subst. With an empty pack_name this behaves
// exactly like clone_template_tokens_with_type_subst.
static std::vector<TokenBase *> clone_template_tokens_with_pack_subst(
	const std::vector<TokenBase *> &src,
	const std::map<std::string, TokenDataType *> &subst,
	const std::string &pack_name,
	const std::vector<DataDef *> &pack_elems)
{
    std::vector<TokenBase *> out;
    for ( size_t i = 0; i < src.size(); ++i )
    {
	TokenBase *bt = src[i];
	if ( !pack_name.empty() && bt && bt->type() == TokenType::ttIdentifier
	  && ((TokenIdent *)bt)->spelling() == pack_name
	  && i + 3 < src.size()
	  && src[i+1] && src[i+1]->id() == TokenID::tkDot
	  && src[i+2] && src[i+2]->id() == TokenID::tkDot
	  && src[i+3] && src[i+3]->id() == TokenID::tkDot )
	{
	    if ( pack_elems.empty() && !out.empty()
	      && out.back()->id() == TokenID::tkComma )
	    { delete out.back(); out.pop_back(); }
	    for ( size_t e = 0; e < pack_elems.size(); ++e )
	    {
		if ( e )
		    out.push_back(new TokenComma());
		out.push_back(new TokenDataType(pack_elems[e]->name.c_str(),
						*pack_elems[e]));
	    }
	    i += 3;   // consume the `...`
	    continue;
	}
	if ( bt && bt->type() == TokenType::ttIdentifier )
	{
	    std::map<std::string, TokenDataType *>::const_iterator si =
		subst.find(((TokenIdent *)bt)->spelling());
	    if ( si != subst.end() )
	    { out.push_back(si->second->clone()); continue; }
	}
	out.push_back(bt ? bt->clone() : NULL);
    }
    return out;
}

// Substitute a variable template's captured type args into its initializer tokens,
// binding the leading fixed type parameters 1:1 and absorbing any surplus args into
// a trailing parameter pack (`is_invocable_v<_Fn, _Args...>` etc.). Without the pack
// path a multi-arg use left `_Args...` unexpanded in the init (`is_invocable<_Fn,
// int...>`), which then failed to parse — the var-template analogue of the
// partial-spec / member-fn-template trailing-pack absorption.
static std::vector<TokenBase *> substitute_var_template_init(
	const Program::VarTemplateDef &vd, const std::vector<DataDef *> &targs)
{
    bool has_pack = !vd.typeparams.empty()
		 && !vd.typeparam_is_pack.empty() && vd.typeparam_is_pack.back();
    size_t nfixed = has_pack ? vd.typeparams.size() - 1 : vd.typeparams.size();
    std::map<std::string, TokenDataType *> subst;
    for ( size_t i = 0; i < nfixed && i < targs.size(); ++i )
	if ( targs[i] )
	    subst[vd.typeparams[i]] =
		new TokenDataType(targs[i]->name.c_str(), *targs[i]);
    std::string pack_name = has_pack ? vd.typeparams.back() : std::string();
    std::vector<DataDef *> pack_elems;
    if ( has_pack )
	for ( size_t i = nfixed; i < targs.size(); ++i )
	    if ( targs[i] )
		pack_elems.push_back(targs[i]);
    return clone_template_tokens_with_pack_subst(vd.init, subst, pack_name, pack_elems);
}

static std::string template_tokens_spelling(
	const std::vector<TokenBase *> &tokens)
{
    std::string spelling;
    for ( TokenBase *t : tokens )
	spelling += template_token_fragment(t);
    return spelling;
}

template<typename Seq>	// std::vector and the TokenStream queue, like delim_scan_step
static size_t template_id_suffix_end(
	const Seq &tokens, size_t lt_index,
	bool *split_gt = NULL)
{
    // *split_gt (when provided): set true if the closing token was a `>>`
    // (tkBSR) that supplied ONE leftover `>` for an ENCLOSING template-id —
    // i.e. the suffix ended at a `>>` while only one `>` was needed to balance
    // this `<...>`. The caller that swallows the suffix must then re-emit a
    // single `>` so the enclosing template-id's close is not lost (the source
    // `Outer<Inner<_Up>>` lexes the trailing pair as one `>>`).
    if ( split_gt )
	*split_gt = false;
    int depth = 0;
    for ( size_t i = lt_index; i < tokens.size(); ++i )
    {
	// operator-function-id: skip `operator` + its symbol token(s) so e.g.
	// `operator<` is not counted as opening a nested template-id.
	if ( size_t n = operator_id_token_span(tokens, i) )
	{
	    i += n - 1;
	    continue;
	}
	if ( tokens[i]->id() == TokenID::tkLT )
	    ++depth;
	else if ( tokens[i]->id() == TokenID::tkGT )
	{
	    --depth;
	    if ( depth <= 0 )
		return i;
	}
	else if ( tokens[i]->id() == TokenID::tkBSR )
	{
	    if ( depth > 1 )
		depth -= 2;
	    else
	    {
		// `>>` closes this `<...>` (depth 1 -> 0) AND leaves a `>` for
		// the enclosing template-id.
		if ( split_gt && depth == 1 )
		    *split_gt = true;
		depth = 0;
	    }
	    if ( depth <= 0 )
		return i;
	}
    }
    return lt_index;
}

// Should the self-name template-id at `tokens[lt_index]` (== `<`), appearing in a
// class template's BODY, be kept as a DISTINCT specialization (re-instantiated)
// rather than collapsed to the injected-class-name (the mangled current type)?
//
// Per [temp.local], a self-name with the template's OWN parameter list
// (`tuple<_Tp>` inside `tuple<_Tp>`) IS the injected-class-name and collapses. A
// self-name with DIFFERENT args is a different specialization. The primary
// `_Tuple_impl`'s `typedef _Tuple_impl<_Idx+1,_Tail...> _Inherited;` is the empty-
// tuple recursion terminator (`_Tuple_impl<1>`); collapsing it to self made the
// ctor's `: _Inherited()` a delegating self-call -> infinite recursion -> stack
// overflow at run time. So it must stay distinct.
//
// But only when the args are CONCRETELY SUBSTITUTABLE — every identifier among
// them is one of the class template's own parameters (`_Idx`, `_Tail`), so the
// clone loop's substitution turns them into a real type. A self-name whose args
// reference an OUTER/dependent name (a member-template parameter, e.g.
// `_UseOtherCtor<_Tuple, tuple<_Up>>` or `_Tuple_impl<_Idx, _UElements...>`)
// cannot be instantiated here and must keep the old collapse (re-instantiating a
// dependent `tuple<_Up>` crashes type resolution). Conservative: anything not
// provably class-param-only stays collapsed.
static bool self_template_id_keep_distinct(
	const Program::TemplateDef &td, const std::vector<TokenBase *> &tokens,
	size_t lt_index)
{
    if ( lt_index >= tokens.size() || tokens[lt_index]->id() != TokenID::tkLT )
	return false;
    std::vector<std::vector<TokenBase *> > slots;
    std::vector<TokenBase *> cur;
    int depth = 0;
    for ( size_t i = lt_index + 1; i < tokens.size(); ++i )
    {
	TokenID id = tokens[i]->id();
	if ( depth == 0 && (id == TokenID::tkGT || id == TokenID::tkBSR) )
	    break;   // close of this `<...>`
	if ( id == TokenID::tkLT || id == TokenID::tkOpBrk || id == TokenID::tkOpSqr )
	    ++depth;
	else if ( id == TokenID::tkGT || id == TokenID::tkClBrk || id == TokenID::tkClSqr )
	    --depth;
	else if ( id == TokenID::tkBSR )
	    depth -= 2;
	if ( depth == 0 && id == TokenID::tkComma )
	{ slots.push_back(cur); cur.clear(); continue; }
	cur.push_back(tokens[i]);
    }
    if ( !cur.empty() )
	slots.push_back(cur);
    if ( slots.empty() )
	return false;   // `Self<>` — nothing to instantiate distinctly
    std::set<std::string> params(td.typeparams.begin(), td.typeparams.end());
    // (a) Is this the injected-class-name (args == the template's own params)?
    bool is_current = slots.size() == td.typeparams.size();
    for ( size_t k = 0; is_current && k < slots.size(); ++k )
    {
	const std::vector<TokenBase *> &slot = slots[k];
	bool is_pack = k < td.typeparam_is_pack.size() && td.typeparam_is_pack[k];
	if ( slot.empty() || !is_contextual_identifier_token(slot[0])
	  || contextual_identifier_name(slot[0]) != td.typeparams[k] )
	    { is_current = false; break; }
	size_t want = is_pack ? 4 : 1;   // pack: param-name + `...`
	if ( slot.size() != want
	  || (is_pack && (slot[1]->id() != TokenID::tkDot
		       || slot[2]->id() != TokenID::tkDot
		       || slot[3]->id() != TokenID::tkDot)) )
	    { is_current = false; break; }
    }
    if ( is_current )
	return false;   // current instantiation -> collapse to injected-class-name
    // (b) Every BARE identifier among the args must be a class template
    // parameter, so substitution yields a concrete, instantiable type. An
    // identifier that HEADS a template-id (`__tuple_types<_Tp...>` in
    // tuple_element's pack-spec body, libc++ sfinae_helpers.h:99) is a
    // TEMPLATE-NAME reference resolved at injection, not a dependent bare
    // name — this loop still walks its own arguments. Requiring param-hood
    // of the template NAME collapsed `tuple_element<_Ip,
    // __tuple_types<_Tp...>>` to the injected-class-name — a
    // SELF-REFERENTIAL typedef, where [temp.dep.type] makes it a DISTINCT
    // specialization (task #103's map:967 wall). A kept id that turns out
    // to denote the current instantiation anyway is unified by its concrete
    // key (the in-flight re-entry arm serves it) — collapse is an identity
    // shortcut, never the authority.
    for ( const std::vector<TokenBase *> &slot : slots )
	for ( size_t ti = 0; ti < slot.size(); ++ti )
	{
	    TokenBase *t = slot[ti];
	    if ( !is_contextual_identifier_token(t)
	      || params.count(contextual_identifier_name(t)) )
		continue;
	    if ( ti + 1 < slot.size() && slot[ti + 1]
	      && slot[ti + 1]->id() == TokenID::tkLT )
		continue;   // heads a template-id -> resolvable template name
	    return false;   // a bare outer/dependent name -> collapse
	}
    return true;
}

static bool member_template_param_intro(TokenBase *t);   // defined with the class parser
// Defined with the tsubst machinery; include_dependent_class=false narrows the
// test to raw template-PARAMETER placeholders (const/ptr walked), excluding
// dependent-placeholder CLASSES (laundered opaques keep their existing routes).
static bool datadef_involves_placeholder(DataDef *dd,
					 bool include_dependent_class = true);

// A member `template <...>` head inside an instantiated class's body: collect
// the member template's own type-param names, return the index one past its
// declaration extent, and set `keep_from` to the first index where a kept
// self template-id is resolution-safe — or return 0 when the head is not one
// this rule covers. Member CLASS templates arm the whole extent (to the
// top-level `;`): a nested TemplateDef's body is captured RAW at the re-parse
// and resolved no earlier than its own instantiation. Member FUNCTION
// templates (a converting ctor `template<class U> alloc9(const alloc9<U>&)`
// is the libc++ __node_handle:84 shape) arm only AFTER the head's closing
// `>`: the head's SFINAE defaults are eagerly re-parsed at registration
// (`_UseOtherCtor<_Tuple, tuple<_Up>>` — see self_template_id_keep_distinct's
// collapse guard), while the declarator and body are registration-inert
// (declarator-name scan + fabricated placeholder params only) and resolve at
// the member's own instantiation with its params bound. A member ALIAS
// template's TARGET is examined during the class re-parse itself (libstdc++
// allocator_traits' partial spec carries `using rebind_traits =
// allocator_traits<rebind_alloc<_Up>>;` — kept spelled, the unresolvable _Up
// detonated the <string> freeze and ate every member after it), a FRIEND
// declaration is eagerly hoisted, and a member VARIABLE template (no
// declarator `(`) has its initializer examined eagerly — those stay on the
// collapse arm.
static size_t member_class_template_extent(
	const std::vector<TokenBase *> &tokens, size_t template_index,
	std::set<std::string> &param_names, size_t &keep_from)
{
    size_t i = template_index + 1;
    if ( i >= tokens.size() || !tokens[i] || tokens[i]->id() != TokenID::tkLT )
	return 0;
    DelimDepth d;
    i += delim_scan_step(tokens, i, d);   // the opening `<` (NULL prev: opens)
    bool name_position = false;           // depth-1 token right after class/typename
    // Collect LOCALLY; publish only on success — a rejected head (a friend /
    // variable template) must not leave stale params armed with no extent, or
    // the next self template-id in an eagerly-parsed friend DECLARATION keeps
    // spelled and detonates the re-parse (__new_allocator's operator== ate
    // max_size and everything after it in the <string> freeze).
    std::set<std::string> collected;
    while ( i < tokens.size() && d.angle > 0 )
    {
	TokenBase *t = tokens[i];
	if ( d.angle == 1 && name_position && t
	  && is_contextual_identifier_token(t) )
	    collected.insert(contextual_identifier_name(t));
	name_position = d.angle == 1 && member_template_param_intro(t);
	i += delim_scan_step(tokens, i, d);
    }
    if ( d.angle > 0 || i >= tokens.size() || !tokens[i] )
	return 0;   // unbalanced head: leave the collapse arm untouched
    size_t head_end = i;   // first token after the head's closing `>`
    if ( tokens[i]->id() == TokenID::tkSTRUCT
      || tokens[i]->id() == TokenID::tkCLASS
      || tokens[i]->id() == TokenID::tkUNION )
    {
	while ( i < tokens.size() )
	{
	    if ( tokens[i] && tokens[i]->id() == TokenID::tkSemi && d.top() )
	    {
		param_names.swap(collected);
		keep_from = template_index;
		return i + 1;
	    }
	    i += delim_scan_step(tokens, i, d);
	}
	return 0;
    }
    // Member FUNCTION template arm: require a top-level declarator `(` before
    // any top-level `=`/`;`/`{` (rejects alias, variable templates), and no
    // `using`/`friend` specifier before it. Extent ends at the top-level `;`
    // (declaration / `= default;`) or one past the matched body `}`.
    bool seen_lparen = false;
    while ( i < tokens.size() )
    {
	TokenBase *t = tokens[i];
	if ( t && d.top() )
	{
	    TokenID id = t->id();
	    if ( !seen_lparen )
	    {
		if ( id == TokenID::tkUSING || id == TokenID::tkFRIEND
		  || id == TokenID::tkAssign || id == TokenID::tkSemi
		  || id == TokenID::tkOpBrc )
		    return 0;   // alias / friend / variable template: collapse
		if ( id == TokenID::tkOpBrk )
		    seen_lparen = true;
	    }
	    else if ( id == TokenID::tkSemi )
	    {
		param_names.swap(collected);
		keep_from = head_end;
		return i + 1;
	    }
	}
	bool was_body_close = seen_lparen && t
	    && t->id() == TokenID::tkClBrc;
	i += delim_scan_step(tokens, i, d);
	if ( was_body_close && d.top() )
	{
	    param_names.swap(collected);
	    keep_from = head_end;
	    return i;   // one past the definition's closing `}`
	}
    }
    return 0;
}

// Do the arguments of the template-id opening at tokens[lt_index] (a tkLT)
// reference any of `names`?
static bool template_id_args_reference_names(
	const std::vector<TokenBase *> &tokens, size_t lt_index,
	const std::set<std::string> &names)
{
    if ( names.empty() || lt_index >= tokens.size()
      || !tokens[lt_index] || tokens[lt_index]->id() != TokenID::tkLT )
	return false;
    DelimDepth d;
    size_t i = lt_index + delim_scan_step(tokens, lt_index, d);
    while ( i < tokens.size() && d.angle > 0 )
    {
	if ( tokens[i] && is_contextual_identifier_token(tokens[i])
	  && names.count(contextual_identifier_name(tokens[i])) )
	    return true;
	i += delim_scan_step(tokens, i, d);
    }
    return false;
}

TokenBase *Program::consume_template_type_arg_qualifiers(TokenBase *tb,
						       std::string &spelling)
{
    while ( is_type_qualifier_token(tb) )
    {
	if ( tb->id() == TokenID::tkCONST )
	    spelling += "const ";
	else if ( tb->id() == TokenID::tkVOLATILE )
	    spelling += "volatile ";
	else if ( tb->id() == TokenID::tkRESTRICT )
	    spelling += "restrict ";
	tb = nextToken();
    }
    return tb;
}

// EAST-cv twin of the owner above: qualifiers written AFTER the base type
// (`T const` — libc++ optional's `add_pointer_t<value_type const>`), consumed
// from the stream between the resolved type and any `*`/`&` declarator
// suffixes, folded into the SAME leading spelling so east and west args spell
// (and key) identically.
void Program::consume_trailing_type_arg_qualifiers(std::string &spelling)
{
    while ( peekToken() && is_type_qualifier_token(peekToken()) )
    {
	TokenBase *q = nextToken();
	if ( q->id() == TokenID::tkCONST )
	    spelling += "const ";
	else if ( q->id() == TokenID::tkVOLATILE )
	    spelling += "volatile ";
	else if ( q->id() == TokenID::tkRESTRICT )
	    spelling += "restrict ";
    }
}

// GCC's __integer_pack(N) builtin — the libstdc++-13 GCC-path index-sequence
// primitive (bits/utility.h: make_integer_sequence / _Build_index_tuple). It is
// valid ONLY as the entire pattern of a template-argument pack expansion
// `X<... __integer_pack(N)... ...>`; at substitution time (N already a concrete
// constant) it yields the constant pack [0, 1, ..., N-1] (size_t). This rewrites
// the live token stream IN PLACE, between a just-consumed `<` and its matching
// close, splicing each `__integer_pack(E)...` into the literal integer args so
// the ordinary template-argument loops then collect plain non-type args. Model:
// GCC cp/pt.cc expand_integer_pack (builds a vec of size_int(i)).
void Program::expand_integer_pack_template_args()
{
    // Bound the rewrite to THIS template-id's argument region: scan to the
    // angle-depth-0 close so an __integer_pack belonging to an outer/sibling
    // construct is never touched. `<` is already consumed, so depth starts at 1.
    // Track paren depth so a `<`/`>` inside `__integer_pack(...)` can't skew it.
    size_t end = tokens.size();
    {
	int adepth = 1, pdepth = 0;
	for ( size_t i = 0; i < tokens.size(); ++i )
	{
	    TokenBase *t = tokens[i];
	    if ( !t ) continue;
	    TokenID id = t->id();
	    if ( id == TokenID::tkOpBrk ) ++pdepth;
	    else if ( id == TokenID::tkClBrk ) { if ( pdepth > 0 ) --pdepth; }
	    else if ( pdepth == 0 )
	    {
		if ( id == TokenID::tkLT ) ++adepth;
		else if ( id == TokenID::tkGT ) { if ( --adepth == 0 ) { end = i; break; } }
		else if ( id == TokenID::tkBSR ) { adepth -= 2; if ( adepth <= 0 ) { end = i; break; } }
	    }
	}
    }

    std::vector<TokenBase *> out;
    bool changed = false;
    size_t j = 0;
    while ( j < end )
    {
	TokenBase *t = tokens[j];
	if ( t && t->type() == TokenType::ttIdentifier
	  && ((TokenIdent *)t)->spelling_is("__integer_pack")
	  && j + 1 < end && tokens[j+1]
	  && tokens[j+1]->id() == TokenID::tkOpBrk )
	{
	    // Match the parenthesized argument `( E )`.
	    int pd = 0;
	    size_t close_p = j + 1;
	    for ( ; close_p < end; ++close_p )
	    {
		if ( !tokens[close_p] ) continue;
		TokenID pid = tokens[close_p]->id();
		if ( pid == TokenID::tkOpBrk ) ++pd;
		else if ( pid == TokenID::tkClBrk ) { if ( --pd == 0 ) break; }
	    }
	    // Require the trailing `...` (three tkDot) within the region; without
	    // it this is not a pack expansion and is left untouched.
	    size_t dots = close_p + 1;
	    bool has_ellipsis = pd == 0 && close_p < end && dots + 2 < end
		&& tokens[dots]   && tokens[dots]->id()   == TokenID::tkDot
		&& tokens[dots+1] && tokens[dots+1]->id() == TokenID::tkDot
		&& tokens[dots+2] && tokens[dots+2]->id() == TokenID::tkDot;
	    int64_t N = -1;
	    if ( has_ellipsis )
	    {
		std::vector<TokenBase *> inner;	// tokens between '(' and ')'
		for ( size_t k = j + 2; k < close_p; ++k )
		    if ( tokens[k] ) inner.push_back(tokens[k]);
		int64_t v;
		if ( fold_nontype_arg_constant(inner, v) && v >= 0 )
		    N = v;
	    }
	    if ( N >= 0 )
	    {
		// Free the consumed pattern tokens (`__integer_pack ( E ) ...`).
		for ( size_t k = j; k <= dots + 2; ++k )
		    delete tokens[k];
		if ( N == 0 )
		{
		    // Empty pack: emit nothing; drop the adjacent separator comma
		    // (prefer the preceding one already in `out`, else the next).
		    bool dropped = false;
		    if ( !out.empty() && out.back()
		      && out.back()->id() == TokenID::tkComma )
		    { delete out.back(); out.pop_back(); dropped = true; }
		    j = dots + 3;
		    if ( !dropped && j < end && tokens[j]
		      && tokens[j]->id() == TokenID::tkComma )
		    { delete tokens[j]; ++j; }
		    changed = true;
		    continue;
		}
		// N >= 1: emit `0, 1, ..., N-1` (no trailing comma — the caller's
		// following `,`/`>` is preserved).
		for ( int64_t e = 0; e < N; ++e )
		{
		    if ( e ) out.push_back(new TokenComma());
		    out.push_back(new TokenInt(e));
		}
		j = dots + 3;	// past the three dots
		changed = true;
		continue;
	    }
	}
	out.push_back(tokens[j]);
	++j;
    }

    if ( changed )
    {
	// Carried-over originals live in `out`; erase removes the deque slots
	// (does not free), then splice the rewritten region back at the front.
	tokens.splice_front(end, out);
    }
}

// clang's __make_integer_seq builtin template (BuiltinTemplateDecl
// BTK__make_integer_seq) — the libc++ index-sequence primitive:
// __utility/integer_sequence.h's __make_indices_imp / <utility>'s
// make_integer_sequence take this branch when __has_builtin says yes (the
// fallback branch is the __repeat/__parity log-time recursion whose
// `K * sizeof...(_Np) + _Np...` patterns are outside the value-pack splice
// arms). `__make_integer_seq<S, T, N>` (N a concrete non-negative constant)
// IS `S<T, 0, 1, ..., N-1>`. The head identifier is already consumed by the
// caller; the live stream holds `< S , T , N >`. This rewrites the stream IN
// PLACE to `< T , 0 , 1 , ..., N-1 >` (the expand_integer_pack_template_args
// model) and delegates instantiation to S. A dependent or non-constant N
// returns NULL — the ordinary lookup path then handles the use (dependent
// shell), exactly like any other template-id.
TokenDataType *Program::instantiate_make_integer_seq(TokenBase *tb,
						     const std::string &ns_hint)
{
    if ( tokens.empty() || !tokens[0] || tokens[0]->id() != TokenID::tkLT )
	return NULL;
    // Bound the argument region with the shared tracker: three top-level args
    // separated by depth-1 commas, closed by the depth-1 `>`. A BSR (`>>`)
    // close would mean N ends in a nested template-id sharing the outer
    // close — not the libc++ shape; leave that to the ordinary path.
    DelimDepth d;
    size_t i = delim_scan_step(tokens, 0, d);	// the `<` (NULL prev: opens)
    size_t arg_start = i;
    size_t close_idx = 0;
    std::vector<std::pair<size_t, size_t> > argr;	// [start, end) per arg
    while ( i < tokens.size() )
    {
	TokenBase *t = tokens[i];
	if ( t && d.angle == 1 && !d.paren && !d.square && !d.brace )
	{
	    if ( t->id() == TokenID::tkComma )
	    {
		argr.push_back(std::make_pair(arg_start, i));
		arg_start = i + 1;
	    }
	    else if ( t->id() == TokenID::tkGT )
	    {
		close_idx = i;
		break;
	    }
	    else if ( t->id() == TokenID::tkBSR )
		return NULL;
	}
	i += delim_scan_step(tokens, i, d);
    }
    if ( !close_idx || argr.size() != 2 )
	return NULL;
    argr.push_back(std::make_pair(arg_start, close_idx));
    for ( size_t a = 0; a < 3; ++a )
	if ( argr[a].first >= argr[a].second )
	    return NULL;
    // S: the target template's bare name — the LAST identifier in the arg
    // (`__integer_sequence`, `integer_sequence`, possibly ns-qualified).
    std::string sname;
    for ( size_t k = argr[0].first; k < argr[0].second; ++k )
	if ( tokens[k] && tokens[k]->type() == TokenType::ttIdentifier )
	    sname = ((TokenIdent *)tokens[k])->spelling();
    if ( sname.empty() )
	return NULL;
    // N must fold to a concrete non-negative constant NOW. The cap bounds the
    // minted argument tokens; a genuine sequence this long is user error.
    std::vector<TokenBase *> nexpr;
    for ( size_t k = argr[2].first; k < argr[2].second; ++k )
	if ( tokens[k] )
	    nexpr.push_back(tokens[k]);
    int64_t n = -1;
    if ( !fold_nontype_arg_constant(nexpr, n) || n < 0 || n > (1 << 20) )
	return NULL;
    // Rebuild the front as `< T , 0 , 1 , ..., N-1 >`. Carried originals move
    // into `out`; everything else in the region is freed here (splice_front
    // only removes the deque slots).
    std::vector<TokenBase *> out;
    out.push_back(tokens[0]);				// `<`
    for ( size_t k = argr[1].first; k < argr[1].second; ++k )
	if ( tokens[k] )
	    out.push_back(tokens[k]);
    for ( int64_t v = 0; v < n; ++v )
    {
	out.push_back(new TokenComma());
	out.push_back(new TokenInt(v));
    }
    out.push_back(tokens[close_idx]);			// `>`
    for ( size_t k = 1; k < close_idx; ++k )
	if ( tokens[k] && (k < argr[1].first || k >= argr[1].second) )
	    delete tokens[k];
    tokens.splice_front(close_idx + 1, out);
    // The builtin minted every pack element as a literal, so the delegated
    // instantiation IS the value-pack real-inst demand site: the two-route
    // identity hazard (see allow_valuepack_real_inst in madc.h) cannot arise
    // when the demanded spelling is itself the folded form. Save/set/restore —
    // instantiate entry consumes and clears both flags.
    bool saved_vri = allow_variadic_real_inst;
    bool saved_vpk = allow_valuepack_real_inst;
    allow_variadic_real_inst = true;
    allow_valuepack_real_inst = true;
    // S is a namespace-level template (`__integer_sequence`,
    // `integer_sequence`) — no owner hint: the builtin never names a member.
    TokenDataType *inst = instantiate_template_id(sname, tb, ns_hint, NULL);
    allow_variadic_real_inst = saved_vri;
    allow_valuepack_real_inst = saved_vpk;
    return inst;
}

// Defined below (near the partial-spec unifiers); used here to resolve a
// deduced pack element's spelling to its instantiated type token.
static DataDef *resolve_arg_spelling_datadef(Program &pgm, const std::string &spelling);
static bool datadef_has_unresolved_dependent_surface(DataDef *dd);


static bool opaque_template_args_select_concrete_partial_spec(
	Program &pgm, const Program::TemplateDef &td, const std::string &tname,
	const std::vector<std::string> &args,
	const std::vector<std::vector<TokenBase *> > &raw_arg_tokens)
{
    if ( args.size() != raw_arg_tokens.size() )
	return false;

    std::vector<TokenDataType *> arg_types_by_slot;
    std::vector<std::vector<TokenBase *> > arg_tokens_by_slot;
    std::vector<std::string> arg_spellings;
    size_t pack_index = first_template_pack_index(td.typeparam_is_pack);
    for ( size_t ai = 0; ai < args.size(); ++ai )
    {
	size_t bind_pi = ai;
	if ( bind_pi >= td.typeparams.size() )
	{
	    if ( pack_index < td.typeparams.size() )
		bind_pi = pack_index;
	    else
		return false;
	}
	if ( template_param_expects_type(td.typeparam_is_type, bind_pi) )
	{
	    DataDef *dd = resolve_arg_spelling_datadef(pgm, args[ai]);
	    if ( !dd || datadef_has_unresolved_dependent_surface(dd) )
		return false;
	    arg_types_by_slot.push_back(new TokenDataType(dd->name.c_str(), *dd));
	    arg_tokens_by_slot.push_back(std::vector<TokenBase *>());
	    arg_spellings.push_back(args[ai]);
	}
	else
	{
	    if ( raw_arg_tokens[ai].size() != 1
	      || !raw_arg_tokens[ai][0]
	      || raw_arg_tokens[ai][0]->id() != TokenID::tkInt )
		return false;
	    int64_t folded = 0;
	    if ( !pgm.fold_nontype_arg_constant(raw_arg_tokens[ai], folded) )
		return false;
	    std::vector<TokenBase *> folded_tokens;
	    folded_tokens.push_back(new TokenInt(folded));
	    arg_types_by_slot.push_back(NULL);
	    arg_tokens_by_slot.push_back(folded_tokens);
	    arg_spellings.push_back(std::to_string(folded));
	}
    }

    std::map<std::string, TokenDataType *> spec_subst;
    std::map<std::string, std::string> spec_tmpl_subst;
    std::map<std::string, std::vector<std::string> > spec_pack_subst;
    std::map<std::string, std::vector<TokenBase *> > spec_nontype_subst;
    const Program::TemplateDef *spec = pgm.match_partial_specialization(
	tname, arg_types_by_slot, arg_spellings, arg_tokens_by_slot,
	td.typeparam_is_type, spec_subst, spec_tmpl_subst, spec_pack_subst,
	spec_nontype_subst, td.defining_namespace, td.owner_class,
	td.registry_name_id);
    return spec && !spec->body.empty();
}

// Env-gated probe (MADC_ARITY_PROBE=<substr>|*): which arity/default-fill
// site is about to reject a template-id, with the TemplateDef's defaults
// state — the throw message alone cannot distinguish the six sites, and the
// dev build carries no -g for a line breakpoint.
template <typename TD>
static void arity_probe(const char *site, const std::string &tname,
			const TD &td, size_t got)
{
	static const char *ap = ::getenv("MADC_ARITY_PROBE");
	if ( !ap || !*ap )
		return;
	if ( strcmp(ap, "*") && tname.find(ap) == std::string::npos )
		return;
	std::string dstate;
	for ( size_t k = 0; k < td.typeparam_defaults.size(); ++k )
		dstate += td.typeparam_defaults[k].empty() ? '0' : '1';
	fprintf(stderr, "[ARITY] site=%s tname=%s params=%zu defaults=%s "
		"got=%zu ns=%s owner=%s\n",
		site, tname.c_str(), td.typeparams.size(), dstate.c_str(),
		got, td.defining_namespace.c_str(),
		td.owner_class ? td.owner_class->name.c_str() : "-");
}

TokenDataType *Program::instantiate_opaque_template_use(Program::TemplateDef &td,
						      const std::string &tname,
						      TokenBase *tb)
{
    InstTimer _it(*this, _inst_opaque_count);	// --show-stats
    nextToken(); // consume '<'
    expand_integer_pack_template_args();
    std::vector<std::string> args;
    std::vector<std::vector<TokenBase *> > raw_arg_tokens;
    size_t pack_index = first_template_pack_index(td.typeparam_is_pack);
    if ( peekToken() && (peekToken()->id() == TokenID::tkGT
      || peekToken()->id() == TokenID::tkBSR) )
    {
	TokenBase *close = nextToken();
	if ( !consume_template_close(close) )
	    Throw(close) << "Expecting '>' in " << tname << "<...>" << flush;
    }
    else
    {
	for (;;)
	{
	    TokenBase *at = nextToken();
	    std::string spelling;
	    std::vector<TokenBase *> arg_tokens;
	    TokenBase *sep = collect_template_argument_spelling(at, spelling,
								&arg_tokens);
	    // Substitution-time non-type fold, PARENTHESIZED-EXPRESSION form
	    // only: a substituted value-pack alias target arrives spelled
	    // `(0 + 0)` (the replicate arm's `(_Values + _Sp)...` with both
	    // sides now literal) and must key as `0` — `__tuple_indices<(0 +
	    // 0)>` and `__tuple_indices<0>` are ONE type ([temp.type]). The
	    // fold is deliberately NARROWER than the real lane's: a bare
	    // spelling (`true`, `__v`, `sizeof(_Tp)`) keeps its raw form
	    // because the opaque lane's partial-spec selection compares
	    // SPELLINGS — folding `true` to `1` broke every
	    // `selector<_Tp, true>`-shaped match (libstdc++
	    // __make_unsigned_selector, the rb102 default-lane regression).
	    if ( !spelling.empty() && spelling[0] == '('
	      && pack_index < td.typeparams.size()
	      && args.size() >= pack_index
	      && pack_index < td.typeparam_is_type.size()
	      && !td.typeparam_is_type[pack_index] )
	    {
		int64_t folded_nt = 0;
		if ( fold_nontype_arg_constant(arg_tokens, folded_nt) )
		{
		    arg_tokens.clear();
		    arg_tokens.push_back(new TokenInt(folded_nt));
		    spelling = std::to_string(folded_nt);
		}
	    }
	    args.push_back(spelling);
	    raw_arg_tokens.push_back(arg_tokens);
	    if ( sep->id() == TokenID::tkComma )
		continue;
	    if ( consume_template_close(sep) )
		break;
	    Throw(sep) << "Expecting ',' or '>' in " << tname << "<...>" << flush;
	}
    }
    bool has_pack = pack_index < td.typeparams.size();
    if ( !has_pack && args.size() > td.typeparams.size() )
    {
	arity_probe("opq-over", tname, td, args.size());
	Throw(tb) << tname << "<> expects " << td.typeparams.size()
		      << " argument(s), got " << args.size() << flush;
    }
    size_t required_args = has_pack ? pack_index : td.typeparams.size();
    while ( args.size() < required_args )
    {
	size_t ai = args.size();
	if ( ai >= td.typeparam_defaults.size()
	  || td.typeparam_defaults[ai].empty() )
	{
	    arity_probe("opq-fill", tname, td, args.size());
	    Throw(tb) << tname << "<> expects " << td.typeparams.size()
			  << " argument(s), got " << args.size() << flush;
	}
	std::string spelling;
	std::vector<TokenBase *> arg_tokens;
	for ( TokenBase *dt : td.typeparam_defaults[ai] )
	{
	    spelling += template_token_fragment(dt);
	    arg_tokens.push_back(dt ? dt->clone() : NULL);
	}
	args.push_back(spelling);
	raw_arg_tokens.push_back(arg_tokens);
    }

    // Key an empty variadic instantiation (`tuple<>`) under the SAME bare name the
    // real-instantiation path (instantiate_template_use, via
    // template_instantiation_key_head) uses — NOT a `__empty_pack`-suffixed variant.
    // A distinct suffix split one logical type `tuple<>` into two structs (`tuple`
    // vs `tuple__empty_pack`), so the pair piecewise ctor's deduced empty value-tuple
    // param did not match the call's `tuple<>` argument — map<int,int> sub-wall B's
    // third identity mismatch. With the same key, datatype_map.find reuses one type.
    std::string mangled = tname;
    std::string canon;
    if ( td.owner_class )
    {
	canon = td.owner_class->canonical_cpp_spelling().empty()
	      ? td.owner_class->name : td.owner_class->canonical_cpp_spelling();
	canon += "::";
    }
    else if ( !td.defining_namespace.empty() )
	canon = td.defining_namespace + "::";
    canon += tname + "<";
    for ( size_t i = 0; i < args.size(); ++i )
    {
	mangled += "_" + canonical_arg_key_fragment(raw_arg_tokens[i], args[i]);
	if ( i )
	    canon += ",";
	canon += args[i];
    }
    canon += ">";


    if ( !class_pattern_capture_in_progress
      && opaque_template_args_select_concrete_partial_spec(*this, td, tname,
	    args, raw_arg_tokens) )
    {
	std::vector<TokenBase *> replay;
	replay.push_back(new TokenLT());
	for ( size_t i = 0; i < raw_arg_tokens.size(); ++i )
	{
	    if ( i )
		replay.push_back(new TokenComma());
	    for ( TokenBase *t : raw_arg_tokens[i] )
		replay.push_back(t ? t->clone() : NULL);
	}
	replay.push_back(new TokenGT());
	for ( std::vector<TokenBase *>::reverse_iterator it = replay.rbegin();
	      it != replay.rend(); ++it )
	    pushToken(*it);

	bool saved_vri = allow_variadic_real_inst;
	allow_variadic_real_inst = true;
	TokenDataType *real = instantiate_template_use(tname, tb,
	    td.defining_namespace, td.owner_class);
	allow_variadic_real_inst = saved_vri;
	if ( real )
	    return real;
    }

    flat_datatype_map_iter have = datatype_map.find(mangled);
    // Env-gated probe (MADC_CLASS_PATTERN_PROBE=<substr>): during a capture
    // parse every nested template-id lands here — show what the capture's
    // dependent surface actually resolves to (cached shell w/ members vs a
    // fresh memberless placeholder). cout: capture mutes cerr.
    {
	static const char *cpp_probe = ::getenv("MADC_CLASS_PATTERN_PROBE");
	if ( cpp_probe && *cpp_probe && class_pattern_capture_in_progress
	  && (tname.find(cpp_probe) != std::string::npos
	       || !strcmp(cpp_probe, "*")) )
	{
	    DataDefSTRUCT *sdd = have != datatype_map.end()
		? dynamic_cast<DataDefSTRUCT *>(&(*have)->definition) : NULL;
	    std::cout << "[class-pattern-probe] capture-opaque: " << mangled
		<< (have != datatype_map.end() ? " HIT" : " MISS-mint")
		<< (sdd ? " members=" : "")
		<< (sdd ? std::to_string(sdd->members.size()) : std::string())
		<< std::endl;
	}
    }
    if ( have != datatype_map.end() )
	return use_site_type_token((TokenDataType *)(*have), tb);

    DataDefCLASS *fwd = new DataDefCLASS(mangled, 0, DataType::dtRESERVED);
    fwd->is_dependent_placeholder = true;
    stamp_opaque_mint_context(fwd);
    fwd->set_canonical_spelling(canon);
    struct_map.set(mangled, fwd);
    // Keep the template-origin STRUCTURE (name + per-arg token runs) so tsubst
    // can rebuild the concrete instantiation from a binding later — the shell's
    // name/spelling alone is unresolvable (see Program::DependentShellOrigin).
    {
	DependentShellOrigin &org = dependent_shell_origin[fwd];
	org.tname = tname;
	org.registry_name_id = td.registry_name_id;
	org.defining_namespace = td.defining_namespace;
	org.owner_class = td.owner_class;
	org.arg_spellings = args;
	org.raw_arg_tokens.resize(raw_arg_tokens.size());
	for ( size_t ai = 0; ai < raw_arg_tokens.size(); ++ai )
	    for ( TokenBase *t : raw_arg_tokens[ai] )
		org.raw_arg_tokens[ai].push_back(t ? t->clone() : NULL);
    }
    TokenDataType *tdt = new TokenDataType(mangled.c_str(), *fwd);
    datatype_map[mangled] = tdt;
    if ( !td.defining_namespace.empty() )
	namespace_datatype_map[td.defining_namespace][mangled] = tdt;
    return use_site_type_token(tdt, tb);
}

TokenDataType *Program::instantiate_shell_origin_replay(
			const DependentShellOrigin &org,
			const std::vector<std::vector<TokenBase *> > &arg_runs)
{
    // The partial-spec replay shape (opaque_template_args_select_concrete_
    // partial_spec above): push `< run [, run ...] >` then re-enter
    // instantiate_template_use. Args here are already CONCRETE, so the
    // variadic real-instantiation gate must be open (a `tuple<int>` use
    // real-instantiates exactly like the member-type-chain path).
    std::vector<TokenBase *> replay;
    replay.push_back(new TokenLT());
    bool first_run = true;
    for ( const std::vector<TokenBase *> &run : arg_runs )
    {
	if ( !first_run )
	    replay.push_back(new TokenComma());
	first_run = false;
	for ( TokenBase *t : run )
	    if ( t )
		replay.push_back(t);
    }
    replay.push_back(new TokenGT());
    size_t replay_base = tokens.size();
    for ( std::vector<TokenBase *>::reverse_iterator it = replay.rbegin();
	  it != replay.rend(); ++it )
	pushToken(*it);

    bool saved_vri = allow_variadic_real_inst;
    bool saved_poisoned = dependent_parse_poisoned;
    allow_variadic_real_inst = true;
    TokenIdent name_tb(org.tname.c_str());
    TokenDataType *real = NULL;
    try
    {
	real = instantiate_template_use(org.tname, &name_tb,
					org.defining_namespace,
					org.owner_class);
    }
    catch ( ... ) { real = NULL; }
    allow_variadic_real_inst = saved_vri;
    // Drain any unconsumed replay tokens so a failure never leaks stray
    // injected tokens into the caller's stream (the capture+replay lesson).
    while ( tokens.size() > replay_base )
	nextToken();
    dependent_parse_poisoned = saved_poisoned;
    return real;
}

static bool is_incomplete_class_datadef(DataDef *dd)
{
    DataDefCLASS *cls = dynamic_cast<DataDefCLASS *>(dd);
    if ( !cls )
	return false;
    if ( cls->is_dependent_placeholder )
	return true;
    // A `{ ... }` body was parsed: the class is COMPLETE even with zero members
    // (a typedef-only trait such as iterator_traits<T> / __are_same<A,B>). Without
    // this, such a fully-instantiated class matches the empty-aggregate heuristic
    // below and is misread as "not yet instantiated", so the cache check in
    // instantiate_template_use re-instantiates it on every reference (measured:
    // iterator_traits<uint32_t> instantiated 6x for an empty <iostream> program).
    if ( cls->is_complete )
	return false;
    return cls->size == 0 && cls->members.empty()
	&& cls->methods.empty() && cls->ctors.empty()
	&& cls->bases.empty();
}

static bool is_incomplete_template_class_type(TokenDataType *tdt)
{
    return tdt && is_incomplete_class_datadef(&tdt->definition);
}

DataDefCLASS *Program::complete_shell_class_type(DataDefCLASS *cls)
{
    if ( !cls || !is_incomplete_class_datadef(cls) )
	return NULL;
    std::map<DataDef *, DependentShellOrigin>::const_iterator oi =
	dependent_shell_origin.find(cls);
    if ( oi == dependent_shell_origin.end()
      || oi->second.raw_arg_tokens.empty() )
	return NULL;
    // SILENT SFINAE discipline (the constraint evaluator's pattern): a replay
    // that cannot re-enter cleanly — a still-dependent shell, a
    // spelling-matched-spec template — must leave no stderr noise and no
    // diagnostic behind, because the caller's opaque path is still valid.
    struct ShellNullBuf : std::streambuf
    { int overflow(int c) { return c; } };
    static ShellNullBuf shell_null_buf;
    size_t sd = diagnostics.size();
    Program::ErrorInfo se = last_error;
    std::streambuf *sc = std::cerr.rdbuf(&shell_null_buf);
    TokenDataType *real = NULL;
    try
    {
	real = instantiate_shell_origin_replay(oi->second,
					       oi->second.raw_arg_tokens);
    }
    catch ( ... ) { real = NULL; }
    std::cerr.rdbuf(sc);
    DataDefCLASS *rc = real
	? dynamic_cast<DataDefCLASS *>(&real->definition) : NULL;
    if ( rc && !is_incomplete_class_datadef(rc) )
	return rc;
    diagnostics.resize(sd);
    last_error = se;
    return NULL;
}

static bool datadef_has_unresolved_dependent_surface(DataDef *dd);

static bool class_has_dependent_base(DataDefCLASS *cls,
				     std::set<DataDefCLASS *> *seen = NULL)
{
    if ( !cls )
	return false;
    std::set<DataDefCLASS *> local_seen;
    if ( !seen )
	seen = &local_seen;
    if ( seen->find(cls) != seen->end() )
	return false;
    seen->insert(cls);
    for ( size_t i = 0; i < cls->bases.size(); ++i )
    {
	DataDefCLASS *base = cls->bases[i].base;
	if ( !base )
	    continue;
	if ( base->is_dependent_placeholder || base->has_dependent_surface
	  || class_has_dependent_base(base, seen) )
	    return true;
    }
    if ( cls->base_class
      && (cls->base_class->is_dependent_placeholder
       || cls->base_class->has_dependent_surface
       || class_has_dependent_base(cls->base_class, seen)) )
	return true;
    return false;
}

static bool class_has_unresolved_dependent_surface(DataDefCLASS *cls)
{
    return cls && (cls->is_dependent_placeholder || cls->has_dependent_surface
	|| class_has_dependent_base(cls));
}

static bool class_allows_opaque_member_type(DataDefCLASS *cls)
{
    if ( class_has_unresolved_dependent_surface(cls) )
	return true;
    return cls && cls->from_system_header
	&& cls->canonical_cpp_spelling().find('<') != std::string::npos;
}

static bool datadef_has_unresolved_dependent_surface(DataDef *dd)
{
    if ( !dd )
	return false;
    if ( dd->is_template_param() )
	return true;
    if ( DataDefCLASS *cls = dynamic_cast<DataDefCLASS *>(dd) )
	return class_has_unresolved_dependent_surface(cls);
    if ( DataDefPTR *ptr = dynamic_cast<DataDefPTR *>(dd) )
	return datadef_has_unresolved_dependent_surface(ptr->base_type);
    if ( DataDefCArray *arr = dynamic_cast<DataDefCArray *>(dd) )
	return datadef_has_unresolved_dependent_surface(arr->element_type);
    return false;
}

// Names WHICH node makes datadef_has_unresolved_dependent_surface() true, so
// a refusal on a spelled-concrete type (a base shell minted opaque mid-flight
// and never re-derived) is diagnosable from the error alone. Walks the same
// chain as the predicate; returns "" when the type has no dependent surface.
static std::string dependent_surface_reason(DataDef *dd,
					    std::set<DataDefCLASS *> *seen = NULL)
{
    if ( !dd )
	return std::string();
    if ( dd->is_template_param() )
	return dd->name + " is a template parameter";
    if ( DataDefPTR *ptr = dynamic_cast<DataDefPTR *>(dd) )
	return dependent_surface_reason(ptr->base_type, seen);
    if ( DataDefCArray *arr = dynamic_cast<DataDefCArray *>(dd) )
	return dependent_surface_reason(arr->element_type, seen);
    DataDefCLASS *cls = dynamic_cast<DataDefCLASS *>(dd);
    if ( !cls )
	return std::string();
    if ( cls->is_dependent_placeholder )
	return cls->name + " is a dependent placeholder";
    if ( cls->has_dependent_surface )
	return cls->name + " carries a dependent surface";
    std::set<DataDefCLASS *> local_seen;
    if ( !seen )
	seen = &local_seen;
    if ( seen->count(cls) )
	return std::string();
    seen->insert(cls);
    for ( size_t i = 0; i < cls->bases.size(); ++i )
    {
	std::string r = dependent_surface_reason(cls->bases[i].base, seen);
	if ( !r.empty() )
	    return cls->name + ": base " + r;
    }
    std::string r = dependent_surface_reason(cls->base_class, seen);
    if ( !r.empty() )
	return cls->name + ": base " + r;
    return std::string();
}

DataDefCLASS *Program::materialize_dependent_member_type(DataDef *owner,
						       const std::string &member_name)
{
    if ( !owner || member_name.empty() )
	return NULL;
    std::string dep_name = owner->name + "__" + sanitize_template_fragment(member_name);
    flat_datatype_map_iter have = datatype_map.find(dep_name);
    if ( have != datatype_map.end() )
	return dynamic_cast<DataDefCLASS *>(&(*have)->definition);

    DataDefCLASS *dep = new DataDefCLASS(dep_name, 0, DataType::dtRESERVED);
    dep->is_dependent_placeholder = true;
    // Record the derivation so tsubst can re-derive the CONCRETE member type
    // under an instance substitution (see DependentDerivedOrigin).
    {
	DependentDerivedOrigin &org = dependent_derived_origin[dep];
	org.source = owner;
	org.kind = DependentDerivedOrigin::MemberType;
	org.member = member_name;
    }
    std::string owner_spelling = owner->canonical_cpp_spelling().empty()
			       ? owner->name : owner->canonical_cpp_spelling();
    dep->set_canonical_spelling(owner_spelling + "::" + member_name);
    // An INCOMPLETE owner with a PENDING lazy completion heals later
    // ([temp.inst] — the pending-record arm): caching this member
    // placeholder under its flat name would OUTLIVE the healing and serve
    // the stale shell to every later resolution (rbA's
    // tuple_element<0,tuple<int&>>::type — the first walk poisoned the
    // cache, the second walk found the healed owner but this stale member;
    // task #103). Mint EPHEMERAL: usable by this resolution, re-derived
    // against the healed owner next time.
    bool ephemeral = false;
    if ( DataDefCLASS *ocls = dynamic_cast<DataDefCLASS *>(owner) )
	ephemeral = is_incomplete_class_datadef(ocls)
		 && has_pending_template_instantiation(ocls->name);
    if ( !ephemeral )
    {
	struct_map.set(dep_name, dep);
	datatype_map[dep_name] = new TokenDataType(dep_name.c_str(), *dep);
    }
    // Env-gated probe (MADC_MTI_PROBE_CLASS=<substr>): every opaque
    // dependent-member synthesis for a matching owner — the laundered-opaque
    // diagnostic (which resolution path lands here, live vs bound).
    {
	static const char *mtp = ::getenv("MADC_MTI_PROBE_CLASS");
	if ( mtp && *mtp && dep_name.find(mtp) != std::string::npos )
	    fprintf(stderr, "MTIPROBE opaque-member owner=%s member=%s in=%s"
		    " canon=%s from=%p\n", owner->name.c_str(),
		    member_name.c_str(), cur_func_name.c_str(),
		    instantiating_canonical_spelling.c_str(),
		    __builtin_return_address(0));
    }
    return dep;
}

DataDefCLASS *Program::materialize_opaque_class_type(const std::string &name,
						   const std::string &canonical)
{
    if ( name.empty() )
	return NULL;
    flat_datatype_map_iter have = datatype_map.find(name);
    if ( have != datatype_map.end() )
	return dynamic_cast<DataDefCLASS *>(&(*have)->definition);

    DataDefCLASS *dep = new DataDefCLASS(name, 0, DataType::dtRESERVED);
    dep->is_dependent_placeholder = true;
    stamp_opaque_mint_context(dep);
    dep->set_canonical_spelling(canonical.empty() ? name : canonical);
    struct_map.set(name, dep);
    datatype_map[name] = new TokenDataType(name.c_str(), *dep);
    return dep;
}

void Program::stamp_opaque_mint_context(DataDefCLASS *dep)
{
    dep->opaque_concrete_tag = !dependent_parse_in_progress;
    // Env-gated probe (MADC_MTI_PROBE_CLASS=<substr>): every opaque class
    // mint with its context — the concrete-tag discriminator diagnostic.
    static const char *mtp = ::getenv("MADC_MTI_PROBE_CLASS");
    if ( mtp && *mtp && dep->name.find(mtp) != std::string::npos )
	fprintf(stderr, "MTIPROBE opaque-mint name=%s dep_parse=%d concrete=%d"
		" from=%p\n", dep->name.c_str(),
		(int)dependent_parse_in_progress,
		(int)dep->opaque_concrete_tag, __builtin_return_address(0));
}

DataDef *Program::dependent_deref_result_type(DataDef *dd)
{
    if ( !dd )
	return NULL;
    if ( DataDefPTR *ptr = dynamic_cast<DataDefPTR *>(dd) )
	return ptr->base_type ? ptr->base_type : &ddINT64;
    if ( !datadef_has_unresolved_dependent_surface(dd) )
	return NULL;
    std::string spelling = dd->canonical_cpp_spelling().empty()
			 ? dd->name : dd->canonical_cpp_spelling();
    DataDefCLASS *dep = materialize_opaque_class_type(
	sanitize_template_fragment(dd->name + "__deref"), "*" + spelling);
    // Record the derivation so tsubst can re-derive the CONCRETE deref type
    // under an instance substitution (see DependentDerivedOrigin).
    if ( dep && dep->is_dependent_placeholder
      && !dependent_derived_origin.count(dep) )
    {
	DependentDerivedOrigin &org = dependent_derived_origin[dep];
	org.source = dd;
	org.kind = DependentDerivedOrigin::Deref;
    }
    return dep;
}

static void record_pending_template_instantiation(
	Program &pgm, const std::string &tname, const std::string &mangled,
	const std::string &canon, const std::vector<TokenDataType *> &args)
{
    std::vector<Program::PendingTemplateInstantiation> &pending =
	pgm.pending_template_instantiations[tname];
    for ( size_t i = 0; i < pending.size(); ++i )
	if ( pending[i].mangled_name == mangled )
	    return;

    Program::PendingTemplateInstantiation pti;
    pti.mangled_name = mangled;
    pti.canonical_spelling = canon;
    for ( size_t i = 0; i < args.size(); ++i )
	pti.args.push_back((TokenDataType *)args[i]->clone());
    pending.push_back(pti);
}

TokenDataType *Program::instantiate_template_id(const std::string &tname,
					       TokenBase *tb,
					       const std::string &ns_hint,
					       DataDefCLASS *owner_hint)
{
    if ( TokenDataType *alias_inst =
	    instantiate_template_alias_use(tname, tb, ns_hint, owner_hint) )
	return alias_inst;
    return instantiate_template_use(tname, tb, ns_hint, owner_hint);
}

static void register_skipped_class_template_function(
	Program &pgm, DataDefCLASS *owner, const std::vector<TokenBase *> &tokens,
	const std::vector<std::string> &typeparams,
	uint32_t access_flags, const std::string &ctor_source_name);

namespace {
struct BasicClassPatternBinding
{
    const Program::TemplateDef &definition;
    const Program::ClassPattern &pattern;
    const std::map<std::string, TokenDataType *> &type_subst;
    const std::vector<TokenDataType *> &arg_types_by_slot;
    const std::vector<std::vector<TokenBase *> > &arg_tokens_by_slot;
    std::string local_name;
    std::string registered_name;
    std::string canonical_spelling;
    bool dependent_surface;
    TokenBase *location;
};

static std::string basic_class_datadef_spelling(DataDef *dd)
{
    if ( !dd )
	return std::string();
    if ( DataDefCONST *qualified = dynamic_cast<DataDefCONST *>(dd) )
    {
	std::string operand = basic_class_datadef_spelling(qualified->base_type);
	if ( dynamic_cast<DataDefPTR *>(qualified->base_type) )
	    return operand + " const";
	return "const " + operand;
    }
    if ( DataDefREF *ref = dynamic_cast<DataDefREF *>(dd) )
	return basic_class_datadef_spelling(ref->base_type) + "&";
    if ( DataDefPTR *ptr = dynamic_cast<DataDefPTR *>(dd) )
	return basic_class_datadef_spelling(ptr->base_type) + "*";
    if ( DataDefCArray *array = dynamic_cast<DataDefCArray *>(dd) )
	return basic_class_datadef_spelling(array->element_type) + "["
	     + std::to_string(array->count) + "]";
    return dd->canonical_cpp_spelling().empty()
	? dd->name : dd->canonical_cpp_spelling();
}

static std::string basic_class_pattern_type_spelling(
	Program &pgm, const BasicClassPatternBinding &binding,
	Program::ClassTypePatternId id, bool concrete,
	std::vector<bool> &active)
{
    if ( !id || id >= binding.pattern.types.size() || active[id] )
	return std::string();
    active[id] = true;
    const Program::ClassTypePattern &type = binding.pattern.types[id];
    std::string spelling;
    switch ( type.kind )
    {
    case Program::ClassTypePatternKind::ConcreteType:
	spelling = basic_class_datadef_spelling(
	    pgm.type_from_id(type.concrete_type_id));
	break;
    case Program::ClassTypePatternKind::TemplateParam:
	if ( type.template_param_index < binding.definition.typeparams.size() )
	{
	    const std::string &name =
		binding.definition.typeparams[type.template_param_index];
	    if ( concrete )
	    {
		std::map<std::string, TokenDataType *>::const_iterator found =
		    binding.type_subst.find(name);
		if ( found != binding.type_subst.end() && found->second )
		    spelling = template_type_arg_spelling(found->second, "");
	    }
	    else
		spelling = name;
	}
	break;
    case Program::ClassTypePatternKind::SelfType:
	spelling = concrete ? binding.canonical_spelling
	    : (binding.pattern.nodes.empty() ? std::string()
	       : binding.pattern.nodes[0].canonical_spelling);
	break;
    case Program::ClassTypePatternKind::Pointer:
    case Program::ClassTypePatternKind::Reference:
    case Program::ClassTypePatternKind::ConstType:
    case Program::ClassTypePatternKind::CArray:
	spelling = basic_class_pattern_type_spelling(
	    pgm, binding, type.operand, concrete, active);
	if ( !spelling.empty() )
	{
	    if ( type.kind == Program::ClassTypePatternKind::Pointer )
		spelling += "*";
	    else if ( type.kind == Program::ClassTypePatternKind::Reference )
		spelling += "&";
	    else if ( type.kind == Program::ClassTypePatternKind::ConstType )
	    {
		const Program::ClassTypePattern &operand =
		    binding.pattern.types[type.operand];
		if ( operand.kind == Program::ClassTypePatternKind::Pointer )
		    spelling += " const";
		else
		    spelling = "const " + spelling;
	    }
	    else
		for ( size_t i = 0; i < type.dimensions.size(); ++i )
		    spelling += "[" + std::to_string(type.dimensions[i]) + "]";
	}
	break;
    case Program::ClassTypePatternKind::NestedType:
	if ( type.nested_node_id < binding.pattern.nodes.size() )
	{
	    const Program::ClassAggregatePatternNode &node =
		binding.pattern.nodes[type.nested_node_id];
	    if ( concrete )
	    {
		std::vector<std::string> names;
		uint32_t current = type.nested_node_id;
		while ( current && current < binding.pattern.nodes.size() )
		{
		    const Program::ClassAggregatePatternNode &part =
			binding.pattern.nodes[current];
		    names.push_back(part.source_name);
		    current = part.parent_id;
		}
		spelling = binding.canonical_spelling;
		for ( size_t i = names.size(); i-- > 0; )
		    spelling += "::" + names[i];
	    }
	    else
		spelling = node.canonical_spelling.empty()
		    ? node.source_name : node.canonical_spelling;
	}
	break;
    case Program::ClassTypePatternKind::TemplateId:
	spelling = type.name + "<";
	for ( size_t i = 0; i < type.arguments.size(); ++i )
	{
	    if ( i )
		spelling += ",";
	    spelling += basic_class_pattern_type_spelling(
		pgm, binding, type.arguments[i], concrete, active);
	}
	spelling += ">";
	break;
    case Program::ClassTypePatternKind::DependentMember:
	spelling = basic_class_pattern_type_spelling(
	    pgm, binding, type.operand, concrete, active);
	if ( !spelling.empty() )
	{
	    spelling += "::" + type.name;
	    if ( type.flags & 1u )
	    {
		spelling += "<";
		for ( size_t i = 0; i < type.arguments.size(); ++i )
		{
		    if ( i )
			spelling += ",";
		    spelling += basic_class_pattern_type_spelling(
			pgm, binding, type.arguments[i], concrete, active);
		}
		spelling += ">";
	    }
	}
	break;
    case Program::ClassTypePatternKind::FunctionPointer:
    case Program::ClassTypePatternKind::PackExpansion:
	break;
    }
    active[id] = false;
    return spelling;
}

static bool basic_class_pattern_type_is_dependent(
	const Program::ClassPattern &pattern,
	Program::ClassTypePatternId id, std::vector<bool> &active)
{
    if ( !id || id >= pattern.types.size() || active[id] )
	return true;
    active[id] = true;
    const Program::ClassTypePattern &type = pattern.types[id];
    bool dependent = false;
    switch ( type.kind )
    {
    case Program::ClassTypePatternKind::ConcreteType:
	break;
    case Program::ClassTypePatternKind::TemplateParam:
    case Program::ClassTypePatternKind::SelfType:
    case Program::ClassTypePatternKind::NestedType:
    case Program::ClassTypePatternKind::DependentMember:
    case Program::ClassTypePatternKind::FunctionPointer:
    case Program::ClassTypePatternKind::PackExpansion:
	dependent = true;
	break;
    case Program::ClassTypePatternKind::Pointer:
    case Program::ClassTypePatternKind::Reference:
    case Program::ClassTypePatternKind::ConstType:
    case Program::ClassTypePatternKind::CArray:
	dependent = basic_class_pattern_type_is_dependent(
	    pattern, type.operand, active);
	break;
    case Program::ClassTypePatternKind::TemplateId:
	for ( size_t i = 0; i < type.arguments.size() && !dependent; ++i )
	    dependent = basic_class_pattern_type_is_dependent(
		pattern, type.arguments[i], active);
	break;
    }
    active[id] = false;
    return dependent;
}

static std::string basic_class_pattern_rebind_root_constructor_name(
	const BasicClassPatternBinding &binding, DataDefCLASS *owner,
	Program::ClassMethodKind kind, const std::string &name)
{
    if ( kind != Program::ClassMethodKind::Constructor || !owner
	|| owner->name != binding.registered_name )
	return name;
    const std::string &source = binding.definition.class_name;
    if ( name.compare(0, source.size(), source) != 0 )
	return name;
    return binding.local_name + name.substr(source.size());
}

static std::string basic_class_compact_spelling(const std::string &spelling)
{
    std::string compact;
    compact.reserve(spelling.size());
    for ( size_t i = 0; i < spelling.size(); ++i )
	if ( !isspace((unsigned char)spelling[i]) )
	    compact += spelling[i];
    return compact;
}

static Program::ClassParseReason class_pattern_eligibility_note(
	const BasicClassPatternBinding &binding,
	Program::ClassParseReason reason, int line)
{
    static const char *cpp_probe = ::getenv("MADC_CLASS_PATTERN_PROBE");
    if ( cpp_probe && reason != Program::ClassParseReason::None
      && (binding.definition.class_name.find(cpp_probe) != std::string::npos
	   || !strcmp(cpp_probe, "*")) )
	std::cerr << "[class-pattern-probe] eligibility REJECT "
	    << binding.definition.class_name << " reason=" << (unsigned)reason
	    << " site=parser.cpp:" << line << std::endl;
    return reason;
}

// True when the friend declaration starting at body[i] (a tkFRIEND token)
// needs the parse lane: a hidden-friend operator DEFINITION (body braces —
// hoisted to namespace scope at parse) or a DEFAULTED comparison (member-list
// synthesis at parse). Bodyless declarations — friend classes, named function
// declarations, `= delete` — are name-grant bookkeeping the serve replays
// verbatim from the pattern's friend name lists.
static bool class_body_friend_needs_parse(
	const std::vector<TokenBase *> &body, size_t i)
{
    DelimDepth d;
    for ( size_t j = i + 1; j < body.size(); ++j )
    {
	TokenBase *t = body[j];
	if ( !t )
	    continue;
	if ( t->id() == TokenID::tkOpBrk || t->id() == TokenID::tkClBrk )
	{
	    d.update(t);
	    continue;
	}
	if ( !d.paren )
	{
	    if ( t->id() == TokenID::tkOpBrc )
		return true;	// definition body
	    if ( t->id() == TokenID::tkSemi )
		return false;	// declaration only
	    if ( t->id() == TokenID::tkAssign )
	    {
		for ( size_t k = j + 1; k < body.size(); ++k )
		    if ( body[k] )
			return body[k]->id() == TokenID::tkDEFAULT;
		return true;
	    }
	}
    }
    return true;	// unterminated — needs the parse lane
}


static Program::ClassParseReason basic_class_pattern_eligibility(
	Program &pgm, const BasicClassPatternBinding &binding,
	const std::map<std::string, std::vector<TokenBase *> > &token_subst,
	const std::map<std::string, std::vector<TokenDataType *> > &pack_subst)
{
    typedef Program::ClassParseReason Reason;
    if ( binding.definition.class_pattern_reason != Reason::None )
	return binding.definition.class_pattern_reason;
    if ( binding.pattern.capture_reason != Reason::None )
	return binding.pattern.capture_reason;
    if ( binding.dependent_surface )
	return class_pattern_eligibility_note(binding, Reason::UnnormalizableType, __builtin_LINE());
    if ( binding.definition.has_non_type_params || !token_subst.empty() )
	return class_pattern_eligibility_note(binding, Reason::DependentValueExpression, __builtin_LINE());
    if ( !pack_subst.empty() )
	return class_pattern_eligibility_note(binding, Reason::UnsupportedDeclKind, __builtin_LINE());
    for ( size_t i = 0; i < binding.definition.typeparams.size(); ++i )
    {
	if ( i < binding.definition.typeparam_is_type.size()
	  && !binding.definition.typeparam_is_type[i] )
	    return class_pattern_eligibility_note(binding, Reason::DependentValueExpression, __builtin_LINE());
	if ( i < binding.definition.typeparam_is_pack.size()
	  && binding.definition.typeparam_is_pack[i] )
	    return class_pattern_eligibility_note(binding, Reason::UnsupportedDeclKind, __builtin_LINE());
    }
    if ( binding.pattern.nodes.empty() )
	return class_pattern_eligibility_note(binding, Reason::UnsupportedDeclKind, __builtin_LINE());
    if ( binding.pattern.nodes[0].kind != Program::ClassAggregateKind::Class
      && binding.pattern.nodes[0].kind != Program::ClassAggregateKind::Struct )
	return class_pattern_eligibility_note(binding, Reason::UnsupportedDeclKind, __builtin_LINE());

    // Friend DECLARATIONS are name-grant bookkeeping the serve replays
    // verbatim; only a hidden-friend DEFINITION or a defaulted comparison
    // still needs the parse lane. The pattern's name lists cannot distinguish
    // the two, so classify from the definition's own tokens; a token-less
    // definition with friend lists stays rejected — it cannot be verified.
    bool friend_bodies_checked = !binding.definition.body.empty();
    for ( size_t t = 0; friend_bodies_checked
			 && t < binding.definition.body.size(); ++t )
	if ( binding.definition.body[t]
	  && binding.definition.body[t]->id() == TokenID::tkFRIEND
	  && class_body_friend_needs_parse(binding.definition.body, t) )
	    return class_pattern_eligibility_note(binding, Reason::UnsupportedFriendDefinition, __builtin_LINE());

    for ( size_t i = 0; i < binding.pattern.nodes.size(); ++i )
    {
	const Program::ClassAggregatePatternNode &node = binding.pattern.nodes[i];
	if ( node.local_id != i || (i == 0 && node.parent_id != 0)
	  || (i > 0 && (node.parent_id >= i || node.source_name.empty())) )
	    return class_pattern_eligibility_note(binding, Reason::UnsupportedNestedDefinition, __builtin_LINE());
	if ( node.kind == Program::ClassAggregateKind::Enum )
	    return class_pattern_eligibility_note(binding, Reason::UnsupportedNestedDefinition, __builtin_LINE());
	if ( !node.static_members.empty() || !node.static_values.empty() )
	    return class_pattern_eligibility_note(binding, Reason::UnsupportedDeclKind, __builtin_LINE());
	if ( !friend_bodies_checked
	  && (!node.friend_functions.empty() || !node.friend_classes.empty()) )
	    return class_pattern_eligibility_note(binding, Reason::UnsupportedFriendDefinition, __builtin_LINE());
	for ( size_t b = 0; b < node.bases.size(); ++b )
	    if ( !node.bases[b].type
	      || node.bases[b].type >= binding.pattern.types.size()
	      || node.bases[b].is_virtual )
		return class_pattern_eligibility_note(binding, Reason::UnsupportedDeclKind, __builtin_LINE());
	for ( size_t t = 0; t < node.nested_templates.size(); ++t )
	{
	    const Program::ClassNestedTemplatePattern &nested =
		node.nested_templates[t];
	    if ( nested.class_name.empty() || nested.is_partial_specialization )
		return class_pattern_eligibility_note(binding, Reason::UnsupportedDeclKind, __builtin_LINE());
	    if ( nested.typeparams.size() != nested.typeparam_is_type.size()
	      || nested.typeparams.size() != nested.typeparam_is_pack.size() )
		return class_pattern_eligibility_note(binding, Reason::UnsupportedDeclKind, __builtin_LINE());
	}
    }

    for ( size_t i = 1; i < binding.pattern.types.size(); ++i )
    {
	const Program::ClassTypePattern &type = binding.pattern.types[i];
	switch ( type.kind )
	{
	case Program::ClassTypePatternKind::ConcreteType:
	    if ( !type.concrete_type_id
	      || !pgm.type_from_id(type.concrete_type_id)
	      || datadef_has_unresolved_dependent_surface(
		  pgm.type_from_id(type.concrete_type_id)) )
	    {
		static const char *cpp_probe =
		    ::getenv("MADC_CLASS_PATTERN_PROBE");
		if ( cpp_probe
		  && (binding.definition.class_name.find(cpp_probe)
			!= std::string::npos || !strcmp(cpp_probe, "*")) )
		    std::cerr << "[class-pattern-probe]   concrete type[" << i
			<< "] name='" << type.name
			<< "' id=" << type.concrete_type_id
			<< " resolved=" << (type.concrete_type_id
			    && pgm.type_from_id(type.concrete_type_id) ? 1 : 0)
			<< std::endl;
		return class_pattern_eligibility_note(binding, Reason::UnnormalizableType, __builtin_LINE());
	    }
	    break;
	case Program::ClassTypePatternKind::TemplateParam:
	    if ( type.template_param_index >=
		 binding.definition.typeparams.size() )
		return class_pattern_eligibility_note(binding, Reason::UnnormalizableType, __builtin_LINE());
	    {
		const std::string &name = binding.definition.typeparams[
		    type.template_param_index];
		std::map<std::string, TokenDataType *>::const_iterator found =
		    binding.type_subst.find(name);
		if ( found == binding.type_subst.end() || !found->second
		  || datadef_has_unresolved_dependent_surface(
		      &found->second->definition) )
		    return class_pattern_eligibility_note(binding, Reason::UnnormalizableType, __builtin_LINE());
	    }
	    break;
	case Program::ClassTypePatternKind::SelfType:
	    break;
	case Program::ClassTypePatternKind::Pointer:
	case Program::ClassTypePatternKind::Reference:
	case Program::ClassTypePatternKind::ConstType:
	    if ( !type.operand || type.operand >= binding.pattern.types.size() )
		return class_pattern_eligibility_note(binding, Reason::UnnormalizableType, __builtin_LINE());
	    break;
	case Program::ClassTypePatternKind::CArray:
	    if ( !type.operand || type.operand >= binding.pattern.types.size()
	      || type.dimensions.empty() )
		return class_pattern_eligibility_note(binding, Reason::UnnormalizableType, __builtin_LINE());
	    for ( size_t d = 0; d < type.dimensions.size(); ++d )
		if ( !type.dimensions[d] || type.dimensions[d] > SIZE_MAX )
		    return class_pattern_eligibility_note(binding, Reason::DependentValueExpression, __builtin_LINE());
	    break;
	case Program::ClassTypePatternKind::NestedType:
	    if ( !type.nested_node_id
	      || type.nested_node_id >= binding.pattern.nodes.size() )
		return class_pattern_eligibility_note(binding, Reason::UnsupportedNestedDefinition, __builtin_LINE());
	    break;
	case Program::ClassTypePatternKind::TemplateId:
	    if ( type.name.empty() )
		return class_pattern_eligibility_note(binding, Reason::UnnormalizableType, __builtin_LINE());
	    for ( size_t c = 0; c < type.name.size(); ++c )
		if ( !isalnum((unsigned char)type.name[c])
		  && type.name[c] != '_' && type.name[c] != ':' )
		    return class_pattern_eligibility_note(binding, Reason::DependentValueExpression, __builtin_LINE());
	    for ( size_t a = 0; a < type.arguments.size(); ++a )
		if ( !type.arguments[a]
		  || type.arguments[a] >= binding.pattern.types.size() )
		    return class_pattern_eligibility_note(binding, Reason::UnnormalizableType, __builtin_LINE());
	    break;
	case Program::ClassTypePatternKind::DependentMember:
	    if ( !type.operand || type.operand >= binding.pattern.types.size()
	      || type.name.empty() || (type.flags & ~1u) )
		return class_pattern_eligibility_note(binding, Reason::UnnormalizableType, __builtin_LINE());
	    if ( !(type.flags & 1u) && !type.arguments.empty() )
		return class_pattern_eligibility_note(binding, Reason::UnnormalizableType, __builtin_LINE());
	    for ( size_t a = 0; a < type.arguments.size(); ++a )
		if ( !type.arguments[a]
		  || type.arguments[a] >= binding.pattern.types.size() )
		    return class_pattern_eligibility_note(binding, Reason::UnnormalizableType, __builtin_LINE());
	    break;
	case Program::ClassTypePatternKind::FunctionPointer:
	case Program::ClassTypePatternKind::PackExpansion:
	    return class_pattern_eligibility_note(binding, Reason::UnsupportedDeclKind, __builtin_LINE());
	}
    }

    for ( size_t n = 0; n < binding.pattern.nodes.size(); ++n )
    {
	const Program::ClassAggregatePatternNode &node = binding.pattern.nodes[n];
	for ( size_t i = 0; i < node.declarations.size(); ++i )
	{
	    switch ( node.declarations[i] )
	    {
	    case Program::ClassDeclKind::TypeAlias:
	    case Program::ClassDeclKind::NestedAggregate:
	    case Program::ClassDeclKind::NestedForward:
	    case Program::ClassDeclKind::DataMember:
	    case Program::ClassDeclKind::Method:
	    case Program::ClassDeclKind::MemberTemplate:
	    case Program::ClassDeclKind::UsingBaseMember:
	    case Program::ClassDeclKind::StaticAssert:
		break;
	    case Program::ClassDeclKind::NestedEnum:
		return class_pattern_eligibility_note(binding, Reason::UnsupportedNestedDefinition, __builtin_LINE());
	    case Program::ClassDeclKind::FriendType:
	    case Program::ClassDeclKind::FriendFunction:
		// The token scan above proved every friend run is a bodyless
		// declaration (name grant, replayed verbatim). Without tokens
		// the kinds alone cannot rule out a hidden-friend definition.
		if ( !friend_bodies_checked )
		    return class_pattern_eligibility_note(binding, Reason::UnsupportedFriendDefinition, __builtin_LINE());
		break;
	    case Program::ClassDeclKind::DefaultedComparison:
		return class_pattern_eligibility_note(binding, Reason::UnsupportedDefaultedComparison, __builtin_LINE());
	    case Program::ClassDeclKind::BitField:
	    case Program::ClassDeclKind::AnonymousAggregate:
	    case Program::ClassDeclKind::StaticDataMember:
		return class_pattern_eligibility_note(binding, Reason::UnsupportedDeclKind, __builtin_LINE());
	    }
	}
	for ( size_t i = 0; i < node.aliases.size(); ++i )
	    if ( node.aliases[i].name.empty() || !node.aliases[i].type
	      || node.aliases[i].type >= binding.pattern.types.size() )
		return class_pattern_eligibility_note(binding, Reason::UnnormalizableType, __builtin_LINE());
	for ( size_t i = 0; i < node.members.size(); ++i )
	{
	    const Program::ClassMemberPattern &member = node.members[i];
	    if ( !member.type || member.type >= binding.pattern.types.size() )
		return class_pattern_eligibility_note(binding, Reason::UnnormalizableType, __builtin_LINE());
	    if ( member.is_bitfield || member.is_anonymous )
		return class_pattern_eligibility_note(binding, Reason::UnsupportedDeclKind, __builtin_LINE());
	    if ( member.is_array )
	    {
		if ( member.dimensions.empty() || !member.count
		  || member.count > SIZE_MAX )
		    return class_pattern_eligibility_note(binding, Reason::DependentValueExpression, __builtin_LINE());
		uint64_t folded = 1;
		for ( size_t d = 0; d < member.dimensions.size(); ++d )
		{
		    uint64_t dim = member.dimensions[d];
		    if ( !dim || folded > UINT64_MAX / dim )
			return class_pattern_eligibility_note(binding, Reason::DependentValueExpression, __builtin_LINE());
		    folded *= dim;
		}
		if ( folded != member.count )
		    return class_pattern_eligibility_note(binding, Reason::DependentValueExpression, __builtin_LINE());
	    }
	    else if ( member.count != 1 || !member.dimensions.empty() )
		return class_pattern_eligibility_note(binding, Reason::UnsupportedDeclKind, __builtin_LINE());
	}

	for ( size_t i = 0; i < node.methods.size(); ++i )
	{
	    const Program::ClassMethodPattern &method = node.methods[i];
	    if ( method.display_name.empty() || method.variable_name.empty()
	      || method.has_eager_body || method.pure_virtual
	      || !method.return_type
	      || method.return_type >= binding.pattern.types.size()
	      || (method.flags & ~(vfSTATIC | vfPRIVATE | vfPROTECTED)) )
		return class_pattern_eligibility_note(binding, Reason::UnsupportedDeclKind, __builtin_LINE());
	    if ( !method.declaration_only && !method.defaulted_or_deleted
	      && method.body_tokens.empty() && method.definition_tokens.empty()
	      && !method.is_member_template )
		return class_pattern_eligibility_note(binding, Reason::RequiresEagerBodyParse, __builtin_LINE());
	    TokenBase *body_origin = NULL;
	    const std::vector<TokenBase *> *body_runs[2] = {
		&method.body_tokens, &method.definition_tokens
	    };
	    for ( size_t r = 0; r < 2 && !body_origin; ++r )
		for ( size_t t = 0; t < body_runs[r]->size(); ++t )
		    if ( (*body_runs[r])[t] )
		    {
			body_origin = (*body_runs[r])[t];
			break;
		    }
	    if ( body_origin
	      && (!body_origin->file
		  || !pgm.is_system_header_path(body_origin->file)) )
	    {
		static const char *cpp_probe = ::getenv("MADC_CLASS_PATTERN_PROBE");
		if ( cpp_probe && (binding.definition.class_name.find(cpp_probe)
					!= std::string::npos
				    || !strcmp(cpp_probe, "*")) )
		    std::cerr << "[class-pattern-probe]   eager-body method '"
			<< method.display_name << "' body file="
			<< (body_origin->file ? body_origin->file : "(null)")
			<< std::endl;
		return class_pattern_eligibility_note(binding, Reason::RequiresEagerBodyParse, __builtin_LINE());
	    }
	    bool is_static = (method.flags & vfSTATIC) != 0;
	    if ( !is_static && method.parameters.empty() )
		return class_pattern_eligibility_note(binding, Reason::UnsupportedDeclKind, __builtin_LINE());
	    if ( method.is_member_template
	      && !method.template_param_is_type.empty()
	      && method.template_param_names.size()
		 != method.template_param_is_type.size() )
		return class_pattern_eligibility_note(binding, Reason::UnsupportedDeclKind, __builtin_LINE());
	    for ( size_t p = 0; p < method.parameters.size(); ++p )
	    {
		const Program::ClassMethodParamPattern &param =
		    method.parameters[p];
		if ( !param.type || param.type >= binding.pattern.types.size() )
		    return class_pattern_eligibility_note(binding, Reason::UnnormalizableType, __builtin_LINE());
		if ( !is_static && p == 0 )
		{
		    if ( !param.cpp_spelling.empty() )
			return class_pattern_eligibility_note(binding, Reason::UnsupportedDeclKind, __builtin_LINE());
		    continue;
		}
		if ( !method.is_member_template && param.cpp_spelling.empty() )
		    return class_pattern_eligibility_note(binding, Reason::UnsupportedDeclKind, __builtin_LINE());
		if ( !method.is_member_template )
		{
		    std::vector<bool> active(
			binding.pattern.types.size(), false);
		    std::string normalized = basic_class_pattern_type_spelling(
			pgm, binding, param.type, false, active);
		    if ( normalized.empty()
		      || basic_class_compact_spelling(normalized).empty() )
			return class_pattern_eligibility_note(binding, Reason::UnsupportedDeclKind, __builtin_LINE());
		}
	    }
	}
    }

    std::string out_of_line_key = binding.definition.defining_namespace
	+ "::" + binding.definition.class_name;
    if ( pgm.out_of_line_nested_class_defs.count(out_of_line_key) )
	return class_pattern_eligibility_note(binding, Reason::UnsupportedOutOfLineNested, __builtin_LINE());
    return class_pattern_eligibility_note(binding, Reason::None, __builtin_LINE());
}

static bool basic_class_pattern_direct_template_param(
	const Program::ClassPattern &pattern,
	Program::ClassTypePatternId id, uint32_t &param_index,
	std::vector<bool> &active)
{
    if ( !id || id >= pattern.types.size() || active[id] )
	return false;
    active[id] = true;
    const Program::ClassTypePattern &type = pattern.types[id];
    if ( type.kind == Program::ClassTypePatternKind::TemplateParam )
    {
	param_index = type.template_param_index;
	return true;
    }
    if ( type.kind != Program::ClassTypePatternKind::Pointer
      && type.kind != Program::ClassTypePatternKind::Reference
      && type.kind != Program::ClassTypePatternKind::ConstType
      && type.kind != Program::ClassTypePatternKind::CArray
      && type.kind != Program::ClassTypePatternKind::PackExpansion )
	return false;
    return basic_class_pattern_direct_template_param(
	pattern, type.operand, param_index, active);
}

static std::string basic_class_pattern_bound_typedef(
	Program &pgm, const BasicClassPatternBinding &binding,
	Program::ClassTypePatternId id)
{
    uint32_t param_index = 0;
    std::vector<bool> active(binding.pattern.types.size(), false);
    if ( !basic_class_pattern_direct_template_param(
	binding.pattern, id, param_index, active)
      || param_index >= binding.definition.typeparams.size() )
	return std::string();
    const std::string &param_name = binding.definition.typeparams[param_index];
    std::map<std::string, TokenDataType *>::const_iterator found =
	binding.type_subst.find(param_name);
    if ( found == binding.type_subst.end() || !found->second )
	return std::string();
    const std::string alias = found->second->spelling();
    return pgm.typedef_alias_matches_datadef(
	alias, &found->second->definition) ? alias : std::string();
}

class BasicClassPatternResolver
{
    struct PendingResolution {
	uint64_t resolution_hash;
	uint8_t kind;
	uint32_t name_id;
	uint32_t namespace_id;
	DataDefCLASS *owner;
	std::vector<DataDef *> arguments;
	DataDef *result;
	PendingResolution(uint64_t hash, uint8_t k, uint32_t n,
		uint32_t ns, DataDefCLASS *o,
		const std::vector<DataDef *> &args, DataDef *dd)
	    : resolution_hash(hash), kind(k), name_id(n), namespace_id(ns),
	      owner(o), arguments(args), result(dd) {}
    };
    Program &pgm;
    const BasicClassPatternBinding &binding;
    std::vector<DataDef *> nodes;
    std::vector<DataDef *> resolved;
    std::vector<bool> active;
    std::vector<PendingResolution> pending;

    uint64_t resolution_key(uint8_t kind, uint32_t name_id,
	uint32_t namespace_id, DataDefCLASS *owner,
	const std::vector<DataDef *> &arguments) const
    {
	ClassPatternHash hash;
	hash.add_u64(kind);
	hash.add_u64(name_id);
	hash.add_u64(namespace_id);
	hash.add_u64((uint64_t)(uintptr_t)owner);
	hash.add_u64(arguments.size());
	for ( size_t i = 0; i < arguments.size(); ++i )
	    hash.add_u64((uint64_t)(uintptr_t)arguments[i]);
	return hash.value();
    }

    DataDef *find_memoized(uint8_t kind, uint32_t name_id,
	uint32_t namespace_id, DataDefCLASS *owner,
	const std::vector<DataDef *> &arguments, uint64_t &hash)
    {
	hash = resolution_key(kind, name_id, namespace_id, owner, arguments);
	if ( ::getenv("MADC_CLASS_PATTERN_NO_MEMO") )
	    return NULL;
	for ( size_t i = pending.size(); i-- > 0; )
	    if ( pending[i].resolution_hash == hash
	      && pending[i].kind == kind && pending[i].name_id == name_id
	      && pending[i].namespace_id == namespace_id
	      && pending[i].owner == owner
	      && pending[i].arguments == arguments )
	    {
		if ( pgm.class_parse_observability )
		    ++pgm._class_pattern_resolver_memo_hits;
		return pending[i].result;
	    }
	DataDef *cached = pgm.find_class_pattern_resolution(hash, kind, name_id,
	    namespace_id, owner, arguments);
	if ( cached )
	{
	    if ( pgm.class_parse_observability )
		++pgm._class_pattern_resolver_memo_hits;
	    return cached;
	}
	if ( pgm.class_parse_observability )
	    ++pgm._class_pattern_resolver_memo_misses;
	return NULL;
    }

    DataDef *invalid(const char *message)
    {
	pgm.Throw(binding.location)
	    << "internal: basic ClassPattern " << message << flush;
	return NULL;
    }

    DataDef *instantiate_pattern_template(
	const std::string &qualified_name,
	const std::vector<Program::ClassTypePatternId> &arguments,
	DataDefCLASS *owner, uint8_t memo_kind,
	uint32_t memo_name_id, uint32_t memo_namespace_id,
	uint64_t &memo_hash,
	std::vector<DataDef *> &memo_arguments, bool &memo_miss)
    {
	memo_arguments.clear();
	memo_arguments.reserve(arguments.size());
	for ( size_t i = 0; i < arguments.size(); ++i )
	    memo_arguments.push_back(resolve(arguments[i]));
	DataDef *cached = find_memoized(memo_kind, memo_name_id,
	    memo_namespace_id, owner, memo_arguments, memo_hash);
	if ( cached )
	    return cached;
	memo_miss = true;

	std::string name = qualified_name;
	std::string ns;
	size_t scope = name.rfind("::");
	if ( scope != std::string::npos )
	{
	    ns = name.substr(0, scope);
	    name = name.substr(scope + 2);
	}

	std::vector<TokenBase *> replay;
	replay.push_back(new TokenLT());
	for ( size_t i = 0; i < arguments.size(); ++i )
	{
	    if ( i )
		replay.push_back(new TokenComma());
	    // The replay arg token carries the REGISTERED type identity
	    // (dd->name) — the spelling the parse lane's tsubst feeds at the
	    // same juncture. A C++-source spelling here leaks into the nested
	    // instantiation's substituted decl tokens (member-template param
	    // spellings, frozen text), where it neither resolves nor deduces
	    // on the consumer side. Instantiation keys are derived from the
	    // attached DataDef, not the token text (fenced/unfenced packs
	    // register identical mangled names), so this is key-neutral —
	    // EXCEPT where the parse lane's key rule itself is token-driven:
	    // template_type_arg_spelling PRESERVES certain use-site spellings
	    // over an aliased dd identity (wchar_t/char16_t/char32_t over
	    // integer dds). For an argument that is one of the binding's own
	    // parameter slots, dd->name there would mint a derived key the
	    // parse lane never uses (basic_istream<int32_t,...> alongside its
	    // basic_istream<wchar_t,...>) — split identity, duplicate
	    // definition. Clone the use-site slot token in exactly that case.
	    TokenDataType *slot_tok = NULL;
	    if ( arguments[i] && arguments[i] < binding.pattern.types.size() )
	    {
		const Program::ClassTypePattern &argp =
		    binding.pattern.types[arguments[i]];
		if ( argp.kind == Program::ClassTypePatternKind::TemplateParam
		  && argp.template_param_index < binding.arg_types_by_slot.size() )
		    slot_tok = binding.arg_types_by_slot[argp.template_param_index];
	    }
	    if ( slot_tok && &slot_tok->definition == memo_arguments[i]
	      && template_type_arg_spelling(slot_tok, "")
		 != basic_class_datadef_spelling(memo_arguments[i]) )
		replay.push_back(slot_tok->clone());
	    else if ( DataDefCONST *carg =
			dynamic_cast<DataDefCONST *>(memo_arguments[i]) )
	    {
		// A const-qualified argument re-enters the parse lane the way
		// source spells it: a `const` qualifier token + the BASE type
		// (consume_template_type_arg_qualifiers owns it from there,
		// keying the instantiation with the const in the SPELLING).
		// Pushing the DataDefCONST wrapper itself would type the
		// instantiated class's members/params with the wrapper — a
		// shape the parse lane never produces and member lookup walks
		// as if it were a class (SIGSEGV on `pair<const K,V>::first`).
		replay.push_back(new TokenCONST());
		replay.push_back(new TokenDataType(
		    carg->base_type->name.c_str(), *carg->base_type));
	    }
	    else if ( memo_arguments[i]->is_pointer()
		   && !memo_arguments[i]->is_reference() )
	    {
		// A POINTER argument re-enters the parse lane the way source
		// spells it too: pointee type + `*` tokens
		// (fold_template_arg_declarator owns it from there), so
		// PARTIAL-SPEC selection can deduce against the pointee.
		// One opaque DataDefPTR token matched only the primary:
		// libc++'s pointer_traits<node_pointer>::element_type
		// resolved on the EMPTY primary and map<K,V>'s tree-iterator
		// chain minted placeholder args (task #72).
		DataDef *core = memo_arguments[i];
		int stars = 0;
		while ( DataDefPTR *p = dynamic_cast<DataDefPTR *>(core) )
		{
		    if ( !p->base_type || p->is_reference() )
			break;
		    core = p->base_type;
		    ++stars;
		}
		if ( DataDefCONST *pc = dynamic_cast<DataDefCONST *>(core) )
		{
		    replay.push_back(new TokenCONST());
		    core = pc->base_type ? pc->base_type : core;
		}
		replay.push_back(new TokenDataType(core->name.c_str(), *core));
		for ( int s = 0; s < stars; ++s )
		    replay.push_back(new TokenMul());
	    }
	    else
		replay.push_back(new TokenDataType(
		    memo_arguments[i]->name.c_str(), *memo_arguments[i]));
	}
	replay.push_back(new TokenGT());
	size_t replay_base = pgm.tokens.size();
	for ( std::vector<TokenBase *>::reverse_iterator it = replay.rbegin();
	      it != replay.rend(); ++it )
	    pgm.pushToken(*it);

	bool saved_vri = pgm.allow_variadic_real_inst;
	pgm.allow_variadic_real_inst = true;
	TokenIdent anchor(name.c_str());
	TokenDataType *instantiated = NULL;
	try
	{
	    instantiated = pgm.instantiate_template_id(name, &anchor, ns, owner);
	}
	catch ( ... )
	{
	    pgm.allow_variadic_real_inst = saved_vri;
	    while ( pgm.tokens.size() > replay_base )
		pgm.nextToken();
	    throw;
	}
	pgm.allow_variadic_real_inst = saved_vri;
	while ( pgm.tokens.size() > replay_base )
	    pgm.nextToken();
	return instantiated ? &instantiated->definition : NULL;
    }

    DataDefCLASS *resolved_class(Program::ClassTypePatternId id)
    {
	DataDefCLASS *owner = dynamic_cast<DataDefCLASS *>(resolve(id));
	if ( !owner )
	    return NULL;
	if ( !owner->is_complete || owner->is_dependent_placeholder )
	{
	    pgm.request_template_instantiation_completion(owner->name);
	    flat_datatype_map_iter refreshed = pgm.datatype_map.find(owner->name);
	    if ( refreshed != pgm.datatype_map.end() )
		owner = dynamic_cast<DataDefCLASS *>(&(*refreshed)->definition);
	}
	return owner;
    }

public:
    BasicClassPatternResolver(Program &program,
	const BasicClassPatternBinding &bound,
	const std::vector<DataDef *> &aggregate_nodes)
	: pgm(program), binding(bound), nodes(aggregate_nodes),
	  resolved(bound.pattern.types.size(), NULL),
	  active(bound.pattern.types.size(), false) {}

    DataDef *resolve(Program::ClassTypePatternId id)
    {
	if ( !id || id >= binding.pattern.types.size() )
	    return invalid("references an invalid type id");
	if ( resolved[id] )
	    return resolved[id];
	if ( active[id] )
	    return invalid("contains a cyclic unary type");
	const Program::ClassTypePattern &type = binding.pattern.types[id];
	uint64_t memo_hash = 0;
	uint8_t memo_kind = 0;
	uint32_t memo_name_id = 0;
	uint32_t memo_namespace_id = 0;
	DataDefCLASS *memo_owner = NULL;
	std::vector<DataDef *> memo_arguments;
	bool memo_miss = false;
	active[id] = true;
	DataDef *result = NULL;
	switch ( type.kind )
	{
	case Program::ClassTypePatternKind::ConcreteType:
	    result = pgm.type_from_id(type.concrete_type_id);
	    break;
	case Program::ClassTypePatternKind::TemplateParam:
	    if ( type.template_param_index < binding.definition.typeparams.size() )
	    {
		const std::string &name = binding.definition.typeparams[
		    type.template_param_index];
		std::map<std::string, TokenDataType *>::const_iterator found =
		    binding.type_subst.find(name);
		if ( found != binding.type_subst.end() && found->second )
		    result = &found->second->definition;
	    }
	    break;
	case Program::ClassTypePatternKind::SelfType:
	    result = nodes.empty() ? NULL : nodes[0];
	    break;
	case Program::ClassTypePatternKind::Pointer:
	    result = pgm.getPointerType(resolve(type.operand));
	    break;
	case Program::ClassTypePatternKind::Reference:
	    result = pgm.getReferenceType(resolve(type.operand));
	    break;
	case Program::ClassTypePatternKind::ConstType:
	    result = pgm.getConstType(resolve(type.operand));
	    break;
	case Program::ClassTypePatternKind::CArray:
	    result = resolve(type.operand);
	    for ( size_t i = type.dimensions.size(); i-- > 0; )
	    {
		DataDefCArray *array = new DataDefCArray(*result, result->name,
		    (size_t)type.dimensions[i], NULL);
		if ( pgm.forest_arena_enabled )
		    pgm.forest_arena_record_unary(array);
		result = array;
	    }
	    break;
	case Program::ClassTypePatternKind::NestedType:
	    if ( type.nested_node_id < nodes.size() )
		result = nodes[type.nested_node_id];
	    break;
	case Program::ClassTypePatternKind::TemplateId:
	{
	    memo_kind = 1;
	    memo_name_id = pgm.template_name_pool.intern(type.name);
	    memo_namespace_id = pgm.namespace_name_pool.intern(
		binding.definition.defining_namespace);
	    result = instantiate_pattern_template(type.name, type.arguments,
		NULL, memo_kind, memo_name_id, memo_namespace_id, memo_hash,
		memo_arguments, memo_miss);
	    break;
	}
	case Program::ClassTypePatternKind::DependentMember:
	{
	    memo_owner = resolved_class(type.operand);
	    if ( memo_owner && (type.flags & 1u) )
	    {
		memo_kind = 3;
		memo_name_id = pgm.template_name_pool.intern(type.name);
		result = instantiate_pattern_template(type.name, type.arguments,
		    memo_owner, memo_kind, memo_name_id, memo_namespace_id,
		    memo_hash, memo_arguments, memo_miss);
	    }
	    else if ( memo_owner )
	    {
		memo_kind = 2;
		memo_name_id = pgm.template_name_pool.intern(type.name);
		result = find_memoized(memo_kind, memo_name_id,
		    memo_namespace_id, memo_owner, memo_arguments, memo_hash);
		if ( !result )
		{
		    memo_miss = true;
		    result = Program::class_member_type(memo_owner, type.name);
		}
	    }
	    break;
	}
	case Program::ClassTypePatternKind::FunctionPointer:
	case Program::ClassTypePatternKind::PackExpansion:
	    break;
	}
	active[id] = false;
	if ( !result )
	{
	    pgm.Throw(binding.location)
		<< "internal: basic ClassPattern could not resolve type "
		<< id << " kind=" << (unsigned)type.kind
		<< " name='" << type.name << "' operand=" << type.operand
		<< " owner='" << (memo_owner ? memo_owner->name : "(null)")
		<< "' in '" << binding.pattern.class_name << "'"
		<< flush;
	    return NULL;
	}
	if ( datadef_has_unresolved_dependent_surface(result) )
	{
	    pgm.Throw(binding.location)
		<< "internal: basic ClassPattern type " << id
		<< " resolved to a dependent placeholder '" << result->name
		<< "' in '" << binding.pattern.class_name << "'" << flush;
	    return NULL;
	}
	if ( memo_miss )
	    pending.push_back(PendingResolution(memo_hash, memo_kind,
		memo_name_id, memo_namespace_id, memo_owner, memo_arguments,
		result));
	resolved[id] = result;
	return result;
    }

    void stage_cache()
    {
	for ( size_t i = 0; i < pending.size(); ++i )
	    pgm.record_class_pattern_resolution(pending[i].resolution_hash,
		pending[i].kind, pending[i].name_id,
		pending[i].namespace_id, pending[i].owner,
		pending[i].arguments, pending[i].result);
	pending.clear();
    }

    std::string concrete_spelling(Program::ClassTypePatternId id)
    {
	return basic_class_datadef_spelling(resolve(id));
    }
};

static const TokenBase *basic_class_pattern_source_token(
	const Program::TemplateDef &definition)
{
    for ( size_t i = 0; i < definition.body.size(); ++i )
	if ( definition.body[i] && definition.body[i]->file )
	    return definition.body[i];
    return NULL;
}

static const char *basic_class_pattern_source_file(
	const Program::TemplateDef &definition)
{
    const TokenBase *source = basic_class_pattern_source_token(definition);
    return source ? source->file : NULL;
}

static void prepare_class_pattern_definition(
	Program &pgm, Program::TemplateDef &definition)
{
    const char *source = basic_class_pattern_source_file(definition);
    if ( pgm.forest_arena_enabled || pgm.forest_is_tu_root_file(source) )
	pgm.capture_class_pattern(definition);
    else if ( !definition.body.empty() )
	// Live header template: capture LAZILY at the first concrete
	// instantiation (instantiate_template_use), where the parse lane
	// would pay a full body parse anyway and the environment is the
	// same one that parse sees. Eager capture here taxed every defined
	// template whether or not it was ever instantiated (the B3 live
	// regression); skipping capture entirely killed the live lane.
	definition.class_pattern_capture_deferred = true;
    else
	definition.class_pattern_reason =
	    Program::ClassParseReason::PatternNotCaptured;
}

class BasicClassPatternParsePosition
{
    const char *file;
    int line;
    int column;
public:
    explicit BasicClassPatternParsePosition(
	const Program::TemplateDef &definition)
	: file(TokenBase::_parse_file), line(TokenBase::_parse_line),
	  column(TokenBase::_parse_column)
    {
	const TokenBase *source = basic_class_pattern_source_token(definition);
	if ( source )
	{
	    TokenBase::_parse_file = source->file;
	    TokenBase::_parse_line = source->line;
	    TokenBase::_parse_column = source->column;
	}
    }
    ~BasicClassPatternParsePosition()
    {
	TokenBase::_parse_file = file;
	TokenBase::_parse_line = line;
	TokenBase::_parse_column = column;
    }
};

// A substituted type token must carry the REGISTERED type identity as its
// spelling (dd->name — what the parse lane's tsubst emits), not the C++
// source spelling. The token's attached DataDef makes either work LIVE, but
// the freeze flattens tokens to spelling text: a source-spelled type in a
// frozen member-template decl neither resolves (datatype lookup) nor deduces
// (the template-id unifier) on the consumer side. Parity = registered name.
static void basic_class_pattern_canonicalize_type_tokens(
	Program &pgm, std::vector<TokenBase *> &out)
{
    for ( size_t i = 0; i < out.size(); ++i )
	if ( TokenDataType *tdt = dynamic_cast<TokenDataType *>(out[i]) )
	    if ( !tdt->definition.name.empty()
	      && tdt->spelling() != tdt->definition.name )
	    {
		// The parse lane's instantiation-key rule
		// (template_type_arg_spelling) PRESERVES certain use-site
		// spellings over an aliased dd identity (wchar_t/char16_t/
		// char32_t over integer dds). Rewriting such a token to
		// dd->name mints derived template-id keys the parse lane
		// never uses (split identity, duplicate definition). Keep
		// the spelling iff the key rule preserves it AND it resolves
		// as a registered type name (frozen text must still resolve
		// by datatype lookup — the reason this canonicalizer exists).
		if ( template_type_arg_spelling(tdt, "") == tdt->spelling()
		  && pgm.datatype_map.find(tdt->spelling())
		     != pgm.datatype_map.end() )
		    continue;
		pgm.set_token_spelling(tdt, tdt->definition.name);
	    }
}

static std::vector<std::vector<TokenBase *> >
basic_class_pattern_substitute_token_runs(
	Program &pgm, const BasicClassPatternBinding &binding,
	const std::vector<std::vector<TokenBase *> > &runs);
static std::vector<TokenBase *> basic_class_pattern_substitute_tokens(
	Program &pgm, const BasicClassPatternBinding &binding,
	const std::vector<TokenBase *> &tokens)
{
    std::vector<TokenBase *> out =
	clone_template_tokens_with_type_subst(tokens, binding.type_subst);
    for ( size_t i = 0; i < out.size() && i < tokens.size(); ++i )
	if ( out[i] && tokens[i] )
	{
	    out[i]->file = tokens[i]->file;
	    out[i]->line = tokens[i]->line;
	    out[i]->column = tokens[i]->column;
	}
    basic_class_pattern_canonicalize_type_tokens(pgm, out);
    return out;
}

static TokenBase *basic_class_pattern_token_at_source(
	TokenBase *token, const TokenBase *source)
{
    if ( token && source )
    {
	token->file = source->file;
	token->line = source->line;
	token->column = source->column;
    }
    return token;
}

static std::vector<TokenBase *> basic_class_pattern_member_template_tokens(
	Program &pgm, const BasicClassPatternBinding &binding,
	const std::vector<TokenBase *> &tokens)
{
    std::vector<TokenBase *> out;
    out.reserve(tokens.size());
    for ( size_t i = 0; i < tokens.size(); ++i )
    {
	TokenBase *token = tokens[i];
	if ( token && token->type() == TokenType::ttIdentifier )
	{
	    const std::string &spelling = ((TokenIdent *)token)->spelling();
	    std::map<std::string, TokenDataType *>::const_iterator subst =
		binding.type_subst.find(spelling);
	    if ( subst != binding.type_subst.end() )
	    {
		out.push_back(basic_class_pattern_token_at_source(
		    subst->second->clone(), token));
		continue;
	    }
	    if ( spelling == binding.definition.class_name )
	    {
		bool foreign_qualified = i >= 2 && tokens[i - 1]
		    && tokens[i - 1]->id() == TokenID::tkNS
		    && tokens[i - 2]
		    && is_contextual_identifier_token(tokens[i - 2])
		    && contextual_identifier_name(tokens[i - 2])
		       != binding.definition.defining_namespace;
		bool self_as_template = i + 1 < tokens.size()
		    && tokens[i + 1]
		    && tokens[i + 1]->id() == TokenID::tkLT;
		bool distinct_specialization = self_as_template
		    && self_template_id_keep_distinct(
			binding.definition, tokens, i + 1);
		if ( !foreign_qualified && !distinct_specialization )
		{
		    TokenIdent *renamed = (TokenIdent *)token->clone();
		    pgm.set_token_spelling(renamed, binding.local_name);
		    out.push_back(basic_class_pattern_token_at_source(
			renamed, token));
		    if ( self_as_template )
		    {
			bool split_gt = false;
			i = template_id_suffix_end(tokens, i + 1, &split_gt);
			if ( split_gt )
			    out.push_back(basic_class_pattern_token_at_source(
				new TokenGT(), token));
		    }
		    continue;
		}
	    }
	}
	out.push_back(token ? basic_class_pattern_token_at_source(
	    token->clone(), token) : NULL);
    }
    basic_class_pattern_canonicalize_type_tokens(pgm, out);
    return out;
}

static TokenBase *basic_class_pattern_first_token(
	const std::vector<TokenBase *> &tokens)
{
    for ( size_t i = 0; i < tokens.size(); ++i )
	if ( tokens[i] )
	    return tokens[i];
    return NULL;
}

static TokenBase *parse_basic_class_pattern_default(
	Program &pgm, const BasicClassPatternBinding &binding,
	DataDefCLASS *owner, Method *method,
	const std::vector<TokenBase *> &raw)
{
    std::vector<TokenBase *> seq =
	basic_class_pattern_substitute_tokens(pgm, binding, raw);
    if ( seq.empty() )
	return NULL;
    seq.push_back(new TokenClBrk());
    TokenStream::State saved_tokens = pgm.tokens.swap_in(seq);
    TokenBase *saved_cur = pgm.curToken();
    TokenBase *saved_prv = pgm.prevToken();
    pgm.setTokenContext(NULL, NULL);
    pgm.pushCompound();
    TokenCpnd *scope = pgm.compounds.empty() ? NULL : pgm.compounds.top();
    if ( scope )
	scope->method = method;
    if ( owner )
	pgm.class_scope_stack.push_back(owner);

    TokenBase *expr = NULL;
    try
    {
	if ( !binding.definition.defining_namespace.empty() )
	{
	    Program::NamespaceScope namespace_scope(
		pgm, binding.definition.defining_namespace);
	    expr = pgm.parseExpression(pgm.nextToken(), true);
	}
	else
	    expr = pgm.parseExpression(pgm.nextToken(), true);
    }
    catch ( ... )
    {
	if ( owner && !pgm.class_scope_stack.empty()
	  && pgm.class_scope_stack.back() == owner )
	    pgm.class_scope_stack.pop_back();
	if ( scope && !pgm.compounds.empty() && pgm.compounds.top() == scope )
	    pgm.popCompound();
	pgm.setTokenContext(saved_cur, saved_prv);
	pgm.tokens = saved_tokens;
	throw;
    }
    if ( owner && !pgm.class_scope_stack.empty()
	  && pgm.class_scope_stack.back() == owner )
	pgm.class_scope_stack.pop_back();
    if ( scope && !pgm.compounds.empty() && pgm.compounds.top() == scope )
	pgm.popCompound();
    pgm.setTokenContext(saved_cur, saved_prv);
    pgm.tokens = saved_tokens;
    return expr;
}

static void register_basic_class_pattern_method(
	Program &pgm, const BasicClassPatternBinding &binding,
	BasicClassPatternResolver &resolver, DataDefCLASS *owner,
	const Program::ClassMethodPattern &pattern)
{
    if ( pattern.is_member_template && !pattern.member_template_decl.empty() )
    {
	std::vector<TokenBase *> tokens = owner->name == binding.registered_name
	    ? basic_class_pattern_member_template_tokens(
		pgm, binding, pattern.member_template_decl)
	    : basic_class_pattern_substitute_tokens(pgm,
		binding, pattern.member_template_decl);
	std::string ctor_source_name;
	if ( pattern.kind == Program::ClassMethodKind::Constructor )
	    ctor_source_name = owner->name == binding.registered_name
		? binding.local_name : pattern.display_name;
	std::vector<bool> saved_pack_state =
	    pgm.last_skipped_template_typeparam_is_pack;
	pgm.last_skipped_template_typeparam_is_pack =
	    pattern.template_param_is_pack;
	// TYPE-ness rides the same global (the pattern's non-type params must
	// re-register as non-type for each owner binding).
	std::vector<bool> saved_is_type_state =
	    pgm.last_skipped_template_typeparam_is_type;
	pgm.last_skipped_template_typeparam_is_type =
	    pattern.template_param_is_type;
	// Per-param DEFAULT runs ride the same global (the [temp.deduct]/8
	// SFINAE payload) — substituted for the owner binding like the decl
	// tokens themselves (`declval<_Tp1&>().~_Tp1()` may name the OWNER's
	// params too; the member's own params substitute at the call).
	std::vector<std::vector<TokenBase *> > saved_defaults_state =
	    pgm.last_skipped_template_typeparam_defaults;
	pgm.last_skipped_template_typeparam_defaults =
	    basic_class_pattern_substitute_token_runs(pgm, binding,
		pattern.template_param_defaults);
	// The CONSTRAINT runs ride identically (they may name the OWNER's
	// params too — `enable_if<is_same<_Tp, ...>::value, bool>::type`).
	std::vector<std::vector<TokenBase *> > saved_constraints_state =
	    pgm.last_skipped_template_typeparam_constraints;
	pgm.last_skipped_template_typeparam_constraints =
	    basic_class_pattern_substitute_token_runs(pgm, binding,
		pattern.template_param_constraints);
	// The registration return-type scan re-parses the declaration tokens
	// (`pair<iterator, bool> emplace(...)`); member aliases like
	// `iterator` resolve through class_scope_stack. The parse lane runs
	// this registration inside the class-body parse with the owner
	// pushed — mirror that context here (same shape as the default-arg
	// parse above).
	if ( owner )
	    pgm.class_scope_stack.push_back(owner);
	try
	{
	    register_skipped_class_template_function(
		pgm, owner, tokens, pattern.template_param_names,
		pattern.flags & (vfPRIVATE | vfPROTECTED), ctor_source_name);
	}
	catch ( ... )
	{
	    if ( owner && !pgm.class_scope_stack.empty()
	      && pgm.class_scope_stack.back() == owner )
		pgm.class_scope_stack.pop_back();
	    pgm.last_skipped_template_typeparam_is_pack = saved_pack_state;
	    pgm.last_skipped_template_typeparam_is_type = saved_is_type_state;
	    pgm.last_skipped_template_typeparam_defaults = saved_defaults_state;
	    pgm.last_skipped_template_typeparam_constraints = saved_constraints_state;
	    throw;
	}
	if ( owner && !pgm.class_scope_stack.empty()
	  && pgm.class_scope_stack.back() == owner )
	    pgm.class_scope_stack.pop_back();
	pgm.last_skipped_template_typeparam_is_pack = saved_pack_state;
	pgm.last_skipped_template_typeparam_is_type = saved_is_type_state;
	pgm.last_skipped_template_typeparam_defaults = saved_defaults_state;
	pgm.last_skipped_template_typeparam_constraints = saved_constraints_state;
	return;
    }

    std::string relative_symbol = pattern.variable_name.empty()
	? pattern.display_name : pattern.variable_name;
    relative_symbol = basic_class_pattern_rebind_root_constructor_name(
	binding, owner, pattern.kind, relative_symbol);
    std::string symbol = owner->name + "__" + relative_symbol;
    if ( pgm.findVariable(symbol) || pgm.funcdef_map.count(symbol) )
	pgm.Throw(binding.location)
	    << "internal: basic ClassPattern method symbol collision for "
	    << symbol << flush;

    DataDef *return_type = resolver.resolve(pattern.return_type);
    FuncDef *fd = new FuncDef(*return_type);
    fd->return_typedef_name = pattern.return_typedef_name;
    fd->is_void_params = pattern.is_void_params;
    fd->is_varargs = pattern.is_varargs;
    fd->declaration_only = pattern.declaration_only;
    fd->defaulted_or_deleted = pattern.defaulted_or_deleted;
    fd->is_deleted = pattern.is_deleted;
    fd->noexcept_spec = pattern.noexcept_spec;
    fd->pure_virtual = pattern.pure_virtual;
    fd->decl_file = basic_class_pattern_source_file(binding.definition);
    fd->is_const_method = pattern.is_const_method;
    fd->is_member_template = pattern.is_member_template;
    fd->template_param_names = pattern.template_param_names;
    fd->template_param_is_type = pattern.template_param_is_type;
    fd->template_param_is_pack = pattern.template_param_is_pack;
    fd->template_return_spelling = pattern.template_return_spelling;
    fd->template_param_spellings = pattern.template_param_spellings;
    fd->member_template_decl = basic_class_pattern_substitute_tokens(pgm,
	binding, pattern.member_template_decl);
    fd->member_template_return_tokens = basic_class_pattern_substitute_tokens(pgm,
	binding, pattern.member_template_return_tokens);
    fd->member_template_param_type_tokens =
	basic_class_pattern_substitute_token_runs(pgm, binding,
	    pattern.param_type_token_runs);
    if ( pattern.is_member_template )
	fd->member_template_owner = owner;
    for ( size_t i = 0; i < pattern.parameters.size(); ++i )
    {
	const Program::ClassMethodParamPattern &param = pattern.parameters[i];
	DataDef *parameter_type = resolver.resolve(param.type);
	fd->parameters.push_back(parameter_type);
	fd->const_params.push_back(param.is_const);
	fd->param_template_param_spelled_directly.push_back(
	    param.template_param_spelled_directly);
	std::string typedef_name = param.typedef_name;
	if ( typedef_name.empty() && param.template_param_spelled_directly )
	    typedef_name = basic_class_pattern_bound_typedef(
		pgm, binding, param.type);
	fd->param_typedef_names.push_back(typedef_name);
	fd->param_defaults.push_back(NULL);
	fd->param_default_tokens.push_back(
	    basic_class_pattern_substitute_tokens(pgm, binding, param.default_tokens));
	bool hidden_this = !(pattern.flags & vfSTATIC) && i == 0;
	std::vector<bool> active(binding.pattern.types.size(), false);
	bool dependent = !hidden_this && basic_class_pattern_type_is_dependent(
	    binding.pattern, param.type, active);
	std::string spelling = hidden_this
	    ? std::string() : resolver.concrete_spelling(param.type);
	{
	    static const char *cpp_probe =
		::getenv("MADC_CLASS_PATTERN_PROBE");
	    if ( cpp_probe && !hidden_this
	      && (owner->name.find(cpp_probe) != std::string::npos
		   || !strcmp(cpp_probe, "*")) )
		std::cerr << "[class-pattern-probe] param-spelling: "
		    << symbol << " param " << i
		    << " dep=" << dependent
		    << " concrete='" << spelling
		    << "' captured='" << param.cpp_spelling << "'"
		    << std::endl;
	}
	if ( !hidden_this && !dependent && !param.cpp_spelling.empty() )
	    spelling = param.cpp_spelling;
	else if ( !hidden_this && dependent && !param.cpp_spelling.empty() )
	{
	    // The resolved-type render cannot see two Itanium-relevant
	    // qualifiers that exist ONLY in the captured source spelling: a
	    // leading const (it rides const_params, never the type graph —
	    // `const string&` would mangle R not RK) and rvalue-refness
	    // (DataDefREF spells '&' for both `&` and `&&`). Both are
	    // STRUCTURAL — substitution never changes them — so carry them
	    // over from the captured spelling onto the concrete render.
	    if ( param.cpp_spelling.compare(0, 6, "const ") == 0
	      && spelling.compare(0, 6, "const ") != 0 )
		spelling = "const " + spelling;
	    size_t cn = param.cpp_spelling.size();
	    size_t sn = spelling.size();
	    if ( cn >= 2 && param.cpp_spelling[cn - 1] == '&'
	      && param.cpp_spelling[cn - 2] == '&'
	      && sn >= 1 && spelling[sn - 1] == '&'
	      && (sn < 2 || spelling[sn - 2] != '&') )
		spelling += "&";
	}
	if ( !hidden_this && spelling.empty() )
	    pgm.Throw(binding.location)
		<< "internal: basic ClassPattern lost method parameter spelling"
		<< flush;
	fd->param_cpp_spellings.push_back(spelling);
    }
    if ( pattern.is_member_template && pattern.member_template_decl.empty() )
    {
	fd->param_cpp_spellings.clear();
	fd->param_template_param_spelled_directly.clear();
    }

    pgm.pack_tap_name(symbol, Program::pdkFunction);
    pgm.funcdef_map[symbol] = fd;
    Variable *mvar = pgm.addVariable(NULL, *fd, symbol);
    if ( !mvar || mvar->type != fd )
	pgm.Throw(binding.location)
	    << "internal: basic ClassPattern failed to register method "
	    << symbol << flush;
    mvar->storage_alias_name = pattern.storage_alias_name;
    Method *method = new Method(*mvar);
    method->owner_class = owner;
    mvar->data = method;

    bool has_deferred_body = !pattern.body_tokens.empty()
	|| !pattern.definition_tokens.empty();
    if ( has_deferred_body )
	for ( size_t i = 0; i < pattern.parameters.size(); ++i )
	{
	    const Program::ClassMethodParamPattern &param = pattern.parameters[i];
	    std::string name = param.name.empty()
		? "__synthetic_p" + std::to_string(i) : param.name;
	    Variable *pvar = new Variable(name, *fd->parameters[i], 1, NULL, false);
	    pvar->flags |= vfPARAM | vfLOCAL | param.flags;
	    if ( param.is_const )
		pvar->flags |= vfCONSTANT;
	    pvar->typedef_name = fd->param_typedef_names[i];
	    method->parameters.push_back(pvar);
	}

    Program::ClassMethodRegistration spec;
    spec.kind = pattern.kind;
    spec.display_name = pattern.display_name;
    if ( owner->name == binding.registered_name )
    {
	if ( pattern.kind == Program::ClassMethodKind::Constructor )
	    spec.display_name = binding.local_name;
	else if ( pattern.kind == Program::ClassMethodKind::Destructor )
	    spec.display_name = "~" + binding.local_name;
    }
    spec.access_flags = pattern.flags & (vfPRIVATE | vfPROTECTED);
    spec.is_static = (pattern.flags & vfSTATIC) != 0;
    spec.is_operator = spec.display_name.compare(0, 8, "operator") == 0;
    spec.bind_cpp_symbol = !pattern.is_member_template;
    if ( !pattern.local_emit_name.empty() )
	{
	    std::string pattern_emit_symbol = owner->name + "__"
		+ basic_class_pattern_rebind_root_constructor_name(
		    binding, owner, pattern.kind, pattern.local_emit_name); // allowed-exception: normalized pattern recipe
	    if ( pattern.kind != Program::ClassMethodKind::Constructor
	      || pattern_emit_symbol != symbol )
		spec.local_emit_name = pattern_emit_symbol;
	}
    pgm.register_class_method_signature(owner, mvar, spec);

    for ( size_t i = 0; i < pattern.parameters.size(); ++i )
	if ( !pattern.parameters[i].default_tokens.empty() )
	    fd->param_defaults[i] = parse_basic_class_pattern_default(
		pgm, binding, owner, method,
		pattern.parameters[i].default_tokens);

    if ( has_deferred_body )
    {
	Program::DeferredFunctionBody body;
	body.var = mvar;
	body.method = method;
	body.body_tokens = basic_class_pattern_substitute_tokens(pgm,
	    binding, pattern.body_tokens);
	body.definition_tokens = basic_class_pattern_substitute_tokens(pgm,
	    binding, pattern.definition_tokens);
	body.trailing_ret_tokens = basic_class_pattern_substitute_tokens(pgm,
	    binding, pattern.trailing_ret_tokens);
	body.ctor_init_tokens = basic_class_pattern_substitute_tokens(pgm,
	    binding, pattern.ctor_init_tokens);
	body.full_definition = !body.definition_tokens.empty();
	TokenBase *source = basic_class_pattern_first_token(
	    body.full_definition ? body.definition_tokens : body.body_tokens);
	body.file = source ? source->file : fd->decl_file;
	body.line = source ? source->line : 0;
	body.column = source ? source->column : 0;
	pgm.deferred_lazy_bodies[symbol] = body;
    }
}

static std::vector<std::vector<TokenBase *> >
basic_class_pattern_substitute_token_runs(
	Program &pgm, const BasicClassPatternBinding &binding,
	const std::vector<std::vector<TokenBase *> > &runs)
{
    std::vector<std::vector<TokenBase *> > out;
    for ( size_t i = 0; i < runs.size(); ++i )
	out.push_back(basic_class_pattern_substitute_tokens(pgm, binding, runs[i]));
    return out;
}

static void register_basic_class_pattern_nested_templates(
	Program &pgm, const BasicClassPatternBinding &binding,
	DataDefCLASS *owner,
	const Program::ClassAggregatePatternNode &node)
{
    for ( size_t i = 0; i < node.nested_templates.size(); ++i )
    {
	const Program::ClassNestedTemplatePattern &nested =
	    node.nested_templates[i];
	if ( nested.kind == Program::ClassNestedTemplateKind::ClassTemplate )
	{
	    Program::TemplateDef td;
	    td.typeparams = nested.typeparams;
	    td.typeparam_defaults = basic_class_pattern_substitute_token_runs(pgm,
		binding, nested.typeparam_defaults);
	    td.typeparam_is_type = nested.typeparam_is_type;
	    td.typeparam_is_pack = nested.typeparam_is_pack;
	    td.has_non_type_params = nested.has_non_type_params;
	    td.class_name = nested.class_name;
	    td.registry_name_id = pgm.template_name_pool.intern(td.class_name);
	    td.body = basic_class_pattern_substitute_tokens(pgm, binding, nested.body);
	    td.defining_namespace = nested.defining_namespace;
	    td.owner_class = owner;
	    td.is_partial_specialization = nested.is_partial_specialization;
	    td.spec_pattern = basic_class_pattern_substitute_token_runs(pgm,
		binding, nested.spec_pattern);
	    td.constraint = basic_class_pattern_substitute_tokens(pgm,
		binding, nested.constraint);
	    td.class_pattern_id = 0;
	    td.class_pattern_reason = Program::ClassParseReason::None;
	    td.class_pattern_capture_deferred = !td.body.empty();
	    if ( td.body.empty() )
		td.class_pattern_reason =
		    Program::ClassParseReason::PatternNotCaptured;
	    if ( td.is_partial_specialization )
	    {
		pgm.class_template_variants_for_write(
		    td.registry_name_id, owner, true).push_back(td);
		pgm.record_class_pattern_nested_template(owner,
		    Program::ClassNestedTemplateKind::ClassTemplate,
		    td.registry_name_id, true);
	    }
	    else
		pgm.register_template(td, false);
	}
	else
	{
	    Program::TemplateAliasDef td;
	    td.typeparams = nested.typeparams;
	    td.typeparam_defaults = basic_class_pattern_substitute_token_runs(pgm,
		binding, nested.typeparam_defaults);
	    td.typeparam_is_type = nested.typeparam_is_type;
	    td.typeparam_is_pack = nested.typeparam_is_pack;
	    td.has_non_type_params = nested.has_non_type_params;
	    td.alias_name = nested.class_name;
	    td.registry_name_id = pgm.template_name_pool.intern(td.alias_name);
	    td.target = basic_class_pattern_substitute_tokens(pgm,
		binding, nested.target);
	    td.defining_namespace = nested.defining_namespace;
	    td.owner_class = owner;
	    pgm.register_template_alias(td);
	}
    }
}

static void import_basic_class_pattern_using_member(
	DataDefCLASS *owner, DataDefCLASS *base, const std::string &name)
{
    if ( !owner || !base )
	return;
    for ( size_t i = 0; i < base->methods.size(); ++i )
    {
	Variable *method = base->methods[i];
	FuncDef *fd = method ? dynamic_cast<FuncDef *>(method->type) : NULL;
	if ( !fd || fd->method_display_name != name )
	    continue;
	bool present = false;
	for ( size_t j = 0; j < owner->methods.size(); ++j )
	    if ( owner->methods[j] == method )
		present = true;
	if ( !present )
	    owner->methods.push_back(method);
	if ( owner->method_map.find(name) == owner->method_map.end() )
	    owner->method_map[name] = method;
    }
}

static bool basic_incomplete_class_shell(DataDefCLASS *ddc)
{
    return ddc && !ddc->is_complete && ddc->size == 0
	&& ddc->members.empty() && ddc->methods.empty()
	&& ddc->ctors.empty() && ddc->bases.empty()
	&& ddc->staticconst.empty() && ddc->static_member_types.empty()
	&& ddc->static_member_const_values.empty()
	&& ddc->friend_class_names.empty() && ddc->friend_function_names.empty()
	&& !ddc->has_vtable;
}

class BasicClassPatternMaterializer
{
    Program &pgm;
    const BasicClassPatternBinding &binding;
    BasicClassPatternResolver &resolver;
    std::vector<DataDef *> &nodes;
    std::vector<uint8_t> state;

    void collect_type_dependencies(Program::ClassTypePatternId id,
	bool require_complete, std::set<uint32_t> &dependencies,
	std::set<Program::ClassTypePatternId> &visited)
    {
	if ( !id || id >= binding.pattern.types.size()
	  || !visited.insert(id).second )
	    return;
	const Program::ClassTypePattern &type = binding.pattern.types[id];
	switch ( type.kind )
	{
	case Program::ClassTypePatternKind::NestedType:
	    if ( require_complete )
		dependencies.insert(type.nested_node_id);
	    break;
	case Program::ClassTypePatternKind::Pointer:
	case Program::ClassTypePatternKind::Reference:
	    collect_type_dependencies(type.operand, false, dependencies, visited);
	    break;
	case Program::ClassTypePatternKind::ConstType:
	case Program::ClassTypePatternKind::CArray:
	    collect_type_dependencies(
		type.operand, require_complete, dependencies, visited);
	    break;
	case Program::ClassTypePatternKind::DependentMember:
	    collect_type_dependencies(type.operand, true, dependencies, visited);
	    for ( size_t i = 0; i < type.arguments.size(); ++i )
		collect_type_dependencies(
		    type.arguments[i], false, dependencies, visited);
	    break;
	case Program::ClassTypePatternKind::TemplateId:
	case Program::ClassTypePatternKind::FunctionPointer:
	    for ( size_t i = 0; i < type.arguments.size(); ++i )
		collect_type_dependencies(
		    type.arguments[i], false, dependencies, visited);
	    break;
	case Program::ClassTypePatternKind::PackExpansion:
	    collect_type_dependencies(
		type.operand, require_complete, dependencies, visited);
	    break;
	case Program::ClassTypePatternKind::ConcreteType:
	case Program::ClassTypePatternKind::TemplateParam:
	case Program::ClassTypePatternKind::SelfType:
	    break;
	}
    }

    void add_type_dependencies(Program::ClassTypePatternId id,
	bool require_complete, std::set<uint32_t> &dependencies)
    {
	std::set<Program::ClassTypePatternId> visited;
	collect_type_dependencies(id, require_complete, dependencies, visited);
    }

public:
    BasicClassPatternMaterializer(Program &program,
	const BasicClassPatternBinding &bound,
	BasicClassPatternResolver &type_resolver,
	std::vector<DataDef *> &aggregate_nodes)
	: pgm(program), binding(bound), resolver(type_resolver),
	  nodes(aggregate_nodes), state(aggregate_nodes.size(), 0) {}

    void materialize(size_t index)
    {
	if ( index >= binding.pattern.nodes.size() || state[index] == 2 )
	    return;
	if ( state[index] == 1 )
	    return;
	state[index] = 1;
	const Program::ClassAggregatePatternNode &node =
	    binding.pattern.nodes[index];
	DataDefCLASS *owner = dynamic_cast<DataDefCLASS *>(nodes[index]);
	if ( !owner )
	    pgm.Throw(binding.location)
		<< "internal: ClassPattern aggregate shell is not a class"
		<< flush;

	std::set<uint32_t> dependencies;
	for ( size_t i = 0; i < node.bases.size(); ++i )
	    add_type_dependencies(node.bases[i].type, true, dependencies);
	for ( size_t i = 0; i < node.aliases.size(); ++i )
	    add_type_dependencies(node.aliases[i].type, false, dependencies);
	for ( size_t i = 0; i < node.members.size(); ++i )
	    add_type_dependencies(node.members[i].type, true, dependencies);
	for ( size_t i = 0; i < node.methods.size(); ++i )
	{
	    add_type_dependencies(node.methods[i].return_type, false, dependencies);
	    for ( size_t p = 0; p < node.methods[i].parameters.size(); ++p )
		add_type_dependencies(
		    node.methods[i].parameters[p].type, false, dependencies);
	}
	for ( size_t i = 0; i < node.using_members.size(); ++i )
	    add_type_dependencies(node.using_members[i].owner_type,
		true, dependencies);
	for ( std::set<uint32_t>::const_iterator dependency = dependencies.begin();
	      dependency != dependencies.end(); ++dependency )
	    if ( *dependency != index )
		materialize(*dependency);

	if ( !node.complete )
	{
	    state[index] = 2;
	    return;
	}

	for ( size_t i = 0; i < node.aliases.size(); ++i )
	{
	    DataDef *alias_type = resolver.resolve(node.aliases[i].type);
	    {
		static const char *cpp_probe =
		    ::getenv("MADC_CLASS_PATTERN_PROBE");
		if ( cpp_probe && (owner->name.find(cpp_probe)
					!= std::string::npos
				    || !strcmp(cpp_probe, "*")) )
		    std::cerr << "[class-pattern-probe] alias: "
			<< owner->name << "::" << node.aliases[i].name
			<< " = " << (alias_type ? alias_type->name : "(null)")
			<< std::endl;
	    }
	    pgm.set_class_type_alias(owner, node.aliases[i].name, alias_type);
	}

	std::vector<BaseSpec> bases;
	for ( size_t i = 0; i < node.bases.size(); ++i )
	{
	    DataDef *base_dd = resolver.resolve(node.bases[i].type);
	    DataDefCLASS *base = dynamic_cast<DataDefCLASS *>(base_dd);
	    // A base that instantiated as a plain DataDefSTRUCT (an EMPTY
	    // struct never earns class-hood — e.g. the C++20 __iterator_traits
	    // primary `{ }`) promotes exactly as the legacy base-clause does.
	    if ( !base && base_dd )
		base = pgm.promote_struct_base_to_class(base_dd->name, base_dd);
	    if ( !base || !base->is_complete )
		pgm.Throw(binding.location)
		    << "internal: ClassPattern base did not resolve complete ("
		    << owner->name << " base "
		    << (base_dd ? base_dd->name : std::string("(null)"))
		    << (base ? (base->is_dependent_placeholder
				? ", incomplete placeholder" : ", incomplete")
			     : "") << ")" << flush;
	    BaseSpec spec = { base, 0, node.bases[i].is_virtual,
		node.bases[i].access, false };
	    bases.push_back(spec);
	}
	pgm.initialize_class_bases(owner, bases);

	for ( size_t i = 0; i < node.members.size(); ++i )
	{
	    const Program::ClassMemberPattern &member = node.members[i];
	    std::vector<carray_dim_t> dimensions;
	    for ( size_t d = 0; d < member.dimensions.size(); ++d )
		dimensions.push_back((carray_dim_t)member.dimensions[d]);
	    owner->addMember(member.name, *resolver.resolve(member.type),
		(size_t)member.count, NULL, member.is_array,
		member.is_array ? &dimensions : NULL);
	    if ( !owner->member_access.empty() )
		owner->member_access.back() = member.access;
	}

	for ( size_t i = 0; i < node.using_members.size(); ++i )
	{
	    DataDefCLASS *base = dynamic_cast<DataDefCLASS *>(
		resolver.resolve(node.using_members[i].owner_type));
	    import_basic_class_pattern_using_member(
		owner, base, node.using_members[i].name);
	}
	for ( size_t i = 0; i < node.methods.size(); ++i )
	    register_basic_class_pattern_method(
		pgm, binding, resolver, owner, node.methods[i]);

	pgm.complete_class_aggregate(owner);
	for ( size_t i = 0; i < owner->members.size(); ++i )
	    if ( datadef_has_unresolved_dependent_surface(owner->members[i].second) )
		pgm.Throw(binding.location)
		    << "internal: ClassPattern committed a dependent member"
		    << flush;
	state[index] = 2;
    }
};

static TokenDataType *instantiate_basic_class_pattern(
	Program &pgm, const BasicClassPatternBinding &binding)
{
    BasicClassPatternParsePosition parse_position(binding.definition);
    AggregateDefinitionOrigin definition_origin = aggregate_definition_origin(
	pgm, basic_class_pattern_source_file(binding.definition));
    Program::ClassRegistrationJournal journal(pgm, false);
    DataDefCLASS *ddc = NULL;
    datadef_map_citer aggregate = pgm.struct_map.find(binding.registered_name);
    if ( aggregate != pgm.struct_map.end() )
	ddc = dynamic_cast<DataDefCLASS *>(aggregate->second);
    flat_datatype_map_iter datatype =
	pgm.datatype_map.find(binding.registered_name);
    DataDefCLASS *typed = datatype == pgm.datatype_map.end() ? NULL
	: dynamic_cast<DataDefCLASS *>(&(*datatype)->definition);
    if ( ddc && typed && ddc != typed )
	pgm.Throw(binding.location)
	    << "internal: basic ClassPattern found conflicting forward shells"
	    << flush;
    if ( !ddc )
	ddc = typed;
    bool completing_forward = ddc != NULL;
    if ( completing_forward && !basic_incomplete_class_shell(ddc) )
	pgm.Throw(binding.location)
	    << "internal: basic ClassPattern cannot complete incompatible shell "
	    << binding.registered_name << flush;

    std::unique_ptr<DataDefCLASS> saved_forward(
	completing_forward ? new DataDefCLASS(*ddc) : NULL);
    if ( !ddc )
	ddc = new DataDefCLASS(binding.registered_name, 0,
			       DataType::dtRESERVED);
    bool registration_committed = false;

    try
    {
	if ( binding.pattern.nodes.empty() )
	    pgm.Throw(binding.location)
		<< "internal: ClassPattern has no aggregate nodes" << flush;
	const Program::ClassAggregatePatternNode &node = binding.pattern.nodes[0];
	ddc->name = binding.registered_name;
	ddc->set_canonical_spelling(binding.canonical_spelling);
	ddc->enclosing_class = binding.definition.owner_class;
	ddc->from_system_header = node.from_system_header;
	ddc->union_layout = node.kind == Program::ClassAggregateKind::Union;
	ddc->definition_origin = definition_origin;
	ddc->is_dependent_placeholder = false;
	ddc->opaque_concrete_tag = false;
	ddc->has_dependent_surface = false;
	// Friend DECLARATIONS replay as the same name-grant bookkeeping the
	// parse lane records (register_skipped_friend_type / named friend
	// function declarations). Grants are by bare name — no substitution.
	ddc->friend_class_names = node.friend_classes;
	ddc->friend_function_names = node.friend_functions;
	if ( completing_forward && aggregate == pgm.struct_map.end() )
	    pgm.struct_map.set(binding.registered_name, ddc);
	TokenDataType *tdt = pgm.register_class_shell(ddc,
	    binding.registered_name, binding.local_name,
	    binding.definition.class_name, binding.definition.owner_class,
	    completing_forward, false);

	std::vector<DataDef *> aggregate_nodes(
	    binding.pattern.nodes.size(), NULL);
	aggregate_nodes[0] = ddc;
	for ( size_t i = 1; i < binding.pattern.nodes.size(); ++i )
	{
	    const Program::ClassAggregatePatternNode &nested =
		binding.pattern.nodes[i];
	    if ( nested.parent_id >= i || nested.source_name.empty() )
		pgm.Throw(binding.location)
		    << "internal: ClassPattern has an invalid nested owner"
		    << flush;
	    DataDefCLASS *parent = dynamic_cast<DataDefCLASS *>(
		aggregate_nodes[nested.parent_id]);
	    if ( !parent )
		pgm.Throw(binding.location)
		    << "internal: ClassPattern nested owner is not a class"
		    << flush;
	    std::string registered = parent->name + "__" + nested.source_name;
	    DataDefCLASS *shell = new DataDefCLASS(
		registered, 0, DataType::dtRESERVED);
	    std::string parent_canonical = parent->canonical_cpp_spelling().empty()
		? parent->name : parent->canonical_cpp_spelling();
	    shell->set_canonical_spelling(
		parent_canonical + "::" + nested.source_name);
	    shell->enclosing_class = parent;
	    shell->from_system_header = nested.from_system_header;
	    shell->union_layout =
		nested.kind == Program::ClassAggregateKind::Union;
	    shell->definition_origin = definition_origin;
	    shell->is_dependent_placeholder = false;
	    shell->opaque_concrete_tag = false;
	    shell->has_dependent_surface = false;
	    shell->friend_class_names = nested.friend_classes;
	    shell->friend_function_names = nested.friend_functions;
	    pgm.register_class_shell(shell, registered, nested.source_name,
		nested.source_name, parent, false, false);
	    aggregate_nodes[i] = shell;
	}

	for ( size_t i = 0; i < binding.pattern.nodes.size(); ++i )
	    register_basic_class_pattern_nested_templates(
		pgm, binding,
		dynamic_cast<DataDefCLASS *>(aggregate_nodes[i]),
		binding.pattern.nodes[i]);

	BasicClassPatternResolver resolver(pgm, binding, aggregate_nodes);
	BasicClassPatternMaterializer materializer(
	    pgm, binding, resolver, aggregate_nodes);
	materializer.materialize(0);
	for ( size_t i = 1; i < binding.pattern.nodes.size(); ++i )
	    materializer.materialize(i);
	pgm.attach_outofline_member_instantiations(
	    binding.definition.class_name,
	    binding.definition.defining_namespace,
	    binding.registered_name, ddc,
	    binding.arg_types_by_slot, binding.arg_tokens_by_slot);
	resolver.stage_cache();
	journal.commit();
	registration_committed = true;
	journal.publish_class_pattern_resolutions();
	return use_site_type_token(tdt, binding.location);
    }
    catch ( ... )
    {
	if ( !registration_committed && saved_forward )
	{
	    *ddc = *saved_forward;
	    ++DataDef::canonical_spelling_gen;
	}
	if ( !registration_committed )
	    journal.rollback();
	throw;
    }
}
}

// RAII in-flight marker for a class instantiation, shared by BOTH lanes
// (pattern serve and legacy body re-parse). While a key is in flight, a
// re-entering instantiation of the SAME specialization returns the
// early-registered incomplete shell (instantiate_template_use's cache-hit
// branch) instead of recursing — the bound for cyclic dependency webs and
// for a base clause naming the template's own specialization as a template
// ARGUMENT (libc++'s allocator : __non_trivial_if<..., allocator<_Tp>>).
struct ClassInstInFlightGuard {
    std::set<std::string> &set;
    std::string key;
    bool inserted;
    ClassInstInFlightGuard(std::set<std::string> &s, const std::string &k)
	: set(s), key(k), inserted(s.insert(k).second) {}
    ~ClassInstInFlightGuard() { if ( inserted ) set.erase(key); }
};

// Env-gated diagnostics for the variadic real-instantiation routing and the
// [temp.deduct]/8 alias-arg validation (MADC_XTEST_VRI_DEBUG=1): prints the
// entry flags per class-template instantiation, the base-clause arming, the
// per-alias-use skip decision, and the classifier's dependence verdicts.
static bool vri_debug_enabled()
{
    static const char *e = ::getenv("MADC_XTEST_VRI_DEBUG");
    return e != NULL;
}

// clang's __type_pack_element builtin template (BuiltinTemplateDecl
// BTK__type_pack_element): `__type_pack_element<I, T0, ..., Tn>` IS the I-th
// type argument. libc++'s tuple_element takes this branch when __has_builtin
// says yes; the fallback branch is a decltype-indexer whose resolution minted
// an opaque dependent shell (tuple_element<0,tuple<int&>>::type — get<0>'s
// return, the mem-init instantiation-demand deferral; task #103). The head
// identifier is already consumed by the caller; the live stream holds
// `< I , T0 , ... >`. A CONCRETE I selects its type argument directly — the
// region is consumed and the resolved type returned (nothing instantiates:
// the result is one of the given args). A dependent / non-constant /
// out-of-range I returns NULL with the stream untouched — the ordinary
// lookup path then serves the use (dependent shell), like any template-id.
TokenDataType *Program::instantiate_type_pack_element(TokenBase *tb,
						      const std::string &ns_hint)
{
    (void)ns_hint;
    if ( tokens.empty() || !tokens[0] || tokens[0]->id() != TokenID::tkLT )
	return NULL;
    DelimDepth d;
    size_t i = delim_scan_step(tokens, 0, d);	// the `<` (NULL prev: opens)
    size_t arg_start = i;
    size_t close_idx = 0;
    std::vector<std::pair<size_t, size_t> > argr;	// [start, end) per arg
    while ( i < tokens.size() )
    {
	TokenBase *t = tokens[i];
	if ( t && d.angle == 1 && !d.paren && !d.square && !d.brace )
	{
	    if ( t->id() == TokenID::tkComma )
	    {
		argr.push_back(std::make_pair(arg_start, i));
		arg_start = i + 1;
	    }
	    else if ( t->id() == TokenID::tkGT )
	    {
		close_idx = i;
		break;
	    }
	    else if ( t->id() == TokenID::tkBSR )
		return NULL;	// nested-template shared close: ordinary path
	}
	i += delim_scan_step(tokens, i, d);
    }
    if ( !close_idx || argr.empty() )
	return NULL;
    argr.push_back(std::make_pair(arg_start, close_idx));
    for ( size_t a = 0; a < argr.size(); ++a )
	if ( argr[a].first >= argr[a].second )
	    return NULL;
    // I must fold to a concrete in-range constant NOW.
    std::vector<TokenBase *> iexpr;
    for ( size_t k = argr[0].first; k < argr[0].second; ++k )
	if ( tokens[k] )
	    iexpr.push_back(tokens[k]);
    int64_t sel = -1;
    if ( !fold_nontype_arg_constant(iexpr, sel )
      || sel < 0 || (size_t)sel + 1 >= argr.size() )
	return NULL;
    // Resolve the selected type run BEFORE consuming anything — a resolution
    // miss leaves the stream untouched for the ordinary path.
    const size_t ss = argr[(size_t)sel + 1].first;
    const size_t se = argr[(size_t)sel + 1].second;
    std::vector<TokenBase *> sel_toks;
    for ( size_t k = ss; k < se; ++k )
	if ( tokens[k] )
	    sel_toks.push_back(tokens[k]);
    DataDef *dd = resolve_type_token_range(sel_toks, 0, sel_toks.size());
    if ( !dd )
	return NULL;
    // A REFERENCE result spells `T&` in C++ spelling space (the bind_spelling
    // rule) — its C-lowered NAME is the pointer.
    std::string sp = dd->is_reference() ? basic_class_datadef_spelling(dd)
					: std::string(dd->name);
    for ( size_t k = 0; k <= close_idx; ++k )
	if ( tokens[k] )
	    delete tokens[k];
    std::vector<TokenBase *> none;
    tokens.splice_front(close_idx + 1, none);
    TokenDataType *tdt = new TokenDataType(sp.c_str(), *dd);
    if ( tb )
    {
	tdt->file = tb->file;
	tdt->line = tb->line;
	tdt->column = tb->column;
    }
    return tdt;
}

TokenDataType *Program::instantiate_template_use(const std::string &tname,
					       TokenBase *tb,
					       const std::string &ns_hint,
					       DataDefCLASS *owner_hint)
{
    InstTimer _it(*this, _inst_class_count);	// --show-stats
    // Builtin templates are compiler vocabulary, not user names (the
    // __integer_pack precedent): resolved natively ahead of the registry,
    // which has no definition to offer for them. NEVER under an owner-scoped
    // lookup: a builtin is a namespace-level entity, and the member-chain
    // walkers probe every enclosing class SPECULATIVELY (expecting a miss to
    // be non-destructive) — the native arm rewrites the live stream, so it
    // must fire only for the one lookup that can actually consume the use.
    if ( !owner_hint && tname.compare("__make_integer_seq") == 0
      && peekToken() && peekToken()->id() == TokenID::tkLT )
	if ( TokenDataType *bi =
		instantiate_make_integer_seq(tb, ns_hint) )
	    return bi;
    // UNLIKE the sibling above, this arm runs under owner-scoped lookups
    // too: the fold is ATOMIC (the stream is consumed ONLY on success —
    // every bail leaves it untouched, so a speculative member probe's miss
    // stays non-destructive), and a class-body typedef parse
    // (`typedef __type_pack_element<_Ip, _Tp...> type;` — the tuple_element
    // spec body) carries owner_hint, which is exactly where libc++ needs
    // the builtin. The name is compiler vocabulary — never a member.
    if ( tname.compare("__type_pack_element") == 0
      && peekToken() && peekToken()->id() == TokenID::tkLT )
	if ( TokenDataType *bi =
		instantiate_type_pack_element(tb, ns_hint) )
	    return bi;
    const uint32_t tname_id = template_name_pool.intern(tname);
    const Program::TemplateDef *tdp = find_template(
	tname_id, ns_hint, owner_hint);
    if ( !tdp )
	return NULL;
    if ( !peekToken() || peekToken()->id() != TokenID::tkLT )
	return NULL;
    // Copy (not reference): instantiating the body can re-enter template
    // registration, and a vector reallocation would dangle a live reference.
    // Both this function and instantiate_opaque_template_use only read td.
    Program::TemplateDef td = *tdp;
    if ( !td.registry_name_id )
	td.registry_name_id = tname_id;
    // Definition-time class-pattern capture parses declarations only. Every nested
    // template-id remains an opaque structural recipe for later tsubst; eager
    // instantiation here is both duplicate work and can recurse before a later
    // terminating partial specialization has even been declared.
    if ( class_pattern_capture_in_progress )
	return instantiate_opaque_template_use(td, tname, tb);
    // A variadic template normally stays an opaque dependent shell — EXCEPT a
    // concrete-arg trailing-type-pack template with a body, which must really
    // instantiate so its members (e.g. `__construct_helper<_Tp,_Args...>::type =
    // decltype(...)`) fold. The arg loop below absorbs the trailing pack into
    // pack_subst; a still-dependent arg falls back to the opaque shell after parsing.
    // Real-instantiate a variadic template ONLY for a concrete-arg trailing-type-pack
    // shape AND only while resolving a member-TYPE chain (allow_variadic_real_inst) —
    // see the flag's declaration. The flag is consumed here, then cleared so nested
    // instantiations triggered by this body do NOT inherit it (a recursive variadic
    // body would otherwise re-enter the real path unboundedly). The STICKY variant
    // (variadic_real_inst_sticky) survives this clear: it propagates real-instantiation
    // through a dependent-member-base forwarding chain (`__invoke_result` ->
    // `__result_of_impl`), bounded by variadic_inst_in_progress (set below).
    bool pack_real_inst = (allow_variadic_real_inst || variadic_real_inst_sticky)
		       && template_pack_real_instantiable(td,
						allow_valuepack_real_inst);
    if ( vri_debug_enabled() && pack_real_inst
      && !td.typeparam_is_type[td.typeparams.size() - 1] )
	fprintf(stderr, "[vriprobe] ntpack-real %s\n", tname.c_str());
    // While resolving a member-TYPE chain (allow/sticky), a PRIMARY with non-type
    // params (`__result_of_impl<bool,bool,typename,typename...>`) is itself opaque
    // (template_pack_real_instantiable rejects non-type params), but a PARTIAL SPEC
    // of it (`__result_of_impl<false,false,_Functor,_ArgTypes...>` — bools concrete,
    // own params type+pack) IS real-instantiable and carries the meaningful body
    // (`typedef decltype(_S_test<...>(0)) type;`). Defer the opaque bail so the
    // partial-spec match below can run and swap to that spec; if none matches, the
    // primary's empty body falls back to the opaque placeholder downstream (3287).
    const template_registry_entry_t *partial_entry =
	partial_spec_map.find_readonly(tname_id);
    bool try_spec_real_inst = (allow_variadic_real_inst || variadic_real_inst_sticky)
			   && partial_entry && partial_entry->find(td.owner_class);
    if ( vri_debug_enabled() )
	fprintf(stderr, "[vriprobe] inst %s vri=%d sticky=%d dep=%d cap=%d\n",
		tname.c_str(), (int)allow_variadic_real_inst,
		(int)variadic_real_inst_sticky,
		(int)dependent_parse_in_progress,
		(int)class_pattern_capture_in_progress);
    allow_variadic_real_inst = false;
    allow_valuepack_real_inst = false;
    // When this real-instantiation forwards through a dependent-member base
    // (`: Base<...>::type`), keep real-instantiation on for the nested base/arg
    // resolution during its re-parse so the whole forwarding trait chain folds.
    bool want_sticky = pack_real_inst
		    && (template_base_is_dependent_member(td)
		     || template_base_clause_has_template_id(td));
    if ( template_has_parameter_pack(td.typeparam_is_pack) && !pack_real_inst
      && !try_spec_real_inst )
	{
	++_class_inst_opaque;
	return instantiate_opaque_template_use(td, tname, tb);
	}
    // A body-less PRIMARY whose registered PARTIAL SPECS carry the bodies
    // (libc++'s `__underlying_type_impl<_Tp, bool>` — declared only, both
    // bodies in the <_Tp,false>/<_Tp,true> specs) must reach the
    // partial-spec match below even without the member-chain
    // real-instantiation flags — the spec swap is what materializes
    // `::type`. No matching spec still falls back to the opaque
    // placeholder downstream. Scope: only OUTSIDE a class body and outside
    // a dependent pattern parse — inside those, the args can reference the
    // enclosing template's parameters (`__select<sizeof(_Tp), _UInts>` in
    // libstdc++'s __make_unsigned_selector) and the real lane's eager arg
    // resolution desyncs where the opaque lane tolerated the tokens; those
    // uses keep the opaque route exactly as before.
    bool spec_may_serve = partial_entry && partial_entry->find(td.owner_class)
		       && class_scope_stack.empty()
		       && !dependent_parse_in_progress;
    if ( td.has_non_type_params && td.body.empty() && !try_spec_real_inst
      && !spec_may_serve )
	{
	++_class_inst_opaque;
	return instantiate_opaque_template_use(td, tname, tb);
	}

    // Parse `< Arg [, Arg ...] >`, resolving type parameters as DataDefs and
    // preserving non-type parameters as token sequences for later substitution.
    nextToken(); // consume '<'
    expand_integer_pack_template_args();
    std::vector<TokenDataType *> type_args;
    std::vector<TokenDataType *> arg_types_by_slot;
    std::vector<std::vector<TokenBase *> > arg_tokens_by_slot;
    std::vector<std::string> arg_spellings;
    // A concrete instantiation's identity is (defining_namespace, name, args).
    // The bare name alone suffices to key the type UNLESS the same bare name is
    // declared in more than one namespace (e.g. std::char_traits vs
    // __gnu_cxx::char_traits) — only then must the namespace enter the mangled
    // key, so the two instantiations don't alias the same datatype_map entry.
    // Keeping the common single-namespace case byte-identical avoids churning
    // every std:: template's internal tag.
    std::string mangled = template_instantiation_key_head(
	*this, tname, tname_id, td.defining_namespace, td.owner_class);
    std::map<std::string, TokenDataType *> subst;
    std::map<std::string, std::vector<TokenBase *> > token_subst;
    // A trailing-pack param deduced by a partial spec (`_SomeTemplate<_Tp, _Types...>`
    // in __replace_first_arg): name -> the pack's element type tokens (empty for an
    // empty pack). Expanded in the body loop where `_Types...` appears.
    std::map<std::string, std::vector<TokenDataType *> > pack_subst;
    // A trailing NON-TYPE pack's elements (task #102): pack name -> one token
    // run per element (each typically a single folded TokenInt). The legacy
    // body clone splices `_Values...` and replicates `( _Values + X )...`
    // patterns from this map.
    std::map<std::string, std::vector<std::vector<TokenBase *> > > token_pack_subst;
    // A trailing TYPE pack absorbs every arg from its position onward (see
    // template_pack_real_instantiable): once `pi` reaches `pack_index`, extra args
    // keep binding to it via this clamp, accumulating into pack_subst rather than
    // overflowing the typeparam list.
    size_t pack_index = first_template_pack_index(td.typeparam_is_pack);
    size_t pi = 0;
    if ( peekToken() && (peekToken()->id() == TokenID::tkGT
	  || peekToken()->id() == TokenID::tkBSR) )
    {
	TokenBase *close = nextToken();
	if ( !consume_template_close(close) )
	    Throw(close) << "Expecting '>' in " << tname << "<...>" << flush;
    }
    else
    {
	for (;;)
	{
	    size_t bind_pi = pi;
	    if ( bind_pi >= td.typeparams.size() )
	    {
		// Past the fixed params: a trailing pack keeps absorbing; otherwise
		// it is a genuine too-many-arguments error.
		if ( pack_index < td.typeparams.size() )
		    bind_pi = pack_index;
		else
		    Throw(tb) << tname << "<> expects " << td.typeparams.size()
				  << " argument(s)" << flush;
	    }
	    bool bind_is_pack = bind_pi < td.typeparam_is_pack.size()
			     && td.typeparam_is_pack[bind_pi];
	    TokenBase *at = nextToken();
	    TokenBase *sep = NULL;
	    if ( template_param_expects_type(td.typeparam_is_type, bind_pi) )
	    {
		std::string cv_spelling;
		at = consume_template_type_arg_qualifiers(at, cv_spelling);
		TokenDataType *adt = resolve_declared_type_token(at, true, true);
		if ( !adt )
		    Throw(at) << "Expecting a type argument to "
				  << tname << "<>" << flush;
		// Fold a trailing declarator suffix (`*`/`&`/`&&`) into the arg type.
		adt = fold_template_arg_declarator(adt, at);
		type_args.push_back(adt);
		arg_types_by_slot.push_back(adt);
		arg_tokens_by_slot.push_back(std::vector<TokenBase *>());
		// A trailing type pack accumulates its elements (the body loop expands
		// `_Args...` from pack_subst); a fixed type param binds singly.
		if ( bind_is_pack )
		    pack_subst[td.typeparams[bind_pi]].push_back(adt);
		else
		    subst[td.typeparams[bind_pi]] = adt;
		arg_spellings.push_back(template_type_arg_spelling(adt,
								  cv_spelling));
		sep = nextToken();
	    }
	    else
	    {
		std::string spelling;
		std::vector<TokenBase *> arg_tokens;
		sep = collect_template_argument_spelling(at, spelling,
							 &arg_tokens);
		// Substitution-time non-type-arg fold: a NON-dependent integral/
		// bool constant arg (`(1==1)`, `is_trivial<int>::value`,
		// `__is_bitwise_relocatable<int>::value`) normalizes to its value
		// so partial-spec selection (`enable_if<true,T>`) and the
		// instantiation key see a literal — mirrors g++/clang folding every
		// non-dependent non-type arg. A still-dependent arg fails to fold
		// and keeps its raw tokens unchanged.
		int64_t folded_nt = 0;
		if ( fold_nontype_arg_constant(arg_tokens, folded_nt) )
		{
		    arg_tokens.clear();
		    arg_tokens.push_back(new TokenInt(folded_nt));
		    spelling = std::to_string(folded_nt);
		}
		if ( bind_is_pack )
		    token_pack_subst[td.typeparams[bind_pi]].push_back(arg_tokens);
		else
		    token_subst[td.typeparams[bind_pi]] = arg_tokens;
		arg_types_by_slot.push_back(NULL);
		arg_tokens_by_slot.push_back(arg_tokens);
		arg_spellings.push_back(spelling);
	    }
	    ++pi;
	    if ( sep->id() == TokenID::tkComma )
		continue;
	    if ( consume_template_close(sep) )
		break;
	    Throw(sep) << "Expecting ',' or '>' in "
			   << tname << "<...>" << flush;
	}
    }

    while ( pi < td.typeparams.size() )
    {
	// A trailing parameter PACK absorbs zero-or-more args: reaching it with no
	// remaining args is a valid EMPTY pack (`tuple<>`, `__and_<>`), not a missing
	// argument. Leave pack_subst without an entry for it (the body loop drops the
	// preceding `,` and the `...`) and stop default-filling.
	if ( pi < td.typeparam_is_pack.size() && td.typeparam_is_pack[pi] )
	    break;
	if ( pi >= td.typeparam_defaults.size()
	  || td.typeparam_defaults[pi].empty() )
	{
	    arity_probe("pat-fill", tname, td, pi);
	    Throw(tb) << tname << "<> expects " << td.typeparams.size()
			  << " argument(s), got " << pi << flush;
	}
	std::vector<TokenBase *> default_tokens =
	    clone_template_tokens_with_type_subst(td.typeparam_defaults[pi],
						 subst);
	if ( template_param_expects_type(td.typeparam_is_type, pi) )
	{
	    std::vector<TokenBase *> inj = default_tokens;
	    inj.push_back(new TokenSemi());
	    for ( std::vector<TokenBase *>::reverse_iterator it = inj.rbegin();
		  it != inj.rend(); ++it )
		pushToken(*it);
	    TokenBase *dtok = nextToken();
	    std::string cv_spelling;
	    dtok = consume_template_type_arg_qualifiers(dtok, cv_spelling);
	    TokenDataType *adt = resolve_declared_type_token(dtok, true, true);
	    if ( !adt )
		Throw(dtok ? dtok : tb)
		    << "Could not resolve default template argument for "
		    << td.typeparams[pi] << " in " << tname << "<>" << flush;
	    // Fold the default's declarator suffix (`_Tp*`, `_Tp&`, `_Tp&&`)
	    // into the argument type, mirroring the explicit-argument path's
	    // star fold. Stopping at the base type left the suffix tokens in
	    // the LIVE stream (std::iterator's `_Pointer = _Tp*, _Reference =
	    // _Tp&` defaults leaked a stray `&` that derailed the enclosing
	    // class definition) and dropped the suffix from the arg identity.
	    for (;;)
	    {
		TokenBase *sfx = peekToken();
		if ( !sfx )
		    break;
		if ( sfx->id() == TokenID::tkMul )
		{
		    nextToken();
		    DataDefPTR *ptr = getPointerType(&adt->definition);
		    TokenDataType *padt = new TokenDataType(ptr->name.c_str(), *ptr);
		    padt->file = dtok->file;
		    padt->line = dtok->line;
		    padt->column = dtok->column;
		    adt = padt;
		    continue;
		}
		if ( sfx->id() == TokenID::tkBand || sfx->id() == TokenID::tkLand )
		{
		    nextToken();
		    DataDefREF *ref = getReferenceType(&adt->definition);
		    TokenDataType *radt = new TokenDataType(ref->name.c_str(), *ref);
		    radt->file = dtok->file;
		    radt->line = dtok->line;
		    radt->column = dtok->column;
		    adt = radt;
		    continue;
		}
		break;
	    }
	    if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
		nextToken();
	    type_args.push_back(adt);
	    arg_types_by_slot.push_back(adt);
	    arg_tokens_by_slot.push_back(std::vector<TokenBase *>());
	    subst[td.typeparams[pi]] = adt;
	    arg_spellings.push_back(template_type_arg_spelling(adt,
							      cv_spelling));
	}
	else
	{
	    // Same substitution-time fold for a non-type DEFAULT argument.
	    int64_t folded_nt = 0;
	    if ( fold_nontype_arg_constant(default_tokens, folded_nt) )
	    {
		default_tokens.clear();
		default_tokens.push_back(new TokenInt(folded_nt));
		token_subst[td.typeparams[pi]] = default_tokens;
		arg_types_by_slot.push_back(NULL);
		arg_tokens_by_slot.push_back(default_tokens);
		arg_spellings.push_back(std::to_string(folded_nt));
	    }
	    else
	    {
		token_subst[td.typeparams[pi]] = default_tokens;
		arg_types_by_slot.push_back(NULL);
		arg_tokens_by_slot.push_back(default_tokens);
		arg_spellings.push_back(template_tokens_spelling(default_tokens));
	    }
	}
	++pi;
    }

    for ( size_t i = 0; i < arg_spellings.size(); ++i )
	mangled += "_" + canonical_arg_key_fragment(arg_tokens_by_slot[i],
						    arg_spellings[i]);

    // Canonical C++ spelling for Itanium mangling, built from the defining
    // namespace + template name + each arg's canonical spelling (the args were
    // instantiated first during the loop above, so they already carry theirs).
    std::string canon = td.defining_namespace.empty() ? std::string()
		      : (td.defining_namespace + "::");
    canon += tname + "<";
    for ( size_t i = 0; i < arg_spellings.size(); ++i )
    {
	if ( i ) canon += ",";
	canon += arg_spellings[i];
    }
    canon += ">";

    bool dependent_surface = false;
    // [temp.dep.type]: an argument that IS (or const/ptr-wraps) a raw
    // template-parameter placeholder makes the template-id a DEPENDENT type in
    // any context — a pattern parse resolving `allocator<_Tp1>` (a member fn
    // template's kept self-name param) must yield a dependent shell
    // re-resolved at tsubst, never inject a class body substituted with the
    // placeholder. Injection minted allocator__Tp1 / __new_allocator__Tp1
    // garbage classes — silent at parse, loud when the freeze drain translated
    // them ("unsubstituted template parameter '_Tp1' reached type lowering").
    // Dependent-placeholder CLASS args (laundered opaques) keep their existing
    // real-instantiation route — only the raw-param test gates here.
    bool placeholder_arg = false;
    for ( size_t i = 0; i < type_args.size(); ++i )
    {
	if ( datadef_has_unresolved_dependent_surface(&type_args[i]->definition) )
	{
	    // NARROW carve-out ([temp.dep.type]), LOCAL to this gate: a
	    // dependent-PLACEHOLDER class stamped opaque_concrete_tag was
	    // minted OUTSIDE any dependent parse — its spelling is fully
	    // concrete (a pack-class use whose real instantiation simply
	    // had not been demanded yet: tuple<int&> before
	    // forward_as_tuple realizes it). Such an arg does not make THIS
	    // template-id dependent; counting it deferred
	    // tuple_element<0,tuple<int&>> forever — the first ::type hop
	    // then baked a stale member shell into get<0>'s return and the
	    // mem-init forward demand (task #103). The shared predicate
	    // keeps its meaning — only this gate carves.
	    DataDefCLASS *acls =
		dynamic_cast<DataDefCLASS *>(&type_args[i]->definition);
	    if ( !(acls && acls->is_dependent_placeholder
		   && acls->opaque_concrete_tag
		   && !acls->has_dependent_surface
		   && !class_has_dependent_base(acls)) )
		dependent_surface = true;
	}
	if ( datadef_involves_placeholder(&type_args[i]->definition,
					  /*include_dependent_class=*/false) )
	    placeholder_arg = true;
    }

    std::string registered_mangled = td.owner_class
	? td.owner_class->name + "__" + mangled : mangled;

    // Partial specialization: if a partial spec of `tname` unifies with the concrete
    // args and is more specialized than the primary, instantiate ITS body with the
    // deduced params instead. The instantiation identity (mangled/canon/
    // registered_mangled, computed above) stays keyed on the concrete args, so
    // caching is unaffected — only the body source + substitution change.
    {
	std::map<std::string, TokenDataType *> spec_subst;
	std::map<std::string, std::string> spec_tmpl_subst;
	std::map<std::string, std::vector<std::string> > spec_pack_subst;
	std::map<std::string, std::vector<TokenBase *> > spec_nontype_subst;
	if ( const Program::TemplateDef *spec = match_partial_specialization(
		tname, arg_types_by_slot, arg_spellings, arg_tokens_by_slot,
		td.typeparam_is_type, spec_subst, spec_tmpl_subst, spec_pack_subst,
		spec_nontype_subst, td.defining_namespace, td.owner_class,
		tname_id) )
	{
	    // Keep the USE-SITE owner across the swap. A nested class template's
	    // partial recipe carries the concrete owner that registered it, while
	    // the instantiation identity must remain keyed on the primary's use-site
	    // owner. The
	    // instantiation identity (registered_mangled, computed above) is keyed on
	    // the primary's use-site owner; letting the spec's stale owner replace it
	    // re-registers the body under the wrong owner prefix → "did not register".
	    DataDefCLASS *use_site_owner = td.owner_class;
	    td = *spec;
	    td.owner_class = use_site_owner;
	    subst = spec_subst;
	    // The matched SPEC carries the real base clause (the primary that drove
	    // want_sticky above was a body-less forward decl). Recompute sticky from
	    // the spec body so a template-id base (`_Tuple_impl<_Idx+1, _Tail...>`,
	    // `_Head_base<_Idx, _Head>`) keeps variadic real-instantiation ON while
	    // THIS spec body re-parses — otherwise those bases fall back to opaque
	    // shells and the instantiated class has no storage (size 0).
	    want_sticky = template_base_is_dependent_member(td)
		       || template_base_clause_has_template_id(td);
	    // A deduced template-template parameter (`__replace_first_arg<_Template<_Up>,
	    // _Tp>` → _Template=allocator) binds to a TEMPLATE NAME, not a type: route it
	    // through token_subst so the body's `_Template<_Tp>` clones to `allocator<_Tp>`
	    // and re-parses as a template-id. (The spec body uses the param as a template.)
	    token_subst.clear();
	    for ( std::map<std::string, std::string>::iterator t = spec_tmpl_subst.begin();
		  t != spec_tmpl_subst.end(); ++t )
	    {
		std::vector<TokenBase *> repl;
		repl.push_back(new TokenIdent(t->second));
		token_subst[t->first] = repl;
	    }
	    // A deduced NON-TYPE param (`_Idx` of `_Tuple_impl<_Idx,_Head,_Tail...>`)
	    // binds to the concrete value tokens; route through token_subst so the
	    // body's `_Idx` (and computed forms like `_Idx + 1`) clone to the literal
	    // and fold. Without this a non-type-param partial spec never specialized.
	    for ( std::map<std::string, std::vector<TokenBase *> >::iterator n =
		      spec_nontype_subst.begin(); n != spec_nontype_subst.end(); ++n )
	    {
		std::vector<TokenBase *> repl;
		for ( TokenBase *t : n->second )
		    if ( t )
			repl.push_back(t->clone());
		token_subst[n->first] = repl;
	    }
	    // A deduced trailing pack (`_Types...`) binds to the absorbed concrete
	    // args; resolve each element spelling to its type token for body
	    // expansion. The real allocator rebind leaves it empty (`allocator<_Tp>`
	    // has no extra args), so an empty pack — and its `...`/comma elision —
	    // is the common path.
	    pack_subst.clear();
	    for ( std::map<std::string, std::vector<std::string> >::iterator p =
		      spec_pack_subst.begin(); p != spec_pack_subst.end(); ++p )
	    {
		std::vector<TokenDataType *> elems;
		for ( size_t ei = 0; ei < p->second.size(); ++ei )
		{
		    DataDef *edd = resolve_arg_spelling_datadef(*this, p->second[ei]);
		    if ( edd )
			elems.push_back(new TokenDataType(edd->name.c_str(), *edd));
		}
		pack_subst[p->first] = elems;
	    }
	    // The SPEC's shape replaces the primary's — recompute the pack
	    // real-instantiation admittance against it. The stale value
	    // (computed on the pack-less declaration-only primary at entry)
	    // left the clone loop's pack arms OFF for a pack-pattern spec,
	    // so its body instantiated EMPTY (tuple_element<0, tuple<int>>
	    // — the map:967 chain's ::type shell). A WON spec with concrete
	    // args IS the demand (the match consumed them); its non-type
	    // FIXED params (_Ip) are bound via token_subst above.
	    if ( td.is_partial_specialization )
		pack_real_inst = template_pack_real_instantiable(
		    td, /*allow_valuepack=*/true, /*nontype_fixed_ok=*/true);
	}
    }

    // Already instantiated? Return a use-site clone of the cached type.
    flat_datatype_map_iter have = datatype_map.find(registered_mangled);
    // Env-gated probe (MADC_MTI_PROBE_CLASS=<substr>): every template-use
    // instantiation key + cache outcome for a matching name — the
    // wrong-cache-hit / key-collision diagnostic.
    {
	static const char *mtp = ::getenv("MADC_MTI_PROBE_CLASS");
	if ( mtp && *mtp && tname.find(mtp) != std::string::npos )
	    fprintf(stderr, "MTIPROBE tmpl-use %s key=%s hit=%d -> %s\n",
		    tname.c_str(), registered_mangled.c_str(),
		    have != datatype_map.end() ? 1 : 0,
		    have != datatype_map.end()
			? (*have)->definition.name.c_str() : "(miss)");
    }
    if ( have != datatype_map.end() )
    {
	TokenDataType *cached = (TokenDataType *)(*have);
	if ( td.body.empty() )
	{
	    ++_class_inst_opaque;
	    return use_site_type_token(cached, tb);
	}
	if ( !is_incomplete_template_class_type(cached) )
	{
	    ++_class_inst_cache;
	    return use_site_type_token(cached, tb);
	}
	if ( class_inst_in_progress.count(registered_mangled) )
	{
	    // This specialization is being instantiated up-stack (pattern
	    // serve OR legacy body re-parse); its shell is registered but
	    // incomplete. Returning the shell is the parse lane's
	    // self-reference semantics; re-instantiating here recurses
	    // forever — cyclic dependency webs, and a base clause naming the
	    // template's own specialization as a template ARGUMENT
	    // (allocator : __non_trivial_if<..., allocator<_Tp>>).
	    ++_class_inst_cache;
	    return use_site_type_token(cached, tb);
	}
    }
    // A variadic template admitted to the real path (template_pack_real_instantiable)
    // but instantiated with a STILL-DEPENDENT arg stays an opaque dependent shell —
    // exactly the pre-change behavior (the 2874 short-circuit sent ALL pack uses here).
    // Only a fully concrete-arg variadic template proceeds to body parse below.
    // Re-entering the SAME mangled instantiation while sticky forwarding is active is a
    // self-referential trait loop → fall to the opaque placeholder to bound recursion.
    // Likewise a re-entry of an instantiation ALREADY IN FLIGHT that has not yet
    // registered a shell (a base clause naming the template's own specialization
    // as a template ARGUMENT, resolved BEFORE TokenCLASS::parse registers the
    // name): the cache-hit branch above cannot serve it, so bound it here with
    // the same opaque placeholder — pending completion recognizes the shell.
    bool recursive_sticky = want_sticky
	&& variadic_inst_in_progress.count(registered_mangled) != 0;
    bool recursive_inflight = class_inst_in_progress.count(registered_mangled) != 0;
    bool recursive_opaque = recursive_sticky || recursive_inflight;
    if ( td.body.empty() || (pack_real_inst && dependent_surface)
      || placeholder_arg || recursive_opaque )
    {
	++_class_inst_opaque;
	{
	    static const char *ojp = ::getenv("MADC_INJ_PROBE");
	    if ( ojp && *ojp
	      && registered_mangled.find(ojp) != std::string::npos )
	    {
		fprintf(stderr, "[inj-opaque] %s body=%zu pri=%d dep=%d ph=%d"
			" rec=%d\n", registered_mangled.c_str(),
			td.body.size(), (int)pack_real_inst,
			(int)dependent_surface, (int)placeholder_arg,
			(int)recursive_opaque);
		for ( size_t ai = 0; ai < type_args.size(); ++ai )
		    if ( type_args[ai] )
			fprintf(stderr, "[inj-opaque]   arg[%zu] %s: %s\n", ai,
				type_args[ai]->definition.name.c_str(),
				dependent_surface_reason(
				    &type_args[ai]->definition).c_str());
	    }
	}
	DataDefCLASS *fwd = new DataDefCLASS(registered_mangled, 0, DataType::dtRESERVED);
	// A bodyless declaration with concrete arguments is incomplete, not
	// dependent; pending completion still recognizes it by its empty shell.
	// The same holds for a pre-registration re-entry of an instantiation in
	// flight up-stack (a base clause naming the enclosing specialization as
	// a template ARGUMENT): its key is fully concrete and the enclosing
	// parse completes this very object (register_class_shell reuses it), so
	// it is incomplete, NOT dependent — the cache-hit twin branch above
	// already serves the post-registration ordering with a clean shell.
	// Branding it outlives the transient: the completed class re-stamps its
	// own flags, but anything instantiated AGAINST the branded shell keeps
	// has_dependent_surface forever (libc++ allocator<int>'s
	// __non_trivial_if base — every trait fold on allocator then refused,
	// and is_trivially_destructible silently answered 0).
	bool unresolved_surface = dependent_surface || placeholder_arg
				|| recursive_sticky;
	fwd->set_canonical_spelling(canon);
	fwd->is_dependent_placeholder = unresolved_surface;
	stamp_opaque_mint_context(fwd);
	fwd->has_dependent_surface = unresolved_surface;
	struct_map.set(registered_mangled, fwd);
	TokenDataType *tdt = new TokenDataType(registered_mangled.c_str(), *fwd);
	datatype_map[registered_mangled] = tdt;
	if ( !td.defining_namespace.empty() )
	    namespace_datatype_map[td.defining_namespace][registered_mangled] = tdt;
	record_pending_template_instantiation(*this, tname, registered_mangled, canon, type_args);
	return use_site_type_token(tdt, tb);
    }

    std::string class_profile_identity;
    if ( td.owner_class )
    {
	class_profile_identity = td.owner_class->canonical_cpp_spelling().empty()
	    ? td.owner_class->name : td.owner_class->canonical_cpp_spelling();
	class_profile_identity += "::";
    }
    else if ( !td.defining_namespace.empty() )
	class_profile_identity = td.defining_namespace + "::";
    class_profile_identity += tname;

    // Definition capture must leave every concrete class-instantiation lane
    // unreachable. Nested template-ids returned through the structural shell
    // guard above.
    assert(!class_pattern_capture_in_progress);

    bool force_legacy = force_legacy_class_patterns;
    const char *force_env = ::getenv("MADC_CLASS_PATTERN_FORCE_LEGACY");
    if ( force_env && *force_env && strcmp(force_env, "0") != 0 )
	force_legacy = true;
    ClassParseReason legacy_reason = td.class_pattern_reason;
    const ClassPattern *selected_pattern = legacy_reason == ClassParseReason::None
	? materialize_class_pattern(td) : NULL;
    {
	static const char *cpp_probe = ::getenv("MADC_CLASS_PATTERN_PROBE");
	if ( cpp_probe && *cpp_probe
	  && registered_mangled.find(cpp_probe) != std::string::npos )
	    std::cout << "[class-pattern-probe] lazy-arm: " << registered_mangled
		<< " pattern=" << (selected_pattern ? 1 : 0)
		<< " reason=" << (unsigned)legacy_reason
		<< " deferred=" << (td.class_pattern_capture_deferred ? 1 : 0)
		<< " live=" << (class_pattern_live_capture ? 1 : 0)
		<< " jdepth=" << class_registration_journal_depth
		<< " uses=" << td.class_pattern_use_count
		<< " partial=" << (td.is_partial_specialization ? 1 : 0)
		<< std::endl;
    }
    if ( !selected_pattern && legacy_reason == ClassParseReason::None
	  && td.class_pattern_capture_deferred && !force_legacy
	  && class_pattern_live_capture )
    {
	// Definition-only pre-filter: eligibility categorically rejects
	// non-type params, value/pack params, and friend-bearing bodies —
	// capturing such a template is a guaranteed-wasted parse. Stamp the
	// same reason eligibility would report and never revisit.
	ClassParseReason doomed = ClassParseReason::None;
	if ( td.has_non_type_params )
	    doomed = ClassParseReason::DependentValueExpression;
	for ( size_t p = 0; doomed == ClassParseReason::None
			     && p < td.typeparams.size(); ++p )
	{
	    if ( p < td.typeparam_is_type.size() && !td.typeparam_is_type[p] )
		doomed = ClassParseReason::DependentValueExpression;
	    else if ( p < td.typeparam_is_pack.size() && td.typeparam_is_pack[p] )
		doomed = ClassParseReason::UnsupportedDeclKind;
	}
	for ( size_t t = 0; doomed == ClassParseReason::None
			     && t < td.body.size(); ++t )
	    if ( td.body[t] && td.body[t]->id() == TokenID::tkFRIEND
	      && class_body_friend_needs_parse(td.body, t) )
		doomed = ClassParseReason::UnsupportedFriendDefinition;
	if ( doomed != ClassParseReason::None )
	{
	    td.class_pattern_reason = doomed;
	    td.class_pattern_capture_deferred = false;
	    writeback_class_pattern_capture(td);
	    legacy_reason = doomed;
	}
	else if ( td.class_pattern_use_count == 0 )
	    // The first concrete demand stays on the parse lane and just
	    // arms the counter. Only repeat demand — the pattern lane's
	    // actual market — justifies the capture parse (a single-use
	    // template would pay capture + substitution against the parse
	    // lane's one body parse).
	    note_class_pattern_use(td);
	else if ( class_registration_journal_depth != 0 )
	    // Repeat demand from INSIDE a pattern serve: a capture here would
	    // open a NESTED isolate journal, which does not snapshot (only
	    // the outermost does) — its rollback could not undo the capture
	    // parse's registrations. Queue it; the outermost serve's return
	    // drains the queue at depth 0. This demand stays on the parse
	    // lane.
	    queue_class_pattern_capture(td);
	else
	{
	    // Lazy live capture on repeat demand: the one-time capture parse
	    // replaces a body parse PER SPECIALIZATION from here on. Capture
	    // on the local copy, persist the outcome on the registered
	    // definition so it runs at most once per template, then
	    // re-materialize.
	    capture_class_pattern(td);
	    td.class_pattern_capture_deferred = false;
	    writeback_class_pattern_capture(td);
	    legacy_reason = td.class_pattern_reason;
	    selected_pattern = legacy_reason == ClassParseReason::None
		? materialize_class_pattern(td) : NULL;
	}
    }
    if ( !selected_pattern )
	legacy_reason = legacy_reason == ClassParseReason::None
	    ? ClassParseReason::PatternNotCaptured : legacy_reason;
    // An ABSENT trailing NON-TYPE pack (`__integer_sequence<uint64_t>`, the
    // __make_integer_seq N=0 delegation) is an EMPTY pack, not an unbound
    // name: seed the empty entry so the body clone's value-pack arms ELIDE
    // `(_Values + _Sp)...` instead of cloning it raw into the member alias
    // (the absent-TYPE-pack rule's twin — see absent_pack_elems below).
    // Real path only: token_pack_subst drives nothing elsewhere.
    if ( pack_real_inst && pack_index < td.typeparams.size()
      && pack_index < td.typeparam_is_type.size()
      && !td.typeparam_is_type[pack_index]
      && !token_pack_subst.count(td.typeparams[pack_index]) )
	token_pack_subst[td.typeparams[pack_index]];
    if ( selected_pattern && legacy_reason == ClassParseReason::None )
    {
	BasicClassPatternBinding binding = {
	    td, *selected_pattern, subst, arg_types_by_slot, arg_tokens_by_slot,
	    mangled, registered_mangled, canon, dependent_surface, tb
	};
	legacy_reason = basic_class_pattern_eligibility(
	    *this, binding, token_subst, pack_subst);
	// A VALUE-pack instantiation (task #102) takes the legacy body clone:
	// the pattern lane has no value-pack support, and these templates were
	// opaque until now so no pattern was ever captured for them.
	if ( legacy_reason == ClassParseReason::None && !force_legacy
	  && token_pack_subst.empty() )
	{
	    ++_class_inst_pattern;
	    {
		static const char *cpp_probe =
		    ::getenv("MADC_CLASS_PATTERN_PROBE");
		if ( cpp_probe && (registered_mangled.find(cpp_probe)
					!= std::string::npos
				    || !strcmp(cpp_probe, "*")) )
		    std::cerr << "[class-pattern-probe] pattern-lane: "
			<< registered_mangled << std::endl;
	    }
	    TokenDataType *served;
	    {
		ClassInstInFlightGuard in_flight(class_inst_in_progress,
						 registered_mangled);
		NamespaceScope namespace_scope(*this, td.defining_namespace);
		served = instantiate_basic_class_pattern(*this, binding);
	    }
	    // Depth is 0 again here (the serve's journal closed): run any
	    // captures queued by nested demand inside the serve.
	    drain_pending_class_pattern_captures();
	    return served;
	}
	if ( legacy_reason == ClassParseReason::None )
	    legacy_reason = ClassParseReason::PatternNotCaptured;
    }

    // Build the substituted, renamed class-definition token sequence:
    // clone each body token; rename the class tag (TokenIdent == class_name) to
    // `mangled`; replace each type-parameter ident with its concrete type token.
    //
    // clone() stamps each new token's file/line/column from the STATIC
    // _parse_file/_parse_line (TokenBase's ctor), which here is the INSTANTIATION
    // SITE (e.g. the user .mad), not the template's defining file. That misfiles
    // every instantiated member body to the use site, so a system-header template
    // (std::vector) is wrongly classified from_system_header=0 and ALL its member
    // bodies parse eagerly — hitting walls in members the program never ODR-uses
    // (vector::operator=(vector&&)'s __move_storage). nextToken() propagates
    // _parse_file from each consumed token during the re-parse below, so giving the
    // clones the template's real (system-header) origin makes from_system_header,
    // lazy-body deferral, AND error attribution all see the true source. Point
    // _parse_* at the template body's origin across the clone loop, then restore.
    const char *cloned_pf = TokenBase::_parse_file;
    int cloned_pl = TokenBase::_parse_line;
    int cloned_pc = TokenBase::_parse_column;
    for ( TokenBase *bt0 : td.body )
	if ( bt0 && bt0->file )
	{
	    TokenBase::_parse_file = bt0->file;
	    TokenBase::_parse_line = bt0->line;
	    TokenBase::_parse_column = bt0->column;
	    break;
	}
    std::vector<TokenBase *> inj;
    // Index of the class-body opener `{` (first top-level brace). A self-name
    // BEFORE it sits in the base clause; AFTER it, in the body. Used to keep a
    // recursive self-template BASE (`_Tuple_impl<_Idx+1,_Tail...>`) a distinct
    // template-id instead of collapsing it to the injected-class-name.
    size_t body_brace_index = td.body.size();
    for ( size_t fb = 0; fb < td.body.size(); ++fb )
	if ( td.body[fb] && td.body[fb]->id() == TokenID::tkOpBrc )
	{ body_brace_index = fb; break; }
    // Indices of trailing `...` tokens (three tkDot) belonging to a pack-
    // expansion PATTERN (`const _Elements&...`) whose pack we substituted
    // in place — see the pack_subst handling below. Skipped when reached.
    std::set<size_t> pack_pattern_skip_dots;
    // Function-parameter names whose pack was EMPTY and elided (`const _Tail&...
    // __tail` with empty _Tail): a later VALUE pack-expansion `__tail...` in the
    // ctor body / mem-init (`_Inherited(__tail...)`) must also vanish, else the
    // elided name is "undeclared". Recorded by the empty-param-pack elision.
    std::set<std::string> empty_value_pack_names;
    // A NON-empty function parameter pack (`Hs... hs`) expands to one parameter
    // PER ELEMENT, and each needs its own name — splicing only the types leaves
    // `int, long hs`, a single name on the LAST parameter, and every later read
    // of `hs` takes that one. Maps the source name to the generated per-element
    // names so the expansions below bind element-for-element.
    std::map<std::string, std::vector<std::string> > param_pack_element_names;
    // Member CLASS/FUNCTION template extent (member_class_template_extent):
    // while bi is inside one (past member_tpl_keep_begin — a function
    // template's head defaults stay on the collapse arm), a self template-id
    // whose args reference the MEMBER's own params keeps its spelled form
    // instead of collapsing.
    std::set<std::string> member_tpl_params;
    size_t member_tpl_extent_end = 0;
    size_t member_tpl_keep_begin = 0;
    for ( size_t bi = 0; bi < td.body.size(); ++bi )
    {
	if ( pack_pattern_skip_dots.count(bi) )
	    continue;
	TokenBase *bt = td.body[bi];
	if ( member_tpl_extent_end && bi >= member_tpl_extent_end )
	{
	    member_tpl_params.clear();
	    member_tpl_extent_end = 0;
	    member_tpl_keep_begin = 0;
	}
	// [temp.variadic] sizeof...(PACK) folds to the pack's ARITY at
	// substitution. Without this arm the dots copy through and the bare
	// pack name inside the parens hits the 1:1 fallback, manufacturing
	// `sizeof...(int32_t&)` (invalid C++) in replayed member-template
	// heads — libc++ tuple's ctor constraints, which the constraint
	// resolver then rejects (task #103). A MEMBER template's own pack
	// (`sizeof...(_Up)`) is not in the owner's subst maps and stays raw.
	std::string sop_pn_cls;
	if ( sizeof_pack_operand_name(td.body, bi, sop_pn_cls) )
	{
	    const std::string pn = sop_pn_cls;
	    std::map<std::string, std::vector<TokenDataType *> >
		::const_iterator tpi = pack_subst.find(pn);
	    std::map<std::string, std::vector<std::vector<TokenBase *> > >
		::const_iterator vpi = token_pack_subst.find(pn);
	    if ( tpi != pack_subst.end() || vpi != token_pack_subst.end() )
	    {
		size_t arity = tpi != pack_subst.end() ? tpi->second.size()
						       : vpi->second.size();
		TokenInt *ti = new TokenInt((int64_t)arity);
		ti->file = bt->file;
		ti->line = bt->line;
		ti->column = bt->column;
		inj.push_back(ti);
		bi += 6;
		continue;
	    }
	}
	// VALUE-pack expansions (task #102, libc++ __integer_sequence):
	// (a) a parenthesized PATTERN `( ... _Values ... )...` replicates the
	//     whole group once per element, the pack identifier swapped for
	//     that element's tokens ([temp.variadic] — `(_Values + _Sp)...`);
	// (b) a bare `_Values...` splices the element runs comma-separated.
	// An EMPTY pack drops the construct and balances one separating comma,
	// mirroring the empty TYPE-pack elision above.
	//
	// The guard admits EITHER pack kind, because the TEMPLATE-ID lane below
	// serves both and a `class... Ts` pack populates only pack_subst. Gating
	// this block on token_pack_subst alone made that lane UNREACHABLE for a
	// pure type pack — `struct impl : leaf<0, Ts>...` fell through to the
	// bare splice and produced the one wrong-arity base `leaf<0,A,B>` this
	// file's own comment warns about. It went unnoticed because both gates
	// were arity 1, where splice and replicate emit the same tokens.
	// Lanes (a) and (b) filter on token_pack_subst themselves, so widening
	// the guard leaves them unchanged.
	if ( bt && (!token_pack_subst.empty() || !pack_subst.empty()) )
	{
	    if ( bt->id() == TokenID::tkOpBrk )
	    {
		DelimDepth vdd;
		size_t after = bi;
		after += delim_scan_step(td.body, after, vdd);
		while ( after < td.body.size() && !vdd.top() )
		    after += delim_scan_step(td.body, after, vdd);
		bool has_dots = after + 2 < td.body.size()
		    && td.body[after] && td.body[after]->id() == TokenID::tkDot
		    && td.body[after+1] && td.body[after+1]->id() == TokenID::tkDot
		    && td.body[after+2] && td.body[after+2]->id() == TokenID::tkDot;
		const std::string *vpname = NULL;
		if ( has_dots )
		    for ( size_t k = bi + 1; k + 1 < after && !vpname; ++k )
			if ( td.body[k]
			  && td.body[k]->type() == TokenType::ttIdentifier )
			{
			    std::map<std::string,
				     std::vector<std::vector<TokenBase *> > >
				::const_iterator pit = token_pack_subst.find(
				    ((TokenIdent *)td.body[k])->spelling());
			    if ( pit != token_pack_subst.end() )
				vpname = &pit->first;
			}
		if ( vpname )
		{
		    const std::vector<std::vector<TokenBase *> > &elems =
			token_pack_subst[*vpname];
		    for ( size_t e = 0; e < elems.size(); ++e )
		    {
			if ( e )
			    inj.push_back(new TokenComma());
			for ( size_t k = bi; k < after; ++k )
			{
			    TokenBase *pt2 = td.body[k];
			    if ( !pt2 )
				continue;
			    if ( pt2->type() == TokenType::ttIdentifier
			      && ((TokenIdent *)pt2)->spelling() == *vpname )
			    {
				for ( TokenBase *et : elems[e] )
				    if ( et )
					inj.push_back(et->clone());
			    }
			    else
				inj.push_back(pt2->clone());
			}
		    }
		    if ( elems.empty() && !inj.empty()
		      && inj.back()->id() == TokenID::tkComma )
		    { delete inj.back(); inj.pop_back(); }
		    bi = after + 2;	// consume through the three dots
		    continue;
		}
	    }
	    // TEMPLATE-ID pattern expansion `Base<… Ts …>...` — the same rule as the
	    // parenthesized case above over a different delimiter. [temp.variadic]/5
	    // makes a base-specifier-list an expansion context (and a mem-initializer
	    // list with it), so libc++'s
	    //   __tuple_impl<__tuple_indices<_Indx...>, _Tp...> : __tuple_leaf<_Indx,_Tp>...
	    // must replicate the WHOLE template-id per element:
	    //   `leaf<0,Ts>...` -> `leaf<0,A>, leaf<0,B>`
	    // and NOT `leaf<0, A, B>`, which is what the bare pack-name splice below
	    // produces when the pack is nested inside a template-argument list — one
	    // base of the wrong arity, silently.
	    // Every pack named anywhere in the pattern binds in LOCKSTEP at the same
	    // index (rbREF3's `leaf<I, Ts>` walks a non-type index pack and a type
	    // pack together); a disagreement in their sizes is an arity violation, and
	    // this lane declines rather than mis-expanding — the pattern then reaches
	    // the ordinary path and fails loudly there.
	    {
		static const char *gate_probe = ::getenv("MADC_TPLPAT_GATE");
		if ( gate_probe && bt && bi + 1 < td.body.size()
		  && td.body[bi+1] && td.body[bi+1]->id() == TokenID::tkLT )
		    fprintf(stderr, "[tplgate] tok=%s type=%d ident=%d"
			    " packs=%zu/%zu\n",
			    template_token_fragment(bt).c_str(),
			    (int)bt->type(),
			    (int)(bt->type() == TokenType::ttIdentifier),
			    pack_subst.size(), token_pack_subst.size());
	    }
	    if ( bt && bt->type() == TokenType::ttIdentifier
	      && bi + 1 < td.body.size() && td.body[bi+1]
	      && td.body[bi+1]->id() == TokenID::tkLT
	      && (!pack_subst.empty() || !token_pack_subst.empty()) )
	    {
		// ONE tracker for the extent (delimiter-tracking.md): step the
		// template-id HEAD first so DelimDepth sees a template-id context
		// and reads the `<` as an argument list rather than less-than.
		DelimDepth tdd;
		size_t after = bi;
		after += delim_scan_step(td.body, after, tdd);
		if ( after < td.body.size() && td.body[after]
		  && td.body[after]->id() == TokenID::tkLT )
		{
		    after += delim_scan_step(td.body, after, tdd);
		    while ( after < td.body.size() && !tdd.top() )
			after += delim_scan_step(td.body, after, tdd);
		}
		// A MEM-INITIALIZER's pattern is `Base<…>( args )...` — the
		// argument list belongs to the pattern, since [temp.variadic]/5
		// makes the whole mem-initializer the expansion. Stopping at the
		// `>` finds no dots, declines, and hands the pack to the splice,
		// which puts it inside the TEMPLATE-ARGUMENT list instead:
		// `leaf<0,A,B>(hs)`. Same tracker, one more balanced group.
		// Correct ONLY because the parameter pack now expands to one
		// NAMED parameter per element (param_pack_element_names) and the
		// element loop below reads element e's name: without that, both
		// copies read the last parameter and the object is silently built
		// from the last argument twice.
		if ( after < td.body.size() && td.body[after]
		  && td.body[after]->id() == TokenID::tkOpBrk )
		{
		    after += delim_scan_step(td.body, after, tdd);
		    while ( after < td.body.size() && !tdd.top() )
			after += delim_scan_step(td.body, after, tdd);
		}
		bool has_dots = after + 2 < td.body.size()
		    && td.body[after] && td.body[after]->id() == TokenID::tkDot
		    && td.body[after+1] && td.body[after+1]->id() == TokenID::tkDot
		    && td.body[after+2] && td.body[after+2]->id() == TokenID::tkDot;
		size_t arity = 0;
		bool have_arity = false;
		bool lockstep_ok = true;
		if ( has_dots )
		    for ( size_t k = bi; k < after; ++k )
		    {
			if ( !td.body[k]
			  || td.body[k]->type() != TokenType::ttIdentifier )
			    continue;
			const std::string sp =
			    ((TokenIdent *)td.body[k])->spelling();
			size_t n = 0;
			bool is_pack = false;
			std::map<std::string, std::vector<TokenDataType *> >
			    ::const_iterator tpk = pack_subst.find(sp);
			if ( tpk != pack_subst.end() )
			{ n = tpk->second.size(); is_pack = true; }
			else
			{
			    std::map<std::string,
				     std::vector<std::vector<TokenBase *> > >
				::const_iterator vpk = token_pack_subst.find(sp);
			    if ( vpk != token_pack_subst.end() )
			    { n = vpk->second.size(); is_pack = true; }
			}
			if ( !is_pack )
			    continue;
			if ( have_arity && n != arity )
			    lockstep_ok = false;
			arity = n;
			have_arity = true;
		    }
		{
		    static const char *pat_probe = ::getenv("MADC_TPLPAT_PROBE");
		    if ( pat_probe && bt )
			fprintf(stderr, "[tplpat] head=%s dots=%d arity=%zu"
				" have=%d lockstep=%d extent=%zu -> %s\n",
				template_token_fragment(bt).c_str(),
				(int)has_dots, arity, (int)have_arity,
				(int)lockstep_ok, after - bi,
				(has_dots && have_arity && lockstep_ok)
				    ? "REPLICATE" : "decline");
		}
		if ( has_dots && have_arity && lockstep_ok )
		{
		    for ( size_t e = 0; e < arity; ++e )
		    {
			if ( e )
			    inj.push_back(new TokenComma());
			for ( size_t k = bi; k < after; ++k )
			{
			    TokenBase *pt2 = td.body[k];
			    if ( !pt2 )
				continue;
			    const std::string sp =
				pt2->type() == TokenType::ttIdentifier
				    ? ((TokenIdent *)pt2)->spelling()
				    : std::string();
			    std::map<std::string, std::vector<TokenDataType *> >
				::const_iterator tpk = sp.empty()
				    ? pack_subst.end() : pack_subst.find(sp);
			    if ( tpk != pack_subst.end() )
			    {
				if ( e < tpk->second.size() && tpk->second[e] )
				    inj.push_back(tpk->second[e]->clone());
				continue;
			    }
			    std::map<std::string,
				     std::vector<std::vector<TokenBase *> > >
				::const_iterator vpk = sp.empty()
				    ? token_pack_subst.end()
				    : token_pack_subst.find(sp);
			    if ( vpk != token_pack_subst.end() )
			    {
				if ( e < vpk->second.size() )
				    for ( TokenBase *et : vpk->second[e] )
					if ( et )
					    inj.push_back(et->clone());
				continue;
			    }
			    // The ctor's expanded PARAMETER pack: element e of
			    // `leaf<0,Hs>(hs)...` must read parameter e, not the
			    // one source name shared by every copy.
			    std::map<std::string, std::vector<std::string> >
				::const_iterator ppk = sp.empty()
				    ? param_pack_element_names.end()
				    : param_pack_element_names.find(sp);
			    if ( ppk != param_pack_element_names.end()
			      && e < ppk->second.size() )
			    {
				TokenIdent *ei2 =
				    new TokenIdent(ppk->second[e].c_str());
				ei2->file   = pt2->file;
				ei2->line   = pt2->line;
				ei2->column = pt2->column;
				inj.push_back(ei2);
				continue;
			    }
			    inj.push_back(pt2->clone());
			}
		    }
		    // An EMPTY pack drops the construct and balances one separating
		    // comma, mirroring the elisions above (`: A, B<Ts>...` with an
		    // empty Ts is `: A`, never `: A,`).
		    if ( arity == 0 && !inj.empty()
		      && inj.back()->id() == TokenID::tkComma )
		    { delete inj.back(); inj.pop_back(); }
		    bi = after + 2;	// consume through the three dots
		    continue;
		}
	    }
	    if ( bt->type() == TokenType::ttIdentifier )
	    {
		std::map<std::string,
			 std::vector<std::vector<TokenBase *> > >
		    ::const_iterator vit = token_pack_subst.find(
			((TokenIdent *)bt)->spelling());
		if ( vit != token_pack_subst.end()
		  && bi + 3 < td.body.size()
		  && td.body[bi+1] && td.body[bi+1]->id() == TokenID::tkDot
		  && td.body[bi+2] && td.body[bi+2]->id() == TokenID::tkDot
		  && td.body[bi+3] && td.body[bi+3]->id() == TokenID::tkDot )
		{
		    for ( size_t e = 0; e < vit->second.size(); ++e )
		    {
			if ( e )
			    inj.push_back(new TokenComma());
			for ( TokenBase *et : vit->second[e] )
			    if ( et )
				inj.push_back(et->clone());
		    }
		    if ( vit->second.empty() && !inj.empty()
		      && inj.back()->id() == TokenID::tkComma )
		    { delete inj.back(); inj.pop_back(); }
		    bi += 3;
		    continue;
		}
	    }
	}
	if ( !member_tpl_extent_end && bi > body_brace_index
	  && bt && bt->id() == TokenID::tkTEMPLATE )
	    member_tpl_extent_end =
		member_class_template_extent(td.body, bi, member_tpl_params,
					     member_tpl_keep_begin);
	if ( bt->type() == TokenType::ttIdentifier )
	{
	    const std::string &s = ((TokenIdent *)bt)->spelling();
	    // VALUE pack-expansion of an elided EMPTY parameter pack: `__tail...`
	    // in `_Inherited(__tail...)` must vanish (the param `__tail` was elided
	    // for the empty pack). Drop `__tail` + `...` and balance one separating
	    // comma (preceding if present, else a following one) so the call's
	    // argument list stays well-formed (`_Inherited(__tail...)` ->
	    // `_Inherited()`, `f(a, __tail...)` -> `f(a)`).
	    if ( empty_value_pack_names.count(s)
	      && bi + 3 < td.body.size()
	      && td.body[bi+1] && td.body[bi+1]->id() == TokenID::tkDot
	      && td.body[bi+2] && td.body[bi+2]->id() == TokenID::tkDot
	      && td.body[bi+3] && td.body[bi+3]->id() == TokenID::tkDot )
	    {
		bool dropped = false;
		if ( !inj.empty() && inj.back()->id() == TokenID::tkComma )
		{ delete inj.back(); inj.pop_back(); dropped = true; }
		bi += 3;   // consume `__tail` (current) + the three dots
		if ( !dropped && bi + 1 < td.body.size()
		  && td.body[bi+1] && td.body[bi+1]->id() == TokenID::tkComma )
		    ++bi;  // consume a following comma instead
		continue;
	    }
	    // The twin of the elision above for a NON-empty parameter pack: the
	    // declaration expanded to one NAMED parameter per element, so a bare
	    // value expansion `ts...` (`_Inherited(__tail...)`,
	    // `impl<Ts...>(ts...)`) must splice those generated names. Without
	    // this the use site still says `ts`, which no longer exists —
	    // "use of undeclared identifier 'ts'".
	    {
		std::map<std::string, std::vector<std::string> >::const_iterator
		    ppn = param_pack_element_names.find(s);
		if ( ppn != param_pack_element_names.end()
		  && bi + 3 < td.body.size()
		  && td.body[bi+1] && td.body[bi+1]->id() == TokenID::tkDot
		  && td.body[bi+2] && td.body[bi+2]->id() == TokenID::tkDot
		  && td.body[bi+3] && td.body[bi+3]->id() == TokenID::tkDot )
		{
		    for ( size_t gi = 0; gi < ppn->second.size(); ++gi )
		    {
			if ( gi )
			    inj.push_back(new TokenComma());
			TokenIdent *gn =
			    new TokenIdent(ppn->second[gi].c_str());
			gn->file   = bt->file;
			gn->line   = bt->line;
			gn->column = bt->column;
			inj.push_back(gn);
		    }
		    bi += 3;   // consume the name (current) + the three dots
		    continue;
		}
	    }
	    std::map<std::string, TokenDataType *>::iterator si = subst.find(s);
	    if ( si != subst.end() ) { inj.push_back(si->second->clone()); continue; }
	    std::map<std::string, std::vector<TokenBase *> >::iterator nti =
		token_subst.find(s);
	    if ( nti != token_subst.end() )
	    {
		for ( size_t ni = 0; ni < nti->second.size(); ++ni )
		    inj.push_back(nti->second[ni]->clone());
		continue;
	    }
	    std::map<std::string, std::vector<TokenDataType *> >::iterator pki =
		pack_subst.find(s);
	    // An ABSENT trailing pack (`C<int>` against `C<T, A...>`) records
	    // NO pack_subst entry at all (the arg loop's "leave pack_subst
	    // without an entry" case) — route it through the SAME empty-pack
	    // elision as a present-but-empty entry, or the raw `A ...` tokens
	    // survive into the clone (`__is_constructible(T, A...)` became
	    // `__is_constructible(int, A...)` and the trait Threw).
	    static const std::vector<TokenDataType *> absent_pack_elems;
	    const std::vector<TokenDataType *> *pack_elems_p =
		pki != pack_subst.end() ? &pki->second : NULL;
	    if ( !pack_elems_p )
		for ( size_t tp = 0; tp < td.typeparams.size(); ++tp )
		    if ( td.typeparams[tp] == s
		      && tp < td.typeparam_is_pack.size()
		      && td.typeparam_is_pack[tp] )
		    {
			pack_elems_p = &absent_pack_elems;
			break;
		    }
	    if ( pack_elems_p )
	    {
		// Pack expansion `_Types...`: emit the absorbed element types
		// comma-separated. An EMPTY pack (the common allocator-rebind
		// case) must drop the immediately-preceding `,` already emitted
		// (so `C<_Up, _Types...>` -> `C<_Up>`, never `C<_Up,>`). The
		// trailing `...` (three tkDot) in the body is then consumed.
		const std::vector<TokenDataType *> &elems = *pack_elems_p;
		// EMPTY function-PARAMETER pack with a declarator suffix
		// (`const _Tail&... __tail`): the pack name is followed by cv/ref/ptr
		// tokens THEN `...`. The whole parameter — leading cv already in
		// `inj`, its separating comma, the suffix, the `...`, and the param
		// name — must vanish (`(const _Head& h, const _Tail&... t)` ->
		// `(const _Head& h)`). The generic comma-drop below only handles an
		// immediately-preceding comma, so handle the suffixed pattern here.
		if ( elems.empty() )
		{
		    size_t pj = bi + 1;
		    while ( pj < td.body.size() && td.body[pj]
		      && (td.body[pj]->id() == TokenID::tkBand
		       || td.body[pj]->id() == TokenID::tkLand
		       || td.body[pj]->id() == TokenID::tkMul
		       || td.body[pj]->id() == TokenID::tkCONST
		       || td.body[pj]->id() == TokenID::tkVOLATILE) )
			++pj;
		    bool param_pack = pj > bi + 1 && pj + 2 < td.body.size()
			&& td.body[pj] && td.body[pj]->id() == TokenID::tkDot
			&& td.body[pj+1] && td.body[pj+1]->id() == TokenID::tkDot
			&& td.body[pj+2] && td.body[pj+2]->id() == TokenID::tkDot;
		    if ( param_pack )
		    {
			// Record the elided parameter name (`__tail`, the first
			// identifier after the `...`) so its VALUE pack-expansion
			// `__tail...` in the body / mem-init is elided too.
			if ( pj + 3 < td.body.size() && td.body[pj+3]
			  && is_contextual_identifier_token(td.body[pj+3]) )
			    empty_value_pack_names.insert(
				contextual_identifier_name(td.body[pj+3]));
			while ( !inj.empty()
			  && (inj.back()->id() == TokenID::tkCONST
			   || inj.back()->id() == TokenID::tkVOLATILE) )
			{ delete inj.back(); inj.pop_back(); }
			bool popped_comma = false;
			if ( !inj.empty() && inj.back()->id() == TokenID::tkComma )
			{ delete inj.back(); inj.pop_back(); popped_comma = true; }
			size_t pk = pj + 3;
			int pdepth = 0;
			while ( pk < td.body.size() && td.body[pk] )
			{
			    TokenID kid = td.body[pk]->id();
			    if ( kid == TokenID::tkOpBrk || kid == TokenID::tkLT )
				++pdepth;
			    else if ( kid == TokenID::tkClBrk )
			    { if ( pdepth == 0 ) break; --pdepth; }
			    else if ( kid == TokenID::tkGT && pdepth > 0 )
				--pdepth;
			    else if ( pdepth == 0 && kid == TokenID::tkComma )
			    { if ( !popped_comma ) ++pk; break; }
			    else if ( pdepth == 0
			      && (kid == TokenID::tkSemi || kid == TokenID::tkClBrc) )
				break;
			    ++pk;
			}
			bi = pk - 1;   // loop ++bi resumes after the elided param
			continue;
		    }
		}
		if ( elems.empty() && !inj.empty()
		  && inj.back()->id() == TokenID::tkComma )
		{
		    delete inj.back();
		    inj.pop_back();
		}
		// NON-EMPTY function PARAMETER pack (`Hs... hs`, `const Hs&... hs`):
		// a pack expansion in a parameter-declaration is N DECLARATIONS, so
		// each element needs its OWN name. Splicing only the types yields
		// `int, long hs` — one name, on the LAST parameter — and both
		// replicated mem-initializers then read that single parameter, so the
		// object is built from the last argument twice (measured a=9 b=9 where
		// both oracles say a=7 b=9). The declaration shape is the same one the
		// EMPTY arm above detects: pack name, optional cv/ref/ptr suffix, the
		// three dots, then an IDENTIFIER (a template-ARGUMENT list has `>` or
		// `,` there instead, which is why this cannot fire on `X<Hs...>`).
		{
		    size_t sj = bi + 1;
		    while ( sj < td.body.size() && td.body[sj]
		      && (td.body[sj]->id() == TokenID::tkBand
		       || td.body[sj]->id() == TokenID::tkLand
		       || td.body[sj]->id() == TokenID::tkMul
		       || td.body[sj]->id() == TokenID::tkCONST
		       || td.body[sj]->id() == TokenID::tkVOLATILE) )
			++sj;
		    if ( !elems.empty() && sj + 3 < td.body.size()
		      && td.body[sj] && td.body[sj]->id() == TokenID::tkDot
		      && td.body[sj+1] && td.body[sj+1]->id() == TokenID::tkDot
		      && td.body[sj+2] && td.body[sj+2]->id() == TokenID::tkDot
		      && td.body[sj+3]
		      && is_contextual_identifier_token(td.body[sj+3]) )
		    {
			const std::string pname =
			    contextual_identifier_name(td.body[sj+3]);
			std::vector<std::string> &gen =
			    param_pack_element_names[pname];
			gen.clear();
			for ( size_t ei = 0; ei < elems.size(); ++ei )
			{
			    if ( ei )
				inj.push_back(new TokenComma());
			    inj.push_back(elems[ei]->clone());
			    for ( size_t sk = bi + 1; sk < sj; ++sk )
				if ( td.body[sk] )
				    inj.push_back(td.body[sk]->clone());
			    // A ONE-element pack keeps the SOURCE name, so
			    // every arity-1 expansion stays byte-identical to
			    // what it was before per-element naming existed —
			    // the rename is only needed where there is more
			    // than one parameter to tell apart, and any use
			    // site this walker does not rewrite (a declining
			    // pattern, an unhandled expansion shape) then still
			    // resolves instead of reading "undeclared 'ts'".
			    std::string en = elems.size() == 1
				? pname
				: pname + "__" + std::to_string(ei);
			    gen.push_back(en);
			    TokenIdent *ni = new TokenIdent(en.c_str());
			    ni->file   = td.body[sj+3]->file;
			    ni->line   = td.body[sj+3]->line;
			    ni->column = td.body[sj+3]->column;
			    inj.push_back(ni);
			}
			bi = sj + 3;   // loop ++bi resumes after the param name
			continue;
		    }
		}
		for ( size_t ei = 0; ei < elems.size(); ++ei )
		{
		    if ( ei )
		        inj.push_back(new TokenComma());
		    inj.push_back(elems[ei]->clone());
		}
		if ( bi + 3 < td.body.size()
		  && td.body[bi+1]->id() == TokenID::tkDot
		  && td.body[bi+2]->id() == TokenID::tkDot
		  && td.body[bi+3]->id() == TokenID::tkDot )
		    bi += 3;   // consume the pack-expansion ellipsis
		else if ( elems.size() == 1 )
		{
		    // Pack expansion PATTERN: the pack name is NOT immediately
		    // followed by `...` (e.g. `const _Elements&...`), so the single
		    // element was substituted in place above, leaving the pattern's
		    // trailing `...` orphaned. Find it (the next three tkDot at the
		    // pack's own nesting depth, before any `,`/`)`/`;`/`{`) and skip
		    // it. Single-element only — a multi-arg pack pattern needs the
		    // pattern REPEATED per element (not yet supported; left to error).
		    int depth = 0;
		    for ( size_t j = bi + 1; j + 2 < td.body.size(); ++j )
		    {
			TokenID jid = td.body[j]->id();
			if ( jid == TokenID::tkLT || jid == TokenID::tkOpBrk
			  || jid == TokenID::tkOpSqr )
			    ++depth;
			else if ( jid == TokenID::tkGT || jid == TokenID::tkClBrk
			  || jid == TokenID::tkClSqr )
			    --depth;
			else if ( jid == TokenID::tkBSR )
			    depth -= 2;
			else if ( depth <= 0 && jid == TokenID::tkDot
			  && td.body[j+1]->id() == TokenID::tkDot
			  && td.body[j+2]->id() == TokenID::tkDot )
			{
			    pack_pattern_skip_dots.insert(j);
			    pack_pattern_skip_dots.insert(j + 1);
			    pack_pattern_skip_dots.insert(j + 2);
			    break;
			}
			else if ( depth <= 0
			  && (jid == TokenID::tkComma || jid == TokenID::tkClBrk
			   || jid == TokenID::tkSemi || jid == TokenID::tkOpBrc) )
			    break;   // pattern boundary, no `...` found
			if ( depth < 0 )
			    break;
		    }
		}
		continue;
	    }
	    if ( s == td.class_name )
	    {
		// A namespace-QUALIFIED reference to a same-named template in
		// a DIFFERENT namespace (`__gnu_cxx::char_traits<_CharT>` as
		// std::char_traits' base) is not a self-reference — renaming
		// it (and swallowing its <...>) corrupts the base/typedef.
		// Leave it for normal qualified resolution.
		bool foreign_qualified =
		    bi >= 2 && td.body[bi-1]
		    && td.body[bi-1]->id() == TokenID::tkNS
		    && td.body[bi-2]
		    && is_contextual_identifier_token(td.body[bi-2])
		    && contextual_identifier_name(td.body[bi-2])
		       != td.defining_namespace;
		if ( !foreign_qualified )
		{
		    // A self-name USED AS A TEMPLATE in the BASE CLAUSE
		    // (`_Tuple_impl<_Idx+1, _Tail...>` as a base of
		    // `_Tuple_impl<_Idx,_Head,_Tail...>`) is a DISTINCT specialization
		    // the class inherits — NOT the injected-class-name. Keep the name
		    // and its `<...>` so the surrounding clone loop substitutes the
		    // args (`_Idx+1`->`0+1`, `_Tail...` expands) and it re-parses as a
		    // fresh template-id, instantiating the right base. Collapsing it to
		    // the mangled self made the class try to inherit from itself
		    // ("Unknown base class"). In the BODY (method signatures), a self
		    // template-id stays collapsed as before.
		    bool self_as_template =
			bi + 1 < td.body.size()
			&& td.body[bi + 1]->id() == TokenID::tkLT;
		    bool self_template_base =
			bi < body_brace_index && self_as_template;
		    // In the BODY, a self-name template-id whose ARGS DIFFER from the
		    // template's own parameters is a DISTINCT specialization, NOT the
		    // injected-class-name — keep it distinct so the clone loop
		    // substitutes its args and it re-instantiates. The primary
		    // `_Tuple_impl`'s `typedef _Tuple_impl<_Idx+1,_Tail...> _Inherited;`
		    // (the empty-tuple recursion terminator) MUST resolve to
		    // `_Tuple_impl<1>`, not collapse to the current instantiation —
		    // collapsing made its ctor's `: _Inherited()` a delegating
		    // self-call -> infinite recursion -> stack overflow at run time. The
		    // true injected-class-name (`tuple<_Tp>` == the template's own
		    // params) still collapses below.
		    bool self_template_body_distinct =
			!self_template_base && self_as_template
			&& self_template_id_keep_distinct(td, td.body, bi + 1);
		    // A self template-id whose args reference the enclosing
		    // member CLASS/FUNCTION template's OWN params (`alloc9<U>`
		    // in `template<class U> struct rebind`, or in a converting
		    // ctor `template<class U> alloc9(const alloc9<U>&)`) names
		    // a specialization that exists only once the MEMBER
		    // instantiates — keep the name and its `<...>` spelled so
		    // the member's own substitution resolves it then.
		    // Collapsing it bound libc++'s
		    // `allocator<T>::rebind<U>::other` to the CURRENT
		    // instantiation (tests/testmemtplrebind.mad), and turned
		    // the converting ctor into a copy-ctor signature the
		    // construction KIND could never deduce against
		    // (tests/testconvctor.mad). keep_begin excludes a function
		    // template's HEAD (its SFINAE defaults re-parse eagerly at
		    // registration — the tuple<_Up> collapse guard).
		    bool self_template_member_distinct =
			!self_template_base && self_as_template
			&& bi >= member_tpl_keep_begin
			&& template_id_args_reference_names(td.body, bi + 1,
							    member_tpl_params);
		    if ( self_template_member_distinct )
		    {
			static const char *mdp = ::getenv("MADC_MEMDIST_PROBE");
			if ( mdp )
			{
			    std::cerr << "[memdist] " << td.class_name
				<< " keeps self template-id at bi=" << bi
				<< " params={";
			    for ( std::set<std::string>::const_iterator pi =
				    member_tpl_params.begin();
				  pi != member_tpl_params.end(); ++pi )
				std::cerr << (pi == member_tpl_params.begin()
					      ? "" : ",") << *pi;
			    std::cerr << "}" << std::endl;
			}
		    }
		    if ( self_template_base || self_template_body_distinct
		      || self_template_member_distinct )
		    {
			inj.push_back(bt->clone());   // keep class_name; args substitute below
			continue;
		    }
		    TokenIdent *ni = (TokenIdent *)bt->clone();
		    set_token_spelling(ni, mangled);
		    inj.push_back(ni);
		    if ( bi + 1 < td.body.size()
		      && td.body[bi + 1]->id() == TokenID::tkLT )
		    {
			// Self-name USED AS A TEMPLATE (`tuple<_Tp>` inside
			// tuple's body == std::tuple<_Tp>, a DIFFERENT type):
			// the mangled current-instantiation name does not take
			// args, so swallow the `<...>`. If the suffix ends at a
			// `>>` that also closed an ENCLOSING template-id (e.g.
			// `_UseOtherCtor<_Tuple, tuple<_Up>>`), re-emit the
			// leftover `>` so the outer template-id stays balanced —
			// otherwise the spelling scanner runs past it into the
			// class body.
			bool split_gt = false;
			bi = template_id_suffix_end(td.body, bi + 1, &split_gt);
			if ( split_gt )
			    inj.push_back(new TokenGT());
		    }
		    continue;
		}
	    }
	}
	inj.push_back(bt->clone());
    }
    // Terminate the class definition so the class parser stops cleanly without
    // consuming the caller's following tokens (e.g. the declared variable name).
    TokenSemi *semi = new TokenSemi();
    inj.push_back(semi);
    // Restore the live parse position now that all instantiation clones are made;
    // nextToken() will re-derive _parse_file from each injected token as the class
    // re-parses (the clones now carry the template's true origin file).
    TokenBase::_parse_file = cloned_pf;
    TokenBase::_parse_line = cloned_pl;
    TokenBase::_parse_column = cloned_pc;

    DBG(std::cout << "instantiate_template_use(): injecting " << inj.size()
	<< " tokens for " << mangled << std::endl);
    // Env-gated probe (MADC_INJ_PROBE=<substr of the mangled key>): the FULL
    // injected token sequence — the unbalanced-body / over-consumption
    // diagnostic (a desync here eats the caller's declarator).
    {
	static const char *ijp = ::getenv("MADC_INJ_PROBE");
	if ( ijp && *ijp && mangled.find(ijp) != std::string::npos )
	{
	    fprintf(stderr, "[inj] %s n=%zu:", mangled.c_str(), inj.size());
	    for ( size_t ii = 0; ii < inj.size(); ++ii )
		fprintf(stderr, " %s",
			inj[ii] ? template_token_fragment(inj[ii]).c_str() : "?");
	    fprintf(stderr, "\n");
	}
    }

    // Inject to the FRONT of the parse deque (push_front in reverse so they
    // dequeue in order), then re-parse the class definition via its keyword token.
    for ( std::vector<TokenBase *>::reverse_iterator it = inj.rbegin(); it != inj.rend(); ++it )
	pushToken(*it);
    // Re-parse the injected class definition at TOP-LEVEL scope. Instantiation
    // is triggered mid-statement (e.g. while parsing `Box<int> b;` inside a
    // function), so the enclosing function's compound scope is active — without
    // this the class's methods would be registered as nested/local functions
    // (id `caller__Class__method__N`), breaking call-site resolution. Save and
    // clear the function context, instantiate, then restore.
    std::stack<TokenCpnd *> saved_compounds;
    std::swap(compounds, saved_compounds);
    // The block-typedef shadow frames belong to the swapped-out compound
    // context — swap them in lockstep or the fresh context's pop/push unwinds
    // the CALLER's block-scope typedefs mid-body.
    std::vector<std::vector<std::pair<std::string, TokenDataType *> > >
	saved_typedef_shadows;
    std::swap(block_typedef_shadows, saved_typedef_shadows);
    std::vector<DataDefCLASS *> saved_class_scope_stack;
    std::swap(class_scope_stack, saved_class_scope_stack);
    std::string saved_func = cur_func_name;
    cur_func_name.clear();
    // The instantiated body is a self-contained, fully-terminated class
    // definition (its own struct/class keyword + a synthesized trailing ';',
    // injected above). It must be parsed in FULL, never inheriting the caller's
    // parse MODE: an enclosing nested-class delegation (TokenSTRUCT/TokenCLASS
    // member loop) leaves class_definition_only / parsing_cpp_struct_class set,
    // which would make this re-parse early-return at the body's '}' and leave
    // the terminating ';' to derail the caller (e.g. a template-id base clause
    // `struct I : bf<int> {...}`). Top-level instantiation already runs with
    // these clear; isolate the nested case to match.
    bool saved_def_only = class_definition_only;
    bool saved_cpp_struct_class = parsing_cpp_struct_class;
    bool saved_cpp_union_class = parsing_cpp_union_class;
    class_definition_only = false;
    parsing_cpp_struct_class = false;
    parsing_cpp_union_class = false;

    // Stashed around the re-parse; TokenCLASS::parse records it on the DataDefCLASS
    // so a bodyless method binds to the real C++ symbol without class-name tests.
    std::string saved_canon = instantiating_canonical_spelling;
    bool saved_dependent_surface = instantiating_dependent_surface;
    instantiating_canonical_spelling = canon;
    instantiating_dependent_surface = dependent_surface;
    NamespaceScope ns_scope(*this, td.defining_namespace);

    bool pushed_owner_scope = false;
    if ( td.owner_class )
    {
	class_scope_stack.push_back(td.owner_class);
	pushed_owner_scope = true;
    }

    // While re-parsing a dependent-member-base forwarding trait, keep variadic
    // real-instantiation ON (sticky) so the base `Base<...>::type` and any nested
    // forwarding template in it really instantiate, and register this mangled name
    // so a self-referential re-entry bounds out to the opaque placeholder. RAII —
    // restores on both the normal and the catch path below.
    struct StickyGuard {
	Program &p; std::string key; bool active; bool saved; bool inserted;
	StickyGuard(Program &pp, const std::string &k, bool on)
	    : p(pp), key(k), active(on), saved(pp.variadic_real_inst_sticky),
	      inserted(false)
	{
	    if ( active )
	    {
		p.variadic_real_inst_sticky = true;
		inserted = p.variadic_inst_in_progress.insert(key).second;
	    }
	}
	~StickyGuard()
	{
	    if ( active )
	    {
		p.variadic_real_inst_sticky = saved;
		if ( inserted )
		    p.variadic_inst_in_progress.erase(key);
	    }
	}
    } sticky_guard(*this, registered_mangled, want_sticky);

    // [temp.inst]: the instantiation itself is never an unevaluated operand —
    // member bodies re-parsed here are real program code, so calls inside them
    // must instantiate normally even when this class was first NAMED inside a
    // decltype/sizeof operand (`typedef decltype(H<It>::call(...))` left
    // H<It>'s body calls uninstantiated: raw MIR imports + placeholder-typed
    // returns). The fn-template binding twin zeroes the depth the same way
    // around its body parse. RAII — restores on the catch path too.
    struct UnevalZeroGuard {
	Program &p; int saved;
	UnevalZeroGuard(Program &pp)
	    : p(pp), saved(pp.unevaluated_operand_depth)
	{ p.unevaluated_operand_depth = 0; }
	~UnevalZeroGuard() { p.unevaluated_operand_depth = saved; }
    } uneval_zero_guard(*this);

    // The re-parse below is an instantiation in flight exactly like a pattern
    // serve: mark it so a self-referential re-entry (base clause naming this
    // very specialization as a template argument) is served the incomplete
    // shell by the cache-hit branch instead of re-instantiating forever.
    ClassInstInFlightGuard reparse_in_flight(class_inst_in_progress,
					     registered_mangled);

    ClassParseCensusScope class_parse_scope(*this, class_profile_identity,
	legacy_reason, canon);

    TokenBase *class_kw = nextToken();   // the injected `class` keyword
    try
    {
	parseKeyword((TokenKeyword *)class_kw); // TokenCLASS::parse → registers DataDefCLASS
    }
    catch ( ... )
    {
	// EXCEPTION-SAFE RESTORE. parseKeyword swapped `compounds` / class_scope_stack
	// / cur_func_name / the cpp-struct flags / the instantiating_* stash to a fresh
	// empty context above. If it THROWS (a benign error during a nested resolution
	// — e.g. instantiating a conditional_t default — that is caught UPSTREAM), the
	// restore below would be skipped, leaving `compounds` swapped-out EMPTY. The
	// caller then parses with no local scope, so its own locals/params vanish: this
	// is why `__uninitialized_move_if_noexcept_a`'s `__last` param became "undeclared"
	// (compounds=0) after a prior argument's nested instantiation threw-and-recovered.
	// Mirror the normal-path restore, then rethrow. (NamespaceScope is already RAII.)
	if ( pushed_owner_scope && !class_scope_stack.empty()
	  && class_scope_stack.back() == td.owner_class )
	    class_scope_stack.pop_back();
	std::swap(class_scope_stack, saved_class_scope_stack);
	std::swap(compounds, saved_compounds);
	// Unwind the fresh context's frames FIRST (a swallowed throw can leave
	// them un-popped with their flat entries live), THEN restore the caller's.
	unwind_block_typedef_shadows(0, "A-catch");
	std::swap(block_typedef_shadows, saved_typedef_shadows);
	cur_func_name = saved_func;
	class_definition_only = saved_def_only;
	parsing_cpp_struct_class = saved_cpp_struct_class;
	parsing_cpp_union_class = saved_cpp_union_class;
	instantiating_canonical_spelling = saved_canon;
	instantiating_dependent_surface = saved_dependent_surface;
	throw;
    }

    if ( pushed_owner_scope
      && !class_scope_stack.empty()
      && class_scope_stack.back() == td.owner_class )
	class_scope_stack.pop_back();

    std::swap(class_scope_stack, saved_class_scope_stack);
    std::swap(compounds, saved_compounds);
    unwind_block_typedef_shadows(0, "A-norm");
    std::swap(block_typedef_shadows, saved_typedef_shadows);
    cur_func_name = saved_func;
    class_definition_only = saved_def_only;
    parsing_cpp_struct_class = saved_cpp_struct_class;
    parsing_cpp_union_class = saved_cpp_union_class;
    instantiating_canonical_spelling = saved_canon;
    instantiating_dependent_surface = saved_dependent_surface;

    // Attach any out-of-line member definitions (`Class<T>::member` in a .tcc) of
    // this template to the freshly-instantiated class as deferred (ODR-use-lazy)
    // member bodies. Keyed on the PRIMARY template's name+ns and the use-site args
    // (arg_*_by_slot), so the def's type-parameters map positionally to concretes.
    {
	datadef_map_citer sm = struct_map.find(registered_mangled);
	DataDefCLASS *inst_ddc = sm != struct_map.end()
	    ? dynamic_cast<DataDefCLASS *>(sm->second) : NULL;
	attach_outofline_member_instantiations(td.class_name,
	    td.defining_namespace, registered_mangled, inst_ddc,
	    arg_types_by_slot, arg_tokens_by_slot);
	// Out-of-line NESTED-CLASS definitions (basic_istream's sentry) parse
	// eagerly with the owner — the owner's member bodies name the type.
	instantiate_outofline_nested_classes(td.class_name,
	    td.defining_namespace, registered_mangled, arg_tokens_by_slot);
    }

    flat_datatype_map_iter now = datatype_map.find(registered_mangled);
    if ( now == datatype_map.end() )
	Throw(tb) << "internal: template instantiation " << registered_mangled << " did not register" << flush;
    DBG(std::cout << "instantiate_template_use(): instantiated " << registered_mangled << std::endl);
    return use_site_type_token((TokenDataType *)(*now), tb);
}

bool Program::alias_use_args_all_concrete(const TemplateAliasDef &td,
		     const std::vector<std::vector<TokenBase *> > &arg_tokens)
{
    // This is a cheap CONCRETENESS PREDICATE, not the real resolution: it must not
    // trigger variadic real-instantiation, or the per-arg resolves below cascade
    // into the alias-use ↔ concreteness-check recursion (stack overflow). The actual
    // fold happens in the body-resolve of the caller, where the flag is honored.
    bool saved_vri = allow_variadic_real_inst;
    allow_variadic_real_inst = false;
    bool pushed_owner_scope = false;
    if ( td.owner_class )
    {
	class_scope_stack.push_back(td.owner_class);
	pushed_owner_scope = true;
    }
    bool all_concrete = true;
    for ( size_t i = 0; i < arg_tokens.size() && all_concrete; ++i )
    {
	// Default to "type" when the slot kind is unknown (pack tails); a type
	// arg is the stricter classification (it must RESOLVE non-dependently).
	bool is_type = i < td.typeparam_is_type.size()
		     ? td.typeparam_is_type[i] : true;
	if ( !is_type )
	{
	    // A non-type arg is concrete iff it constant-folds; a still-dependent
	    // arg (`bwr<_Tp>::value` with `_Tp` unbound) Throws and is caught here.
	    int64_t v = 0;
	    if ( !fold_nontype_arg_constant(arg_tokens[i], v) )
		all_concrete = false;
	    continue;
	}
	// A type arg is concrete iff it resolves (in an isolated stream, the same
	// idiom as the body resolution below) to a type with no unresolved
	// dependent surface — `NT*` concrete, `_Tp*`/a dependent placeholder not.
	std::vector<TokenBase *> body;
	for ( TokenBase *t : arg_tokens[i] )
	    if ( t )
		body.push_back(t->clone());
	body.push_back(new TokenSemi());
	size_t saved_diag_count = diagnostics.size();
	Program::ErrorInfo saved_error = last_error;
	TokenStream::State saved_tokens = tokens.swap_in(std::move(body));
	TokenDataType *rt = NULL;
	try
	{
	    rt = resolve_declared_type_token(nextToken(), true, true);
	}
	catch ( ... ) { rt = NULL; }
	tokens.swap_back(std::move(saved_tokens));
	diagnostics.resize(saved_diag_count);
	last_error = saved_error;
	if ( !rt || datadef_has_unresolved_dependent_surface(&rt->definition) )
	    all_concrete = false;
    }
    if ( pushed_owner_scope
      && !class_scope_stack.empty()
      && class_scope_stack.back() == td.owner_class )
	class_scope_stack.pop_back();
    allow_variadic_real_inst = saved_vri;
    return all_concrete;
}

TokenDataType *Program::namespace_chain_datatype(const std::string &nm)
{
    std::string scope = current_namespace();
    while ( !scope.empty() )
    {
	namespace_datatype_map_t::iterator nti =
	    namespace_datatype_map.find(scope);
	if ( nti != namespace_datatype_map.end() )
	{
	    datatype_map_iter ndmi = nti->find(nm);
	    if ( ndmi != nti->end() )
		return ndmi->second;
	}
	size_t sp = scope.rfind("::");
	scope = sp == std::string::npos ? std::string() : scope.substr(0, sp);
    }
    return NULL;
}

bool Program::alias_arg_tokens_dependent(const std::vector<TokenBase *> &toks)
{
    TokenBase *prev = NULL;
    for ( TokenBase *t : toks )
    {
	if ( !t )
	    continue;
	// A MEMBER name (`__not_<...>::value`) is looked up in its owner, not
	// in scope — its unresolvability here says nothing about dependence
	// (every trait's `::value` would otherwise classify dependent and
	// silently skip the [temp.deduct]/8 validation in dependent parses).
	// The OWNER name before the `::` still classifies normally.
	bool after_scope_op = prev && prev->id() == TokenID::tkNS;
	prev = t;
	// The `typename` DISAMBIGUATOR ([temp.res]) marks the following
	// qualified-id as a type — it is not a name to look up, and its
	// presence says nothing about dependence once the surrounding tokens
	// are substituted concrete (`_If<..., typename iterator_traits<_Iter>::
	// iterator_category>` at _Iter=int*). Classifying it "unresolvable"
	// poisoned every alias arg spelled with it (libc++ iterator_traits web).
	if ( is_contextual_identifier_token(t)
	  && contextual_identifier_name(t) == "typename" )
	    continue;
	if ( !after_scope_op && is_contextual_identifier_token(t) )
	{
	    const std::string nm = contextual_identifier_name(t);
	    if ( resolve_template_param(nm) )
	    {
		if ( vri_debug_enabled() )
		    fprintf(stderr, "[vriprobe] argdep: tparam %s\n", nm.c_str());
		return true;
	    }
	    // An identifier that resolves to NOTHING in scope — not a type,
	    // value, or template — names a template parameter whose frame is
	    // not active (a member alias template's OWN param `_Iter` inside
	    // its declaration: `__enable_if_t<is_convertible<_Iter,...>>`).
	    // That is DEPENDENT, not a substitution failure; a genuine SFINAE
	    // miss (enable_if<false,T>::type) has every name resolvable and
	    // still fails composition.
	    const uint32_t nm_id = template_name_pool.intern(nm);
	    if ( datatype_map.find(nm) == datatype_map.end()
	      && !namespace_chain_datatype(nm)
	      && !findVariable(nm)
	      && !find_template(nm_id, std::string(), NULL)
	      && !find_template_alias(nm_id, std::string(), NULL)
	      && !namespace_map.count(nm)
	      && !resolve_builtin_type_spelling(nm) )
	    {
		if ( vri_debug_enabled() )
		    fprintf(stderr, "[vriprobe] argdep: unresolvable %s\n", nm.c_str());
		return true;
	    }
	}
	if ( t->type() == TokenType::ttDataType
	  && datadef_has_unresolved_dependent_surface(
		&((TokenDataType *)t)->definition) )
	{
	    if ( vri_debug_enabled() )
		fprintf(stderr, "[vriprobe] argdep: dep-surface type %s\n",
			((TokenDataType *)t)->definition.name.c_str());
	    return true;
	}
    }
    return false;
}

TokenDataType *Program::instantiate_template_alias_use(const std::string &tname,
						     TokenBase *tb,
						     const std::string &ns_hint,
						     DataDefCLASS *owner_hint)
{
    InstTimer _it(*this, _inst_alias_count);	// --show-stats
    const uint32_t tname_id = template_name_pool.intern(tname);
    const Program::TemplateAliasDef *tdp = find_template_alias(
	tname_id, ns_hint, owner_hint);
    if ( !tdp )
	return NULL;
    if ( !peekToken() || peekToken()->id() != TokenID::tkLT )
	return NULL;
    // COPY the def by value: find_template_alias returns a pointer into the
    // template_alias_map vector, and resolving the template arguments below
    // instantiates other templates/aliases, which call register_template_alias
    // and can REALLOCATE that vector — dangling a reference. (Symptom: a
    // member alias template like __conditional<B>::type read back 0 typeparams
    // after its args resolved, so `type<T,U>` wrongly "expects 0 type
    // arguments".) The copy is self-contained: typeparams/defaults are value
    // vectors and target holds cloned token pointers not stored in that vector.
    Program::TemplateAliasDef td = *tdp;
    if ( !td.registry_name_id )
	td.registry_name_id = tname_id;
    if ( td.has_non_type_params )
    {
	nextToken(); // consume '<'
	std::vector<std::string> args;
	std::vector<std::vector<TokenBase *> > arg_tokens;
	for (;;)
	{
	    TokenBase *at = nextToken();
	    std::string spelling;
	    std::vector<TokenBase *> toks;
	    TokenBase *sep = collect_template_argument_spelling(at, spelling,
								&toks);
	    args.push_back(spelling);
	    arg_tokens.push_back(toks);
	    if ( sep->id() == TokenID::tkComma )
		continue;
	    if ( consume_template_close(sep) )
		break;
	    Throw(sep) << "Expecting ',' or '>' in " << tname << "<...>" << flush;
	}
	while ( args.size() < td.typeparams.size() )
	{
	    size_t ai = args.size();
	    if ( ai >= td.typeparam_defaults.size()
	      || td.typeparam_defaults[ai].empty() )
		break;
	    std::string spelling;
	    std::vector<TokenBase *> toks;
	    for ( TokenBase *dt : td.typeparam_defaults[ai] )
	    {
		spelling += template_token_fragment(dt);
		toks.push_back(dt->clone());
	    }
	    args.push_back(spelling);
	    arg_tokens.push_back(toks);
	}

	if ( tname == "__detected_or_t" && arg_tokens.size() >= 2 )
	{
	    std::string op_name = single_contextual_token_name(arg_tokens[1]);
	    DataDefCLASS *op_owner = NULL;
	    const Program::TemplateAliasDef *op_alias = NULL;
	    if ( !op_name.empty() )
	    {
		const uint32_t op_name_id = template_name_pool.intern(op_name);
		for ( std::vector<DataDefCLASS *>::reverse_iterator it =
			  class_scope_stack.rbegin();
		      it != class_scope_stack.rend() && !op_alias; ++it )
		    op_alias = find_template_alias_in_class_tree(*this,
							op_name_id,
							*it,
							&op_owner);
	    }
	    std::vector<std::vector<TokenBase *> > op_args;
	    for ( size_t ai = 2; ai < arg_tokens.size(); ++ai )
		op_args.push_back(arg_tokens[ai]);
	    if ( op_alias )
	    {
		if ( TokenDataType *detected =
			resolve_simple_member_detection_alias(*this, *op_alias,
							      op_args, tb) )
		    return detected;
	    }
	    if ( TokenDataType *fallback =
		    resolve_type_token_sequence(*this, arg_tokens[0], tb) )
		return fallback;
	}

	// Cycle break: re-entering resolution of the SAME alias use (keyed tname +
	// arg spellings) is a self-referential trait loop — now reachable because a
	// variadic member really instantiates and its body re-names this alias. The
	// re-entrant call skips the resolve + concreteness check and falls to the
	// opaque placeholder, bounding the recursion (the outer resolution proceeds).
	std::string ip_key = tname + "<";
	for ( size_t i = 0; i < args.size(); ++i )
	    ip_key += (i ? "," : "") + args[i];
	ip_key += ">";
	struct InProgressGuard {
	    std::set<std::string> &s; std::string k; bool owned;
	    InProgressGuard(std::set<std::string> &set, const std::string &key)
		: s(set), k(key), owned(set.insert(key).second) {}
	    ~InProgressGuard() { if ( owned ) s.erase(k); }
	} ip_guard(alias_resolve_in_progress, ip_key);
	bool ip_reentrant = !ip_guard.owned;

	// Substitute the collected args — type AND non-type, each as its raw
	// token sequence — into the alias body and resolve, the alias-template
	// analogue of the type-params-only path below. Without this an alias
	// template with a non-type param (`conditional_t<bool,T,F>`,
	// `enable_if_t<bool,T>`, …) collapsed straight to the opaque placeholder,
	// so `conditional_t<true,int,long>` never became `int`.
	//
	// The body is resolved in an ISOLATED token stream (save/swap-in a fresh
	// deque/restore) rather than push/drain on the shared `tokens`: this alias
	// use is frequently reached WHILE instantiating an outer template body
	// (real `move_iterator::reference`), and resolving the substituted body
	// recurses into more template/alias instantiation — sentinel-draining the
	// shared stream desynced the suspended outer parse (SIGSEGV). Isolation
	// makes the recursion self-contained. If resolution fails — a genuinely
	// dependent use, or an absent `::type` (SFINAE) — fall through to the
	// opaque placeholder exactly as before.
	if ( !ip_reentrant )
	{
	    std::map<std::string, const std::vector<TokenBase *> *> tok_subst;
	    std::set<std::string> pack_param_names;
	    std::set<std::string> used_params;
	    for ( size_t i = 0; i < td.typeparams.size() && i < arg_tokens.size(); ++i )
	    {
		tok_subst[td.typeparams[i]] = &arg_tokens[i];
		if ( i < td.typeparam_is_pack.size() && td.typeparam_is_pack[i] )
		    pack_param_names.insert(td.typeparams[i]);
	    }
	    // ALL declared pack params — an ABSENT trailing pack (the alias
	    // used with fewer args: `__is_constructible_impl<_Tp>`) has no
	    // arg slot and thus no tok_subst entry; its body mention must be
	    // ELIDED (with its `...` and a preceding comma), or the raw name
	    // survives into the substituted body and the whole alias falls to
	    // the opaque placeholder (silent wrong trait values).
	    std::set<std::string> declared_packs;
	    for ( size_t i = 0; i < td.typeparams.size(); ++i )
		if ( i < td.typeparam_is_pack.size() && td.typeparam_is_pack[i] )
		    declared_packs.insert(td.typeparams[i]);
	    std::vector<TokenBase *> body;
	    for ( size_t bi = 0; bi < td.target.size(); ++bi )
	    {
		TokenBase *bt = td.target[bi];
		if ( bt && bt->type() == TokenType::ttIdentifier )
		{
		    const std::string &nm = ((TokenIdent *)bt)->spelling();
		    std::map<std::string, const std::vector<TokenBase *> *>::iterator si =
			tok_subst.find(nm);
		    if ( si == tok_subst.end() && declared_packs.count(nm) )
		    {
			if ( !body.empty() && body.back()
			  && body.back()->id() == TokenID::tkComma )
			{
			    delete body.back();
			    body.pop_back();
			}
			if ( bi + 3 < td.target.size()
			  && td.target[bi+1] && td.target[bi+1]->id() == TokenID::tkDot
			  && td.target[bi+2] && td.target[bi+2]->id() == TokenID::tkDot
			  && td.target[bi+3] && td.target[bi+3]->id() == TokenID::tkDot )
			    bi += 3;
			continue;
		    }
		    if ( si != tok_subst.end() )
		    {
			used_params.insert(nm);
			for ( TokenBase *rt : *si->second )
			    body.push_back(rt->clone());
			// A PACK param (`_Args`) in the alias body is followed by a
			// `...` pack-expansion ellipsis (`__construct_helper<_Tp,
			// _Args...>`). The arg slot holds the (single) bound element;
			// drop the trailing `...` so the substituted body is a valid
			// `<A*, A*>`, not `<A*, A*...>` (which derails arg parsing).
			if ( pack_param_names.count(nm)
			  && bi + 3 < td.target.size()
			  && td.target[bi+1] && td.target[bi+1]->id() == TokenID::tkDot
			  && td.target[bi+2] && td.target[bi+2]->id() == TokenID::tkDot
			  && td.target[bi+3] && td.target[bi+3]->id() == TokenID::tkDot )
			    bi += 3;
			continue;
		    }
		}
		body.push_back(bt ? bt->clone() : NULL);
	    }
	    body.push_back(new TokenSemi());

	    // Env-gated probe (MADC_ANU_PROBE=<alias-name substr>): the isolated
	    // resolve below reports only resolved/(fail) — print the substituted
	    // body it attempts and, on failure, the token the resolve stopped at
	    // (the MTB/MCT probe precedent one lane over).
	    static const char *anu_probe = ::getenv("MADC_ANU_PROBE");
	    const bool anu_on = anu_probe && *anu_probe
			     && tname.find(anu_probe) != std::string::npos;
	    if ( anu_on )
	    {
		fprintf(stderr, "ANUPROBE %s body:", tname.c_str());
		for ( TokenBase *pt : body )
		{
		    if ( !pt )
			continue;
		    std::string nm = contextual_identifier_name(pt);
		    if ( !nm.empty() )
			fprintf(stderr, " %s", nm.c_str());
		    else if ( pt->type() == TokenType::ttDataType )
			fprintf(stderr, " [T]%s",
				((TokenDataType *)pt)->definition.name.c_str());
		    else
			fprintf(stderr, " #%d", (int)pt->id());
		}
		fprintf(stderr, "\n");
	    }

	    size_t saved_diag_count = diagnostics.size();
	    Program::ErrorInfo saved_error = last_error;
	    TokenStream::State saved_tokens = tokens.swap_in(std::move(body));

	    bool pushed_owner_scope = false;
	    if ( td.owner_class )
	    {
		class_scope_stack.push_back(td.owner_class);
		pushed_owner_scope = true;
	    }

	    TokenDataType *resolved = NULL;
	    try
	    {
		TokenBase *head = nextToken();
		resolved = resolve_declared_type_token(head, true, true);
		// Declarator suffix (`= U *`) folds BEFORE the
		// leftover-strictness check, so a pointer-target alias
		// passes it legitimately (same owner as the arg loop).
		if ( resolved )
		    resolved = fold_template_arg_declarator(resolved, head);
		// The substituted body IS the type spelling: tokens left
		// before the `;` sentinel mean the resolution did not cover
		// it — a FAILURE, not a success (#27's require_full_parse
		// rule). The leak: `enable_if<false,void>::type` — the
		// member-miss probe declines without consuming, the chain
		// tolerance hands back the CLASS, and the dangling `::type`
		// silently passed, so enable_if_t<false> "resolved" and
		// defeated SFINAE (__or_/__and_'s catch-all never won —
		// std::is_destructible read wrong through the whole family).
		if ( resolved && peekToken()
		  && peekToken()->id() != TokenID::tkSemi
		  && !dependent_parse_in_progress
		  && !class_pattern_capture_in_progress )
		    resolved = NULL;
	    }
	    catch ( ... ) { resolved = NULL; }
	    if ( anu_on && !resolved )
	    {
		TokenBase *stop = peekToken();
		std::string nm = stop ? contextual_identifier_name(stop)
				      : std::string();
		fprintf(stderr, "ANUPROBE %s FAIL stopped-at %s(#%d)\n",
			tname.c_str(),
			nm.empty() ? "?" : nm.c_str(),
			stop ? (int)stop->id() : -1);
	    }

	    if ( pushed_owner_scope
	      && !class_scope_stack.empty()
	      && class_scope_stack.back() == td.owner_class )
		class_scope_stack.pop_back();

	    tokens.swap_back(std::move(saved_tokens));
	    DBG({
		std::string aj;
		for ( size_t i = 0; i < args.size(); ++i )
		    aj += (i ? "," : "") + args[i];
		std::cout << "alias_nontype_use: " << tname << "<" << aj
			  << "> resolved="
			  << (resolved ? resolved->definition.name : "(fail)")
			  << std::endl;
	    });
	    if ( !resolved )
	    {
		diagnostics.resize(saved_diag_count);
		last_error = saved_error;
		// A NON-DEPENDENT (concrete-args) alias use whose body failed to
		// resolve is a genuine SFINAE substitution failure — e.g.
		// `enable_if_t<false,T>`, where `enable_if<false,T>` has no
		// `::type`. Return NULL so the enclosing fn-template candidate's
		// return-type resolution fails and the candidate is discarded
		// ([temp.deduct]/8), exactly as clang's SubstType returns a null
		// QualType on the absent-`::type` case. Caching an opaque
		// placeholder instead (below) masks the failure and made madc
		// bind the SFINAE-removed overload (the `__relocate_a_1` memmove
		// overload for a non-trivially-relocatable element). A genuinely
		// dependent use (an arg still names an unbound template parameter)
		// keeps the opaque placeholder below — correct for a dependent
		// surface that resolves later.
		if ( alias_use_args_all_concrete(td, arg_tokens) )
		    return NULL;
	    }
	    else
	    {
		// [temp.deduct]/8: EVERY template argument must be valid in
		// the immediate context — INCLUDING args the alias target
		// never names. gcc 13's whole __or_fn/__and_fn design hangs
		// on exactly this: `__first_t<false_type,
		// __enable_if_t<!bool(_Bn::value)>...>` succeeds or SFINAE-
		// fails on the UNUSED pack args. Validate each arg the
		// substitution did not splice into the body: a failing
		// concrete arg is a substitution failure (NULL); a DEPENDENT
		// arg (names a live template parameter / dependent surface)
		// keeps the opaque placeholder below, as before.
		// A capture parse skips the validation entirely. A DEPENDENT
		// parse skips it only when the use itself is dependent — an
		// arg naming a live/unbound template parameter (`__enable_if_t
		// <is_convertible<_Iter,_Iterator>::value>` inside
		// __normal_iterator's member alias template is legitimately
		// unresolvable now). A NON-dependent use validates even inside
		// a dependent parse: `__first_t<true_type, __enable_if_t<
		// bool(...)>...>` with concrete args inside _M_realloc_insert's
		// materialization must SFINAE-fail, or __and_ folds the wrong
		// branch (the vecbind move/copy lane divergence). The
		// discriminator is DEPENDENCE, not concreteness: a genuine
		// SFINAE miss (enable_if<false,T>::type) has every name
		// resolvable — not dependent — and must still fail here.
		bool alias_use_dependent = false;
		for ( size_t i = 0; !alias_use_dependent && i < arg_tokens.size(); ++i )
		    alias_use_dependent = alias_arg_tokens_dependent(arg_tokens[i]);
		const bool skip_validation = class_pattern_capture_in_progress
					  || (dependent_parse_in_progress
					      && alias_use_dependent);
		if ( vri_debug_enabled() )
		    fprintf(stderr, "[vriprobe] alias-validate %s skip=%d dep=%d cap=%d argdep=%d\n",
			    tname.c_str(), (int)skip_validation,
			    (int)dependent_parse_in_progress,
			    (int)class_pattern_capture_in_progress,
			    (int)alias_use_dependent);
		bool unused_failed = false, unused_dependent = false;
		for ( size_t i = 0; !skip_validation && i < arg_tokens.size()
			     && !unused_failed && !unused_dependent; ++i )
		{
		    // An EMPTY arg slot (`__void_t<>` — an empty pack) is not
		    // an argument at all; nothing to validate.
		    if ( arg_tokens[i].empty() )
			continue;
		    const std::string &pname =
			i < td.typeparams.size() ? td.typeparams[i]
			: (!td.typeparams.empty() ? td.typeparams.back()
						  : std::string());
		    if ( used_params.count(pname) )
			continue;
		    bool arg_is_type = i < td.typeparam_is_type.size()
				     ? td.typeparam_is_type[i] : true;
		    if ( !arg_is_type )
		    {
			int64_t v = 0;
			if ( !fold_nontype_arg_constant(arg_tokens[i], v) )
			{
			    if ( alias_arg_tokens_dependent(arg_tokens[i]) )
				unused_dependent = true;
			    else
				unused_failed = true;
			}
			continue;
		    }
		    std::vector<TokenBase *> probe;
		    for ( TokenBase *t : arg_tokens[i] )
			if ( t )
			    probe.push_back(t->clone());
		    probe.push_back(new TokenSemi());
		    size_t sdc = diagnostics.size();
		    Program::ErrorInfo se = last_error;
		    TokenStream::State st = tokens.swap_in(std::move(probe));
		    TokenDataType *art = NULL;
		    try
		    {
			art = resolve_declared_type_token(nextToken(), true, true);
			if ( art && peekToken()
			  && peekToken()->id() != TokenID::tkSemi )
			    art = NULL;	// leftover before the sentinel = fail
		    }
		    catch ( ... ) { art = NULL; }
		    tokens.swap_back(std::move(st));
		    diagnostics.resize(sdc);
		    last_error = se;
		    if ( !art )
		    {
			if ( alias_arg_tokens_dependent(arg_tokens[i]) )
			    unused_dependent = true;
			else
			    unused_failed = true;
		    }
		    else if ( datadef_has_unresolved_dependent_surface(
				&art->definition) )
			unused_dependent = true;
		}
		if ( unused_failed )
		    return NULL;
		if ( !unused_dependent )
		    return use_site_type_token(resolved, tb);
		// a dependent unused arg: the whole alias-id is dependent —
		// fall through to the opaque placeholder below.
	    }
	}

	std::string mangled = tname;
	std::string canon = td.defining_namespace.empty() ? std::string()
			  : (td.defining_namespace + "::");
	canon += tname + "<";
	for ( size_t i = 0; i < args.size(); ++i )
	{
	    mangled += "_" + canonical_arg_key_fragment(arg_tokens[i], args[i]);
	    if ( i )
		canon += ",";
	    canon += args[i];
	}
	canon += ">";

	flat_datatype_map_iter have = datatype_map.find(mangled);
	if ( have != datatype_map.end() )
	    return use_site_type_token((TokenDataType *)(*have), tb);

	DataDefCLASS *fwd = new DataDefCLASS(mangled, 0, DataType::dtRESERVED);
	fwd->is_dependent_placeholder = true;
	stamp_opaque_mint_context(fwd);
	fwd->has_dependent_surface = true;
	fwd->set_canonical_spelling(canon);
	struct_map.set(mangled, fwd);
	TokenDataType *tdt = new TokenDataType(mangled.c_str(), *fwd);
	datatype_map[mangled] = tdt;
	if ( !td.defining_namespace.empty() )
	    namespace_datatype_map[td.defining_namespace][mangled] = tdt;
	return use_site_type_token(tdt, tb);
    }

    nextToken(); // consume '<'
    std::vector<TokenDataType *> args;
    std::vector<std::string> arg_spellings;
    std::map<std::string, TokenDataType *> subst;
	for (;;)
	{
	    TokenBase *at = nextToken();
	    std::string cv_spelling;
	    at = consume_template_type_arg_qualifiers(at, cv_spelling);
	    (void)cv_spelling;
	    TokenDataType *adt = resolve_declared_type_token(at, true, true);
	    if ( !adt )
		Throw(at) << "Expecting a type argument to " << tname << "<>" << flush;
	// East-cv between the base type and any declarator suffix
	// (`value_type const`, optional:790) — same owner-pair as the leading
	// consume above; without it the separator read the `const` and threw.
	consume_trailing_type_arg_qualifiers(cv_spelling);
	adt = fold_template_arg_declarator(adt, at);
	args.push_back(adt);
	arg_spellings.push_back(template_type_arg_spelling(adt, cv_spelling));
	TokenBase *sep = nextToken();
	if ( sep->id() == TokenID::tkComma )
	    continue;
	if ( consume_template_close(sep) )
	    break;
	Throw(sep) << "Expecting ',' or '>' in " << tname << "<...>" << flush;
    }
    if ( args.size() > td.typeparams.size() )
    {
	arity_probe("nest-over", tname, td, args.size());
	Throw(tb) << tname << "<> expects " << td.typeparams.size()
		      << " type argument(s), got " << args.size() << flush;
    }
    for ( size_t i = 0; i < args.size(); ++i )
	subst[td.typeparams[i]] = args[i];
    while ( args.size() < td.typeparams.size() )
    {
	size_t ai = args.size();
	if ( ai >= td.typeparam_defaults.size()
	  || td.typeparam_defaults[ai].empty() )
	{
	    arity_probe("nest-fill", tname, td, args.size());
	    Throw(tb) << tname << "<> expects " << td.typeparams.size()
			  << " type argument(s), got " << args.size() << flush;
	}
	std::vector<TokenBase *> inj;
	for ( TokenBase *bt : td.typeparam_defaults[ai] )
	{
	    if ( bt->type() == TokenType::ttIdentifier )
	    {
		const std::string &s = ((TokenIdent *)bt)->spelling();
		std::map<std::string, TokenDataType *>::iterator si = subst.find(s);
		if ( si != subst.end() )
		{
		    inj.push_back(si->second->clone());
		    continue;
		}
	    }
	    inj.push_back(bt->clone());
	}
	inj.push_back(new TokenSemi());
	for ( std::vector<TokenBase *>::reverse_iterator it = inj.rbegin();
	      it != inj.rend(); ++it )
	    pushToken(*it);
	TokenBase *dtok = nextToken();
	std::string cv_spelling;
	dtok = consume_template_type_arg_qualifiers(dtok, cv_spelling);
	(void)cv_spelling;
	TokenDataType *adt = resolve_declared_type_token(dtok, true, true);
	if ( !adt )
	    Throw(dtok ? dtok : tb) << "Could not resolve default template argument for "
					<< td.typeparams[ai] << " in "
					<< tname << "<>" << flush;
	// A defaulted param's declarator suffix (`class V = U*`) folds too.
	adt = fold_template_arg_declarator(adt, dtok);
	if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
	    nextToken();
	args.push_back(adt);
	arg_spellings.push_back(template_type_arg_spelling(adt, cv_spelling));
	subst[td.typeparams[ai]] = adt;
    }

    std::vector<TokenBase *> inj;
    for ( TokenBase *bt : td.target )
    {
	if ( bt->type() == TokenType::ttIdentifier )
	{
	    const std::string &s = ((TokenIdent *)bt)->spelling();
	    std::map<std::string, TokenDataType *>::iterator si = subst.find(s);
	    if ( si != subst.end() )
	    {
		inj.push_back(si->second->clone());
		continue;
	    }
	}
	inj.push_back(bt->clone());
    }
    TokenSemi *alias_sentinel = new TokenSemi();
    inj.push_back(alias_sentinel);
    for ( std::vector<TokenBase *>::reverse_iterator it = inj.rbegin();
	  it != inj.rend(); ++it )
	pushToken(*it);

    bool pushed_owner_scope = false;
    if ( td.owner_class )
    {
	class_scope_stack.push_back(td.owner_class);
	pushed_owner_scope = true;
    }

    TokenBase *head = nextToken();
    TokenDataType *resolved = resolve_declared_type_token(head, true, true);
    // Alias-target DECLARATOR suffix (`using rebind = U *;` — libc++
    // pointer_traits): fold `*`/`&`/fn-ptr onto the resolved base via the
    // one owner. The sentinel drain below silently DISCARDED the suffix,
    // so every pointer-target alias yielded its POINTEE (`up<int>` == int
    // — map's tree-iterator chain instantiated with de-pointered args and
    // its operator-> return degraded to a placeholder, task #72).
    if ( resolved )
	resolved = fold_template_arg_declarator(resolved, head);
    bool have_sentinel = false;
    for ( size_t si = 0; si < tokens.size(); ++si )
	if ( tokens[si] == alias_sentinel )
	{
	    have_sentinel = true;
	    break;
	}
    if ( have_sentinel )
    {
	while ( peekToken() && peekToken() != alias_sentinel )
	    nextToken();
	if ( peekToken() == alias_sentinel )
	    nextToken();
    }
    else if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
	nextToken();

    if ( pushed_owner_scope
      && !class_scope_stack.empty()
      && class_scope_stack.back() == td.owner_class )
	class_scope_stack.pop_back();

    // FALLBACK: the body failed to resolve in the CALLER's context, but it was
    // written in the alias's DEFINING namespace and may reference a sibling
    // member UNQUALIFIED (`getvt = typename midalias<T>::value_type;` where the
    // sibling alias `midalias` is in the same namespace). When this alias is
    // reached via a QUALIFIED use from outside (`foo::getvt<X>`) that namespace
    // is not lexically active, so the sibling was undeclared. Retry ONCE with
    // the defining namespace activated — strictly additive (only on a prior
    // failure), so it cannot change any resolution that already succeeded.
    // Real trigger: the std::__detail `iter_value_t`/`__iter_traits` alias chain
    // pulled by reverse_iterator at --std=c++20.
    if ( !resolved && !td.defining_namespace.empty()
      && current_namespace() != td.defining_namespace )
    {
	std::vector<TokenBase *> inj2;
	for ( TokenBase *bt : td.target )
	{
	    if ( bt->type() == TokenType::ttIdentifier )
	    {
		const std::string &s = ((TokenIdent *)bt)->spelling();
		std::map<std::string, TokenDataType *>::iterator si = subst.find(s);
		if ( si != subst.end() )
		{
		    inj2.push_back(si->second->clone());
		    continue;
		}
	    }
	    inj2.push_back(bt->clone());
	}
	TokenSemi *sentinel2 = new TokenSemi();
	inj2.push_back(sentinel2);
	for ( std::vector<TokenBase *>::reverse_iterator it = inj2.rbegin();
	      it != inj2.rend(); ++it )
	    pushToken(*it);

	bool po2 = false;
	if ( td.owner_class )
	{ class_scope_stack.push_back(td.owner_class); po2 = true; }
	namespace_stack.push_back(td.defining_namespace);

	TokenBase *head2 = nextToken();
	try
	{
	    resolved = resolve_declared_type_token(head2, true, true);
	    if ( resolved )   // same declarator-suffix fold as the main lane
		resolved = fold_template_arg_declarator(resolved, head2);
	}
	catch ( ... ) { resolved = NULL; }

	if ( !namespace_stack.empty()
	  && namespace_stack.back() == td.defining_namespace )
	    namespace_stack.pop_back();
	if ( po2 && !class_scope_stack.empty()
	  && class_scope_stack.back() == td.owner_class )
	    class_scope_stack.pop_back();

	bool hs2 = false;
	for ( size_t si = 0; si < tokens.size(); ++si )
	    if ( tokens[si] == sentinel2 ) { hs2 = true; break; }
	if ( hs2 )
	{
	    while ( peekToken() && peekToken() != sentinel2 )
		nextToken();
	    if ( peekToken() == sentinel2 )
		nextToken();
	}
	else if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
	    nextToken();

	if ( resolved )
	    return use_site_type_token(resolved, tb);
    }

    if ( !resolved && td.owner_class
      && class_has_unresolved_dependent_surface(td.owner_class) )
    {
	std::string member_fragment = tname;
	std::string owner_spelling = td.owner_class->canonical_cpp_spelling().empty()
				   ? td.owner_class->name
				   : td.owner_class->canonical_cpp_spelling();
	std::string canon = owner_spelling + "::" + tname + "<";
	for ( size_t ai = 0; ai < arg_spellings.size(); ++ai )
	{
	    member_fragment += "_" + canonical_arg_key_fragment(
		std::vector<TokenBase *>(), arg_spellings[ai]);
	    if ( ai )
		canon += ",";
	    canon += arg_spellings[ai];
	}
	canon += ">";
	std::string dep_name = td.owner_class->name + "__"
			     + sanitize_template_fragment(member_fragment);
	DataDefCLASS *dep = materialize_opaque_class_type(dep_name, canon);
	if ( dep )
	{
	    dep->has_dependent_surface = true;
	    return make_alias_type_token(dep_name, dep, tb);
	}
    }

    return resolved ? use_site_type_token(resolved, tb) : NULL;
}

void Program::complete_pending_template_instantiations(const std::string &class_name)
{
    std::map<std::string, std::vector<Program::PendingTemplateInstantiation>>::iterator pi =
	pending_template_instantiations.find(class_name);
    if ( pi == pending_template_instantiations.end() )
	return;
    if ( !template_with_body(class_name) )
	return;

    std::vector<Program::PendingTemplateInstantiation> pending = pi->second;
    for ( size_t i = 0; i < pending.size(); ++i )
    {
	flat_datatype_map_iter have = datatype_map.find(pending[i].mangled_name);
	if ( have == datatype_map.end()
	  || !is_incomplete_template_class_type((TokenDataType *)(*have)) )
	    continue;
	if ( template_completion_requested.find(pending[i].mangled_name)
	  == template_completion_requested.end() )
	    continue;

	std::vector<TokenBase *> toks;
	toks.push_back(new TokenLT());
	for ( size_t ai = 0; ai < pending[i].args.size(); ++ai )
	{
	    if ( ai )
		toks.push_back(new TokenComma());
	    toks.push_back(pending[i].args[ai]->clone());
	}
	toks.push_back(new TokenGT());
	for ( std::vector<TokenBase *>::reverse_iterator it = toks.rbegin();
	      it != toks.rend(); ++it )
	    pushToken(*it);

	TokenIdent fake_name(class_name.c_str());
	instantiate_template_use(class_name, &fake_name);
    }
}

bool Program::has_pending_template_instantiation(const std::string &mangled_name) const
{
    for ( std::map<std::string, std::vector<Program::PendingTemplateInstantiation>>::const_iterator pi =
	      pending_template_instantiations.begin();
	  pi != pending_template_instantiations.end(); ++pi )
	for ( size_t i = 0; i < pi->second.size(); ++i )
	    if ( pi->second[i].mangled_name == mangled_name )
		return true;
    return false;
}

bool Program::request_template_instantiation_completion(const std::string &mangled_name)
{
    template_completion_requested.insert(mangled_name);
    for ( std::map<std::string, std::vector<Program::PendingTemplateInstantiation>>::iterator pi =
	      pending_template_instantiations.begin();
	  pi != pending_template_instantiations.end(); ++pi )
    {
	for ( size_t i = 0; i < pi->second.size(); ++i )
	{
	    if ( pi->second[i].mangled_name != mangled_name )
		continue;
	    complete_pending_template_instantiations(pi->first);
	    return true;
	}
    }
    return false;
}

// Demand-completion for a class type reaching a context that REQUIRES a
// COMPLETE type ([basic.def]p5 by-value declaration, [expr.sizeof]p1): a
// bodyless forward instantiation minted before its template's definition
// (libc++ <iosfwd>'s stream typedefs — the definitions arrive with
// <sstream>) completes IN PLACE when the definition has since registered.
// A no-op for anything else: a complete class, a non-class, a genuinely
// dependent shell (no pending record exists for those). Returns the
// possibly-refreshed type; in-place completion means the original pointer
// heals too — the refresh covers a replaced map entry.
DataDef *Program::complete_class_type_on_demand(DataDef *dd)
{
    DataDefCLASS *cls = dynamic_cast<DataDefCLASS *>(dd);
    if ( !cls || !is_incomplete_class_datadef(cls) )
	return dd;
    request_template_instantiation_completion(cls->name);
    flat_datatype_map_iter refreshed = datatype_map.find(cls->name);
    if ( refreshed != datatype_map.end() )
	return &(*refreshed)->definition;
    return dd;
}

static std::vector<std::vector<TokenBase *> >
collect_dependent_member_template_args(Program &pgm)
{
    std::vector<std::vector<TokenBase *> > args;
    TokenBase *open = pgm.nextToken();
    if ( !open || open->id() != TokenID::tkLT )
	return args;
    if ( pgm.peekToken() && pgm.peekToken()->id() == TokenID::tkGT )
    {
	pgm.nextToken();
	return args;
    }
    for (;;)
    {
	TokenBase *first = pgm.nextToken();
	std::string spelling;
	std::vector<TokenBase *> tokens;
	TokenBase *separator = pgm.collect_template_argument_spelling(
	    first, spelling, &tokens);
	args.push_back(tokens);
	if ( separator && separator->id() == TokenID::tkComma )
	    continue;
	if ( separator && pgm.consume_template_close(separator) )
	    break;
	pgm.Throw(separator ? separator : open)
	    << "Expecting ',' or '>' in dependent member template-id" << flush;
    }
    return args;
}

TokenDataType *Program::resolve_typename_type_token(TokenBase *first,
						  bool allow_lazy_types,
						  TokenBase *typename_tb)
{
    if ( !first )
	Throw(typename_tb) << "Expecting qualified type after 'typename'" << flush;
    if ( first->id() == TokenID::tkNS )
    {
	TokenBase *head = nextToken();
	TokenDataType *resolved =
	    resolve_declared_type_token(head, true, allow_lazy_types);
	return resolved;
    }

    TokenDataType *owner_type = NULL;
    if ( is_contextual_identifier_token(first)
      && peekToken() && peekToken()->id() == TokenID::tkLT )
    {
	std::string first_name = contextual_identifier_name(first);
	for ( std::vector<DataDefCLASS *>::reverse_iterator it =
		  class_scope_stack.rbegin();
	      it != class_scope_stack.rend(); ++it )
	{
	    if ( !*it )
		continue;
	    // Member-TYPE chain head: allow a concrete trailing-type-pack template to
	    // really instantiate so a subsequent `::member` reads an evaluated member.
	    bool saved_vri = allow_variadic_real_inst;
	    allow_variadic_real_inst = true;
	    owner_type = instantiate_template_id(first_name, first,
						std::string(), *it);
	    allow_variadic_real_inst = saved_vri;
	    if ( owner_type )
		break;
	}
    }
    if ( !owner_type )
	owner_type = resolve_declared_type_token(first, true, allow_lazy_types, false);
    if ( !owner_type )
	return NULL;
    DataDefCLASS *owner = dynamic_cast<DataDefCLASS *>(&owner_type->definition);
    // `typename T::member` where T is a TEMPLATE-PARAMETER placeholder (an
    // active dependent pattern/capture parse): there is no class to look
    // inside — every member is dependent by construction. Walk the chain in
    // "param mode": each hop materializes a dependent-member placeholder
    // stamped with DependentDerivedOrigin{MemberType} (the same recipe the
    // opaque-class arm below records), so tsubst / the class-pattern resolver
    // re-derive the CONCRETE type under an instance substitution.
    DataDef *param_owner = NULL;
    if ( !owner )
    {
	if ( !owner_type->definition.is_template_param() )
	    return NULL;
	param_owner = &owner_type->definition;
    }
    // Env-gated probe (MADC_TYPENAME_PROBE=<substr of first name>): trace every
    // owner hop of a `typename A::B::...` chain — the owner-swap diagnostic.
    static const char *tnp = ::getenv("MADC_TYPENAME_PROBE");
    bool tnp_on = tnp && *tnp && is_contextual_identifier_token(first)
	       && contextual_identifier_name(first).find(tnp) != std::string::npos;
    if ( tnp_on )
    {
	const std::string fname = contextual_identifier_name(first);
	DataDef *cur = resolve_current_class_type_alias(fname);
	fprintf(stderr,
		"TNPROBE head %s -> %s incomplete=%d [flat=%d curalias=%s "
		"stack=%s method=%s]\n",
		fname.c_str(),
		owner ? owner->name.c_str() : param_owner->name.c_str(),
		(int)(owner && is_incomplete_class_datadef(owner)),
		(int)(datatype_map.find(fname) != datatype_map.end()),
		cur ? cur->name.c_str() : "-",
		class_scope_stack.empty() ? "-"
			: class_scope_stack.back()->name.c_str(),
		(!compounds.empty() && compounds.top()
		 && compounds.top()->method
		 && compounds.top()->method->owner_class)
			? compounds.top()->method->owner_class->name.c_str()
			: "-");
    }
    if ( owner && is_incomplete_class_datadef(owner) )
    {
	request_template_instantiation_completion(owner->name);
	flat_datatype_map_iter refreshed = datatype_map.find(owner->name);
	if ( refreshed != datatype_map.end() )
	    owner = dynamic_cast<DataDefCLASS *>(&(*refreshed)->definition);
	if ( !owner )
	    return NULL;
	if ( tnp_on )
	    fprintf(stderr, "TNPROBE head-refresh -> %s\n", owner->name.c_str());
    }

    while ( peekToken() && peekToken()->id() == TokenID::tkNS )
    {
	if ( owner && is_incomplete_class_datadef(owner) )
	{
	    request_template_instantiation_completion(owner->name);
	    flat_datatype_map_iter refreshed = datatype_map.find(owner->name);
	    if ( refreshed != datatype_map.end() )
		owner = dynamic_cast<DataDefCLASS *>(&(*refreshed)->definition);
	    if ( !owner )
		return NULL;
	    if ( tnp_on )
		fprintf(stderr, "TNPROBE loop-refresh -> %s\n", owner->name.c_str());
	}
	nextToken(); // consume ::
	TokenBase *member_tb = nextToken();
	if ( member_tb && member_tb->id() == TokenID::tkTEMPLATE )
	    member_tb = nextToken();
	if ( !member_tb || !is_contextual_identifier_token(member_tb) )
	    Throw(member_tb ? member_tb : typename_tb)
		<< "Expecting member type after '::' in typename" << flush;
	std::string member_name = contextual_identifier_name(member_tb);
	std::vector<std::vector<TokenBase *> > member_template_args;
	bool member_is_template = false;
	if ( tnp_on )
	    fprintf(stderr, "TNPROBE hop owner=%s member=%s\n",
		    owner ? owner->name.c_str() : param_owner->name.c_str(),
		    member_name.c_str());
	if ( peekToken() && peekToken()->id() == TokenID::tkLT )
	{
	    member_is_template = true;
	    // Param mode: no class to instantiate against — keep the raw
	    // `<...>` args for the placeholder's derivation recipe.
	    TokenDataType *inst = owner
		? instantiate_template_id(member_name, member_tb,
					  std::string(), owner)
		: NULL;
	    if ( inst )
	    {
		owner = dynamic_cast<DataDefCLASS *>(&inst->definition);
		if ( !owner )
		    return inst;
		if ( !peekToken() || peekToken()->id() != TokenID::tkNS )
		    return inst;
		continue;
	    }
	    member_template_args = collect_dependent_member_template_args(*this);
	}

	DataDef *alias_dd = owner ? resolve_class_type_alias(owner, member_name)
				  : NULL;
	if ( tnp_on )
	    fprintf(stderr, "TNPROBE alias %s::%s -> %s\n",
		    owner ? owner->name.c_str() : param_owner->name.c_str(),
		    member_name.c_str(), alias_dd ? alias_dd->name.c_str() : "(null)");
	// A member-alias MISS on an INCOMPLETE owner: the owner was minted
	// DURING a dependent parse and cached, but by now its recorded args may
	// be fully CONCRETE (tuple_element<0, tuple<int&>> from get<0>'s
	// instantiation — the map:967 chain). complete_shell_class_type() owns
	// the replay and its silence; a shell that stays opaque returns NULL and
	// falls through to the opaque materialization exactly as before.
	if ( !alias_dd && owner && is_incomplete_class_datadef(owner) )
	{
	    if ( tnp_on )
	    {
		std::map<DataDef *, DependentShellOrigin>::const_iterator oi =
		    dependent_shell_origin.find(owner);
		fprintf(stderr, "TNPROBE replay-gate %s org=%d runs=%zu\n",
			owner->name.c_str(),
			(int)(oi != dependent_shell_origin.end()),
			oi != dependent_shell_origin.end()
			    ? oi->second.raw_arg_tokens.size() : (size_t)0);
	    }
	    if ( DataDefCLASS *rc = complete_shell_class_type(owner) )
	    {
		owner = rc;
		alias_dd = resolve_class_type_alias(owner, member_name);
		if ( tnp_on )
		    fprintf(stderr, "TNPROBE shell-replay -> %s alias=%s\n",
			    owner->name.c_str(),
			    alias_dd ? alias_dd->name.c_str() : "(null)");
	    }
	}
	if ( !alias_dd && (owner ? class_allows_opaque_member_type(owner)
				 : true) )
	{
	    alias_dd = materialize_dependent_member_type(
		owner ? static_cast<DataDef *>(owner) : param_owner, member_name);
	    if ( alias_dd && member_is_template )
	    {
		DependentDerivedOrigin &origin = dependent_derived_origin[alias_dd];
		origin.member_is_template = true;
		origin.raw_arg_tokens = member_template_args;
	    }
	}
	if ( !alias_dd )
	    return NULL;
	if ( !peekToken() || peekToken()->id() != TokenID::tkNS )
	    return make_alias_type_token(member_name, alias_dd, member_tb);
	owner = dynamic_cast<DataDefCLASS *>(alias_dd);
	if ( !owner )
	    return NULL;
	param_owner = NULL;   // subsequent hops run in class mode
    }

    return owner_type;
}

TokenDataType *Program::resolve_class_member_type_chain(DataDefCLASS *owner,
						      TokenBase *owner_tb,
						      bool committed_type_context)
{
    if ( !owner || !peekToken() || peekToken()->id() != TokenID::tkNS )
	return NULL;

    bool first_segment = true;
    while ( peekToken() && peekToken()->id() == TokenID::tkNS )
    {
	if ( is_incomplete_class_datadef(owner) )
	{
	    request_template_instantiation_completion(owner->name);
	    flat_datatype_map_iter refreshed = datatype_map.find(owner->name);
	    if ( refreshed != datatype_map.end() )
		owner = dynamic_cast<DataDefCLASS *>(&(*refreshed)->definition);
	    if ( !owner )
		return NULL;
	}
	// Probe the FIRST segment before consuming anything: in expression
	// position `Type::static_member` must reach the expression parser
	// untouched — descend only when `::name` names a member TYPE (alias,
	// nested class, member template) or the owner admits opaque dependent
	// members. Once a segment is consumed we are committed and the
	// "not a type member" diagnostic below is correct.
	if ( first_segment )
	{
	    TokenBase *probe = tokens.size() > 1 ? tokens[1] : NULL;
	    if ( probe && probe->id() == TokenID::tkTEMPLATE )
		probe = tokens.size() > 2 ? tokens[2] : NULL;
	    if ( !probe || !is_contextual_identifier_token(probe) )
		return NULL;
	    std::string probe_name = contextual_identifier_name(probe);
	    // The opaque-dependent-member escape is deliberately NOT part of
	    // the probe: speculative type resolution (if-condition heads,
	    // expression positions) must not consume `::static_member` of a
	    // dependent-surface class. Committed type contexts that need
	    // opaque materialization (typename ...) run their own loop.
	    // A member ALIAS template (`Owner<...>::type<A,B>`, e.g. libstdc++'s
	    // `__conditional<C>::template type<If,Else>`) is the third member-TYPE
	    // shape the loop body resolves (via instantiate_template_id ->
	    // instantiate_template_alias_use), so the probe must admit it too —
	    // otherwise the chain never descends and the type fails to resolve.
	    const uint32_t probe_name_id = template_name_pool.intern(probe_name);
	    // A COMMITTED type context (base-specifier position — `typename`
	    // is forbidden there, so `Owner<T>::member` can only be a type)
	    // admits the opaque escape the speculative probe excludes.
	    bool committed_opaque = committed_type_context
		&& class_allows_opaque_member_type(owner);
	    if ( !resolve_class_type_alias(owner, probe_name)
	      && !find_template(probe_name_id, std::string(), owner)
	      && !find_template_alias(probe_name_id, std::string(), owner)
	      && !committed_opaque )
		return NULL;
	    first_segment = false;
	}
	nextToken(); // consume ::
	TokenBase *member_tb = nextToken();
	if ( member_tb && member_tb->id() == TokenID::tkTEMPLATE )
	    member_tb = nextToken();
	if ( !member_tb || !is_contextual_identifier_token(member_tb) )
	    Throw(member_tb ? member_tb : owner_tb)
		<< "Expecting member type after '::'" << flush;
	std::string member_name = contextual_identifier_name(member_tb);
	std::vector<std::vector<TokenBase *> > member_template_args;
	bool member_is_template = false;
	if ( peekToken() && peekToken()->id() == TokenID::tkLT )
	{
	    member_is_template = true;
	    if ( TokenDataType *inst =
		    instantiate_template_id(member_name, member_tb,
					    std::string(), owner) )
	    {
		owner = dynamic_cast<DataDefCLASS *>(&inst->definition);
		if ( !owner )
		    return inst;
		if ( !peekToken() || peekToken()->id() != TokenID::tkNS )
		    return inst;
		continue;
	    }
	    member_template_args = collect_dependent_member_template_args(*this);
	}

	DataDef *alias_dd = resolve_class_type_alias(owner, member_name);
	if ( !alias_dd && class_allows_opaque_member_type(owner) )
	{
	    alias_dd = materialize_dependent_member_type(owner, member_name);
	    if ( alias_dd && member_is_template )
	    {
		DependentDerivedOrigin &origin = dependent_derived_origin[alias_dd];
		origin.member_is_template = true;
		origin.raw_arg_tokens = member_template_args;
	    }
	}
	if ( !alias_dd )
	    Throw(member_tb) << "'" << member_name
				 << "' is not a type member" << flush;
	if ( !peekToken() || peekToken()->id() != TokenID::tkNS )
	    return make_alias_type_token(member_name, alias_dd, member_tb);
	owner = dynamic_cast<DataDefCLASS *>(alias_dd);
	if ( !owner )
	    return NULL;
    }

    return NULL;
}

// When a resolved type is a class and a `::` follows (and the caller asked for
// it), descend the member-type chain (`T::member::...`); otherwise hand back
// the type unchanged. The one seam every resolve_declared_type_token branch
// uses — template-id instantiations included — so `Tmpl<Args>::member` works
// wherever a declared type is accepted (typedef, declaration, template arg).
TokenDataType *Program::resolve_member_chain_or_type(TokenDataType *type_tok,
						     TokenBase *tb,
						     bool consume_class_member_chain)
{
    if ( !type_tok )
	return NULL;
    if ( consume_class_member_chain
      && peekToken() && peekToken()->id() == TokenID::tkNS )
	if ( DataDefCLASS *owner =
		dynamic_cast<DataDefCLASS *>(&type_tok->definition) )
	    if ( TokenDataType *member =
		    resolve_class_member_type_chain(owner, tb) )
		return member;
    return type_tok;
}

TokenDataType *Program::resolve_declared_type_token(TokenBase *tb,
						  bool consume_ns_tokens,
						  bool allow_lazy_types,
						  bool consume_class_member_chain)
{
    if ( !tb )
	return NULL;
    if ( tb->type() == TokenType::ttDataType )
    {
	if ( peekToken() && peekToken()->id() == TokenID::tkLT )
	{
	    std::string tname = ((TokenDataType *)tb)->spelling();
	    if ( TokenDataType *inst = instantiate_template_id(tname, tb) )
		return resolve_member_chain_or_type(inst, tb,
						    consume_class_member_chain);
	}
	return resolve_member_chain_or_type((TokenDataType *)tb, tb,
					    consume_class_member_chain);
    }
    if ( tb->id() == TokenID::tkCLASS
      || tb->id() == TokenID::tkSTRUCT
      || tb->id() == TokenID::tkUNION )
    {
	TokenBase *name_tb = nextToken();
	if ( !name_tb || !is_contextual_identifier_token(name_tb) )
	{
	    Throw(name_tb ? name_tb : tb)
		<< "Expecting type name after elaborated type specifier" << flush;
	}
	// Bareness must be judged BEFORE the recursion: a qualified
	// (`struct A::B`) or template-id (`struct V<T>`) form consumes
	// stream tokens on its way to failing, so a post-failure peek
	// would be looking at the wrong token.
	bool bare_name = !(peekToken()
			&& (peekToken()->id() == TokenID::tkNS
			 || peekToken()->id() == TokenID::tkLT));
	if ( TokenDataType *tdt = resolve_declared_type_token(name_tb,
		consume_ns_tokens, allow_lazy_types) )
	    return tdt;
	// [basic.scope.pdecl]/7: an elaborated-type-specifier whose bare
	// unqualified name finds no prior declaration FIRST-DECLARES the
	// class in the smallest enclosing scope — libc++ relies on it with
	// `operator=(const _If<_IsConst, struct __private_nat, ...>&)`
	// (__bit_reference:883), where __private_nat is declared nowhere
	// else. A qualified or template-id form that failed stays NULL.
	if ( bare_name )
	{
	    std::string ename = contextual_identifier_name(name_tb);
	    DataDefSTRUCT *sdd = mint_incomplete_struct_tag(ename,
		    tb->id() == TokenID::tkUNION);
	    flat_datatype_map_iter mi = datatype_map.find(ename);
	    if ( mi != datatype_map.end()
	      && &(*mi)->definition == static_cast<DataDef *>(sdd) )
		return *mi;
	    // C mode: the bare name is deliberately NOT a type name — hand
	    // back a detached type token carrying the minted incomplete tag.
	    TokenDataType *tdt = new TokenDataType(ename.c_str(), *sdd);
	    tdt->file = name_tb->file;
	    tdt->line = name_tb->line;
	    tdt->column = name_tb->column;
	    return tdt;
	}
	return NULL;
    }
    // Leading `::` — the global-scope qualifier ([namespace.qual]):
    // `typedef ::timespec t;` / `using A = ::T;` / `::wrap w;` resolve the
    // name against the GLOBAL scope only (libc++ __threading_support:54 is
    // the motivating use). Global types register in the flat datatype_map
    // under their bare name (namespace members key mangled), so the direct
    // probe IS the global-only lookup; template-ids and member chains then
    // continue exactly as for a bare global name. A `::ns::T` chain (global-
    // qualified NAMESPACE) stays unhandled here and returns NULL as before.
    if ( tb->id() == TokenID::tkNS )
    {
	TokenBase *gt = peekToken();
	if ( !gt || !is_contextual_identifier_token(gt) )
	    return NULL;
	std::string gname = contextual_identifier_name(gt);
	flat_datatype_map_iter gi = datatype_map.find(gname);
	if ( gi == datatype_map.end() )
	    return NULL;
	nextToken();	// consume the global name
	if ( peekToken() && peekToken()->id() == TokenID::tkLT )
	    if ( TokenDataType *inst = instantiate_template_id(gname, gt) )
		return resolve_member_chain_or_type(inst, gt,
						    consume_class_member_chain);
	return resolve_member_chain_or_type((TokenDataType *)(*gi), gt,
					    consume_class_member_chain);
    }
    if ( !is_contextual_identifier_token(tb) )
	return NULL;

    std::string tname = contextual_identifier_name(tb);
    if ( tname == "typename" )
	return resolve_typename_type_token(nextToken(),
					   allow_lazy_types, tb);
    if ( is_decltype_identifier(tname) )
    {
	if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	    return NULL;
	nextToken(); // consume '('
	TokenBase *expr_head = nextToken();
	if ( !expr_head )
	    Throw(tb) << "Expecting expression in decltype(...)" << flush;
	// The decltype operand is UNEVALUATED: entities it names are not ODR-used,
	// so template-call bodies must not be instantiated (declval's "must not be
	// used!" body). The depth guard suppresses body instantiation in parseCallFunc
	// for this operand and every nested call within it; the return type is still
	// resolved. RAII-restore so an exception mid-parse cannot leave it raised.
	++unevaluated_operand_depth;
	TokenBase *expr = NULL;
	try { expr = parseExpression(expr_head, true); }
	catch ( ... ) { --unevaluated_operand_depth; throw; }
	--unevaluated_operand_depth;
	TokenBase *close = nextToken();
	if ( !close || close->id() != TokenID::tkClBrk )
	    Throw(close ? close : tb) << "Expecting ')' after decltype(...)" << flush;
	DataDef *dd = expr ? expr->datadef() : NULL;
	if ( getenv("MADC_DT_PROBE") )
	    fprintf(stderr, "[dtprobe] decltype operand -> '%s' (expr id=%d type=%d)\n",
		    dd ? dd->name.c_str() : "(null)",
		    expr ? (int)expr->id() : -1,
		    expr ? (int)expr->type() : -1);
	if ( !dd )
	    Throw(tb) << "Could not resolve decltype(...) operand type" << flush;
	TokenDataType *tdt = new TokenDataType(dd->name.c_str(), *dd);
	tdt->file = tb->file;
	tdt->line = tb->line;
	tdt->column = tb->column;
	// [dcl.type.simple]: a decltype-specifier can head a qualified name —
	// `decltype(_S_test<A,B>(0))::type` (the file-scope common_type
	// idiom). Continue the member chain exactly as the named-type arms do.
	return resolve_member_chain_or_type(tdt, tb, consume_class_member_chain);
    }
    // `__underlying_type(E)` — the type-yielding intrinsic BOTH standard
    // libraries build std::underlying_type on (libstdc++'s typedef and
    // libc++'s __underlying_type_impl<_Tp, true>). Answered from the
    // DataDefENUM's recorded underlying type (declared fixed base, or the
    // canon range rule computed at the definition's close).
    if ( tname == "__underlying_type" )
    {
	if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	    return NULL;
	nextToken(); // consume '('
	TokenBase *op_tb = nextToken();
	if ( !op_tb )
	    Throw(tb) << "Expecting a type in __underlying_type(...)" << flush;
	TokenDataType *op = resolve_declared_type_token(op_tb, true,
							allow_lazy_types);
	TokenBase *close = nextToken();
	if ( !close || close->id() != TokenID::tkClBrk )
	    Throw(close ? close : tb)
		<< "Expecting ')' after __underlying_type(...)" << flush;
	if ( !op )
	    Throw(tb) << "Could not resolve the __underlying_type(...) operand"
		      << flush;
	DataDef *odd = &op->definition;
	if ( DataDefENUM *edd = dynamic_cast<DataDefENUM *>(odd) )
	{
	    DataDef *u = edd->underlying ? edd->underlying
					 : static_cast<DataDef *>(&ddINT32);
	    TokenDataType *tdt = new TokenDataType(u->name.c_str(), *u);
	    tdt->file = tb->file;
	    tdt->line = tb->line;
	    tdt->column = tb->column;
	    return tdt;
	}
	// A still-DEPENDENT operand (an opaque dependent-surface shell):
	// defer by returning the operand — the concrete instantiation's
	// re-parse resolves it against the real enum. A concrete non-enum
	// is an error, as both canons report.
	if ( odd->type() == DataType::dtRESERVED )
	    return op;
	Throw(tb) << "__underlying_type applied to non-enumeration type '"
		  << odd->name << "'" << flush;
    }

    // Statement-scope completeness demand: a declared-type use reading a
    // MEMBER of a concrete-arg template-id (`typedef Tmpl<...>::type A;`)
    // requires the instance's members to exist, and the opaque variadic
    // shell is memberless (the conjunction<...,false_type> mis-fold, task
    // #94). Outside a class body and outside a dependent pattern parse the
    // args cannot name an enclosing template's parameters, so a variadic
    // primary may really instantiate — the same per-demand-site arming as
    // the expression twin (`Tmpl<args>::member` read) and spec_may_serve.
    // The `::` follow is REQUIRED: a bare declared use (`map<K,V> m;`)
    // keeps the lazy opaque route (arming it real-instantiated container
    // internals eagerly and broke their lowering — the new_allocator
    // address() regression).
    bool stmt_scope_demand = !dependent_parse_in_progress
			  && class_scope_stack.empty()
			  && !class_pattern_capture_in_progress;
    if ( stmt_scope_demand )
    {
	bool member_follows = false;
	if ( !tokens.empty() && tokens[0]
	  && tokens[0]->id() == TokenID::tkLT )
	{
	    DelimDepth d;
	    // The deque starts AT the '<'; seed the tracker's context with
	    // the template-name token so the opener is recognized.
	    d.prev = tb;
	    size_t qi = 0;
	    size_t guard = 0;
	    while ( qi < tokens.size() && ++guard < 4096 )
	    {
		size_t n = delim_scan_step(tokens, qi, d);
		qi += n ? n : 1;
		if ( qi > 0 && !d.angle )
		    break;
	    }
	    member_follows = qi < tokens.size() && tokens[qi]
			  && tokens[qi]->id() == TokenID::tkNS;
	}
	stmt_scope_demand = member_follows;
    }
    if ( peekToken() && peekToken()->id() == TokenID::tkLT )
    {
	bool saved_vri = allow_variadic_real_inst;
	if ( stmt_scope_demand )
	    allow_variadic_real_inst = true;
	TokenDataType *inst = instantiate_template_id(tname, tb);
	allow_variadic_real_inst = saved_vri;
	if ( inst )
	    return resolve_member_chain_or_type(inst, tb,
						consume_class_member_chain);
	// Nested class template OR member ALIAS template used UNQUALIFIED inside
	// its enclosing class (`_Rb_tree_impl<_Compare> _M_impl;` in the _Rb_tree
	// body; `__pointer<_Key> _M_pkey;` where `template<class _Tp> using
	// __pointer = ...;` is a member alias template, node_handle.h): the call
	// above passes owner_hint=NULL, which find_template / find_template_alias
	// match only against top-level templates, so a member template is missed
	// and a later branch returns the bare template/alias with the '<...>' left
	// unconsumed. Retry with each active class scope as the owner_hint so the
	// member template (class or alias) is found and instantiated.
	// Snapshot the scope pointers: instantiate_template_id below can push the
	// owner onto class_scope_stack (a real variadic-member instantiation now
	// does), reallocating the vector and invalidating a live reverse_iterator —
	// the next deref then segfaults. The DataDefCLASS objects outlive the call,
	// so a copy of the pointers is safe to iterate.
	if ( !class_scope_stack.empty() )
	{
	    std::vector<DataDefCLASS *> scopes(class_scope_stack.rbegin(),
					       class_scope_stack.rend());
	    for ( DataDefCLASS *sc : scopes )
		if ( TokenDataType *inst =
			instantiate_template_id(tname, tb, "", sc) )
		    return resolve_member_chain_or_type(inst, tb,
							consume_class_member_chain);
	}
    }

    // [basic.scope.class]: inside a class, its OWN member type aliases (and
    // active template parameters) shadow namespace-scope and global names —
    // BEFORE the namespace chain and the flat map. libc++ declares a real
    // class template `std::__1::__function::__base`, whose flat tag entry
    // otherwise shadowed every class's local `typedef ... __base;`
    // (numeric_limits' entire value surface reads through that alias).
    if ( DataDef *class_alias = resolve_current_class_type_alias(tname) )
    {
	TokenDataType *alias_tok = make_alias_type_token(tname, class_alias, tb);
	return resolve_member_chain_or_type(alias_tok, tb,
					    consume_class_member_chain);
    }

    // Unqualified type lookup inside a namespace: C++ searches the enclosing
    // namespace chain (std::pmr -> std) BEFORE the global scope
    // (namespace_chain_datatype owns the walk).
    if ( TokenDataType *proto = namespace_chain_datatype(tname) )
    {
	TokenDataType *use = (TokenDataType *)proto->clone();
	use->file   = tb->file;
	use->line   = tb->line;
	use->column = tb->column;
	return resolve_member_chain_or_type(use, tb,
					    consume_class_member_chain);
    }

    flat_datatype_map_iter dmi = datatype_map.find(tname);
    if ( dmi != datatype_map.end() )
    {
	// dmi->second is the shared prototype token created at the typedef's
	// definition, carrying the definition-site position. Return a clone
	// stamped with this use-site token's position, so a typedef'd-type
	// usage (and any diagnostic or CIR node derived from it) maps to the
	// use site rather than the typedef definition.
	TokenDataType *use = (TokenDataType *)(*dmi)->clone();
	use->file   = tb->file;
	use->line   = tb->line;
	use->column = tb->column;
	return resolve_member_chain_or_type(use, tb, consume_class_member_chain);
    }

    // `Name<ConcreteType>` where Name is a captured (alias or class) template:
    // instantiate (or reuse) the concrete type and return it. Guarded on a
    // following '<', so non-template identifiers are unaffected.
    {
	bool saved_vri2 = allow_variadic_real_inst;
	if ( stmt_scope_demand )
	    allow_variadic_real_inst = true;
	TokenDataType *inst = instantiate_template_id(tname, tb);
	allow_variadic_real_inst = saved_vri2;
	if ( inst )
	    return resolve_member_chain_or_type(inst, tb,
						consume_class_member_chain);
    }

    // `Q1::Q2::...::Name<Args>` where Name is a captured template. The maps are
    // keyed by bare name but declarations are namespace-qualified variants, so
    // keep the qualifier chain as a namespace hint for the shared resolver.
    if ( peekToken() && peekToken()->id() == TokenID::tkNS )
    {
	// tokens[0] is the '::' after tb; a qualifier ident sits at index 1,
	// each followed by '::', until the template name (an ident) is followed
	// by '<'.
	std::string ns_name = tname;
	std::string resolved_ns = resolve_namespace_name_in_scope(ns_name);
	if ( !resolved_ns.empty() )
	    ns_name = resolved_ns;
	size_t j = 1;
	while ( j + 1 < tokens.size()
	     && tokens[j] && is_contextual_identifier_token(tokens[j]) )
	{
	    std::string member_name = contextual_identifier_name(tokens[j]);
	    if ( tokens[j+1]->id() == TokenID::tkLT
	      && template_declared_in_namespace(member_name, ns_name) )
	    {
		for ( size_t k = 0; k < j; k++ )
		    nextToken();               // consume '::' + each (qualifier '::')
		TokenBase *name_tok = nextToken(); // consume the template name
		if ( TokenDataType *inst =
			instantiate_template_id(member_name, name_tok, ns_name) )
		    return resolve_member_chain_or_type(inst, tb,
						consume_class_member_chain);
		break;
	    }
	    if ( tokens[j+1]->id() == TokenID::tkNS )
	    {
		ns_name += "::" + member_name;
		j += 2;                            // skip a namespace qualifier
	    }
	    else
		break;
	}
    }

    if ( TokenDataType *ns_type = resolve_namespaced_type_token(tb, consume_ns_tokens) )
	return resolve_member_chain_or_type(ns_type, tb,
					    consume_class_member_chain);

    if ( !allow_lazy_types || findVariable(tname) )
	return NULL;

    DataDef *dd = lazy_resolve_type(tname);
    if ( !dd )
	return NULL;
    return new TokenDataType(dd->name.c_str(), *dd);
}

DataDef *Program::resolve_type_token_range(const std::vector<TokenBase *> &toks,
					   size_t start, size_t end)
{
    if ( start >= end || end > toks.size() )
	return NULL;
    // Isolated token stream: swap in [start,end) + a ';' sentinel so the
    // canonical resolver (template-ids, `std::`, class-scope typedefs) reads
    // exactly the return type and stops, then restore the live position. The
    // resolver may instantiate a template-id (idempotent/memoized) — that is
    // the desired side effect; everything else is local.
    std::vector<TokenBase *> seq;
    for ( size_t i = start; i < end; ++i )
	if ( toks[i] )
	    seq.push_back(toks[i]);
    seq.push_back(new TokenSemi());
    TokenBase *saved_cur = _cur_token;
    TokenBase *saved_prv = _prv_token;
    TokenStream::State saved_tokens = tokens.swap_in(std::move(seq));
    _cur_token = NULL;
    _prv_token = NULL;
    DataDef *result = NULL;
    try
    {
	TokenDataType *rt = resolve_declared_type_token(nextToken(), true, true);
	// A trailing DECLARATOR (`T&`, `T&&`, `T*`, `T const&`) is part of the
	// type spelling, but resolve_declared_type_token stops at the type NAME
	// and leaves it on the stream — so the completeness check below read a
	// perfectly good reference type as a substitution failure. Every
	// reference-returning member template therefore failed to resolve its
	// return, and the caller
	// (resolve_member_template_call_return_type) fell back to enumerating
	// same-named candidates and SILENTLY answered with a sibling overload's
	// return type: libc++'s __libcpp_is_referenceable, whose `_Tp& __test(int)`
	// lost to its own `false_type __test(...)`, so add_pointer<int>::type
	// came out as `int`.
	// Same folding rule as skipped_template_function_return_type's
	// ref_wraps/star_wraps: stars innermost, one reference outermost
	// (references never nest).
	size_t star_wraps = 0, ref_wraps = 0;
	while ( rt && peekToken() )
	{
	    TokenID did = peekToken()->id();
	    if ( did == TokenID::tkBand || did == TokenID::tkLand )
	    { ++ref_wraps; nextToken(); continue; }
	    if ( did == TokenID::tkMul )
	    { ++star_wraps; nextToken(); continue; }
	    if ( did == TokenID::tkCONST || did == TokenID::tkVOLATILE )
	    { nextToken(); continue; }
	    break;
	}
	// The range IS the type spelling: anything left before the sentinel
	// means the resolution did not cover it — a SUBSTITUTION FAILURE, not
	// a success (the #27 require_full_parse rule). The motivating leak:
	// `enable_if<false,void>::type` — the member-miss probe declines
	// without consuming, the tolerance hands back the CLASS, and the
	// dangling `::type` silently passed, so enable_if_t<false> "resolved"
	// and defeated SFINAE (__or_/__and_'s catch-all never won).
	// A DEPENDENT parse (pattern registration / capture) legitimately
	// leaves dependent tails unconsumed — enforce completeness only in
	// concrete contexts, where leftovers mean substitution failure.
	if ( rt && (dependent_parse_in_progress
		 || class_pattern_capture_in_progress
		 || (peekToken() && peekToken()->id() == TokenID::tkSemi)) )
	{
	    result = &rt->definition;
	    for ( size_t s = 0; result && s < star_wraps; ++s )
		result = getPointerType(result);
	    if ( result && ref_wraps )
		result = getReferenceType(result);
	}
    }
    catch ( ... )
    {
	result = NULL;
    }
    tokens.swap_back(std::move(saved_tokens));
    _cur_token = saved_cur;
    _prv_token = saved_prv;
    return result;
}

static void parse_objtemp_ctor_arguments(Program &pgm, TokenObjTemp *ot,
					 TokenBase *loc, TokenID close_id,
					 const char *close_spelling)
{
    while ( pgm.peekToken() && pgm.peekToken()->id() != close_id )
    {
	ot->ctor_args.push_back(pgm.parseExpression(pgm.nextToken(), true));
	if ( pgm.peekToken() && pgm.peekToken()->id() == TokenID::tkComma )
	    pgm.nextToken();
    }
    if ( !pgm.peekToken() || pgm.peekToken()->id() != close_id )
	pgm.Throw(loc) << "Expected '" << close_spelling
		       << "' after constructor arguments" << flush;
    pgm.nextToken();
}

// Functional construction `T(args)` / `T{args}` / `Template<...>(args)` in expression position:
// build a TokenObjTemp constructing an anonymous temporary of class T. Recognized
// ONLY when the identifier names a CLASS type (a captured template-id we can
// instantiate, or a known class) IMMEDIATELY followed by '(' or '{' -- so ordinary
// function/variable references (resolved earlier in parseExpression) are untouched.
// Returns NULL when it is not a functional construction. General C++ feature; no
// per-class machinery (works for any class, incl. header-defined std:: classes).
// True when the `(` about to be parsed opens a CALL on a callable receiver
// already sitting on exStack — a functor-class object (declares operator()) or
// a function/function-pointer variable — that the `(` binds to directly
// (prevToken is the receiver's own last token: its identifier, or the `)`/`]`
// closing a call/subscript result). In that case `call(Type(...), ...)` is an
// argument list whose first argument is a functional construction, NOT a
// C-style cast `(Type)expr`. Without this guard, a first argument whose leading
// token is a TYPE (e.g. a substituted class template type parameter,
// `_KeyOfValue()(__v)` in std::_Rb_tree::_M_insert_) steals the `(` for the
// cast/compound-literal path, which drops the temp and the trailing arguments.
bool Program::paren_opens_call_on_receiver(std::stack<TokenBase *> &exStack)
{
	if ( exStack.empty() )
		return false;
	TokenBase *pv = prevToken();
	if ( !pv
	  || (pv->type() != TokenType::ttIdentifier
	   && pv->id() != TokenID::tkClBrk
	   && pv->id() != TokenID::tkClSqr) )
		return false;
	TokenBase *recv = exStack.top();
	std::string op_call("operator()");
	DataDefCLASS *rc = operand_object_class(recv);
	if ( rc && rc->findMethod(op_call) )
		return true;
	TokenVar *rv = dynamic_cast<TokenVar *>(recv);
	if ( rv && rv->var.type && rv->var.type->is_function() )
		return true;
	return false;
}

TokenObjTemp *Program::try_parse_functional_ctor(TokenBase *name_tb)
{
	std::string name = contextual_identifier_name(name_tb);
	if ( name.empty() )
		return NULL;
	DataDefCLASS *cdd = NULL;
	const uint32_t name_id = template_name_pool.intern(name);
	if ( peekToken() && peekToken()->id() == TokenID::tkLT
	  && (find_template(name_id, std::string(), NULL)
	   || find_template_alias(name_id, std::string(), NULL)) )
	{
		// Template-id: instantiate (consumes `<...>`), then require '('.
		if ( TokenDataType *inst = instantiate_template_id(name, name_tb) )
			cdd = dynamic_cast<DataDefCLASS *>(&inst->definition);
	}
	else
	{
		flat_datatype_map_iter dmi = datatype_map.find(name);
		if ( dmi != datatype_map.end() )
			cdd = dynamic_cast<DataDefCLASS *>(&(*dmi)->definition);
		if ( !cdd )
		{
			datadef_map_citer sdmi = struct_map.find(name);
			if ( sdmi != struct_map.end() )
				cdd = dynamic_cast<DataDefCLASS *>(sdmi->second);
		}
	}
	if ( !cdd )
		return NULL;
	if ( !peekToken()
	  || (peekToken()->id() != TokenID::tkOpBrk
	   && peekToken()->id() != TokenID::tkOpBrc) )
		return NULL;   // a bare type-id, not a construction
	TokenID open_id = peekToken()->id();
	TokenID close_id = open_id == TokenID::tkOpBrc ? TokenID::tkClBrc
						       : TokenID::tkClBrk;
	const char *close_spelling = open_id == TokenID::tkOpBrc ? "}" : ")";
	nextToken(); // consume '(' or '{'
	TokenObjTemp *ot = new TokenObjTemp(cdd);
	ot->file = name_tb->file; ot->line = name_tb->line; ot->column = name_tb->column;
	parse_objtemp_ctor_arguments(*this, ot, name_tb, close_id, close_spelling);
	instantiate_member_ctor_template_for_construction(cdd, ot->ctor_args);
	return ot;
}

TokenBase *Program::parse_functional_type_expression(TokenBase *type_tb,
						   DataDef *type_dd)
{
    if ( !type_tb || !type_dd )
	return NULL;
    if ( !peekToken()
      || (peekToken()->id() != TokenID::tkOpBrk
       && peekToken()->id() != TokenID::tkOpBrc) )
	return NULL;

    TokenID open_id = peekToken()->id();
    TokenID close_id = open_id == TokenID::tkOpBrc ? TokenID::tkClBrc
						   : TokenID::tkClBrk;
    const char *close_spelling = open_id == TokenID::tkOpBrc ? "}" : ")";
    if ( open_id == TokenID::tkOpBrc
      && dynamic_cast<DataDefCLASS *>(type_dd) == NULL )
	return NULL;
    nextToken(); // consume '(' or '{'
    if ( DataDefCLASS *cdd = dynamic_cast<DataDefCLASS *>(type_dd) )
    {
	TokenObjTemp *ot = new TokenObjTemp(cdd);
	ot->file = type_tb->file;
	ot->line = type_tb->line;
	ot->column = type_tb->column;
	parse_objtemp_ctor_arguments(*this, ot, type_tb, close_id, close_spelling);
	instantiate_member_ctor_template_for_construction(cdd, ot->ctor_args);
	return ot;
    }

    TokenBase *expr = NULL;
    if ( peekToken() && peekToken()->id() == TokenID::tkClBrk )
    {
	nextToken(); // value-initialization: T()
	if ( type_dd->is_pointer() )
	{
	    TokenNullptr *np = new TokenNullptr();
	    np->setDataType(type_dd);
	    np->file = type_tb->file;
	    np->line = type_tb->line;
	    np->column = type_tb->column;
	    expr = np;
	}
	else
	{
	    TokenInt *zero = new TokenInt(0);
	    zero->setDataType(type_dd);
	    zero->file = type_tb->file;
	    zero->line = type_tb->line;
	    zero->column = type_tb->column;
	    expr = zero;
	}
    }
    else
    {
	TokenBase *expr_head = nextToken();
	if ( !expr_head )
	    Throw(type_tb) << "Expecting expression in functional cast" << flush;
	expr = parseExpression(expr_head, true, false, false, 0, true);
	if ( !peekToken() || peekToken()->id() != TokenID::tkClBrk )
	    Throw(type_tb) << "Expected ')' after functional cast expression" << flush;
	nextToken(); // consume ')'
    }

    TokenCast *tc = new TokenCast(type_dd, expr);
    tc->file = type_tb->file;
    tc->line = type_tb->line;
    tc->column = type_tb->column;
    return tc;
}

// A type-name usage must carry its own source position, not the position of
// the shared prototype TokenDataType held in datatype_map (which is stamped at
// the typedef's definition site). Return a clone of `proto` positioned at the
// use-site token `at`, so declarations and diagnostics map to the usage.
static TokenDataType *use_site_type_token(TokenDataType *proto, TokenBase *at)
{
    if ( !proto || !at )
	return proto;
    TokenDataType *t = (TokenDataType *)proto->clone();
    t->file = at->file;
    t->line = at->line;
    t->column = at->column;
    return t;
}

static size_t query_datadef_measure(const DataDef *dd, bool want_alignof)
{
    if ( !dd )
	return 0;
    // [expr.sizeof]/2 and [expr.alignof]: applied to a REFERENCE type, both
    // yield the REFERENT's measure — `sizeof(int&)` is 4, not the 8 bytes madc
    // stores a reference in. referent_if_reference is the one owner of that
    // unwrap; this is the single measurement point both sizeof and alignof
    // reach, so it belongs here rather than at either call site.
    if ( DataDef *ref = referent_if_reference(const_cast<DataDef *>(dd)) )
	if ( ref != dd )
	    dd = ref;
    return want_alignof ? dd->alignment() : dd->size;
}

static std::string canonical_builtin_simple_type_name(DataDef *dd)
{
    if ( !dd )
	return "";
    if ( dd == &ddDOUBLE )
	return "double";
    if ( DataDefENUM *enum_dd = dynamic_cast<DataDefENUM *>(dd) )
	return "enum:" + enum_dd->enum_name;
    if ( DataDefCOMPLEX *complex_dd = dynamic_cast<DataDefCOMPLEX *>(dd) )
    {
	std::string elem = canonical_builtin_simple_type_name(complex_dd->element_type);
	return elem.empty() ? "" : "complex(" + elem + ")";
    }
    if ( DataDefPTR *ptr_dd = dynamic_cast<DataDefPTR *>(dd) )
    {
	std::string base = canonical_builtin_simple_type_name(ptr_dd->base_type);
	return base.empty() ? "" : "ptr(" + base + ")";
    }
    if ( DataDefCArray *array_dd = dynamic_cast<DataDefCArray *>(dd) )
    {
	std::string elem = canonical_builtin_simple_type_name(array_dd->element_type);
	return elem.empty() ? "" : "array(" + elem + ")";
    }
    if ( dd->is_struct() )
	return "struct:" + dd->name;

    switch ( dd->rawtype() )
    {
	case DataType::dtVOID: return "void";
	case DataType::dtBOOL: return "bool";
	case DataType::dtUINT8: return "unsigned char";
	case DataType::dtINT8: return "char";
	case DataType::dtUINT16: return "unsigned short";
	case DataType::dtINT16: return "short";
	case DataType::dtUINT24: return "unsigned int24";
	case DataType::dtINT24: return "int24";
	case DataType::dtUINT32: return "unsigned int";
	case DataType::dtINT32: return "int";
	case DataType::dtUINT64: return "unsigned long";
	case DataType::dtINT64: return "long";
	case DataType::dtFLOAT: return "float";
	case DataType::dtDOUBLE: return "double";
	case DataType::dtLDOUBLE: return "long double";
	default: break;
    }
    return dd->name;
}

static void strip_top_level_type_qualifiers(std::string &sig)
{
    static const char *prefixes[] = {"const ", "restrict "};
    bool changed = true;
    while ( changed )
    {
	changed = false;
	for ( size_t i = 0; i < sizeof(prefixes) / sizeof(prefixes[0]); ++i )
	{
	    const char *prefix = prefixes[i];
	    size_t len = strlen(prefix);
	    if ( sig.compare(0, len, prefix) == 0 )
	    {
		sig.erase(0, len);
		changed = true;
	    }
	}
    }
}

bool Program::parse_builtin_types_compatible_operand(TokenBase *type_tb,
						   std::string &sig)
{
    sig.clear();
    if ( !type_tb )
	return false;

    std::string leading_qualifiers;
    while ( is_type_qualifier_token(type_tb) )
    {
	if ( !leading_qualifiers.empty() )
	    leading_qualifiers += ' ';
	leading_qualifiers += ((TokenKeyword *)type_tb)->spelling();
	type_tb = nextToken();
	if ( !type_tb )
	    return false;
    }

    if ( type_tb->type() == TokenType::ttDataType )
    {
	TokenDataType *tdt = (TokenDataType *)type_tb;
	if ( tdt->spelling_is("long double") )
	    sig = "long double";
	else
	    sig = canonical_builtin_simple_type_name(&tdt->definition);
    }
    else if ( type_tb->type() == TokenType::ttIdentifier )
    {
	std::string tname = ((TokenIdent *)type_tb)->spelling();
	if ( is_typeof_identifier(tname) )
	{
	    if ( !skip_expression_whitespace() || peekToken()->id() != TokenID::tkOpBrk )
		return false;
	    nextToken();
	    TokenBase *inner_tb = nextToken();
	    if ( !inner_tb )
		return false;
	    DataDef *inner_dd = NULL;
	    if ( inner_tb->type() == TokenType::ttIdentifier )
	    {
		std::string inner_name = ((TokenIdent *)inner_tb)->spelling();
		Variable *inner_var = findVariable(inner_name);
		if ( inner_var )
		    inner_dd = inner_var->type;
		else
		    inner_dd = resolve_named_datadef(inner_name);
	    }
	    else if ( inner_tb->type() == TokenType::ttDataType )
		inner_dd = &((TokenDataType *)inner_tb)->definition;
	    else if ( inner_tb->type() == TokenType::ttKeyword
		   && (inner_tb->id() == TokenID::tkSTRUCT || inner_tb->id() == TokenID::tkUNION) )
	    {
		TokenBase *tag_tb = nextToken();
		if ( !tag_tb || !is_contextual_identifier_token(tag_tb) )
		    return false;
		inner_dd = resolve_named_datadef(contextual_identifier_name(tag_tb));
	    }
	    if ( !inner_dd )
	    {
		TokenBase *expr = parseExpression(inner_tb, true, false, true, 1);
		inner_dd = expr ? expr->datadef() : NULL;
	    }
	    if ( !inner_dd )
		return false;
	    if ( skip_expression_whitespace() && peekToken()->id() == TokenID::tkClBrk )
		nextToken();
	    else if ( (!curToken() || curToken()->id() != TokenID::tkClBrk)
	       && (!prevToken() || prevToken()->id() != TokenID::tkClBrk) )
		return false;
	    sig = canonical_builtin_simple_type_name(inner_dd);
	}
	else
	{
	    DataDef *dd = resolve_named_datadef(tname);
	    sig = canonical_builtin_simple_type_name(dd);
	}
    }
    else if ( type_tb->type() == TokenType::ttKeyword
	   && (type_tb->id() == TokenID::tkSTRUCT || type_tb->id() == TokenID::tkUNION) )
    {
	TokenBase *tag_tb = nextToken();
	if ( !tag_tb || !is_contextual_identifier_token(tag_tb) )
	    return false;
	sig = (type_tb->id() == TokenID::tkSTRUCT ? "struct:" : "union:")
	    + contextual_identifier_name(tag_tb);
    }
    else if ( type_tb->type() == TokenType::ttKeyword && type_tb->id() == TokenID::tkENUM )
    {
	TokenBase *tag_tb = nextToken();
	if ( !tag_tb || !is_contextual_identifier_token(tag_tb) )
	    return false;
	sig = "enum:" + contextual_identifier_name(tag_tb);
    }
    else
	return false;

    if ( sig.empty() )
	return false;
    if ( !leading_qualifiers.empty() )
	sig = leading_qualifiers + " " + sig;

    bool wrapped = false;
    while ( peekToken() )
    {
	skip_expression_whitespace();
	if ( !peekToken() )
	    break;
	if ( peekToken()->id() == TokenID::tkMul )
	{
	    nextToken();
	    std::string ptr_qualifiers;
	    skip_expression_whitespace();
	    while ( peekToken() && is_type_qualifier_token(peekToken()) )
	    {
		if ( !ptr_qualifiers.empty() )
		    ptr_qualifiers += ' ';
		ptr_qualifiers += ((TokenKeyword *)nextToken())->spelling();
	    }
	    sig = ptr_qualifiers.empty()
		? "ptr(" + sig + ")"
		: ptr_qualifiers + " ptr(" + sig + ")";
	    wrapped = true;
	    continue;
	}
	if ( peekToken()->id() == TokenID::tkOpSqr )
	{
	    nextToken();
	    int depth = 1;
	    while ( depth > 0 )
	    {
		TokenBase *dim_tb = nextToken();
		if ( !dim_tb )
		    return false;
		if ( dim_tb->id() == TokenID::tkOpSqr )
		    ++depth;
		else if ( dim_tb->id() == TokenID::tkClSqr )
		    --depth;
	    }
	    sig = "array(" + sig + ")";
	    wrapped = true;
	    continue;
	}
	break;
    }

    if ( !wrapped )
	strip_top_level_type_qualifiers(sig);
    return true;
}

Variable *Program::resolve_c_identifier(TokenIdent *ident_tb, bool expression_head)
{
	Variable *var = NULL;

	if ( expression_head )
	{
	    // C++ unqualified lookup: a function parameter or block local shadows a
	    // same-named namespace member. Check the function-local scope BEFORE the
	    // namespace so e.g. `perl::substr`'s `length` parameter is not resolved to
	    // the `perl::length` function, or `ruby::delete`'s `chars` parameter to the
	    // `ruby::chars` function (emitting a function pointer where a value is
	    // expected). The namespace still precedes the GLOBAL scope below, so an
	    // unqualified `index` inside `namespace perl` still binds to perl::index,
	    // not the global C `index`. Skipped for an explicit `ns::member` qualifier
	    // (stmt_callee_namespace set) — that names the namespace and must not be
	    // shadowed by a local.
	    TokenCpnd *code = stmt_callee_namespace.empty() && !compounds.empty()
			    ? compounds.top() : NULL;
	    if ( code )
		var = code->findVariableLocal(strpool, ident_tb->spelling());
	    if ( !var )
	    {
		std::string lookup_ns = active_cpp_lookup_namespace();
		if ( !lookup_ns.empty() )
		    var = find_namespace_member_in_scope_chain(lookup_ns,
							       ident_tb->spelling());
	    }
	}
	if ( !var )
	    var = findVariable(ident_tb->spelling());
	if ( !var && !expression_head )
	{
	    std::string lookup_ns = active_cpp_lookup_namespace();
	    if ( !lookup_ns.empty() )
		var = find_namespace_member_in_scope_chain(lookup_ns,
							   ident_tb->spelling());
	}
	return var;
}

static bool read_constant_integer(Variable *var, madc_wide_int &out)
{
    if ( !var || !var->is_constant() || !var->data || !var->type || !var->type->is_integer() )
	return false;
    switch ( var->type->rawtype() )
    {
	case DataType::dtBOOL:   out = *((bool *)var->data) ? 1 : 0; return true;
	case DataType::dtINT8:   out = *((int8_t *)var->data);   return true;
	case DataType::dtUINT8:  out = *((uint8_t *)var->data);  return true;
	case DataType::dtINT16:  out = *((int16_t *)var->data);  return true;
	case DataType::dtUINT16: out = *((uint16_t *)var->data); return true;
	case DataType::dtINT24:  out = *((int16_t *)var->data);  return true;
	case DataType::dtUINT24: out = *((uint16_t *)var->data); return true;
	case DataType::dtINT32:  out = *((int32_t *)var->data);  return true;
	case DataType::dtUINT32: out = *((uint32_t *)var->data); return true;
	// 64-bit reads stay SIGN-CARRIED into the wide fold carrier (an int64_t
	// read even for dtUINT64): identical bits and identical fold results to
	// the historical int64 evaluator for every ≤64-bit program. See the
	// madc_wide_int typedef note (datadef.h).
	case DataType::dtINT64:  out = *((int64_t *)var->data);  return true;
	case DataType::dtUINT64: out = *((int64_t *)var->data);  return true;
	case DataType::dtINT128:  out = *((madc_wide_int *)var->data); return true;
	case DataType::dtUINT128: out = (madc_wide_int)*((madc_wide_uint *)var->data); return true;
	default:
	    return false;
    }
}

static void copy_token_location(TokenBase *dst, TokenBase *src)
{
    if ( !dst || !src )
	return;
    dst->file = src->file;
    dst->line = src->line;
    dst->column = src->column;
}

TokenBase *Program::make_expression_context_literal(const madc::value &resolved,
						  TokenBase *src)
{
    TokenBase *tb = NULL;

    switch ( resolved.type() )
    {
	case madc::value::kind::boolean:
	    tb = new TokenInt(resolved.as_boolean() ? 1 : 0);
	    break;
	case madc::value::kind::integer:
	    tb = new TokenInt(resolved.as_integer());
	    break;
	case madc::value::kind::real:
	    tb = new TokenReal(resolved.as_real());
	    break;
	case madc::value::kind::string:
	{
	    std::string literal = resolved.as_string();
	    Variable *literal_var = addLiteral(literal);
	    if ( !literal_var )
		return NULL;
	    tb = new TokenVar(*literal_var);
	    break;
	}
	default:
	    return NULL;
    }

    copy_token_location(tb, src);
    return tb;
}

bool Program::resolve_integer_constant(TokenBase *tb, madc_wide_int &out)
{
    if ( !tb )
	return false;
    if ( tb->type() == TokenType::ttInteger )
    {
	// wival(): the full 128-bit value for a semantically wide constant
	// (parser-folded, ddINT128/ddUINT128-typed); the plain (or
	// gcc-canon-truncated) 64-bit value for everything else.
	out = tb->wival();
	return true;
    }
    if ( tb->type() == TokenType::ttChar )
    {
	out = ((TokenChar *)tb)->get();
	return true;
    }
    // Also accept contextual-identifier keywords (`class`, `try`, `catch`,
    // etc.) as integer constants when they resolve to one — this lets
    // `case class:` work for an enum that has `class` as one of its tags.
    std::string name;
    if ( tb->type() == TokenType::ttIdentifier )
	name = ((TokenIdent *)tb)->spelling();
    else if ( is_contextual_identifier_token(tb) )
	name = contextual_identifier_name(tb);
    else
	return false;
    // Scoped-enum constant in a constant expression: `Tag::Value` (e.g. a
    // `case Color::Green:` label). The enumerators live in the tag's
    // pseudo-namespace (see TokenENUM::parse), so resolve through it. Keep this
    // probe transactional: `ns::Tmpl<...>::member` also starts with a namespace
    // name, and the qualified-member constant folder below must see the intact
    // token chain when this narrow enum lookup does not resolve.
    if ( peekToken() && peekToken()->id() == TokenID::tkNS )
    {
	TokenStream::Pos saved_tokens = tokens.savepos();
	TokenBase *saved_cur = _cur_token;
	TokenBase *saved_prv = _prv_token;
	namespace_map_t::iterator nsi = namespace_map.find(name);
	if ( nsi != namespace_map.end() )
	{
	    nextToken(); // consume '::'
	    TokenBase *member_tb = nextToken();
	    if ( member_tb && is_contextual_identifier_token(member_tb) )
	    {
		std::string member = contextual_identifier_name(member_tb);
		Variable *nsv = find_namespace_member(name, member);
		if ( nsv && read_constant_integer(nsv, out) )
		    return true;
	    }
	    tokens = saved_tokens;
	    _cur_token = saved_cur;
	    _prv_token = saved_prv;
	    if ( _cur_token )
	    {
		TokenBase::_parse_file = _cur_token->file;
		TokenBase::_parse_line = _cur_token->line;
		TokenBase::_parse_column = _cur_token->column;
	    }
	    return false;
	}
	return false;
    }
    // Unqualified PRIOR ENUMERATOR inside the scoped-enum body being defined
    // ([dcl.enum]/5): enumerators are usable in the enum's own body right
    // after their own definition — `general = fixed | scientific` (libc++
    // __charconv/chars_format.h:24). They live only in the tag's
    // pseudo-namespace; TokenENUM::parse points here for the body's duration.
    if ( active_scoped_enum_ns )
    {
	variable_map_iter ei = active_scoped_enum_ns->find(name);
	if ( ei != active_scoped_enum_ns->end()
	  && read_constant_integer(ei->second, out) )
	    return true;
    }
    Variable *var = findVariable(name);
    return read_constant_integer(var, out);
}

static bool is_named_cpp_cast(const std::string &name);
static bool datadef_involves_placeholder(DataDef *dd, bool include_dependent_class);

static madc_wide_int apply_integer_cast_value(DataDef *cast_dd, madc_wide_int val,
					      bool force_unsigned = false)
{
    if ( !cast_dd )
	return val;
    bool is_unsigned = force_unsigned || cast_dd->is_unsigned();
    int sz = cast_dd->size;
    if ( sz == 1 )
	return is_unsigned ? (madc_wide_int)(uint8_t)val : (madc_wide_int)(int8_t)val;
    if ( sz == 2 )
	return is_unsigned ? (madc_wide_int)(uint16_t)val : (madc_wide_int)(int16_t)val;
    if ( sz == 4 )
	return is_unsigned ? (madc_wide_int)(uint32_t)val : (madc_wide_int)(int32_t)val;
    // 8-byte cast truncates the wide carrier to 64 bits. UNSIGNED
    // zero-extends back into the carrier — `(unsigned long)(-1)` is 2^64-1,
    // so `T(-1) < T(0)` with unsigned T folds FALSE (libc++
    // __libcpp_numeric_limits' is_signed; the old sign-carried-always arm
    // folded it TRUE and every dependent value downstream was off by one).
    // SIGNED keeps the sign-carried truncation: `(long)((__int128)1 << 64)`
    // still folds to 0.
    if ( sz == 8 )
	return is_unsigned ? (madc_wide_int)(uint64_t)val
			   : (madc_wide_int)(int64_t)val;
    // 16-byte cast is the identity on the carrier: (__int128)x re-signs a
    // 64-bit value correctly (already sign-carried); (unsigned __int128)x has
    // the same 128-bit pattern.
    return val;
}

madc_wide_int Program::parse_constant_named_cpp_cast(TokenBase *cast_tb,
						     const std::string &cast_name)
{
    if ( !peekToken() || peekToken()->id() != TokenID::tkLT )
	Throw(cast_tb) << "Expecting '<' after " << cast_name << flush;
    nextToken();

    TokenBase *type_tb = nextToken();
    bool force_unsigned = false;
    while ( type_tb && (type_tb->id() == TokenID::tkCONST
	   || type_tb->id() == TokenID::tkVOLATILE
	   || type_tb->id() == TokenID::tkRESTRICT) )
	type_tb = nextToken();
    if ( type_tb && type_tb->type() == TokenType::ttIdentifier
      && ((TokenIdent *)type_tb)->spelling_is("unsigned") )
	force_unsigned = true;

    TokenDataType *tdt = resolve_declared_type_token(type_tb, true, true);
    if ( !tdt )
	Throw(type_tb ? type_tb : cast_tb)
	    << cast_name << " target is not a type" << flush;
    DataDef *cast_dd = &tdt->definition;
    while ( peekToken()
	 && (peekToken()->id() == TokenID::tkMul
	  || peekToken()->id() == TokenID::tkCONST
	  || peekToken()->id() == TokenID::tkVOLATILE
	  || peekToken()->id() == TokenID::tkRESTRICT) )
    {
	TokenBase *pt = nextToken();
	if ( pt->id() == TokenID::tkMul )
	    cast_dd = getPointerType(cast_dd);
    }
    if ( peekToken()
      && (peekToken()->id() == TokenID::tkBand
       || peekToken()->id() == TokenID::tkLand) )
    {
	nextToken();
	cast_dd = getPointerType(cast_dd);
    }
    if ( !peekToken() || peekToken()->id() != TokenID::tkGT )
	Throw(cast_tb) << "Expecting '>' to close "
			   << cast_name << "<...>" << flush;
    nextToken();
    if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	Throw(cast_tb) << "Expecting '(' after "
			   << cast_name << "<...>" << flush;
    nextToken();

    madc_wide_int val = parse_constant_integer_expression();
    TokenBase *close = nextToken();
    if ( !close || close->id() != TokenID::tkClBrk )
	Throw(close ? close : cast_tb)
	    << "Expecting ')' after " << cast_name << "<...>(...)" << flush;
    return apply_integer_cast_value(cast_dd, val, force_unsigned);
}

bool Program::try_parse_constant_functional_cast(TokenBase *type_tb,
						 madc_wide_int &out)
{
    if ( !type_tb || !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	return false;

    DataDef *cast_dd = NULL;
    if ( type_tb->type() == TokenType::ttDataType )
	cast_dd = &static_cast<TokenDataType *>(type_tb)->definition;
    else if ( is_contextual_identifier_token(type_tb) )
    {
	std::string name = contextual_identifier_name(type_tb);
	cast_dd = resolve_current_class_type_alias(name);
	if ( !cast_dd )
	    cast_dd = resolve_named_datadef(name);
    }
    if ( ::getenv("MADC_STATCONST_PROBE") && type_tb
      && is_contextual_identifier_token(type_tb) )
	fprintf(stderr, "[statconst] fncast head %s -> %s%s\n",
		contextual_identifier_name(type_tb).c_str(),
		cast_dd ? cast_dd->name.c_str() : "(null)",
		cast_dd && cast_dd->is_template_param() ? " [param]" : "");
    if ( !cast_dd )
	return false;
    // A functional cast on a TEMPLATE-PARAM placeholder (`_Tp(-1) < _Tp(0)`
    // during a pattern CAPTURE) is dependent: folding under the placeholder
    // would bake the placeholder's signedness into the pattern's constant
    // (the [traitfold] rule's functional-cast twin). Refuse — the capture
    // skips the initializer and the instantiation re-folds it under the
    // concrete binding.
    if ( cast_dd->is_template_param() )
	return false;

    nextToken(); // consume '('
    madc_wide_int val = parse_constant_integer_expression();
    TokenBase *close = nextToken();
    if ( !close || close->id() != TokenID::tkClBrk )
	Throw(close ? close : type_tb)
	    << "Expecting ')' after functional cast in constant expression" << flush;
    out = apply_integer_cast_value(cast_dd, val);
    return true;
}

bool Program::is_shared_global_extern_reference(TokenCpnd *code, Variable *var)
{
    return parsing_extern_decl
	&& code
	&& var
	&& var->is_global();
}

static size_t query_fixed_array_sizeof_value(TokenVar *tv, bool want_alignof, bool deref);

TokenBase *Program::parse_parenthesized_expression(const char *context,
						 bool stop_on_closing_paren)
{
    TokenBase *open = nextToken();
    if ( !open || open->id() != TokenID::tkOpBrk )
	Throw(open) << "expecting ( after " << context << flush;

    TokenBase *first = nextToken();
    TokenBase *expr = parseExpression(first, true, false, stop_on_closing_paren, 1);
    if ( !expr )
	Throw(first ? first : open) << "Failed to parse " << context << " expression" << flush;

    return expr;
}

DataDef *Program::resolve_type_query_datadef(TokenBase *type_tb,
					   const std::string &op_name,
					   bool &have_value, size_t &query_value)
{
    bool want_alignof = is_alignof_identifier(op_name);
    DataDef *dd = NULL;
    Variable *var = NULL;

    if ( is_contextual_identifier_token(type_tb) )
    {
	std::string tname = contextual_identifier_name(type_tb);
	var = findVariable(tname);
	if ( var && peekToken()
	  && (peekToken()->id() == TokenID::tkOpSqr
	   || peekToken()->id() == TokenID::tkDot
	   || peekToken()->id() == TokenID::tkDeRef) )
	{
	    TokenBase *chain = parsePostfixChain(type_tb);
	    DataDef *cdd = chain ? chain->datadef() : NULL;
	    if ( !cdd )
		Throw(type_tb) << op_name << ": cannot determine type of expression" << flush;
	    query_value = query_datadef_measure(cdd, want_alignof);
	    if ( !want_alignof )
	    {
		if ( TokenMember *tm = dynamic_cast<TokenMember *>(chain) )
		{
		    if ( tm->is_fixed_array_member() )
		    {
			DataDef *otype = tm->object.type;
			if ( DataDefPTR *opt = dynamic_cast<DataDefPTR *>(otype) )
			    otype = opt->base_type;
			if ( DataDefSTRUCT *sdd = dynamic_cast<DataDefSTRUCT *>(otype) )
			{
			    std::string mname = tm->var.name;
			    query_value *= sdd->m_count(mname);
			}
		    }
		}
	    }
	    have_value = true;
	    return NULL;
	}
	if ( var )
	{
	    query_value = query_datadef_measure(var->type, want_alignof);
	    if ( !want_alignof && var->is_fixed_array() )
		query_value *= var->total_elements();
	    have_value = true;
	    return NULL;
	}
	dd = resolve_current_class_type_alias(tname);
	if ( dd )
	    return dd;
    }

    if ( !is_c_mode() && is_contextual_identifier_token(type_tb)
      && is_decltype_identifier(contextual_identifier_name(type_tb))
      && peekToken() && peekToken()->id() == TokenID::tkOpBrk )
    {
	// sizeof(decltype(expr)) / alignof(decltype(expr)) — `decltype` is a
	// reserved tkCPPKEYWORD in C++ modes, so it reaches neither the
	// identifier nor the datatype arm below. Route through the one
	// declared-type resolver, which owns the decltype arm (libc++
	// bsd_locale_fallbacks.h family; the statement-head route is the
	// sibling in parseStatement's keyword arm).
	if ( TokenDataType *tdt =
		resolve_declared_type_token(type_tb, true, true) )
	    return &tdt->definition;
    }

    if ( type_tb->type() == TokenType::ttDataType )
    {
	// Template-id operand whose template name lexed as a datatype
	// (sizeof(vector<int>) after the bare name registered): the one
	// declared-type resolver consumes and instantiates '<...>' — the
	// same path the explicit-dtor name and dynamic_cast arms use.
	if ( peekToken() && peekToken()->id() == TokenID::tkLT )
	{
	    if ( TokenDataType *tdt =
		    resolve_declared_type_token(type_tb, true, true) )
		return &tdt->definition;
	}
	dd = &((TokenDataType *)type_tb)->definition;
    }
    else if ( type_tb->type() == TokenType::ttIdentifier )
    {
	std::string tname = ((TokenIdent *)type_tb)->spelling();
	var = findVariable(tname);
	if ( var && peekToken()
	  && (peekToken()->id() == TokenID::tkOpSqr
	   || peekToken()->id() == TokenID::tkDot
	   || peekToken()->id() == TokenID::tkDeRef) )
	{
	    TokenBase *chain = parsePostfixChain(type_tb);
	    DataDef *cdd = chain ? chain->datadef() : NULL;
	    if ( !cdd )
		Throw(type_tb) << op_name << ": cannot determine type of expression" << flush;
	    query_value = query_datadef_measure(cdd, want_alignof);
	    if ( !want_alignof )
	    {
		if ( TokenMember *tm = dynamic_cast<TokenMember *>(chain) )
		{
		    if ( tm->is_fixed_array_member() )
		    {
			DataDef *otype = tm->object.type;
			if ( DataDefPTR *opt = dynamic_cast<DataDefPTR *>(otype) )
			    otype = opt->base_type;
			if ( DataDefSTRUCT *sdd = dynamic_cast<DataDefSTRUCT *>(otype) )
			{
			    std::string mname = tm->var.name;
			    query_value *= sdd->m_count(mname);
			}
		    }
		}
	    }
	    have_value = true;
	    var = NULL;
	}
	else if ( var )
	{
	    query_value = query_datadef_measure(var->type, want_alignof);
	    if ( !want_alignof && var->is_fixed_array() )
		query_value *= var->total_elements();
	    have_value = true;
	}
	else
	{
	    dd = resolve_current_class_type_alias(tname);
	    if ( !dd )
		dd = resolve_named_datadef(tname);
	    // Template-id or qualified type as the operand — sizeof(Box<int>),
	    // alignof(std::vector<int>), sizeof(Tmpl<X>::member): the bare-name
	    // lookups above cannot consume '<...>' or a '::' chain. Route
	    // through the one declared-type resolver — the same path the
	    // explicit-dtor name and dynamic_cast arms use; it instantiates on
	    // demand ([expr.sizeof] requires a complete type) and consumes
	    // nothing when it fails, so the sizeof(expression) fallback still
	    // sees an intact stream. Variables already won above, so a
	    // less-than expression (sizeof(v < 3)) never reaches this arm.
	    if ( !dd && peekToken()
	      && (peekToken()->id() == TokenID::tkLT
	       || peekToken()->id() == TokenID::tkNS) )
	    {
		if ( TokenDataType *tdt =
			resolve_declared_type_token(type_tb, true, true) )
		    dd = &tdt->definition;
	    }
	}
    }
    else if ( type_tb->type() == TokenType::ttKeyword
	   && (type_tb->id() == TokenID::tkSTRUCT || type_tb->id() == TokenID::tkUNION) )
    {
	TokenBase *tag_tb = nextToken();
	if ( tag_tb && tag_tb->type() == TokenType::ttIdentifier )
	    dd = resolve_named_datadef(((TokenIdent *)tag_tb)->spelling());
	if ( !dd )
	    Throw(tag_tb) << "Unknown struct/union type in " << op_name << flush;
    }
    else if ( type_tb->type() == TokenType::ttKeyword && type_tb->id() == TokenID::tkENUM )
    {
	// sizeof(enum X) — enums are int-sized
	if ( peekToken() && is_contextual_identifier_token(peekToken()) )
	    nextToken(); // consume tag
	query_value = sizeof(int);
	have_value = true;
    }
    else if ( type_tb->type() == TokenType::ttKeyword && type_tb->id() == TokenID::tkCONST )
    {
	// sizeof(const type) — skip const qualifier
	TokenBase *inner = nextToken();
	return resolve_type_query_datadef(inner, op_name, have_value, query_value);
    }
    else if ( type_tb->id() == TokenID::tkMul )
    {
	TokenBase *deref_tb = nextToken();
	if ( !deref_tb || !is_contextual_identifier_token(deref_tb) )
	    Throw(type_tb) << "Expecting identifier after '*' in " << op_name << flush;
	DataDef *deref_base = NULL;
	if ( peekToken()
	  && (peekToken()->id() == TokenID::tkDot
	   || peekToken()->id() == TokenID::tkDeRef
	   || peekToken()->id() == TokenID::tkOpSqr) )
	{
	    TokenBase *chain = parsePostfixChain(deref_tb);
	    DataDef *cdd = chain ? chain->datadef() : NULL;
	    if ( !cdd )
		Throw(deref_tb) << op_name << "(*expr): cannot determine type" << flush;
	    if ( cdd->is_pointer() )
	    {
		DataDefPTR *cdp = dynamic_cast<DataDefPTR *>(cdd);
		deref_base = (cdp && cdp->base_type) ? cdp->base_type : &ddINT64;
	    }
	    else
		deref_base = cdd;
	}
	else
	{
	    std::string dname = contextual_identifier_name(deref_tb);
	    Variable *dvar = findVariable(dname);
	    if ( !dvar )
		Throw(deref_tb) << "undeclared identifier '" << dname << "' in " << op_name << "(*...)" << flush;
	    if ( dvar->is_fixed_array() )
		deref_base = dvar->type;
	    else if ( dvar->type->is_pointer() )
	    {
		DataDefPTR *dptr = dynamic_cast<DataDefPTR *>(dvar->type);
		deref_base = (dptr && dptr->base_type) ? dptr->base_type : &ddINT64;
	    }
	    else
		Throw(deref_tb) << op_name << "(*" << dname << "): not a pointer or array" << flush;
	}
	query_value = query_datadef_measure(deref_base, want_alignof);
	have_value = true;
    }

    return dd;
}

size_t Program::evaluate_type_query(TokenBase *op_tb, const std::string &op_name)
{
    bool want_alignof = is_alignof_identifier(op_name);

    if ( peekToken() && peekToken()->id() != TokenID::tkOpBrk )
    {
	TokenBase *probe = peekToken();
	bool deref = (probe->id() == TokenID::tkMul);
	if ( deref )
	{
	    nextToken();
	    probe = peekToken();
	}
	// sizeof "literal" — string literal without parens
	if ( probe && probe->type() == TokenType::ttString )
	{
	    TokenStr *ts = static_cast<TokenStr *>(nextToken());
	    return ts->spelling_len() + 1; // include NUL terminator
	}
	if ( !probe || !is_contextual_identifier_token(probe) )
	    Throw(op_tb) << "Expecting '(' or identifier after " << op_name << flush;
	TokenBase *id_tb = nextToken();
	TokenBase *chain = parsePostfixChain(id_tb);
	DataDef *cdd = type_query_chain_datadef(chain);
	if ( !cdd )
	    Throw(id_tb) << op_name << ": cannot determine type of expression" << flush;
	size_t value = query_datadef_measure(cdd, want_alignof);
	if ( deref && cdd->is_pointer() )
	{
	    DataDefPTR *pdd = dynamic_cast<DataDefPTR *>(cdd);
	    if ( pdd && pdd->base_type )
		value = query_datadef_measure(pdd->base_type, want_alignof);
	}
	else if ( TokenVar *tv = dynamic_cast<TokenVar *>(chain) )
	{
	    if ( tv->var.is_fixed_array() )
		value = query_fixed_array_sizeof_value(tv, want_alignof, deref);
	}
	return value;
    }

    if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	Throw(op_tb) << "Expecting '(' after " << op_name << flush;
    nextToken();
    TokenBase *type_tb = nextToken();
    DataDef *dd = NULL;
    size_t value = 0;
    bool have_value = false;

    dd = resolve_type_query_datadef(type_tb, op_name, have_value, value);
    // [expr.sizeof]p1 / [expr.alignof]: the operand type must be COMPLETE.
    // A bodyless forward instantiation (libc++ <iosfwd>'s stream typedefs)
    // measured 0 here silently; complete it on demand now that the
    // definition may have registered.
    if ( dd )
	dd = complete_class_type_on_demand(dd);
    // Fallback: sizeof(expression) — parse as expression, use its type
    bool expr_fallback_consumed_paren = false;
    if ( !have_value && !dd )
    {
	// sizeof("literal") — C string literals are char arrays. Check type_tb
	// before parseExpression transforms it.
	if ( type_tb && type_tb->type() == TokenType::ttString )
	{
	    TokenStr *ts = static_cast<TokenStr *>(type_tb);
	    value = ts->spelling_len() + 1; // include NUL terminator
	    have_value = true;
	    dd = NULL;
	}
	else
	{
	    TokenBase *expr = parseExpression(type_tb, true, false, true, 1);
	    if ( expr && expr->datadef() )
	    {
		dd = expr->datadef();
		// For fixed arrays accessed as expressions, use element size
		if ( TokenVar *tv = dynamic_cast<TokenVar *>(expr) )
		    if ( tv->var.is_fixed_array() )
			value = query_fixed_array_sizeof_value(tv, want_alignof, false);
		if ( !value )
		    value = query_datadef_measure(dd, want_alignof);
		have_value = true;
		dd = NULL; // have_value is set, skip the pointer/array loop below
		expr_fallback_consumed_paren = true;
	    }
	    if ( !have_value )
		Throw(type_tb) << "Unknown type in " << op_name << flush;
	}
    }

    while ( !have_value && peekToken() )
    {
	if ( peekToken()->id() == TokenID::tkMul )
	{
	    nextToken();
	    dd = getPointerType(dd);
	    continue;
	}
	if ( peekToken()->id() == TokenID::tkOpBrk )
	{
	    TokenBase *open = nextToken();
	    TokenBase *star = nextToken();
	    if ( !star || star->id() != TokenID::tkMul )
		Throw(star ? star : open) << "Unsupported parenthesized declarator in " << op_name << flush;
	    dd = getPointerType(dd);
	    TokenBase *close = nextToken();
	    if ( !close || close->id() != TokenID::tkClBrk )
		Throw(close ? close : open) << "Expecting ')' in " << op_name << " function pointer type" << flush;
	    if ( peekToken() && peekToken()->id() == TokenID::tkOpBrk )
	    {
		nextToken();
		int depth = 1;
		while ( depth > 0 )
		{
		    TokenBase *pt = nextToken();
		    if ( !pt )
			Throw(open) << "Unexpected end of input in " << op_name << " function pointer parameter list" << flush;
		    if ( pt->id() == TokenID::tkOpBrk )
			++depth;
		    else if ( pt->id() == TokenID::tkClBrk )
			--depth;
		}
	    }
	    continue;
	}
	break;
    }
    // The expression fallback (sizeof(expr)) already consumed the closing
    // paren via parseExpression's stop_on_closing_paren. Only consume it
    // here for the type-name / variable-name path.
    if ( !expr_fallback_consumed_paren )
    {
	if ( !peekToken() || peekToken()->id() != TokenID::tkClBrk )
	    Throw(type_tb) << "Expecting ')' after " << op_name << " type" << flush;
	nextToken();
    }

    if ( !have_value && dd )
	value = query_datadef_measure(dd, want_alignof);

    return value;
}

// --- Type-trait builtins (__is_class, __is_base_of, …) ------------------------
// libstdc++ <type_traits>/<tuple> implement std::is_* via these compiler
// intrinsics. madc monomorphizes templates (token-substitute + re-parse on use),
// so by the time `__is_class(T)` is parsed the arg is a CONCRETE type — no
// dependent-placeholder handling is needed; evaluate to a bool constant here.
//
// CORRECTNESS-FIRST: only traits madc can answer FAITHFULLY from its DataDef model
// are recognized; the rest fall through to the normal undeclared-identifier path
// (a clear error, never a WRONG bool that would silently corrupt SFINAE). Adding a
// new trait = one entry here + one branch in eval_type_trait — provided madc can
// model it exactly.
// Implement EXACTLY the gcc-13 trait builtins that madc can answer faithfully —
// no more: providing a builtin gcc lacks (e.g. __is_pointer/__is_void, which gcc
// implements in libstdc++, not the compiler) could shadow a library identifier.
static const int TRAIT_ARITY_VARIADIC = -2;   // one-or-more type arguments

static int type_trait_arity(const std::string &name)
{
    if ( name == "__is_same" || name == "__is_base_of"
      || name == "__is_assignable" )
	return 2;
    // Ungated with the [dcl.spec]/1 east-specifier fix: folding
    // __has_*_iterator_category flips libc++'s copy dispatch onto
    // __copy<_ClassicAlgPolicy,...>, whose `pair<...> inline constexpr`
    // declaration head now parses (the guard's motivating regression).
    if ( name == "__is_convertible_to" || name == "__is_convertible" )
	return 2;
    if ( name == "__is_class" || name == "__is_union" || name == "__is_enum"
      || name == "__has_trivial_destructor" || name == "__is_trivial"
      || name == "__is_empty" || name == "__is_standard_layout"
      || name == "__is_pod" || name == "__is_destructible"
      || name == "__is_final" )
	return 1;
    if ( name == "__is_constructible" || name == "__is_nothrow_constructible" )
	return TRAIT_ARITY_VARIADIC;
    return 0;   // not a supported trait
}

// Declared in madc.h: __has_builtin answers from this same registry, so a
// library guarding a trait with `#if __has_builtin(__has_trivial_destructor)`
// learns what madc really implements.
bool is_type_trait_builtin(const std::string &name)
{
    return type_trait_arity(name) != 0;
}

static bool trait_is_enum(DataDef *dd)
{
    return dynamic_cast<DataDefENUM *>(dd) != NULL;
}
// __is_class: a (non-union) class OR struct. DataDefCLASS derives from
// DataDefSTRUCT, so both match the cast; union_layout separates out unions, and a
// DataDefENUM is not a DataDefSTRUCT so enums are excluded.
static bool trait_is_class(DataDef *dd)
{
    DataDefSTRUCT *s = dynamic_cast<DataDefSTRUCT *>(dd);
    return s && !s->union_layout;
}
static bool trait_is_union(DataDef *dd)
{
    DataDefSTRUCT *s = dynamic_cast<DataDefSTRUCT *>(dd);
    return s && s->union_layout;
}
// __is_final(T) ([class.pre]/4): T is a class declared with the `final`
// class-virt-specifier, so it can never be a base. A non-class type is not final
// (is_final<int> = false), matching both canons. The flag is recorded from the
// class head.
//
// libc++ cannot lay out __compressed_pair without this: its empty-base
// specialization is selected by
//   bool _CanBeEmptyBase = is_empty<_Tp>::value && !__libcpp_is_final<_Tp>::value
// and __libcpp_is_final is integral_constant<bool, __is_final(_Tp)> with NO
// __has_builtin guard. Missing the intrinsic left that whole default unfoldable,
// so the member-holding primary won and an empty allocator cost a byte inside
// every compressed pair — the basic_string size came out 8 bytes over the clang
// oracle. Gate: tests/teststring_libcxx.mad asserts the size per flavor.
static bool trait_is_final(DataDef *dd)
{
    // DataDefSTRUCT, not DataDefCLASS: `struct X final { int x; };` never earns
    // promotion to a class, and a union is a class type too ([class.union]).
    DataDefSTRUCT *s = dynamic_cast<DataDefSTRUCT *>(dd);
    return s && s->struct_is_final;
}
// __is_empty(T) ([meta.unary.prop]): T is a non-union class with NO non-static
// data members, no virtual functions, no virtual bases, and every base class is
// itself empty. A non-class type is not empty (is_empty<int> = false). libstdc++
// instantiates is_empty<allocator<T>> for its allocator EBO compression, which
// <memory>'s allocator_traits chain drags into the vector reallocation path.
static bool trait_is_empty(DataDef *dd)
{
    // A non-class/union type is not empty (is_empty<int> = false). `members`
    // lives on the DataDefSTRUCT base, so a bare empty struct (DataDefSTRUCT not
    // promoted to DataDefCLASS) is handled too.
    DataDefSTRUCT *s = dynamic_cast<DataDefSTRUCT *>(dd);
    if ( !s || s->union_layout )
	return false;
    if ( !s->members.empty() )		// non-static data members -> not empty
	return false;
    DataDefCLASS *c = dynamic_cast<DataDefCLASS *>(dd);
    if ( !c )
	return true;			// plain empty struct: no bases / virtuals
    if ( c->is_polymorphic() )		// virtual functions -> not empty
	return false;
    if ( c->base_class && !trait_is_empty(c->base_class) )
	return false;
    for ( size_t i = 0; i < c->bases.size(); ++i )
    {
	if ( c->bases[i].is_virtual )	// a virtual base -> not empty
	    return false;
	if ( c->bases[i].base && !trait_is_empty(c->bases[i].base) )
	    return false;
    }
    return true;
}
// __has_trivial_destructor(T) ([class.dtor] triviality, the gcc-13 builtin
// libstdc++'s stl_construct.h dispatches `_Destroy_aux<...>` on): a non-class
// type is trivially destructible; a class is iff it has no user-declared (or
// virtual) destructor AND every direct base and every class-type data member is
// trivially destructible. Pointer members are non-class, hence trivial.
static bool trait_has_trivial_destructor(DataDef *dd)
{
    DataDefCLASS *c = dynamic_cast<DataDefCLASS *>(dd);
    if ( !c )
	return true;
    if ( c->has_user_dtor )
	return false;
    if ( c->base_class && !trait_has_trivial_destructor(c->base_class) )
	return false;
    for ( size_t i = 0; i < c->bases.size(); ++i )
	if ( c->bases[i].base && !trait_has_trivial_destructor(c->bases[i].base) )
	    return false;
    for ( size_t i = 0; i < c->members.size(); ++i )
	if ( c->members[i].second
	  && !trait_has_trivial_destructor(c->members[i].second) )
	    return false;
    return true;
}
// __is_trivial(T) ([basic.types]: a trivially-copyable type with a trivial
// default constructor — the gcc/clang builtin libstdc++'s uninitialized_copy /
// stl_algobase dispatch the memmove optimization on). A non-class type
// (scalar/pointer/enum) is trivial; a class is trivial iff it declares no
// constructor or destructor, is not polymorphic, and every base and class-type
// member is itself trivial. Conservative for the rare user-copy-ctor-only case
// (returns false), which only ever disables an optimization — never miscompiles.
// Verified against g++ and clang++ (int/ptr/POD=1, user-ctor/user-dtor/virtual=0).
static bool trait_is_trivial(DataDef *dd)
{
    DataDefCLASS *c = dynamic_cast<DataDefCLASS *>(dd);
    if ( !c )
	return true;
    if ( c->has_user_ctor || c->has_user_dtor || c->is_polymorphic() )
	return false;
    if ( c->base_class && !trait_is_trivial(c->base_class) )
	return false;
    for ( size_t i = 0; i < c->bases.size(); ++i )
	if ( c->bases[i].base && !trait_is_trivial(c->bases[i].base) )
	    return false;
    for ( size_t i = 0; i < c->members.size(); ++i )
	if ( c->members[i].second && !trait_is_trivial(c->members[i].second) )
	    return false;
    return true;
}
// __is_standard_layout(T) ([class.prop]): a scalar / pointer / enum is standard-
// layout; a class is standard-layout iff it has no virtual functions and no virtual
// bases, all non-static data members share the SAME access control and are each
// standard-layout, every base class is standard-layout, non-static data members
// appear in at most ONE class of the hierarchy, and the first member's type is not a
// base type. The repeated-base-subobject clause ([class.prop] last bullet) is rare
// and not modeled — conservative-true there only relaxes an EBO optimization, never
// miscompiles (mirrors trait_is_trivial's documented conservatism). Verified against
// g++/clang for int/ptr/empty-class (=1) and virtual/mixed-access (=0).
static bool trait_is_standard_layout(DataDef *dd)
{
    DataDefSTRUCT *s = dynamic_cast<DataDefSTRUCT *>(dd);
    if ( !s )
	return true;   // scalar / pointer / enum
    DataDefCLASS *c = dynamic_cast<DataDefCLASS *>(dd);
    if ( c && c->is_polymorphic() )
	return false;   // virtual functions / vptr
    uint32_t acc0 = 0;
    bool have_acc = false;
    for ( size_t i = 0; i < s->members.size(); ++i )
    {
	uint32_t a = i < s->member_access.size() ? s->member_access[i] : 0;
	if ( !have_acc ) { acc0 = a; have_acc = true; }
	else if ( a != acc0 ) return false;          // mixed access control
	if ( s->members[i].second && !trait_is_standard_layout(s->members[i].second) )
	    return false;
    }
    if ( c )
    {
	bool base_has_members = false;
	if ( c->base_class )
	{
	    if ( !trait_is_standard_layout(c->base_class) ) return false;
	    if ( !c->base_class->members.empty() ) base_has_members = true;
	}
	for ( size_t i = 0; i < c->bases.size(); ++i )
	{
	    if ( c->bases[i].is_virtual ) return false;     // virtual base
	    if ( c->bases[i].base )
	    {
		if ( !trait_is_standard_layout(c->bases[i].base) ) return false;
		if ( !c->bases[i].base->members.empty() ) base_has_members = true;
	    }
	}
	if ( base_has_members && !c->members.empty() )
	    return false;    // non-static data members in both a base and the derived class
	if ( !c->members.empty() && c->members[0].second )
	{
	    DataDef *fm = c->members[0].second;        // first member's type != a base type
	    if ( c->base_class && fm == (DataDef *)c->base_class ) return false;
	    for ( size_t i = 0; i < c->bases.size(); ++i )
		if ( c->bases[i].base && fm == (DataDef *)c->bases[i].base ) return false;
	}
    }
    return true;
}
// __is_pod(T) ([basic.types] pre-C++20; a gcc-13 compiler builtin): POD == trivial
// AND standard-layout. libstdc++'s _Rb_tree_impl selects an EBO layout via
// `__is_pod(_Key_compare)` (stl_tree.h), so std::map / std::set need it.
static bool trait_is_pod(DataDef *dd)
{
    return trait_is_trivial(dd) && trait_is_standard_layout(dd);
}
// __is_base_of(B, D): true if B and D name the same class, or B is a (direct or
// indirect) base of class D. Ignores access (matches the intrinsic's semantics —
// std:: layers accessibility on top). Both must be class types.
static bool trait_is_base_of(DataDef *base, DataDef *derived)
{
    DataDefCLASS *b = dynamic_cast<DataDefCLASS *>(base);
    DataDefCLASS *d = dynamic_cast<DataDefCLASS *>(derived);
    if ( !b || !d )
	return false;
    if ( b == d || b->name == d->name )
	return true;
    if ( d->base_class && trait_is_base_of(b, d->base_class) )
	return true;
    for ( size_t i = 0; i < d->bases.size(); ++i )
	if ( d->bases[i].base && trait_is_base_of(b, d->bases[i].base) )
	    return true;
    return false;
}

// One parsed type-argument to a type trait, with the ref/cv qualification that
// `__is_assignable` / `__is_constructible` are sensitive to (`int&` != `int`,
// `const int&` != `int&`). `dd` is the REFERENT type (references are recorded as
// flags, not folded into a DataDefREF) after folding any trailing `*`.
struct TraitTypeArg
{
    DataDef *dd;
    bool is_lref;          // trailing `&`
    bool is_rref;          // trailing `&&`
    bool referent_const;   // leading `const`
    TraitTypeArg() : dd(NULL), is_lref(false), is_rref(false), referent_const(false) {}
    bool same_as(const TraitTypeArg &o) const
    {
	return dd && o.dd && dd->name == o.dd->name
	    && is_lref == o.is_lref && is_rref == o.is_rref
	    && referent_const == o.referent_const;
    }
};

// A SUBSTITUTED trait argument arrives as ONE type token with the reference
// already baked into the DataDef (`_Tp` bound to `int&` substitutes a
// DataDefREF; `const T&` a REF wrapping a CONST) — there are no trailing
// `&`/`&&`/`const` tokens for the arg parsers to set the flags from. Un-unwrapped,
// the REF read as a non-class prvalue — never assignable-to — so
// is_move_assignable<int> silently folded FALSE through the whole
// __and_fn/__conditional_t chain; a baked REF also never same_as-matched the
// spelled form of the same type. Normalize to the referent+flags shape the
// spelled form produces. madc's IR keeps ONE reference kind post-resolution,
// so a baked reference reads as the LVALUE form (trait uses that need the
// rvalue distinction spell it with trailing `&&` tokens, which win above).
static void unwrap_baked_trait_arg(TraitTypeArg &a)
{
    if ( a.is_lref || a.is_rref )
	return;
    if ( DataDefREF *rdd = dynamic_cast<DataDefREF *>(a.dd) )
    {
	a.is_lref = true;
	a.dd = rdd->base_type;
    }
    if ( DataDefCONST *cdd = dynamic_cast<DataDefCONST *>(a.dd) )
    {
	a.referent_const = true;
	a.dd = cdd->base_type;
    }
}

// A REFERENCE type is never a class/union/enum, never empty, final, trivial,
// standard-layout or POD, and never relates via __is_base_of — the class-family
// trait predicates only see the REFERENT DataDef and would answer for T instead
// of T&. The one family member that flips the other way:
// __has_trivial_destructor(T&) is TRUE regardless of the referent's dtor
// (destroying a reference is a no-op). Oracle (g++-13 == clang++-18,
// tmp/reftrait1.cpp + tmp/reftrait2.cpp): __is_empty(E&)=0 __is_class(E&)=0
// __is_trivial(int&)=0 __has_trivial_destructor(int&)=1 __is_final(F&)=0
// __is_standard_layout(int&)=0 __is_pod(int&)=0 __has_trivial_destructor(NT&)=1
// __is_base_of(B&,D&)=0. Both dispatch sites (evaluate_type_trait and
// eval_local_type_trait — the recorded trait_builtin_dispatch_twins family)
// gate through this ONE helper.
static bool trait_arg_is_reference(const TraitTypeArg &a)
{
    return a.is_lref || a.is_rref;
}

// Tri-state: 1 = yes, 0 = no, -1 = madc cannot determine faithfully (the caller
// raises a clear error rather than emit a WRONG bool — a wrong trait result would
// silently corrupt SFINAE; see the correctness-first note on type_trait_arity).

// Is class `c` copy-/move-assignable? A usable (non-`= delete`) user `operator=`
// makes it assignable; an `operator=` that is `= delete` makes it not. With no
// user `operator=` the implicit one applies: assignable iff every base and every
// object/reference data member is assignable (a reference member deletes the
// implicit copy-assign). Mirrors what class_copy_assign_members synthesizes plus
// the deleted-operator=/reference-member exclusions g++/clang apply.
static int trait_class_assignable(DataDefCLASS *c)
{
    if ( !c )
	return -1;
    for ( Variable *mv : c->methods )
    {
	if ( !mv )
	    continue;
	FuncDef *fd = dynamic_cast<FuncDef *>(mv->type);
	if ( !fd || fd->parameters.size() < 2 )
	    continue;
	bool is_assign = mv->name == "operator="
	    || fd->method_display_name == "operator="
	    || mv->name == c->name + "__operator=";
	if ( !is_assign )
	    continue;
	if ( !fd->is_deleted )
	    return 1;            // a usable copy/move operator= exists
	return 0;                // the (only) operator= is deleted
    }
    // A deleted `operator=` was dropped from `methods` (recorded as a flag).
    if ( c->has_deleted_copy_assign )
	return 0;
    if ( c->base_class )
    {
	int s = trait_class_assignable(c->base_class);
	if ( s != 1 )
	    return s;
    }
    for ( size_t i = 0; i < c->bases.size(); ++i )
    {
	if ( !c->bases[i].base )
	    continue;
	int s = trait_class_assignable(c->bases[i].base);
	if ( s != 1 )
	    return s;
    }
    for ( size_t i = 0; i < c->members.size(); ++i )
    {
	DataDef *m = c->members[i].second;
	if ( !m )
	    continue;
	if ( dynamic_cast<DataDefREF *>(m) )
	    return 0;            // a reference member deletes the implicit copy-assign
	if ( DataDefCLASS *mc = dynamic_cast<DataDefCLASS *>(m) )
	{
	    int s = trait_class_assignable(mc);
	    if ( s != 1 )
		return s;
	}
    }
    return 1;
}

// Is a scalar/pointer/enum lvalue of type `to` assignable from a value of type
// `from`? Same type or two arithmetic types (arithmetic conversions) or a
// pointer from a pointer/null. Anything else madc does not model exactly -> -1.
static int trait_scalar_assignable_from(DataDef *to, DataDef *from)
{
    if ( !to || !from )
	return -1;
    if ( to == from || to->name == from->name )
	return 1;
    if ( to->is_numeric() && from->is_numeric() )
	return 1;
    if ( to->is_pointer() && (from->is_pointer() || from->is_numeric()) )
	return 1;
    return -1;
}

// __is_assignable(To, From): is `declval<To>() = declval<From>()` well-formed?
// (The gcc/clang intrinsic; libstdc++'s std::is_assignable wraps it.)
// A class is destructible iff it has an accessible, non-deleted destructor.
// A USER-DECLARED destructor decides directly: method_map's '~' entries (own
// or inherited from a base — a deleted/inaccessible base destructor deletes
// the derived implicit one, and a derived user destructor over a deleted base
// destructor would be ill-formed, so any bad '~' entry means 0 and any good
// set means 1). With no user destructor anywhere, the IMPLICIT destructor
// walks bases and members ([class.dtor]p7). -1 = cannot answer faithfully.
static int trait_class_destructible(DataDefCLASS *c, int depth,
				    bool check_access)
{
    if ( !c )
	return -1;
    if ( depth > 32 )
	return -1;                   // pathological nesting — refuse, don't hang
    if ( c->has_deleted_dtor )
	return 0;                    // dropped `~X() = delete` (recorded)
    bool saw_user_dtor = false;
    for ( std::map<std::string, Variable *>::const_iterator it =
	    c->method_map.begin(); it != c->method_map.end(); ++it )
    {
	if ( it->first.empty() || it->first[0] != '~' || !it->second )
	    continue;
	saw_user_dtor = true;
	FuncDef *fd = dynamic_cast<FuncDef *>(it->second->type);
	if ( fd && fd->is_deleted )
	    return 0;
	// Access matters only for the TRAIT's external-context answer; an
	// explicit destructor CALL is checked per its own context by the
	// caller (a private destructor is callable from the class's members).
	if ( check_access
	  && (it->second->flags & (vfPRIVATE | vfPROTECTED)) )
	    return 0;
    }
    if ( saw_user_dtor )
	return 1;
    std::vector<DataDefCLASS *> parents;
    if ( c->base_class )
	parents.push_back(c->base_class);
    for ( size_t i = 0; i < c->bases.size(); ++i )
	if ( c->bases[i].base && c->bases[i].base != c->base_class )
	    parents.push_back(c->bases[i].base);
    for ( size_t i = 0; i < parents.size(); ++i )
    {
	int s = trait_class_destructible(parents[i], depth + 1, check_access);
	if ( s != 1 )
	    return s;
    }
    for ( size_t i = 0; i < c->members.size(); ++i )
    {
	DataDef *m = c->members[i].second;
	if ( !m )
	    continue;
	while ( DataDefCArray *arr = dynamic_cast<DataDefCArray *>(m) )
	{
	    if ( !arr->element_type )
		return -1;
	    m = arr->element_type;   // element-wise: the element type decides
	}
	if ( DataDefCLASS *mc = dynamic_cast<DataDefCLASS *>(m) )
	{
	    int s = trait_class_destructible(mc, depth + 1, check_access);
	    if ( s != 1 )
		return s;
	}
    }
    return 1;
}

// __is_destructible(T) ([meta.unary.prop]): reference types are destructible;
// void / function / unbounded-array types are not; an array is destructible
// iff its element type is; a class needs an accessible non-deleted destructor
// (trait_class_destructible above); scalars/enums/pointers are. -1 = refuse.
static int trait_is_destructible(const TraitTypeArg &t)
{
    if ( t.is_lref || t.is_rref )
	return 1;
    DataDef *dd = t.dd;
    if ( !dd )
	return -1;
    if ( dynamic_cast<DataDefVOID *>(dd) )
	return 0;
    if ( dynamic_cast<FuncDef *>(dd) )
	return 0;
    while ( DataDefCArray *arr = dynamic_cast<DataDefCArray *>(dd) )
    {
	if ( !arr->element_type )
	    return -1;
	if ( arr->count == 0 )
	    return 0;                // array of unknown bound
	dd = arr->element_type;
    }
    if ( DataDefCLASS *c = dynamic_cast<DataDefCLASS *>(dd) )
	return trait_class_destructible(c, 0, true);
    return 1;
}

static int trait_is_assignable(const TraitTypeArg &to, const TraitTypeArg &from)
{
    DataDefCLASS *to_class = dynamic_cast<DataDefCLASS *>(to.dd);
    // A non-class prvalue (no reference) cannot be assigned to; nor can a
    // non-class rvalue reference. A class prvalue/rvalue-ref CAN (member op=).
    if ( !to_class && !to.is_lref )
	return 0;
    if ( !to_class && to.is_rref )
	return 0;
    if ( to.referent_const )
	return 0;
    if ( !to_class )
	return trait_scalar_assignable_from(to.dd, from.dd);
    return trait_class_assignable(to_class);
}

// Is `from` implicitly convertible to the scalar (arithmetic / enum / pointer)
// type `to` by copy-initialization? The same conversion core the assignable
// trait models, plus the enum asymmetry: nothing converts TO an enum but the
// enum itself ([dcl.init] — no implicit arithmetic->enum), while enum->
// arithmetic depends on scoped-ness madc does not record (-1).
static int trait_scalar_convertible_from(DataDef *to, const TraitTypeArg &from)
{
    if ( !to || !from.dd )
	return -1;
    if ( dynamic_cast<DataDefENUM *>(to) )
	return (to == from.dd || to->name == from.dd->name) ? 1 : 0;
    if ( dynamic_cast<DataDefENUM *>(from.dd) )
	return -1;
    return trait_scalar_assignable_from(to, from.dd);
}

// A user CONVERSION FUNCTION on the class ([class.conv.fct]) — registered with
// the `operator <type>` display-name prefix (the same marker the pattern
// normalizer's Conversion kind keys on).
static bool trait_class_has_conversion_op(DataDefCLASS *c)
{
    if ( !c )
	return false;
    for ( variable_vec_iter vvi = c->methods.begin(); vvi != c->methods.end();
	  ++vvi )
    {
	FuncDef *fd = *vvi ? dynamic_cast<FuncDef *>((*vvi)->type) : NULL;
	if ( fd && fd->method_display_name.compare(0, 9, "operator ") == 0 )
	    return true;
    }
    if ( c->base_class && trait_class_has_conversion_op(c->base_class) )
	return true;
    for ( size_t i = 0; i < c->bases.size(); ++i )
	if ( trait_class_has_conversion_op(c->bases[i].base) )
	    return true;
    return false;
}

// __is_convertible_to(From, To) ([meta.rel] is_convertible — libc++ spells
// its entire is_convertible through this builtin). Conservative tri-state:
// the shapes the iterator-category detection chain folds exactly (same
// class, derived tag -> base tag, ctor-less unrelated tags -> 0, scalar
// pairs); anything needing user conversion machinery stays undetermined
// (-1 = not constant-foldable) rather than guessing a canon answer.
static int trait_is_convertible_uninstrumented(const TraitTypeArg &from,
					       const TraitTypeArg &to);

// Env-gated probe (MADC_ISCONV_PROBE=1): every __is_convertible fold with its
// verdict — the overload-flip diagnostic when a newly-foldable trait changes
// a library SFINAE selection.
static int trait_is_convertible(const TraitTypeArg &from, const TraitTypeArg &to)
{
    int r = trait_is_convertible_uninstrumented(from, to);
    static const char *icp = ::getenv("MADC_ISCONV_PROBE");
    if ( icp )
	fprintf(stderr, "[isconv] from=%s%s to=%s%s -> %d\n",
		from.dd ? from.dd->name.c_str() : "?",
		from.is_lref ? "&" : (from.is_rref ? "&&" : ""),
		to.dd ? to.dd->name.c_str() : "?",
		to.is_lref ? "&" : (to.is_rref ? "&&" : ""), r);
    return r;
}

static int trait_is_convertible_uninstrumented(const TraitTypeArg &from,
					       const TraitTypeArg &to)
{
    if ( !from.dd || !to.dd )
	return -1;
    // Class-NESS by struct-hood (trait_is_class's own test): a plain
    // `struct B {}` stays DataDefSTRUCT — class-only state (ctors,
    // conversion ops) is read through the CLASS cast when present.
    bool to_cls = trait_is_class(to.dd) || trait_is_union(to.dd);
    bool from_cls = trait_is_class(from.dd) || trait_is_union(from.dd);
    if ( to_cls && from_cls )
    {
	if ( to.dd == from.dd || to.dd->name == from.dd->name )
	    return 1;			// copy-initialization from the same type
	if ( trait_is_base_of(to.dd, from.dd) )
	    return 1;			// derived -> base ([conv.ptr]/[dcl.init])
	// Unrelated classes with NO user constructors on the target and NO
	// conversion functions on the source (the iterator TAG shape): there
	// is no conversion path at all — a definite 0, which is what the
	// negative branches of __has_iterator_category_convertible_to need.
	// A never-promoted plain struct has neither.
	DataDefCLASS *toc = dynamic_cast<DataDefCLASS *>(to.dd);
	DataDefCLASS *fromc = dynamic_cast<DataDefCLASS *>(from.dd);
	if ( (!toc || toc->ctors.empty())
	  && (!fromc || !trait_class_has_conversion_op(fromc)) )
	    return 0;
	return -1;			// user machinery — undetermined
    }
    if ( to_cls || from_cls )
	return -1;			// class <-> scalar: user machinery
    return trait_scalar_convertible_from(to.dd, from);
}

static int trait_is_constructible(const TraitTypeArg &to,
				  const std::vector<TraitTypeArg> &args,
				  bool need_nothrow, int depth);

// The IMPLICITLY-declared default/copy/move constructor: available iff every
// base and every data member is itself so constructible ([class.default.ctor],
// [class.copy.ctor]); for the nothrow question the same walk ANDs the members'
// nothrow-ness (the implicit ctor's noexcept is exactly that conjunction,
// [except.spec]p7). copy_form distinguishes the memberwise-copy walk from the
// default-init walk.
static int trait_class_memberwise_ctor(DataDefCLASS *c, bool copy_form,
					bool need_nothrow, int depth)
{
    std::vector<DataDefCLASS *> parents;
    if ( c->base_class )
	parents.push_back(c->base_class);
    for ( size_t i = 0; i < c->bases.size(); ++i )
	if ( c->bases[i].base && c->bases[i].base != c->base_class )
	    parents.push_back(c->bases[i].base);
    for ( size_t i = 0; i < parents.size(); ++i )
    {
	TraitTypeArg to;
	to.dd = parents[i];
	std::vector<TraitTypeArg> pargs;
	if ( copy_form )
	{
	    TraitTypeArg a;
	    a.dd = parents[i];
	    a.is_lref = true;
	    a.referent_const = true;
	    pargs.push_back(a);
	}
	int s = trait_is_constructible(to, pargs, need_nothrow, depth + 1);
	if ( s != 1 )
	    return s;
    }
    for ( size_t i = 0; i < c->members.size(); ++i )
    {
	DataDef *m = c->members[i].second;
	if ( !m )
	    continue;
	if ( dynamic_cast<DataDefREF *>(m) )
	{
	    if ( copy_form )
		continue;            // copying a bound reference member is fine
	    return -1;               // default-init needs an NSDMI madc does not
				     // surface here — refuse, don't guess
	}
	while ( DataDefCArray *arr = dynamic_cast<DataDefCArray *>(m) )
	{
	    if ( !arr->element_type )
		return -1;
	    m = arr->element_type;   // element-wise: the element type decides
	}
	if ( DataDefCLASS *mc = dynamic_cast<DataDefCLASS *>(m) )
	{
	    TraitTypeArg to;
	    to.dd = mc;
	    std::vector<TraitTypeArg> margs;
	    if ( copy_form )
	    {
		TraitTypeArg a;
		a.dd = mc;
		a.is_lref = true;
		a.referent_const = true;
		margs.push_back(a);
	    }
	    int s = trait_is_constructible(to, margs, need_nothrow, depth + 1);
	    if ( s != 1 )
		return s;
	}
	// scalar / pointer / enum / plain-struct member: default-init and
	// memberwise copy are both well-formed and non-throwing
    }
    return 1;
}

// __is_constructible(T, Args...) for a class T: does ONE non-deleted
// constructor accept the argument list, at the fidelity madc models —
// exact/derived class matches and scalar conversions per parameter. A
// candidate needing unmodeled machinery (a constructor TEMPLATE's SFINAE
// constraints, a class-type conversion) makes a NO answer undeterminable
// (-1); a positive match from a plain candidate stays decisive.
static int trait_class_constructible(DataDefCLASS *c,
				     const std::vector<TraitTypeArg> &args,
				     bool need_nothrow, int depth)
{
    bool same_class_arg = args.size() == 1 && args[0].dd
	&& (args[0].dd == c || args[0].dd->name == c->name);
    // Deleted special members are dropped from `ctors` at class parse; the
    // recorded class flags are their only trace ([class.copy.ctor]: a deleted
    // selected ctor makes the initialization ill-formed).
    if ( args.empty() && c->has_deleted_default_ctor )
	return 0;
    if ( same_class_arg && c->has_deleted_copy_ctor )
	return 0;
    bool saw_unmodelable = false;
    bool saw_user_ctor = false;
    bool matched_deleted = false;
    bool defaulted_default = c->has_defaulted_default_ctor;
    int matched = 0;
    int matched_nothrow = -1;     // agreed nothrow answer of the matches
    int movelike_nx = -2;         // nothrow of the T&/T&& (non-const) candidate
    int copylike_nx = -2;         // nothrow of the const T& candidate
    for ( size_t ci = 0; ci < c->ctors.size(); ++ci )
    {
	FuncDef *fd = c->ctors[ci]
	    ? dynamic_cast<FuncDef *>(c->ctors[ci]->type) : NULL;
	if ( !fd )
	    continue;
	if ( fd->is_member_template )
	{
	    saw_unmodelable = true;   // a ctor template can accept nearly anything
	    continue;
	}
	saw_user_ctor = true;
	// A `= default` special member behaves as the implicit one — the
	// memberwise walk below owns it (its noexcept is the conjunction).
	// An explicitly-defaulted DEFAULT ctor must keep the class default-
	// constructible even beside other user ctors ([class.default.ctor]:
	// the suppression rule counts user-DECLARED ctors, and this one is
	// the default ctor itself).
	//
	// It arrives here WITHOUT defaulted_or_deleted: madc parses `= default`
	// on the default ctor as an empty body, so it is an ordinary nullary
	// FuncDef by the time the trait sees it, carrying no noexcept spec.
	// Reading that absent spec as "unknown" refused the whole trait
	// (-1) for every such class — which is what `std::mutex` is. The class
	// flag is the only thing distinguishing it from `X() {}`, whose
	// noexcept madc genuinely cannot know.
	bool is_defaulted_default = fd->defaulted_or_deleted
	    ? !fd->is_deleted
	    : (c->has_defaulted_default_ctor && fd->parameters.size() <= 1);
	if ( is_defaulted_default )
	{
	    if ( args.empty() && fd->parameters.size() <= 1 )
		defaulted_default = true;
	    continue;
	}
	size_t nparams = fd->parameters.empty() ? 0 : fd->parameters.size() - 1;
	size_t ndefaults = 0;
	for ( size_t i = fd->param_defaults.size(); i-- > 1; )
	{
	    bool has_def = fd->param_defaults[i]
		|| (i < fd->param_default_tokens.size()
		    && !fd->param_default_tokens[i].empty());
	    if ( !has_def )
		break;
	    ++ndefaults;
	}
	if ( args.size() > nparams || args.size() + ndefaults < nparams )
	    continue;                 // arity mismatch — not viable
	bool viable = true;
	bool unmodelable = false;
	for ( size_t i = 0; i < args.size() && viable; ++i )
	{
	    DataDef *pdd = fd->parameters[i + 1];
	    DataDef *pref = pdd;
	    if ( DataDefPTR *pr = dynamic_cast<DataDefPTR *>(pref) )
		if ( pr->is_reference() && pr->base_type )
		    pref = pr->base_type;
	    if ( DataDefCONST *pc = dynamic_cast<DataDefCONST *>(pref) )
		pref = pc->base_type ? pc->base_type : pref;
	    const TraitTypeArg &a = args[i];
	    if ( !pref || !a.dd )
	    { unmodelable = true; viable = false; break; }
	    if ( DataDefCLASS *pcl = dynamic_cast<DataDefCLASS *>(pref) )
	    {
		if ( a.dd == pcl || a.dd->name == pcl->name )
		    continue;
		if ( dynamic_cast<DataDefCLASS *>(a.dd)
		  && trait_is_base_of(pcl, a.dd) )
		    continue;
		unmodelable = true;   // would need a conversion madc can't rank
		viable = false;
		break;
	    }
	    int s = trait_scalar_convertible_from(pref, a);
	    if ( s == 1 )
		continue;
	    if ( s < 0 )
		unmodelable = true;
	    viable = false;
	}
	if ( unmodelable )
	{ saw_unmodelable = true; continue; }
	if ( !viable )
	    continue;
	if ( fd->is_deleted )
	{ matched_deleted = true; continue; }
	// NxNone cannot answer "may throw": the LEXER erases conditional
	// `noexcept(expr)` specifiers, so an unspecified FuncDef is
	// indistinguishable from an erased one — only a captured
	// unconditional spec (NxTrue) is decisive. Refuse rather than guess.
	int nx = fd->noexcept_spec == FuncDef::NxTrue ? 1 : -1;
	if ( matched && matched_nothrow != nx )
	    matched_nothrow = -1;     // ambiguous selection — refuse the nothrow claim
	else
	    matched_nothrow = nx;
	// Classify a same-class single-arg candidate by its parameter's
	// const-ness (madc's one post-resolution reference kind: the MOVE
	// ctor's param is the non-const reference, the COPY ctor's the const
	// one) for the value-category preference below.
	if ( same_class_arg && nparams >= 1 )
	{
	    bool p_const = 1 < fd->const_params.size() && fd->const_params[1];
	    DataDef *p1 = fd->parameters[1];
	    if ( DataDefPTR *pr = dynamic_cast<DataDefPTR *>(p1) )
		if ( pr->is_reference() && pr->base_type )
		{
		    if ( dynamic_cast<DataDefCONST *>(pr->base_type) )
			p_const = true;
		    if ( p_const )
			copylike_nx = nx;
		    else
			movelike_nx = nx;
		}
	}
	++matched;
    }
    if ( matched )
    {
	if ( !need_nothrow )
	    return 1;
	if ( matched == 1 || matched_nothrow != -1 )
	    return matched_nothrow;
	// Disagreeing matches: the reduced [over.ics.rank] preference — an
	// RVALUE same-class argument selects the T&&/T& (non-const) overload
	// over const T&; an lvalue (or const) argument the const T& one.
	if ( same_class_arg )
	{
	    int pick = (args[0].is_rref && !args[0].referent_const)
		     ? movelike_nx : copylike_nx;
	    if ( pick != -2 )
		return pick;
	}
	return -1;
    }
    if ( matched_deleted )
	return 0;
    if ( saw_unmodelable )
	return -1;
    // No explicit candidate: the implicit/defaulted special members remain.
    // Any user-declared ctor suppresses the implicit DEFAULT ctor
    // ([class.default.ctor]p1); the implicit copy/move survives.
    if ( args.empty() )
	return (saw_user_ctor && !defaulted_default)
	     ? 0 : trait_class_memberwise_ctor(c, false, need_nothrow, depth);
    if ( same_class_arg )
	return trait_class_memberwise_ctor(c, true, need_nothrow, depth);
    return 0;                        // no converting ctor takes these args
}

// __is_constructible(T, Args...) / __is_nothrow_constructible(T, Args...):
// is the variable definition `T t(declval<Args>()...)` well-formed (and,
// for the nothrow form, known non-throwing)? Tri-state like the assignable
// trait: -1 = madc cannot answer faithfully (the caller raises a clear
// error / declines the fold rather than emit a wrong bool).
static int trait_is_constructible(const TraitTypeArg &to,
				  const std::vector<TraitTypeArg> &args,
				  bool need_nothrow, int depth)
{
    if ( !to.dd )
	return -1;
    if ( depth > 32 )
	return -1;                   // pathological nesting — refuse, don't hang
    if ( to.is_lref || to.is_rref )
    {
	// [dcl.init.ref] at this fidelity: same-type (or derived-to-base
	// class) sources bind per value category; const-lvalue/rvalue refs
	// also bind a convertible scalar temporary. Reference binding never
	// throws, so the nothrow answer is the same.
	if ( args.size() != 1 )
	    return 0;
	const TraitTypeArg &a = args[0];
	if ( !a.dd )
	    return -1;
	bool related = a.dd == to.dd || a.dd->name == to.dd->name;
	if ( !related && dynamic_cast<DataDefCLASS *>(to.dd)
	  && dynamic_cast<DataDefCLASS *>(a.dd) )
	    related = trait_is_base_of(to.dd, a.dd);
	if ( related )
	{
	    if ( to.is_rref )
		return a.is_lref ? 0 : 1;      // T&& never binds an lvalue
	    if ( to.referent_const )
		return 1;                       // const T& binds everything
	    return a.is_lref ? 1 : 0;           // plain T& needs an lvalue
	}
	if ( !dynamic_cast<DataDefCLASS *>(to.dd)
	  && (to.referent_const || to.is_rref) )
	    return trait_scalar_convertible_from(to.dd, a);  // temp materializes
	return 0;
    }
    if ( dynamic_cast<DataDefVOID *>(to.dd) )
	return 0;
    if ( dynamic_cast<DataDefCArray *>(to.dd) )
	return args.empty() ? -1 : 0;    // array-of-T constructibility: not modeled
    if ( DataDefCLASS *c = dynamic_cast<DataDefCLASS *>(to.dd) )
	return trait_class_constructible(c, args, need_nothrow, depth);
    if ( dynamic_cast<DataDefSTRUCT *>(to.dd)
      && !dynamic_cast<DataDefCOMPLEX *>(to.dd) )
    {
	// A plain C aggregate: value-init (0 args) and trivial copy from the
	// same struct are well-formed and non-throwing; paren-init from other
	// values is not a thing before C++20's P0960 (madc's dialect level).
	if ( args.empty() )
	    return 1;
	if ( args.size() == 1 && args[0].dd
	  && (args[0].dd == to.dd || args[0].dd->name == to.dd->name) )
	    return 1;
	return 0;
    }
    // Scalar target (arithmetic / enum / pointer): value-init, or one
    // converting argument; scalar initialization never throws, so the
    // nothrow answer equals the constructible one.
    if ( args.empty() )
	return 1;
    if ( args.size() == 1 )
	return trait_scalar_convertible_from(to.dd, args[0]);
    return 0;
}

TokenBase *Program::evaluate_type_trait(TokenBase *op_tb, const std::string &name)
{
    int arity = type_trait_arity(name);
    if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	Throw(op_tb) << "Expecting '(' after " << name << flush;
    nextToken(); // consume '('

    std::vector<TraitTypeArg> args;
    for (;;)
    {
	TraitTypeArg a;
	TokenBase *at = nextToken();
	std::string cv_spelling;
	at = consume_template_type_arg_qualifiers(at, cv_spelling);
	a.referent_const = cv_spelling.find("const") != std::string::npos;
	TokenDataType *adt = resolve_declared_type_token(at, true, true);
	if ( !adt )
	    Throw(at ? at : op_tb) << "Expecting a type argument to " << name << flush;
	DataDef *dd = &adt->definition;
	// Fold trailing pointer stars (`__is_pointer(int*)`), mirroring the
	// template-argument parser.
	while ( peekToken() && peekToken()->id() == TokenID::tkMul )
	{
	    nextToken();
	    dd = getPointerType(dd);
	}
	a.dd = dd;
	// Trailing reference (`T&` / `T&&`) — load-bearing for __is_assignable.
	if ( peekToken() && peekToken()->id() == TokenID::tkBand )
	{ nextToken(); a.is_lref = true; }
	else if ( peekToken() && peekToken()->id() == TokenID::tkLand )
	{ nextToken(); a.is_rref = true; }
	unwrap_baked_trait_arg(a);
	// A DEPENDENT argument (an unbound template param `_Tp`, a dependent
	// member-type placeholder) is unanswerable: any 0/1 answered here
	// bakes a wrong constant into whatever context asked. Refuse — a
	// speculative/SFINAE caller catches this like any other decline.
	if ( datadef_has_unresolved_dependent_surface(a.dd) )
	    Throw(op_tb) << name << "(...) on a dependent type argument ("
			 << (a.dd ? a.dd->name : std::string("?"))
			 << ") cannot fold ["
			 << dependent_surface_reason(a.dd) << "]" << flush;
	args.push_back(a);
	TokenBase *sep = nextToken();
	if ( sep && sep->id() == TokenID::tkComma )
	    continue;
	if ( sep && sep->id() == TokenID::tkClBrk )
	    break;
	Throw(sep ? sep : op_tb) << "Expecting ',' or ')' in " << name << "(...)" << flush;
    }

    if ( arity == TRAIT_ARITY_VARIADIC ? args.empty()
				       : (int)args.size() != arity )
	Throw(op_tb) << name << " expects "
		     << (arity == TRAIT_ARITY_VARIADIC ? 1 : arity)
		     << (arity == TRAIT_ARITY_VARIADIC ? " or more" : "")
		     << " type argument(s), got " << args.size() << flush;

    bool result = false;
    if ( name == "__is_same" )
	result = args[0].same_as(args[1]);
    else if ( name == "__is_enum" )
	result = !trait_arg_is_reference(args[0]) && trait_is_enum(args[0].dd);
    else if ( name == "__is_class" )
	result = !trait_arg_is_reference(args[0]) && trait_is_class(args[0].dd);
    else if ( name == "__is_union" )
	result = !trait_arg_is_reference(args[0]) && trait_is_union(args[0].dd);
    else if ( name == "__is_empty" )
	result = !trait_arg_is_reference(args[0]) && trait_is_empty(args[0].dd);
    else if ( name == "__is_final" )
	result = !trait_arg_is_reference(args[0]) && trait_is_final(args[0].dd);
    else if ( name == "__is_base_of" )
	result = !trait_arg_is_reference(args[0])
	      && !trait_arg_is_reference(args[1])
	      && trait_is_base_of(args[0].dd, args[1].dd);
    else if ( name == "__has_trivial_destructor" )
	result = trait_arg_is_reference(args[0])
	      || trait_has_trivial_destructor(args[0].dd);
    else if ( name == "__is_trivial" )
	result = !trait_arg_is_reference(args[0]) && trait_is_trivial(args[0].dd);
    else if ( name == "__is_standard_layout" )
	result = !trait_arg_is_reference(args[0])
	      && trait_is_standard_layout(args[0].dd);
    else if ( name == "__is_pod" )
	result = !trait_arg_is_reference(args[0]) && trait_is_pod(args[0].dd);
    else if ( name == "__is_destructible" )
    {
	int s = trait_is_destructible(args[0]);
	if ( s < 0 )
	    Throw(op_tb) << "cannot faithfully evaluate __is_destructible(...) "
			 << "for this operand type" << flush;
	result = s != 0;
    }
    else if ( name == "__is_assignable" )
    {
	int s = trait_is_assignable(args[0], args[1]);
	if ( vri_debug_enabled() )
	    fprintf(stderr, "[vriprobe] LIVE __is_assignable to=%s l%d r%d c%d "
		    "from=%s l%d r%d c%d -> %d\n",
		    args[0].dd ? args[0].dd->name.c_str() : "?",
		    (int)args[0].is_lref, (int)args[0].is_rref,
		    (int)args[0].referent_const,
		    args[1].dd ? args[1].dd->name.c_str() : "?",
		    (int)args[1].is_lref, (int)args[1].is_rref,
		    (int)args[1].referent_const, s);
	if ( s < 0 )
	    Throw(op_tb) << "cannot faithfully evaluate __is_assignable(...) for "
			 << "these operand types" << flush;
	result = s != 0;
    }
    else if ( name == "__is_constructible"
	   || name == "__is_nothrow_constructible" )
    {
	std::vector<TraitTypeArg> ctor_args(args.begin() + 1, args.end());
	int s = trait_is_constructible(args[0], ctor_args,
				       name == "__is_nothrow_constructible", 0);
	if ( s < 0 )
	    Throw(op_tb) << "cannot faithfully evaluate " << name
			 << "(...) for these operand types" << flush;
	result = s != 0;
    }
    else if ( name == "__is_convertible_to" || name == "__is_convertible" )
    {
	int s = trait_is_convertible(args[0], args[1]);
	if ( s < 0 )
	    Throw(op_tb) << "cannot faithfully evaluate " << name
			 << "(...) for these operand types" << flush;
	result = s != 0;
    }

    TokenInt *ti = new TokenInt(result ? 1 : 0);
    ti->setDataType(&ddBOOL);
    ti->file = op_tb->file;
    ti->line = op_tb->line;
    ti->column = op_tb->column;
    return ti;
}

static bool is_runtime_sized_type(DataDef *dd)
{
    if ( !dd )
	return false;
    if ( DataDefSTRUCT *sdd = dynamic_cast<DataDefSTRUCT *>(dd) )
	return sdd->has_runtime_size();
    if ( DataDefCArray *add = dynamic_cast<DataDefCArray *>(dd) )
	return add->chain_has_runtime_size();
    return false;
}

// A type query whose VALUE is not knowable at parse time: a VLA type (runtime
// value) or a bare template-parameter placeholder (instantiation-time value —
// folding it would bake the placeholder's meaningless size 0 into the Tree-1
// pattern; tsubst expands the deferred TokenTypeQuery's type marker instead).
static bool type_query_size_is_deferred(DataDef *dd)
{
    if ( !dd )
	return false;
    return is_runtime_sized_type(dd) || dd->is_template_param();
}

static TokenBase *make_type_query_token(TokenBase *op_tb, DataDef *dd, bool want_alignof)
{
    TokenBase *result = NULL;
    if ( !type_query_size_is_deferred(dd)
      || (want_alignof && !dd->is_template_param()) )
    {
	TokenInt *ti = new TokenInt((int64_t)query_datadef_measure(dd, want_alignof));
	ti->setDataType(&ddUINT64);
	result = ti;
    }
    else
	result = new TokenTypeQuery(dd, want_alignof);
    result->file = op_tb ? op_tb->file : NULL;
    result->line = op_tb ? op_tb->line : 0;
    result->column = op_tb ? op_tb->column : 0;
    return result;
}

static size_t query_fixed_array_sizeof_value(TokenVar *tv, bool want_alignof, bool deref)
{
    if ( !tv || !tv->var.type )
	return 0;
    size_t value = query_datadef_measure(tv->var.type, want_alignof);
    if ( !want_alignof && !deref )
	value *= tv->var.total_elements();
    return value;
}

static bool try_eval_known_integer(TokenBase *tb, int64_t &out)
{
    if ( !tb )
	return false;
    if ( TokenInt *ti = dynamic_cast<TokenInt *>(tb) )
    {
	out = ti->ival();
	return true;
    }
    if ( TokenChar *tc = dynamic_cast<TokenChar *>(tb) )
    {
	out = tc->ival();
	return true;
    }
    if ( TokenVar *tv = dynamic_cast<TokenVar *>(tb) )
    {
	if ( tv->var.is_constant() )
	{
	    out = tv->var.get<int64_t>();
	    return true;
	}
	return false;
    }
    if ( TokenNeg *tn = dynamic_cast<TokenNeg *>(tb) )
    {
	int64_t rhs = 0;
	if ( try_eval_known_integer(tn->right, rhs) )
	{
	    out = -rhs;
	    return true;
	}
	return false;
    }
    if ( TokenAdd *ta = dynamic_cast<TokenAdd *>(tb) )
    {
	int64_t lhs = 0, rhs = 0;
	if ( try_eval_known_integer(ta->left, lhs) && try_eval_known_integer(ta->right, rhs) )
	{
	    out = lhs + rhs;
	    return true;
	}
	return false;
    }
    if ( TokenSub *ts = dynamic_cast<TokenSub *>(tb) )
    {
	int64_t lhs = 0, rhs = 0;
	if ( try_eval_known_integer(ts->left, lhs) && try_eval_known_integer(ts->right, rhs) )
	{
	    out = lhs - rhs;
	    return true;
	}
	return false;
    }
    return false;
}

TokenBase *Program::materialize_cast_literal_operand(TokenBase *tb)
{
    if ( !tb )
	return tb;
    if ( tb->type() != TokenType::ttString )
	return tb;

    TokenStr *first = static_cast<TokenStr *>(tb);
    std::string literal = first->str;
    bool wide_literal = first->wide;
    while ( peekToken() && peekToken()->type() == TokenType::ttString )
    {
	TokenStr *next = static_cast<TokenStr *>(nextToken());
	if ( wide_literal || next->wide )
	{
	    if ( !wide_literal )
	    {
		std::string converted;
		for ( unsigned char c : literal )
		{
		    converted += (char)c;
		    converted += '\0';
		    converted += '\0';
		    converted += '\0';
		}
		literal = converted;
		wide_literal = true;
	    }
	    if ( next->wide )
		literal += next->str;
	    else
	    {
		for ( unsigned char c : next->str )
		{
		    literal += (char)c;
		    literal += '\0';
		    literal += '\0';
		    literal += '\0';
		}
	    }
	}
	else
	    literal += next->str;
    }

    Variable *var = wide_literal ? addWideLiteral(literal) : addLiteral(literal);
    TokenVar *tv = new TokenVar(*var);
    tv->file = tb->file;
    tv->line = tb->line;
    tv->column = tb->column;
    return tv;
}

static int64_t fixed_array_object_size(const Variable &var)
{
    if ( !var.is_fixed_array() || !var.type || !var.type->size )
	return -1;
    return (int64_t)var.type->size * (int64_t)var.total_elements();
}

static int64_t token_pointer_element_size(TokenBase *tb)
{
    if ( !tb )
	return 1;
    if ( TokenVar *tv = dynamic_cast<TokenVar *>(tb) )
    {
	if ( tv->var.is_fixed_array() && tv->var.type )
	    return tv->var.type->size ? (int64_t)tv->var.type->size : 1;
    }
    if ( TokenMember *tm = dynamic_cast<TokenMember *>(tb) )
    {
	if ( tm->is_fixed_array_member() && tm->var.type )
	    return tm->var.type->size ? (int64_t)tm->var.type->size : 1;
    }
    DataDef *dd = tb->datadef();
    if ( DataDefPTR *pdd = dynamic_cast<DataDefPTR *>(dd) )
	return (pdd->base_type && pdd->base_type->size) ? (int64_t)pdd->base_type->size : 1;
    if ( DataDefCArray *add = dynamic_cast<DataDefCArray *>(dd) )
	return (add->element_type && add->element_type->size) ? (int64_t)add->element_type->size : 1;
    return (dd && dd->size) ? (int64_t)dd->size : 1;
}

static int64_t known_object_size_for_expr(TokenBase *expr, int mode);

static int64_t remaining_object_size(int64_t base_size, int64_t index, int64_t elem_size)
{
    if ( base_size < 0 || index < 0 || elem_size <= 0 )
	return -1;
    int64_t used = index * elem_size;
    if ( used >= base_size )
	return 0;
    return base_size - used;
}

static int64_t known_object_size_for_lvalue(TokenBase *expr, int mode)
{
    if ( !expr )
	return -1;
    if ( TokenVar *tv = dynamic_cast<TokenVar *>(expr) )
    {
	int64_t array_size = fixed_array_object_size(tv->var);
	if ( array_size >= 0 )
	    return array_size;
	return tv->var.type ? (int64_t)tv->var.type->size : -1;
    }
    if ( TokenMember *tm = dynamic_cast<TokenMember *>(expr) )
    {
	if ( tm->is_fixed_array_member() )
	{
	    DataDefSTRUCT *sdd = tm->owner_struct_type();
	    std::string mname = tm->var.name;
	    if ( sdd && tm->var.type )
		return (int64_t)sdd->m_count(mname) * (int64_t)tm->var.type->size;
	}
	return tm->var.type ? (int64_t)tm->var.type->size : -1;
    }
    if ( TokenSubscript *ts = dynamic_cast<TokenSubscript *>(expr) )
    {
	int64_t index = 0;
	if ( !try_eval_known_integer(ts->index, index) )
	    return -1;
	int64_t base_size = -1;
	if ( ts->object.is_fixed_array() )
	    base_size = fixed_array_object_size(ts->object);
	else
	    base_size = ts->object.object_size_hint;
	return remaining_object_size(base_size, index, ts->datadef() ? (int64_t)ts->datadef()->size : 1);
    }
    if ( TokenSubscriptExpr *tse = dynamic_cast<TokenSubscriptExpr *>(expr) )
    {
	int64_t index = 0;
	if ( !try_eval_known_integer(tse->index, index) )
	    return -1;
	int64_t base_size = known_object_size_for_expr(tse->base_expr, mode);
	return remaining_object_size(base_size, index, tse->datadef() ? (int64_t)tse->datadef()->size : 1);
    }
    return expr->datadef() ? (int64_t)expr->datadef()->size : -1;
}

static int64_t known_object_size_for_expr(TokenBase *expr, int mode)
{
    if ( !expr )
	return -1;
    if ( TokenVar *tv = dynamic_cast<TokenVar *>(expr) )
    {
	int64_t array_size = fixed_array_object_size(tv->var);
	if ( array_size >= 0 )
	    return array_size;
	return tv->var.object_size_hint;
    }
    if ( TokenMember *tm = dynamic_cast<TokenMember *>(expr) )
    {
	if ( tm->is_fixed_array_member() )
	{
	    DataDefSTRUCT *sdd = tm->owner_struct_type();
	    std::string mname = tm->var.name;
	    if ( sdd && tm->var.type )
		return (int64_t)sdd->m_count(mname) * (int64_t)tm->var.type->size;
	}
	return tm->var.object_size_hint;
    }
    if ( TokenAddrOf *tao = dynamic_cast<TokenAddrOf *>(expr) )
    {
	int64_t array_size = fixed_array_object_size(tao->var);
	if ( array_size >= 0 )
	    return array_size;
	return tao->var.type ? (int64_t)tao->var.type->size : -1;
    }
    if ( TokenAddrExpr *tae = dynamic_cast<TokenAddrExpr *>(expr) )
	return known_object_size_for_lvalue(tae->expr, mode);
    if ( TokenAdd *ta = dynamic_cast<TokenAdd *>(expr) )
    {
	int64_t offset = 0;
	if ( try_eval_known_integer(ta->right, offset) )
	{
	    int64_t base_size = known_object_size_for_expr(ta->left, mode);
	    return remaining_object_size(base_size, offset, token_pointer_element_size(ta->left));
	}
	if ( try_eval_known_integer(ta->left, offset) )
	{
	    int64_t base_size = known_object_size_for_expr(ta->right, mode);
	    return remaining_object_size(base_size, offset, token_pointer_element_size(ta->right));
	}
	return -1;
    }
    if ( TokenSub *ts = dynamic_cast<TokenSub *>(expr) )
    {
	int64_t offset = 0;
	if ( try_eval_known_integer(ts->right, offset) )
	{
	    int64_t base_size = known_object_size_for_expr(ts->left, mode);
	    return remaining_object_size(base_size, offset, token_pointer_element_size(ts->left));
	}
	return -1;
    }
    if ( TokenTerQ *tt = dynamic_cast<TokenTerQ *>(expr) )
    {
	int64_t true_size = known_object_size_for_expr(tt->true_expr, mode);
	int64_t false_size = known_object_size_for_expr(tt->false_expr, mode);
	if ( true_size < 0 || false_size < 0 )
	    return -1;
	return mode == 1 ? std::min(true_size, false_size)
			 : std::max(true_size, false_size);
    }
    if ( TokenCast *tc = dynamic_cast<TokenCast *>(expr) )
	return known_object_size_for_expr(tc->expr, mode);
    if ( TokenCallFunc *tcf = dynamic_cast<TokenCallFunc *>(expr) )
    {
	if ( (tcf->var.name == "__builtin_alloca" || tcf->var.name == "alloca" || tcf->var.name == "malloc")
	  && tcf->argc() == 1 )
	{
	    int64_t size = 0;
	    if ( try_eval_known_integer(tcf->parameters[0], size) && size >= 0 )
		return size;
	}
    }
    return -1;
}

static void update_pointer_object_size_hints(TokenBase *expr)
{
    if ( !expr )
	return;
    if ( TokenAssign *ta = dynamic_cast<TokenAssign *>(expr) )
    {
	if ( TokenVar *lhs = dynamic_cast<TokenVar *>(ta->left) )
	{
	    if ( lhs->var.type && lhs->var.type->is_pointer() && !lhs->var.is_fixed_array() )
		lhs->var.object_size_hint = known_object_size_for_expr(ta->right, 0);
	}
	update_pointer_object_size_hints(ta->left);
	update_pointer_object_size_hints(ta->right);
	return;
    }
    if ( TokenComma *tc = dynamic_cast<TokenComma *>(expr) )
    {
	update_pointer_object_size_hints(tc->left);
	update_pointer_object_size_hints(tc->right);
	return;
    }
    if ( TokenTerQ *tt = dynamic_cast<TokenTerQ *>(expr) )
    {
	update_pointer_object_size_hints(tt->condition);
	update_pointer_object_size_hints(tt->true_expr);
	update_pointer_object_size_hints(tt->false_expr);
    }
}

TokenBase *Program::materialize_runtime_struct_size_captures(TokenCpnd *code,
							    DataDefSTRUCT *dds, TokenBase *loc)
{
    if ( !code || !dds || !dds->has_runtime_size() )
	return NULL;

    std::string cap_name = "__vla_type_size_" + std::to_string(runtime_size_capture_counter++);
    Variable *cap_var = addVariable(code, ddUINT64, cap_name, 1, NULL, false);
    TokenDecl *td = new TokenDecl(*cap_var);
    td->file = loc ? loc->file : NULL;
    td->line = loc ? loc->line : 0;
    td->column = loc ? loc->column : 0;

    TokenAssign *assign = new TokenAssign();
    assign->file = td->file;
    assign->line = td->line;
    assign->column = td->column;
    assign->left = new TokenVar(*cap_var);
    assign->right = new TokenTypeQuery(dds, false, false);
    td->initialize = assign;

    dds->runtime_size_expr = new TokenVar(*cap_var);
    return td;
}

// Capture a VLA dimension expression into a hidden uint64 local declared
// just before the VLA variable. Both the heap-allocation count and any
// later sizeof(var) read the capture, so the dimension expression's side
// effects run exactly once and sizeof reflects the declaration-time value
// even when the dimension variable changes afterwards (C99 6.5.3.4p2; gcc
// keeps the VLA bound in a hidden temp the same way). dim_expr is REPLACED
// with a TokenVar referencing the capture; the returned TokenDecl carries
// the original expression as the capture's initializer.
TokenBase *Program::materialize_vla_dim_capture(TokenCpnd *code,
						TokenBase *&dim_expr,
						TokenBase *loc)
{
    if ( !code || !dim_expr )
	return NULL;

    std::string cap_name = "__madc_vla_dim_" + std::to_string(vla_dim_capture_counter++);
    Variable *cap_var = addVariable(code, ddUINT64, cap_name, 1, NULL, false);
    TokenDecl *td = new TokenDecl(*cap_var);
    td->file = loc ? loc->file : NULL;
    td->line = loc ? loc->line : 0;
    td->column = loc ? loc->column : 0;

    TokenAssign *assign = new TokenAssign();
    assign->file = td->file;
    assign->line = td->line;
    assign->column = td->column;
    assign->left = new TokenVar(*cap_var);
    assign->right = dim_expr;
    td->initialize = assign;

    dim_expr = new TokenVar(*cap_var);
    return td;
}

TokenBase *Program::try_parse_dynamic_type_query(TokenBase *op_tb,
					       const std::string &op_name)
{
    bool want_alignof = is_alignof_identifier(op_name);
    if ( want_alignof )
	return NULL;

    auto consume_simple_named_type = [&](DataDef *dd) -> TokenBase * {
	if ( !type_query_size_is_deferred(dd) )
	    return NULL;
	nextToken();
	return make_type_query_token(op_tb, dd, false);
    };

    if ( peekToken() && peekToken()->id() != TokenID::tkOpBrk )
    {
	TokenBase *probe = peekToken();
	if ( is_contextual_identifier_token(probe) )
	{
	    std::string name = contextual_identifier_name(probe);
	    if ( !findVariable(name) )
	    {
		DataDef *dd = resolve_template_param(name);
		if ( !dd )
		    dd = resolve_named_datadef(name);
		if ( TokenBase *query = consume_simple_named_type(dd) )
		    return query;
	    }
	}
	return NULL;
    }

    if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	return NULL;

    size_t ix = 0;
    if ( ix >= tokens.size() || tokens[ix]->id() != TokenID::tkOpBrk )
	return NULL;
    ++ix;
    if ( ix >= tokens.size() )
	return NULL;

    DataDef *dd = NULL;
    TokenBase *type_tb = tokens[ix];
    if ( type_tb->type() == TokenType::ttDataType )
	dd = &((TokenDataType *)type_tb)->definition;
    else if ( type_tb->type() == TokenType::ttIdentifier )
    {
	std::string name = ((TokenIdent *)type_tb)->spelling();
	if ( !findVariable(name) )
	{
	    dd = resolve_template_param(name);
	    if ( !dd )
		dd = resolve_named_datadef(name);
	}
    }
    else if ( type_tb->type() == TokenType::ttKeyword
	   && (type_tb->id() == TokenID::tkSTRUCT || type_tb->id() == TokenID::tkUNION) )
    {
	++ix;
	if ( ix >= tokens.size() || !is_contextual_identifier_token(tokens[ix]) )
	    return NULL;
	dd = resolve_named_datadef(contextual_identifier_name(tokens[ix]));
    }
    if ( !type_query_size_is_deferred(dd) )
	return NULL;

    TokenBase *open = nextToken();
    (void)open;
    TokenBase *consumed = nextToken();
    if ( !consumed )
	return NULL;
    if ( consumed->type() == TokenType::ttKeyword
      && (consumed->id() == TokenID::tkSTRUCT || consumed->id() == TokenID::tkUNION) )
    {
	TokenBase *tag_tb = nextToken();
	if ( !tag_tb || !is_contextual_identifier_token(tag_tb) )
	    Throw(tag_tb ? tag_tb : consumed) << "Expecting struct/union tag in " << op_name << flush;
    }
    if ( !peekToken() || peekToken()->id() != TokenID::tkClBrk )
	Throw(consumed) << "Expecting ')' after " << op_name << " type" << flush;
    nextToken();
    return make_type_query_token(op_tb, dd, false);
}

// Row form of a VLA sizeof: `sizeof a[i]...` / `sizeof *a` where `a` is a
// flat runtime-sized array (a pointer whose pointee CArray chain carries a
// runtime dim — VLA parameter or malloc'd VLA local). Subscripts peel
// dimensions off that chain; the remaining row type is fully described by
// its stored dim expressions, so the size defers via make_type_query_token
// (TokenTypeQuery) and the CIR builder lowers it to the runtime product of
// the remaining dims times the element size. Returns NULL — without
// consuming tokens — when the root does not gate or the operand is not
// exactly a deref / subscript chain.
TokenBase *Program::try_parse_vla_row_sizeof(TokenBase *op_tb, Variable *v,
					     bool paren, bool deref,
					     size_t after_ix)
{
    DataDefPTR *vp = dynamic_cast<DataDefPTR *>(v->type);
    DataDefCArray *vc = vp ? dynamic_cast<DataDefCArray *>(vp->base_type)
			   : NULL;
    if ( !vc || !vc->chain_has_runtime_size() )
	return NULL;
    if ( paren )
    {
	// Commit only when the parenthesized operand is EXACTLY the deref /
	// subscript chain — `sizeof (a[0] + 1)` stays on the generic
	// expression path.
	size_t scan = after_ix;
	while ( scan < tokens.size() && tokens[scan]
	     && tokens[scan]->id() == TokenID::tkOpSqr )
	{
	    int depth = 1;
	    ++scan;
	    while ( scan < tokens.size() && tokens[scan] && depth > 0 )
	    {
		if ( tokens[scan]->id() == TokenID::tkOpSqr )
		    ++depth;
		else if ( tokens[scan]->id() == TokenID::tkClSqr )
		    --depth;
		++scan;
	    }
	    if ( depth > 0 )
		return NULL;
	}
	if ( scan >= tokens.size() || !tokens[scan]
	  || tokens[scan]->id() != TokenID::tkClBrk )
	    return NULL;
    }

    if ( paren )
	nextToken();                       // '('
    DataDef *row_dd = vp->base_type;
    std::vector<TokenBase *> idx_exprs;    // source order (outermost first)
    if ( deref )
    {
	nextToken();                       // '*'
	nextToken();                       // identifier: *a == a[0]
    }
    else
    {
	TokenBase *id_tb = nextToken();    // identifier
	TokenBase *chain = parsePostfixChain(id_tb);
	size_t ni = 0;
	bool pure = true;
	TokenBase *cur = chain;
	while ( TokenSubscriptExpr *e = dynamic_cast<TokenSubscriptExpr *>(cur) )
	{
	    ++ni;
	    idx_exprs.push_back(e->index);
	    cur = e->base_expr;
	}
	std::reverse(idx_exprs.begin(), idx_exprs.end());
	if ( TokenSubscript *ts0 = dynamic_cast<TokenSubscript *>(cur) )
	{
	    ni += 1 + ts0->extra_indices.size();
	    std::vector<TokenBase *> head;
	    head.push_back(ts0->index);
	    for ( TokenBase *x : ts0->extra_indices )
		head.push_back(x);
	    idx_exprs.insert(idx_exprs.begin(), head.begin(), head.end());
	}
	else if ( !dynamic_cast<TokenVar *>(cur) )
	    pure = false;                  // mixed postfix chain (member, …)
	for ( size_t step = 1; pure && step < ni; ++step )
	{
	    DataDefCArray *rc = dynamic_cast<DataDefCArray *>(row_dd);
	    if ( !rc )
	    {
		pure = false;              // over-subscripted
		break;
	    }
	    row_dd = rc->element_type;
	}
	if ( !pure )
	{
	    // Fold the same constant the generic path computes for these
	    // shapes (the operand tokens are already consumed).
	    TokenInt *ti = new TokenInt((int64_t)query_datadef_measure(
					    type_query_chain_datadef(chain),
					    false));
	    ti->setDataType(&ddUINT64);
	    copy_token_location(ti, op_tb);
	    if ( paren )
		nextToken();               // ')'
	    return ti;
	}
    }
    if ( paren )
	nextToken();                       // ')'
    TokenBase *result = make_type_query_token(op_tb, row_dd, false);
    // C11 6.5.3.4p2: a VLA-typed operand IS evaluated — carry the index
    // expressions on the deferred query so the builder emits them (values
    // discarded) ahead of the size computation. A constant-folded result
    // means the operand type was NOT variably modified: not evaluated.
    if ( TokenTypeQuery *ttq = dynamic_cast<TokenTypeQuery *>(result) )
	ttq->operand_side_effects = idx_exprs;
    return result;
}

// sizeof applied to a VLA VARIABLE (`sizeof(a)` / `sizeof a` where `a` was
// declared `T a[n]`): the result is a runtime value — the product of the
// declaration-time dimension captures (materialize_vla_dim_capture rewrote
// the stored dim expressions to TokenVars over those hidden locals) times
// the element size. A subscripted or deref'd operand routes to the row form
// above instead. Returns NULL without consuming tokens when the operand is
// neither; the constant path handles everything else.
// alignof never needs this: alignment is a property of the element type.
TokenBase *Program::try_parse_vla_variable_sizeof(TokenBase *op_tb,
						  const std::string &op_name)
{
    if ( is_alignof_identifier(op_name) )
	return NULL;

    bool paren = peekToken() && peekToken()->id() == TokenID::tkOpBrk;
    size_t ix = paren ? 1 : 0;
    if ( tokens.size() <= ix + 1 || !tokens[ix] )
	return NULL;
    bool deref = tokens[ix]->id() == TokenID::tkMul;
    if ( deref )
	++ix;
    if ( tokens.size() <= ix || !tokens[ix]
      || !is_contextual_identifier_token(tokens[ix]) )
	return NULL;
    TokenBase *ident_tb = tokens[ix];
    TokenBase *after_tb = ix + 1 < tokens.size() ? tokens[ix + 1] : NULL;
    bool subscripted = after_tb && after_tb->id() == TokenID::tkOpSqr;

    std::string vla_var_name = contextual_identifier_name(ident_tb);
    Variable *v = findVariable(vla_var_name);
    if ( !v )
	return NULL;

    if ( deref || subscripted )
    {
	if ( deref && subscripted )
	    return NULL;                   // `sizeof *a[i]` — generic path
	return try_parse_vla_row_sizeof(op_tb, v, paren, deref, ix + 1);
    }

    if ( paren && (!after_tb || after_tb->id() != TokenID::tkClBrk) )
	return NULL;
    if ( !v->is_vla() || !v->vla_size_expr )
	return NULL;

    // Fresh leaf per use — AST nodes are single-use; the declaration keeps
    // ownership of the stored dim expressions.
    auto dim_leaf = [&](TokenBase *e) -> TokenBase * {
	if ( !e )
	    return NULL;
	if ( TokenVar *tv = dynamic_cast<TokenVar *>(e) )
	{
	    TokenVar *fresh = new TokenVar(tv->var);
	    copy_token_location(fresh, op_tb);
	    return fresh;
	}
	if ( TokenInt *ti = dynamic_cast<TokenInt *>(e) )
	{
	    TokenInt *c = new TokenInt(ti->ival());
	    c->setDataType(&ddUINT64);
	    copy_token_location(c, op_tb);
	    return c;
	}
	return NULL;
    };
    auto mul = [&](TokenBase *l, TokenBase *r) -> TokenBase * {
	TokenMul *m = new TokenMul();
	copy_token_location(m, op_tb);
	m->left = l;
	m->right = r;
	return m;
    };

    TokenBase *total = dim_leaf(v->vla_size_expr);
    if ( !total )
	return NULL;
    DataDef *elem = v->type;
    if ( DataDefPTR *wp = dynamic_cast<DataDefPTR *>(elem) )
	elem = wp->base_type;
    while ( DataDefCArray *c = dynamic_cast<DataDefCArray *>(elem) )
    {
	TokenBase *d;
	if ( c->has_runtime_size() )
	    d = dim_leaf(c->count_expr);
	else
	{
	    TokenInt *ci = new TokenInt((int64_t)c->count);
	    ci->setDataType(&ddUINT64);
	    copy_token_location(ci, op_tb);
	    d = ci;
	}
	if ( !d )
	    return NULL;
	total = mul(total, d);
	elem = c->element_type;
    }
    TokenInt *esz = new TokenInt((int64_t)elem->size);
    esz->setDataType(&ddUINT64);
    copy_token_location(esz, op_tb);
    total = mul(total, esz);

    if ( paren )
    {
	nextToken(); // consume '('
	nextToken(); // consume identifier
	nextToken(); // consume ')'
    }
    else
	nextToken(); // consume identifier
    return total;
}

TokenDataType *Program::parse_typeof_datatype(TokenBase *op_tb)
{
    if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	Throw(op_tb) << "Expecting '(' after typeof" << flush;
    nextToken();

    TokenBase *type_tb = nextToken();
    if ( !type_tb )
	Throw(op_tb) << "Unexpected end of input in typeof" << flush;

    DataDef *dd = NULL;
    bool closed_paren = false;
    if ( type_tb->type() == TokenType::ttDataType )
	dd = &((TokenDataType *)type_tb)->definition;
    else if ( type_tb->type() == TokenType::ttKeyword && type_tb->id() == TokenID::tkSTRUCT )
    {
	TokenBase *tag_tb = nextToken();
	if ( tag_tb && tag_tb->type() == TokenType::ttIdentifier )
	    dd = resolve_named_datadef(((TokenIdent *)tag_tb)->spelling());
	if ( !dd )
	    Throw(tag_tb) << "Unknown struct type in typeof" << flush;
    }
    else if ( type_tb->type() == TokenType::ttIdentifier )
    {
	std::string tname = ((TokenIdent *)type_tb)->spelling();
	dd = resolve_named_datadef(tname);
	if ( !dd )
	{
	    // The bracketed subparse (initial_brackets=1) usually consumes
	    // typeof's own ')' — check that FIRST, or a ')' that follows the
	    // whole typeof (the enclosing cast's `(typeof (x))` close-paren)
	    // gets stolen and the cast degrades to an unbalanced group.
	    TokenBase *expr = parseExpression(type_tb, true, false, true, 1);
	    if ( (curToken() && curToken()->id() == TokenID::tkClBrk)
	      || (prevToken() && prevToken()->id() == TokenID::tkClBrk) )
		; // subparse already consumed typeof's ')'
	    else if ( peekToken() && peekToken()->id() == TokenID::tkClBrk )
		nextToken();
	    else
		Throw(type_tb) << "Expecting ')' after typeof expression" << flush;
	    dd = expr ? expr->datadef() : NULL;
	    closed_paren = true;
	}
    }
    else
    {
	TokenBase *expr = parseExpression(type_tb, true, false, true, 1);
	if ( (curToken() && curToken()->id() == TokenID::tkClBrk)
	  || (prevToken() && prevToken()->id() == TokenID::tkClBrk) )
	    ; // subparse already consumed typeof's ')' (see above)
	else if ( peekToken() && peekToken()->id() == TokenID::tkClBrk )
	    nextToken();
	else
	    Throw(type_tb) << "Expecting ')' after typeof expression" << flush;
	dd = expr ? expr->datadef() : NULL;
	closed_paren = true;
    }

    while ( !closed_paren && dd && peekToken() && peekToken()->id() == TokenID::tkMul )
    {
	nextToken();
	dd = getPointerType(dd);
    }
    if ( !closed_paren && (!peekToken() || peekToken()->id() != TokenID::tkClBrk) )
	Throw(type_tb) << "Expecting ')' after typeof" << flush;
    if ( !closed_paren )
	nextToken();

    if ( !dd )
	Throw(type_tb) << "typeof: cannot determine operand type" << flush;

    return new TokenDataType(dd->name.c_str(), *dd);
}

bool Program::parsing_template_instantiated_member_body()
{
    if ( instantiating_canonical_spelling.empty()
      || compounds.empty() || !compounds.top()
      || !compounds.top()->method )
	return false;
    return compounds.top()->method->owner_class != NULL;
}

void Program::consume_deferred_static_assert_statement(TokenBase *tb)
{
    if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	Throw(tb) << "Expecting '(' after " << ((TokenIdent *)tb)->spelling() << flush;
    nextToken();

    int depth = 1;
    while ( depth > 0 )
    {
	TokenBase *t = nextToken();
	if ( !t )
	    Throw(tb) << "Unexpected end of input in static assertion" << flush;
	if ( t->id() == TokenID::tkOpBrk )
	    ++depth;
	else if ( t->id() == TokenID::tkClBrk )
	    --depth;
    }
    if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
	nextToken();
}

TokenBase *Program::parse_static_assert_statement(TokenBase *tb)
{
    if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	Throw(tb) << "Expecting '(' after " << ((TokenIdent *)tb)->spelling() << flush;

    if ( parsing_template_instantiated_member_body()
      || fn_template_instantiation_depth > 0 )
    {
	consume_deferred_static_assert_statement(tb);
	return NULL;
    }

    nextToken();

    int64_t cond = parse_constant_integer_expression();
    std::string message = "static assertion failed";
    if ( peekToken() && peekToken()->id() == TokenID::tkComma )
    {
	nextToken();
	TokenBase *msg_tb = nextToken();
	if ( !msg_tb || msg_tb->type() != TokenType::ttString )
	    Throw(msg_tb ? msg_tb : tb) << "Expecting string literal in static assertion" << flush;
	message = ((TokenStr *)msg_tb)->str;
    }

    if ( !peekToken() || peekToken()->id() != TokenID::tkClBrk )
	Throw(tb) << "Expecting ')' after static assertion" << flush;
    nextToken();
    if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
	nextToken();

    if ( !cond )
	Throw(tb) << message << flush;
    return NULL;
}

void Program::consume_class_static_assert_declaration(TokenBase *tb)
{
    if ( !peekToken() || peekToken()->id() != TokenID::tkOpBrk )
	Throw(tb) << "Expecting '(' after " << contextual_identifier_name(tb) << flush;
    nextToken(); // consume '('

    TokenBase *first_expr = NULL;
    size_t top_expr_tokens = 0;
    bool before_message = true;
    std::string message = "static assertion failed";
    int depth = 1;
    while ( depth > 0 )
    {
	TokenBase *t = nextToken();
	if ( !t )
	    Throw(tb) << "Unexpected end of input in static assertion" << flush;

	if ( depth == 1 && before_message )
	{
	    if ( t->id() == TokenID::tkComma )
	    {
		before_message = false;
		continue;
	    }
	    if ( t->id() != TokenID::tkClBrk )
	    {
		if ( !first_expr )
		    first_expr = t;
		++top_expr_tokens;
	    }
	}
	else if ( depth == 1 && !before_message && t->type() == TokenType::ttString )
	    message = ((TokenStr *)t)->str;

	if ( t->id() == TokenID::tkOpBrk )
	    ++depth;
	else if ( t->id() == TokenID::tkClBrk )
	    --depth;
    }
    if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
	nextToken();

    bool simple_false = false;
    if ( top_expr_tokens == 1 && first_expr )
    {
	if ( first_expr->type() == TokenType::ttInteger )
	    simple_false = static_cast<TokenInt *>(first_expr)->ival() == 0;
	else if ( is_contextual_identifier_token(first_expr) )
	{
	    bool value = true;
	    if ( is_bool_literal_identifier(contextual_identifier_name(first_expr),
		    value) )
		simple_false = !value;
	}
    }
    if ( simple_false )
	Throw(tb) << message << flush;
}

bool Program::try_parse_constant_offsetof_address(int64_t &out)
{
    auto saved_tokens = tokens.savepos();
    size_t saved_diag_count = diagnostics.size();
    Program::ErrorInfo saved_error = last_error;

    auto fail = [&]() -> bool {
	tokens = saved_tokens;
	diagnostics.resize(saved_diag_count);
	last_error = saved_error;
	return false;
    };

    TokenBase *open_outer = nextToken();
    TokenBase *open_cast = nextToken();
    if ( !open_outer || open_outer->id() != TokenID::tkOpBrk
      || !open_cast || open_cast->id() != TokenID::tkOpBrk )
	return fail();

    DataDef *base_dd = NULL;
    TokenBase *type_tb = nextToken();
    if ( !type_tb )
	return fail();
    if ( type_tb->type() == TokenType::ttKeyword
      && (type_tb->id() == TokenID::tkSTRUCT || type_tb->id() == TokenID::tkUNION) )
    {
	TokenBase *tag_tb = nextToken();
	if ( !tag_tb || !is_contextual_identifier_token(tag_tb) )
	    return fail();
	base_dd = resolve_named_datadef(contextual_identifier_name(tag_tb));
    }
    else if ( peekToken() && peekToken()->id() == TokenID::tkLT
	   && (is_contextual_identifier_token(type_tb)
	    || type_tb->type() == TokenType::ttDataType) )
    {
	// A TEMPLATE-ID type argument — `offsetof(_FirstPaddingByte<>,
	// __first_padding_byte_)`, libc++ __libcpp_datasizeof's value, with
	// EMPTY angles filling from the default (`bool = __libcpp_is_final<
	// _Tp>::value || !is_class<_Tp>::value`). The one declared-type
	// resolver instantiates it and consumes the `<...>`; the bare-name
	// lookup below cannot (a template is not a type).
	if ( TokenDataType *tdt = resolve_declared_type_token(type_tb, true, true) )
	    base_dd = &tdt->definition;
    }
    else if ( type_tb->type() == TokenType::ttDataType )
	base_dd = &static_cast<TokenDataType *>(type_tb)->definition;
    else if ( is_contextual_identifier_token(type_tb) )
	base_dd = resolve_named_datadef(contextual_identifier_name(type_tb));
    if ( !base_dd )
	return fail();

    while ( peekToken() && peekToken()->id() != TokenID::tkClBrk )
	nextToken();
    TokenBase *close_cast = nextToken();
    if ( !close_cast || close_cast->id() != TokenID::tkClBrk )
	return fail();

    TokenBase *zero_tb = nextToken();
    madc_wide_int zero_value = 0;
    if ( !resolve_integer_constant(zero_tb, zero_value) || zero_value != 0 )
	return fail();
    TokenBase *close_outer = nextToken();
    if ( !close_outer || close_outer->id() != TokenID::tkClBrk )
	return fail();

    TokenBase *access = nextToken();
    if ( !access || (access->id() != TokenID::tkDeRef && access->id() != TokenID::tkDot) )
	return fail();

    int64_t offset = 0;
    DataDef *current = base_dd;
    while ( true )
    {
	if ( DataDefPTR *pdd = dynamic_cast<DataDefPTR *>(current) )
	    current = pdd->base_type;
	DataDefSTRUCT *sdd = dynamic_cast<DataDefSTRUCT *>(current);
	if ( !sdd )
	    return fail();

	TokenBase *member_tb = nextToken();
	if ( !member_tb || !is_contextual_identifier_token(member_tb) )
	    return fail();
	std::string member_name = contextual_identifier_name(member_tb);
	ssize_t member_offset = sdd->m_offset(member_name);
	if ( member_offset < 0 )
	    return fail();
	offset += member_offset;
	current = sdd->m_type(member_name);
	if ( !current )
	    return fail();

	while ( peekToken() && peekToken()->id() == TokenID::tkOpSqr )
	{
	    nextToken();
	    int64_t index = parse_constant_integer_expression();
	    TokenBase *close_sq = nextToken();
	    if ( !close_sq || close_sq->id() != TokenID::tkClSqr )
		return fail();
	    size_t elem_size = current->size ? current->size : 1;
	    offset += index * (int64_t)elem_size;
	}

	if ( peekToken()
	  && (peekToken()->id() == TokenID::tkDeRef || peekToken()->id() == TokenID::tkDot) )
	{
	    nextToken();
	    continue;
	}
	break;
    }

    out = offset;
    return true;
}

// Fold a qualified name that resolves to a class-scoped integral constant
// (a static-const data member or an enumerator) in CONSTANT context:
// `Class::member`, `Outer::Inner::member`, `ns::Class::member`,
// `ns::Tmpl<...>::member`. Reuses instantiate_template_id (for template-id
// segments) and resolve_class_static_member_const_value (for the final member).
// `first` is the already-consumed leading token (a type or a namespace name).
// Consumes the `::`-chain on success; returns false (without guaranteeing the
// stream position) only when the leading token can't begin such a chain — the
// callers below gate on that so non-qualified atoms are untouched.
bool Program::fold_constant_qualified_member(TokenBase *first, madc_wide_int &out)
{
    if ( !first )
	return false;
    DataDefCLASS *scope = NULL;
    std::string pending_ns;            // set while positioned right after a namespace name
    if ( first->type() == TokenType::ttDataType )
	scope = dynamic_cast<DataDefCLASS *>(&((TokenDataType *)first)->definition);
    else if ( is_contextual_identifier_token(first) )
    {
	// In the raw constant-expression token stream a type name is still a
	// bare identifier (not yet resolved to ttDataType).
	std::string nm = contextual_identifier_name(first);
	const uint32_t nm_id = template_name_pool.intern(nm);
	// A decltype-specifier as the qualifier ([expr.prim.id.qual]) — the
	// libc++ detection idiom's `static const bool value =
	// decltype(__test<_Tp>(0))::value;`. The one declared-type resolver
	// owns the decltype arm (it consumes `decltype( expr )` and any
	// member-TYPE chain, leaving a non-type `::value` unconsumed); its
	// resolved class is the scope for the member walk below. At PATTERN
	// parse the operand is dependent and resolves to a placeholder (not a
	// class) -> return false; the capture's savepos discipline restores the
	// stream and falls to the structural skip. The INSTANTIATION re-runs
	// this capture with concrete tokens and folds the real value.
	if ( !is_c_mode() && is_decltype_identifier(nm)
	  && peekToken() && peekToken()->id() == TokenID::tkOpBrk )
	{
	    if ( TokenDataType *dt = resolve_declared_type_token(first, true, true) )
		scope = dynamic_cast<DataDefCLASS *>(&dt->definition);
	    if ( !scope )
		return false;
	}
	// Template-id leading segment `Name<...>::...`: instantiate to a scope.
	if ( peekToken() && peekToken()->id() == TokenID::tkLT
	  && (find_template(nm_id, std::string(), NULL)
	   || find_template_alias(nm_id, std::string(), NULL)) )
	{
	    // Fold a trait's `::value` (e.g. `__and_<__has_construct<...>>::value`):
	    // let the variadic trait template really instantiate so its `::value`
	    // member is concrete. The cycle that once made this unsafe is gone now
	    // that the inner trait (`__has_construct`) folds to a true_type leaf.
	    bool saved_vri = allow_variadic_real_inst;
	    allow_variadic_real_inst = true;
	    TokenDataType *inst = instantiate_template_id(nm, first);
	    allow_variadic_real_inst = saved_vri;
	    if ( inst )
		scope = dynamic_cast<DataDefCLASS *>(&inst->definition);
	}
	if ( !scope )
	{
	    flat_datatype_map_iter di = datatype_map.find(nm);
	    if ( di != datatype_map.end() )
		scope = dynamic_cast<DataDefCLASS *>(&(*di)->definition);
	}
	// A class-scope TYPEDEF ALIAS as the qualifier: `typedef impl<T>
	// __base;` then `static const bool v = __base::ok;` — libc++
	// numeric_limits' ENTIRE value surface reads through this shape.
	// The alias lives on the enclosing class (set_class_type_alias),
	// not in the flat maps; resolve_current_class_type_alias is the
	// one owner (method-owner shadow + class-scope stack).
	if ( !scope )
	    scope = dynamic_cast<DataDefCLASS *>(
			resolve_current_class_type_alias(nm));
	if ( !scope && (namespace_map.count(nm) || namespace_datatype_map.count(nm)) )
	    pending_ns = nm;
	if ( !scope && pending_ns.empty() )
	    return false;
    }
    else
	return false;
    if ( !scope && pending_ns.empty() )
	return false;
    // `Trait<...>{}` / `Trait{}` (or `()`) value-init in a constant expression is
    // the std::integral_constant conversion to its `value` — `static_assert(
    // is_same<int,int>{})`, `__is_invocable<...>{}`, `true_type{}`. Fold to the
    // scope's (possibly inherited) static `value` member, the same constant the
    // `::value` form reads. Only EMPTY `{}`/`()` (value-init); a braced
    // initializer with contents is not a constant trait.
    if ( scope && tokens.size() >= 2 && tokens[0] && tokens[1]
      && (tokens[0]->id() == TokenID::tkOpBrc
       || tokens[0]->id() == TokenID::tkOpBrk) )
    {
	TokenID close = tokens[0]->id() == TokenID::tkOpBrc
		      ? TokenID::tkClBrc : TokenID::tkClBrk;
	int64_t v = 0;
	if ( tokens[1]->id() == close
	  && resolve_class_static_member_const_value(scope, "value", v) )
	{
	    nextToken();   // consume the opening { or (
	    nextToken();   // consume the closing } or )
	    out = v;
	    return true;
	}
    }
    if ( !peekToken() || peekToken()->id() != TokenID::tkNS )
	return false;

    while ( peekToken() && peekToken()->id() == TokenID::tkNS )
    {
	nextToken(); // consume '::'
	TokenBase *seg = nextToken();
	if ( !seg )
	    return false;
	std::string seg_name;
	if ( seg->type() == TokenType::ttDataType )
	    seg_name = ((TokenDataType *)seg)->spelling();
	else if ( is_contextual_identifier_token(seg) )
	    seg_name = contextual_identifier_name(seg);
	else
	    return false;

	// template-id segment `Name<...>` — instantiate (in pending_ns if set).
	DataDefCLASS *seg_scope = NULL;
	if ( peekToken() && peekToken()->id() == TokenID::tkLT )
	{
	    bool saved_vri = allow_variadic_real_inst;
	    allow_variadic_real_inst = true;
	    TokenDataType *inst =
		    instantiate_template_id(seg_name, seg, pending_ns,
					    pending_ns.empty() ? scope : NULL);
	    allow_variadic_real_inst = saved_vri;
	    if ( inst )
		seg_scope = dynamic_cast<DataDefCLASS *>(&inst->definition);
	}

	bool more = peekToken() && peekToken()->id() == TokenID::tkNS;
	if ( more )
	{
	    // Intermediate segment: must name a class to descend into.
	    if ( !seg_scope )
	    {
		if ( !pending_ns.empty() )
		{
		    namespace_datatype_map_t::iterator ni =
			namespace_datatype_map.find(pending_ns);
		    if ( ni != namespace_datatype_map.end() )
		    {
			datatype_map_iter di = ni->find(seg_name);
			if ( di != ni->end() )
			    seg_scope = dynamic_cast<DataDefCLASS *>(
				&di->second->definition);
		    }
		}
		else if ( scope )
		    seg_scope = dynamic_cast<DataDefCLASS *>(
			resolve_class_type_alias(scope, seg_name));
	    }
	    if ( !seg_scope )
		return false;
	    scope = seg_scope;
	    pending_ns.clear();
	    continue;
	}

	// Final segment: a member of the current class scope.
	if ( seg_scope || !scope )
	    return false;            // a type, or no scope to look in
	// The static-member capture map stores int64 (wide static-const
	// members are out of the slice-3 fold's scope); widen on the way out.
	int64_t member_val = 0;
	if ( !resolve_class_static_member_const_value(scope, seg_name, member_val) )
	    return false;
	out = member_val;
	return true;
    }
    return false;
}

madc_wide_int Program::parse_constant_primary()
{
    TokenBase *tb = nextToken();
    madc_wide_int out = 0;

    if ( resolve_integer_constant(tb, out) )
	return out;
    // Qualified class-scoped integral constant: `Class::member`,
    // `ns::Tmpl<...>::member`, etc. Folds to the captured value; gated on the
    // leading token beginning such a chain, so plain atoms fall through.
    if ( fold_constant_qualified_member(tb, out) )
	return out;
    if ( try_parse_constant_functional_cast(tb, out) )
	return out;
    if ( tb && is_contextual_identifier_token(tb) )
    {
	std::string name = contextual_identifier_name(tb);
	bool bool_value = false;
	if ( is_bool_literal_identifier(name, bool_value) )
	    return bool_value ? 1 : 0;
	if ( name == "sizeof" || is_alignof_identifier(name) )
	    return (madc_wide_int)evaluate_type_query(tb, name);
	// Type-trait builtins in constant context — the std::integral_constant
	// initializer shape `static const bool value = __is_class(T);` and non-type
	// template args. Args are concrete (madc monomorphizes); fold to 0/1.
	if ( is_type_trait_builtin(name) )
	{
	    TokenBase *r = evaluate_type_trait(tb, name);
	    return static_cast<TokenInt *>(r)->ival();
	}
	// Unqualified sibling static-const member inside the class body,
	// e.g. `static const category all = (ctype | numeric);`. Resolves
	// to the value captured by capture_constant_initializer_value.
	// Falls through to the throw below for any non-member identifier,
	// so non-class constant contexts are unaffected.
	int64_t member_val = 0;
	if ( resolve_current_class_static_member_const_value(name, member_val) )
	    return member_val;
	if ( is_nullptr_identifier(name) )
	    return 0;
	if ( is_named_cpp_cast(name) )
	    return parse_constant_named_cpp_cast(tb, name);
	// C++20 requires-EXPRESSION as a constraint atom (e.g. inside a concept's
	// constraint `... && requires(_Iter __i) { ++__i; }`). `requires` is already
	// consumed (it is `tb`); evaluate the requirement-seq's well-formedness.
	if ( name == "requires" )
	    return evaluate_requires_expression_constant();
	// C++14 VARIABLE TEMPLATE in a constant expression: `is_floating_point_v
	// <double>` (a non-type bool arg — e.g. enable_if's condition in
	// std::numbers). Substitute the type args into the initializer tokens and
	// fold them recursively in an isolated stream: the init
	// `is_floating_point<_Tp>::value` becomes `is_floating_point<double>::value`,
	// which folds via the normal trait `::value` path. (The parseExpression
	// use-site resolution does not cover this constant-context path.)
	if ( peekToken() && peekToken()->id() == TokenID::tkLT )
	{
	    VarTemplateDef *vti =
		var_template_map.find(name);
	    if ( vti == var_template_map.end() && !current_namespace().empty() )
		vti = var_template_map.find(current_namespace() + "::" + name);
	    if ( vti != var_template_map.end() && !vti->init.empty() )
	    {
		std::vector<DataDef *> targs = capture_call_template_args();
		std::vector<TokenBase *> sub =
		    substitute_var_template_init(*vti, targs);
		if ( !sub.empty() )
		{
		    sub.push_back(new TokenSemi());
		    TokenStream::State saved = tokens.swap_in(std::move(sub));
		    madc_wide_int v = 0;
		    try { v = parse_constant_integer_expression(); }
		    catch ( ... ) { tokens.swap_back(std::move(saved)); throw; }
		    tokens.swap_back(std::move(saved));
		    return v;
		}
	    }
	}
	// C++20 CONCEPT used as a non-type bool in a constant expression — e.g.
	// `__conditional_t<random_access_iterator<It>, ...>`'s condition, or a
	// `static_assert(Concept<T>)`. Substitute the type args into the stored
	// constraint and fold it recursively in an ISOLATED stream → 0/1. Nested
	// concept-ids recurse back into this same arm; trait-based atoms
	// (`derived_from`→`__is_base_of`, `same_as`→`__is_same`, plain type-trait
	// builtins) fold via the existing primary paths; `&&`/`||` short-circuit
	// (parse_constant_land/lor) and `requires`-expressions evaluate via the
	// requires arm below. Same shape as the C++14 variable-template arm above.
	if ( peekToken() && peekToken()->id() == TokenID::tkLT )
	{
	    std::map<std::string, ConceptDef>::iterator cit =
		concept_map.find(name);
	    if ( cit == concept_map.end() && !current_namespace().empty() )
		cit = concept_map.find(current_namespace() + "::" + name);
	    if ( cit != concept_map.end() && !cit->second.constraint.empty() )
	    {
		std::vector<DataDef *> targs = capture_call_template_args();
		std::map<std::string, TokenDataType *> subst;
		for ( size_t i = 0; i < cit->second.typeparams.size()
				&& i < targs.size(); ++i )
		    if ( targs[i] )
			subst[cit->second.typeparams[i]] =
			    new TokenDataType(targs[i]->name.c_str(), *targs[i]);
		std::vector<TokenBase *> sub =
		    clone_template_tokens_with_type_subst(cit->second.constraint,
							  subst);
		if ( !sub.empty() )
		{
		    sub.push_back(new TokenSemi());
		    TokenStream::State saved = tokens.swap_in(std::move(sub));
		    madc_wide_int v = 0;
		    try { v = parse_constant_integer_expression(); }
		    catch ( ... ) { tokens.swap_back(std::move(saved)); throw; }
		    tokens.swap_back(std::move(saved));
		    return v ? 1 : 0;
		}
	    }
	}
    }
    if ( tb && tb->id() == TokenID::tkNeg )
	return -parse_constant_primary();
    if ( tb && tb->id() == TokenID::tkAdd )
	return parse_constant_primary();
    if ( tb && tb->id() == TokenID::tkLnot )
	return !parse_constant_primary();
    if ( tb && tb->id() == TokenID::tkBnot )
	return ~parse_constant_primary();
    if ( tb && tb->id() == TokenID::tkBand )
    {
	// offsetof-style addresses are 64-bit; widen on the way out.
	int64_t addr = 0;
	if ( try_parse_constant_offsetof_address(addr) )
	    return addr;
	Throw(tb) << "Unsupported address expression in constant expression" << flush;
    }
    if ( tb && tb->id() == TokenID::tkOpBrk )
    {
	// Check for cast: (type)value — e.g. (char)SB, (unsigned char)~0
	TokenBase *inner = peekToken();
	if ( inner && (inner->type() == TokenType::ttDataType
	  || inner->id() == TokenID::tkCONST
	  || inner->id() == TokenID::tkRESTRICT) )
	{
	    // Extract the cast target type for truncation
	    DataDef *cast_dd = NULL;
	    bool is_unsigned = false;
	    while ( peekToken()
	         && peekToken()->id() != TokenID::tkClBrk )
	    {
		TokenBase *ct = nextToken();
		if ( ct->type() == TokenType::ttDataType )
		    cast_dd = &((TokenDataType *)ct)->definition;
		if ( ct->type() == TokenType::ttIdentifier )
		{
		    std::string tname = ((TokenIdent *)ct)->spelling();
		    if ( tname == "unsigned" ) is_unsigned = true;
		}
	    }
	    if ( peekToken() )
		nextToken(); // consume ')'
	    madc_wide_int val = parse_constant_primary();
	    return apply_integer_cast_value(cast_dd, val, is_unsigned);
	}
	out = parse_constant_integer_expression();
	tb = nextToken();
	if ( !tb || tb->id() != TokenID::tkClBrk )
	    Throw(tb) << "Expecting ')' in constant expression" << flush;
	return out;
    }
    Throw(tb) << "Expecting integer constant expression" << flush;
    return 0;
}

madc_wide_int Program::parse_constant_mul()
{
    madc_wide_int lhs = parse_constant_primary();

    while ( peekToken() )
    {
	TokenBase *op = peekToken();
	if ( op->id() != TokenID::tkMul && op->id() != TokenID::tkDiv && op->id() != TokenID::tkMod )
	    break;
	nextToken(); // consume operator
	madc_wide_int rhs = parse_constant_primary();
	if ( op->id() == TokenID::tkMul ) lhs *= rhs;
	else if ( op->id() == TokenID::tkDiv )
	{
	    if ( rhs == 0 )
		Throw(op) << "Division by zero in constant expression" << flush;
	    lhs /= rhs;
	}
	else
	{
	    if ( rhs == 0 )
		Throw(op) << "Modulo by zero in constant expression" << flush;
	    lhs %= rhs;
	}
    }

    return lhs;
}

// additive: parse_constant_mul ([+-] parse_constant_mul)*
madc_wide_int Program::parse_constant_add()
{
    madc_wide_int lhs = parse_constant_mul();

    while ( peekToken() )
    {
	TokenBase *op = peekToken();
	if ( op->id() != TokenID::tkAdd && op->id() != TokenID::tkSub && op->id() != TokenID::tkNeg )
	    break;
	nextToken(); // consume operator
	madc_wide_int rhs = parse_constant_mul();
	if ( op->id() == TokenID::tkAdd ) lhs += rhs;
	else lhs -= rhs;
    }

    return lhs;
}

// shift: parse_constant_add ([<<>>] parse_constant_add)*
madc_wide_int Program::parse_constant_shift()
{
    madc_wide_int lhs = parse_constant_add();

    while ( peekToken() )
    {
	TokenBase *op = peekToken();
	if ( op->id() != TokenID::tkBSL && op->id() != TokenID::tkBSR )
	    break;
	nextToken();
	madc_wide_int rhs = parse_constant_add();
	if ( op->id() == TokenID::tkBSL ) lhs <<= rhs;
	else                              lhs >>= rhs;
    }

    return lhs;
}

// bitwise-and / xor / or: same precedence order as C.
madc_wide_int Program::parse_constant_band()
{
    madc_wide_int lhs = parse_constant_eq();
    while ( peekToken() && peekToken()->id() == TokenID::tkBand )
    {
	nextToken();
	lhs &= parse_constant_eq();
    }
    return lhs;
}

madc_wide_int Program::parse_constant_bxor()
{
    madc_wide_int lhs = parse_constant_band();
    while ( peekToken() && peekToken()->id() == TokenID::tkXor )
    {
	nextToken();
	lhs ^= parse_constant_band();
    }
    return lhs;
}

madc_wide_int Program::parse_constant_bor()
{
    madc_wide_int lhs = parse_constant_bxor();
    while ( peekToken() && peekToken()->id() == TokenID::tkBor )
    {
	nextToken();
	lhs |= parse_constant_bxor();
    }
    return lhs;
}

madc_wide_int Program::parse_constant_rel()
{
    madc_wide_int lhs = parse_constant_shift();
    while ( peekToken() )
    {
	TokenBase *op = peekToken();
	if ( op->id() != TokenID::tkLT && op->id() != TokenID::tkGT
	  && op->id() != TokenID::tkLE && op->id() != TokenID::tkGE )
	    break;
	nextToken();
	madc_wide_int rhs = parse_constant_shift();
	switch ( op->id() )
	{
	    case TokenID::tkLT: lhs = lhs < rhs; break;
	    case TokenID::tkGT: lhs = lhs > rhs; break;
	    case TokenID::tkLE: lhs = lhs <= rhs; break;
	    default:            lhs = lhs >= rhs; break;
	}
    }
    return lhs;
}

madc_wide_int Program::parse_constant_eq()
{
    madc_wide_int lhs = parse_constant_rel();
    while ( peekToken() )
    {
	TokenBase *op = peekToken();
	if ( op->id() != TokenID::tkEquals && op->id() != TokenID::tkNotEq )
	    break;
	nextToken();
	madc_wide_int rhs = parse_constant_rel();
	lhs = (op->id() == TokenID::tkEquals) ? (lhs == rhs) : (lhs != rhs);
    }
    return lhs;
}

// Consume (without evaluating) one RHS operand of a `&&`/`||` whose value the
// LHS already short-circuits. A token-consuming recursive-descent evaluator MUST
// still advance past the operand (so the caller lands on the next operator /
// sentinel), but C++ [expr.const] does NOT require a short-circuited operand to
// be a constant expression — so `false && <runtime-call>` folds to false instead
// of throwing. (Previously `lhs = lhs && parse_constant_bor()` relied on C++'s
// own short-circuit, which SKIPPED the call and left the RHS tokens unconsumed,
// so a non-type template arg like `__can_memmove && __assignable` never reached
// its `;` sentinel and the whole fold failed.)
void Program::skip_const_logical_operand(bool stop_at_and)
{
    // DelimDepth (the one balanced-delimiter owner): the skipped operand can
    // carry a TEMPLATE-ID (`1 || is_convertible<int, char>::value` — libc++'s
    // __iterator_traits_impl bool argument), whose commas are template-argument
    // separators, not expression boundaries. The old paren/square/brace-only
    // counter returned at that comma, left the operand's tail unconsumed, and
    // the caller's sentinel check aborted the WHOLE fold (the _If alias then
    // instantiated an opaque zero-sized placeholder).
    DelimDepth d;
    while ( TokenBase *t = peekToken() )
    {
	TokenID id = (TokenID)t->id();
	if ( d.top() )
	{
	    if ( id == TokenID::tkSemi || id == TokenID::tkComma
	      || id == TokenID::tkClBrk || id == TokenID::tkClSqr
	      || id == TokenID::tkClBrc || id == TokenID::tkQmark
	      || id == TokenID::tkColon || id == TokenID::tkLor )
		return;
	    if ( stop_at_and && id == TokenID::tkLand )
		return;
	}
	delimStepStream(nextToken(), d);
    }
}

madc_wide_int Program::parse_constant_land()
{
    madc_wide_int lhs = parse_constant_bor();
    while ( peekToken() && peekToken()->id() == TokenID::tkLand )
    {
	nextToken();
	if ( !lhs )
	{
	    skip_const_logical_operand(true);   // short-circuit: 0 && X == 0
	    continue;
	}
	lhs = parse_constant_bor() ? 1 : 0;
    }
    return lhs;
}

madc_wide_int Program::parse_constant_lor()
{
    madc_wide_int lhs = parse_constant_land();
    while ( peekToken() && peekToken()->id() == TokenID::tkLor )
    {
	nextToken();
	if ( lhs )
	{
	    skip_const_logical_operand(false);  // short-circuit: 1 || X == 1
	    lhs = 1;
	    continue;
	}
	lhs = parse_constant_land() ? 1 : 0;
    }
    return lhs;
}

madc_wide_int Program::parse_constant_ternary()
{
    madc_wide_int cond = parse_constant_lor();
    if ( peekToken() && peekToken()->id() == TokenID::tkQmark )
    {
	nextToken(); // consume '?'
	madc_wide_int true_val = parse_constant_integer_expression();
	TokenBase *colon = nextToken();
	if ( !colon || colon->id() != TokenID::tkColon )
	    Throw(colon) << "Expecting ':' in ternary constant expression" << flush;
	madc_wide_int false_val = parse_constant_ternary();
	return cond ? true_val : false_val;
    }
    return cond;
}

madc_wide_int Program::parse_constant_integer_expression()
{
    return parse_constant_ternary();
}

// Materialize a folded constant value as a TokenInt (see madc.h). Historical
// typing preserved exactly for int64-range values; a >64-bit value keeps its
// low 64 bits on the token, parks the full value in valpool (wide_handle),
// and is typed ddINT128/ddUINT128 so wival()/emission see it as semantically
// wide (gcc types such fold results __int128/unsigned __int128).
TokenInt *Program::make_folded_integer_token(madc_wide_int v)
{
    int64_t lo = (int64_t)v;
    TokenInt *tok = new TokenInt(lo);
    if ( (madc_wide_int)lo == v )
    {
	// Fits 64 bits: widen the token's TYPE past default int only when the
	// value exceeds 32-bit range (the pre-slice-3 case-label behavior).
	uint64_t uval = (uint64_t)lo;
	if ( uval > 0x7FFFFFFF )
	    tok->setDataType(lo < 0 ? (DataDef *)&ddINT64 : (DataDef *)&ddUINT64);
	return tok;
    }
    tok->wide_handle = valpool.put_u128((uint64_t)(madc_wide_uint)v,
					(uint64_t)((madc_wide_uint)v >> 64));
    tok->setDataType(v < 0 ? (DataDef *)&ddINT128 : (DataDef *)&ddUINT128);
    return tok;
}

// A streambuf that silently swallows output. The speculative constant-folds below
// (fold_if_constexpr_condition / fold_nontype_arg_constant) mute std::cerr so a
// non-constant arg's caught Throw doesn't leak a diagnostic. Muting via
// rdbuf(NULL) is FRAGILE: a NULL rdbuf makes every insertion set badbit, and a
// write that reaches the throwstream's exceptions(badbit) during the nested
// instantiation the fold triggers throws basic_ios::clear — which ABORTS that
// (legitimate) instantiation instead of merely suppressing a message, and corrupts
// the real error into a spurious "iostream error". A real swallowing buffer keeps
// the stream good, so only the intended suppression happens.
namespace { struct MadcNullStreambuf : std::streambuf {
    int overflow(int c) override { return c; }   // accept and discard
}; MadcNullStreambuf g_madc_null_streambuf; }

bool Program::fold_if_constexpr_condition(int64_t &out)
{
    // Collect the balanced condition tokens (stream is just past the opening `(`),
    // consuming the matching `)`. Keep them so a non-constant condition can be
    // pushed back for the runtime-`if` fallback.
    std::vector<TokenBase *> cond_toks;
    int depth = 1;
    TokenBase *t;
    while ( depth > 0 && (t = nextToken()) )
    {
	if ( t->id() == TokenID::tkOpBrk )
	    ++depth;
	else if ( t->id() == TokenID::tkClBrk )
	{
	    if ( --depth == 0 )
		break;                 // the matching ')' — consumed, not collected
	}
	cond_toks.push_back(t);
    }
    if ( depth != 0 )
    {
	// Unbalanced — push back what we took and bail to the runtime path.
	for ( std::vector<TokenBase *>::reverse_iterator it = cond_toks.rbegin();
	      it != cond_toks.rend(); ++it )
	    pushToken(*it);
	return false;
    }

    // Fold a CLONE in an isolated stream (same idiom as fold_nontype_arg_constant:
    // muted std::cerr, since a non-constant condition Throws and throwbuf::sync
    // prints before the exception we catch).
    size_t saved_diag_count = diagnostics.size();
    Program::ErrorInfo saved_error = last_error;
    std::vector<TokenBase *> body;
    for ( TokenBase *ct : cond_toks )
	body.push_back(ct->clone());
    body.push_back(new TokenSemi());
    TokenStream::State saved_tokens = tokens.swap_in(std::move(body));
    std::streambuf *saved_cerr = std::cerr.rdbuf();
    std::ios::iostate saved_cerr_state = std::cerr.rdstate();
    std::cerr.rdbuf(&g_madc_null_streambuf);
    bool ok = false;
    try
    {
	madc_wide_int v = parse_constant_integer_expression();
	if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
	{
	    // The condition is contextually bool; normalize a wide fold so a
	    // value whose LOW 64 bits are zero (e.g. (__int128)1 << 100) stays
	    // truthy through the int64 out-param.
	    out = ((int64_t)v != 0) ? (int64_t)v : (v != 0 ? 1 : 0);
	    ok = true;
	}
    }
    catch ( ... ) { ok = false; }
    std::cerr.rdbuf(saved_cerr);
    std::cerr.clear(saved_cerr_state);
    tokens = saved_tokens;
    if ( !ok )
    {
	diagnostics.resize(saved_diag_count);
	last_error = saved_error;
	// Restore the live stream: condition tokens followed by the ')'.
	pushToken(new TokenClBrk());
	for ( std::vector<TokenBase *>::reverse_iterator it = cond_toks.rbegin();
	      it != cond_toks.rend(); ++it )
	    pushToken(*it);
    }
    return ok;
}

void Program::skip_discarded_statement()
{
    TokenBase *p = peekToken();
    if ( !p )
	return;
    if ( p->id() == TokenID::tkOpBrc )
    {
	nextToken();                       // consume '{'
	int depth = 1;
	TokenBase *t;
	while ( depth > 0 && (t = nextToken()) )
	{
	    if ( t->id() == TokenID::tkOpBrc ) ++depth;
	    else if ( t->id() == TokenID::tkClBrc ) --depth;
	}
	return;
    }
    // A single (non-block) statement: consume through its terminating ';' at
    // bracket/brace/paren depth 0.
    int pd = 0, bd = 0, sd = 0;
    TokenBase *t;
    while ( (t = peekToken()) )
    {
	TokenID id = t->id();
	if ( id == TokenID::tkSemi && pd == 0 && bd == 0 && sd == 0 )
	{ nextToken(); break; }
	nextToken();
	if ( id == TokenID::tkOpBrk ) ++pd;
	else if ( id == TokenID::tkClBrk && pd > 0 ) --pd;
	else if ( id == TokenID::tkOpBrc ) ++bd;
	else if ( id == TokenID::tkClBrc && bd > 0 ) --bd;
	else if ( id == TokenID::tkOpSqr ) ++sd;
	else if ( id == TokenID::tkClSqr && sd > 0 ) --sd;
    }
}

static bool constant_initializer_has_runtime_access(Program &pgm)
{
    // Explicit paren/square/brace, NOT d.top(): this scan never tracked angle
    // brackets, and top() also demands angle == 0 — `a < b;` would open one and
    // silently stop the `;` from terminating the scan.
    DelimDepth d;
    for ( size_t i = 0; i < pgm.tokens.size(); ++i )
    {
	TokenBase *t = pgm.tokens[i];
	if ( !t )
	    continue;
	if ( t->id() == TokenID::tkSemi
	  && d.paren == 0 && d.square == 0 && d.brace == 0 )
	    break;
	d.update(t);
	if ( t->id() == TokenID::tkDot || t->id() == TokenID::tkDeRef )
	{
	    // The offsetof idiom `((T*)0)->member` (madc's own stddef.h
	    // spelling; libc++ __libcpp_datasizeof::value is exactly this) is
	    // an ADDRESS COMPUTATION, not runtime access — recognize the
	    // null-pointer-deref shape and let the fold's dedicated parser
	    // (try_parse_constant_offsetof_address) decide.
	    bool nullptr_deref = t->id() == TokenID::tkDeRef && i >= 2
		&& pgm.tokens[i-1] && pgm.tokens[i-1]->id() == TokenID::tkClBrk
		&& pgm.tokens[i-2]
		&& pgm.tokens[i-2]->type() == TokenType::ttInteger
		&& pgm.tokens[i-2]->ival() == 0;
	    if ( !nullptr_deref )
		return true;
	}
	if ( !is_contextual_identifier_token(t) )
	    continue;
	TokenBase *next = (i + 1 < pgm.tokens.size()) ? pgm.tokens[i + 1] : NULL;
	if ( next && (next->id() == TokenID::tkDot || next->id() == TokenID::tkDeRef) )
	    return true;
	std::string name = contextual_identifier_name(t);
	// A decltype-specifier's operand is UNEVALUATED ([dcl.type.decltype]):
	// nothing inside it is runtime access, and member/call shapes there
	// (`decltype(__test<_Tp>(0))::value` — the libc++ detection idiom)
	// must not veto the fold. Skip the balanced operand extent (DelimDepth
	// owns balanced-delimiter scanning); the group nets zero on `d`.
	if ( is_decltype_identifier(name)
	  && i + 1 < pgm.tokens.size() && pgm.tokens[i + 1]
	  && pgm.tokens[i + 1]->id() == TokenID::tkOpBrk )
	{
	    DelimDepth skipd;
	    size_t j = i + 1;
	    while ( j < pgm.tokens.size() )
	    {
		j += delim_scan_step(pgm.tokens, j, skipd);
		if ( skipd.paren == 0 )
		    break;
	    }
	    i = j - 1;		// the loop's ++i resumes past the ')'
	    continue;
	}
	bool bool_value = false;
	bool constant_callable = name == "sizeof"
			      || is_alignof_identifier(name)
			      || is_type_trait_builtin(name)
			      || is_bool_literal_identifier(name, bool_value)
			      || is_nullptr_identifier(name);
	// A TYPE name heading `(...)` is a functional CAST, not a runtime
	// call — `type(-1) < type(0)` through the class's own member typedef
	// is libc++ __libcpp_numeric_limits' entire is_signed/digits chain.
	// Same resolution order the fold itself uses (flat map, then the
	// class-scope alias owner; a template-param alias resolves too — the
	// fold then declines it under a placeholder, which is the correct
	// capture-time outcome).
	if ( next && next->id() == TokenID::tkOpBrk && !constant_callable
	  && (pgm.datatype_map.find(name) != pgm.datatype_map.end()
	   || pgm.resolve_current_class_type_alias(name)) )
	    constant_callable = true;
	if ( next && next->id() == TokenID::tkOpBrk && !constant_callable )
	    return true;
    }
    return false;
}

// Speculatively fold a static-data-member initializer (caller has already consumed
// the '=') to a constant integer, expecting a terminating ';'. On success the
// initializer is CONSUMED (stream left at ';') and the value returned via `out`; on
// any failure the stream/diagnostics are restored and false returned, so the caller
// falls back to skipping a non-constant initializer. Same save/try/restore idiom as
// bracket_dim_constant_expression_parses.
bool Program::capture_constant_initializer_value(int64_t &out)
{
    if ( constant_initializer_has_runtime_access(*this) )
	return false;
    auto saved_tokens = tokens.savepos();
    size_t saved_diag_count = diagnostics.size();
    Program::ErrorInfo saved_error = last_error;
    // A non-constant / still-dependent initializer (a dependent `static constexpr`
    // member like libstdc++'s `value = static_cast<...>(...)`) makes
    // parse_constant_integer_expression Throw, and throwbuf::sync() prints to stderr
    // BEFORE the exception we catch — so this legitimate "skip the non-constant
    // initializer" fallback would leak a spurious error. Mute std::cerr for the
    // speculative parse only; restore + clear its state after. (Same idiom as
    // fold_nontype_arg_constant / constraint_expression_well_formed.)
    std::streambuf *saved_cerr = std::cerr.rdbuf();
    std::ios::iostate saved_cerr_state = std::cerr.rdstate();
    std::cerr.rdbuf(&g_madc_null_streambuf);
    bool ok = false;
    int64_t v = 0;
    try
    {
	v = parse_constant_integer_expression();
	if ( peekToken() && peekToken()->id() == TokenID::tkSemi )
	    ok = true;
    }
    catch ( ... ) { ok = false; }
    std::cerr.rdbuf(saved_cerr);
    std::cerr.clear(saved_cerr_state);
    if ( ok )
    {
	out = v;
	return true;                // keep the consumed position (stream at ';')
    }
    tokens = saved_tokens;
    diagnostics.resize(saved_diag_count);
    last_error = saved_error;
    return false;
}

bool Program::bracket_dim_constant_expression_parses()
{
    auto saved_tokens = tokens.savepos();
    size_t saved_diag_count = diagnostics.size();
    Program::ErrorInfo saved_error = last_error;
    try
    {
	int64_t n = parse_constant_integer_expression();
	TokenBase *cl = nextToken();
	tokens = saved_tokens;
	diagnostics.resize(saved_diag_count);
	last_error = saved_error;
	return n >= 0 && cl && cl->id() == TokenID::tkClSqr;
    }
    catch ( ... )
    {
	tokens = saved_tokens;
	diagnostics.resize(saved_diag_count);
	last_error = saved_error;
	return false;
    }
}

bool Program::bracket_dim_uses_runtime_value(
					   const std::set<std::string> *runtime_names)
{
    int depth = 1;
    for ( size_t ix = 0; ix < tokens.size() && depth > 0; ++ix )
    {
	TokenBase *t = tokens[ix];
	if ( t->id() == TokenID::tkOpSqr ) { ++depth; continue; }
	if ( t->id() == TokenID::tkClSqr ) { --depth; continue; }
	if ( t->id() == TokenID::tkSemi || t->id() == TokenID::tkOpBrc ) break;
	// ++ or -- in a dimension expression is inherently runtime
	if ( t->id() == TokenID::tkInc || t->id() == TokenID::tkDec )
	    return true;
	std::string name;
	if ( t->type() == TokenType::ttIdentifier )
	    name = ((TokenIdent *)t)->spelling();
	else
	    continue;
	if ( runtime_names && runtime_names->count(name) )
	    return true;
	Variable *v = findVariable(name);
	if ( !v )
	    continue;
	if ( v->is_constant() )
	{
	    // A const-qualified var folds to a constant dimension ONLY if its
	    // value is known at compile time. A const with a runtime initializer
	    // (e.g. `const int len = atoi(argv[1]);`) carries no folded value
	    // (`var->data` is NULL) and is therefore still a VLA bound.
	    madc_wide_int cval;
	    if ( read_constant_integer(v, cval) )
		continue;
	    return true;
	}
	return true;
    }
    return false;
}

bool Program::bracket_dim_has_constant_fold_query()
{
    int depth = 1;
    for ( size_t ix = 0; ix < tokens.size() && depth > 0; ++ix )
    {
	TokenBase *t = tokens[ix];
	if ( t->id() == TokenID::tkOpSqr ) { ++depth; continue; }
	if ( t->id() == TokenID::tkClSqr ) { --depth; continue; }
	if ( depth != 1 )
	    continue;
	if ( t->type() != TokenType::ttIdentifier )
	    continue;
	std::string name = ((TokenIdent *)t)->spelling();
	if ( name == "sizeof" || is_alignof_identifier(name) )
	    return true;
    }
    return false;
}

bool Program::bracket_dim_needs_runtime_value(
					    const std::set<std::string> *runtime_names)
{
    if ( !bracket_dim_uses_runtime_value(runtime_names) )
	return false;
    if ( !bracket_dim_has_constant_fold_query() )
	return true;
    return !bracket_dim_constant_expression_parses();
}

DataDef *Program::parse_typedef_array_suffix(DataDef *base_dd,
					   const std::string &alias_name,
					   TokenBase *err_tok)
{
    if ( !base_dd )
	return base_dd;
    if ( !(peekToken() && peekToken()->id() == TokenID::tkOpSqr) )
	return base_dd;

    size_t alias_count = 1;
    TokenBase *alias_count_expr = NULL;
    while ( peekToken() && peekToken()->id() == TokenID::tkOpSqr )
    {
	nextToken(); // consume '['
	TokenBase *cl = nextToken();
	if ( cl && cl->id() == TokenID::tkClSqr )
	{
	    alias_count = 0;
	    continue;
	}
	pushToken(cl);
	if ( !alias_count_expr && bracket_dim_needs_runtime_value() )
	{
	    alias_count_expr = parseExpression(nextToken(), true);
	    cl = nextToken();
	    if ( !cl || cl->id() != TokenID::tkClSqr )
		Throw(cl ? cl : err_tok) << "Expected ] in typedef array declaration" << flush;
	    continue;
	}
	int64_t n = parse_constant_integer_expression();
	if ( n < 0 )
	    Throw(err_tok) << "Typedef array dimension must be non-negative" << flush;
	cl = nextToken();
	if ( !cl || cl->id() != TokenID::tkClSqr )
	    Throw(cl ? cl : err_tok) << "Expected ] in typedef array declaration" << flush;
	if ( n == 0 )
	    alias_count = 0;
	else
	    alias_count *= (size_t)n;
    }
    DataDefCArray *arr_dd = new DataDefCArray(*base_dd, alias_name, alias_count,
					      alias_count_expr);
    if ( forest_arena_enabled )
	forest_arena_record_unary(arr_dd);	// v25: DK_CARRAY write-through
    return arr_dd;
}

// Despaced-canonical index invalidation counter — bumped by
// DataDef::set_canonical_spelling when an already-swept dd's spelling changes
// (see StructRegistry::find_despaced).
uint64_t DataDef::canonical_spelling_gen = 0;
thread_local bool madc_class_pattern_capture_active = false;

DataDefVOID ddVOID;
DataDefVOIDref ddVOIDref;
DataDefBOOL ddBOOL;
DataDefCHAR ddCHAR;
DataDefINT ddINT;
DataDefINT8 ddINT8;
DataDefINT16 ddINT16;
DataDefINT24 ddINT24;
DataDefINT32 ddINT32;
DataDefINT64 ddINT64;
DataDefUINT8 ddUINT8;
DataDefUINT16 ddUINT16;
DataDefUINT24 ddUINT24;
DataDefUINT32 ddUINT32;
DataDefUINT64 ddUINT64;
DataDefINT128 ddINT128;
DataDefUINT128 ddUINT128;
DataDefFLOAT ddFLOAT;
DataDefDOUBLE ddDOUBLE;
DataDefLDOUBLE ddLDOUBLE;
DataDefSTRUCT ddMAX_ALIGN_T("max_align_t", 0);
DataDefARRAY ddARRAY;
// Out-of-line (ddCHAR is declared above; DataDefLPSTR IS-A DataDefPTR now). Keep
// the "LPSTR" name the plain-tag definition carried (DataDefPTR's ctor would name
// it "char*"); _type/size are identical to the old rtPtr(dtCHAR) form.
DataDefLPSTR::DataDefLPSTR() : DataDefPTR(ddCHAR) { name = "LPSTR"; }
// void& is a structural reference to void (was a bare dtVOIDref tag). ddVOID
// is defined just above ddVOIDref, so the global init order is satisfied.
DataDefVOIDref::DataDefVOIDref() : DataDefREF(ddVOID) { name = "void&"; }
DataDefLPSTR ddLPSTR;
DataDefPTR ddVOIDptr(ddVOID), ddCHARptr(ddCHAR), ddINTptr(ddINT), ddINT32ptr(ddINT32);
DataDefAUTO ddAUTO;

struct DataDefMAXAlignTInit
{
    DataDefMAXAlignTInit()
    {
	ddMAX_ALIGN_T.addMember("__max_align_ll", ddINT64, 1);
	ddMAX_ALIGN_T.addMember("__max_align_ld", ddDOUBLE, 1);
	ddMAX_ALIGN_T.finalize();
	ddMAX_ALIGN_T.is_complete = true;
    }
} ddMAX_ALIGN_T_init;

void printuint32(uint32_t &i)
{
    std::cout << "i: " << i << std::endl << std::flush;
}

void printuint32(uint32_t i)
{
    std::cout << "i: " << i << std::endl << std::flush;
}

void EatSpaces(istream &is)
{
    while ( is.good() && !is.eof() && isspace(is.peek()) )
        is.get();
}


// Variable constructor, will allocate data and initialize if requested
Variable::Variable(std::string n, DataDef &d, uint32_t c, void *init, bool alloc)
{
    name = n;
    type = &d;
    count = c;
    flags = 0;
    data = NULL;
    aot_data_offset = (size_t)-1;
    aot_cstr_offset = (size_t)-1;
    vla_size_expr = nullptr;
    param_vla_side_effect_expr = nullptr;
    if ( init ) { alloc = true; }
    if ( !alloc ) { flags |= vfSTACK; }
    // Size 0 (e.g. FuncDef, void) has no storage. Function-pointer types
    // (DataDefFPTR, size 8) are a pointer slot and DO need allocation.
    if ( alloc && count == 1
      && ((type->basetype() != BaseType::btFunct && type->size > 0)
	|| dynamic_cast<DataDefFPTR *>(type) != NULL) )
    {
	data = calloc(count, d.size);
	flags |= vfALLOC;
	DBG(std::cout << "Variable::Variable data = calloc(" << count << ", " << d.size << ") for " << n << std::endl);
	DBG(std::cout << "Data address: " << (uint64_t)data << std::endl);
    }
}

Variable::~Variable()
{
    if ( !(flags & vfALLOC) )
	return;

    DBG(std::cout << "Variable::~Variable(" << name << ") freeing data" << std::endl);

    free(data);
}

Variable *DataDefCLASS::findMethod(const std::string &s)
{
    // check method_map first (unmangled names)
    std::map<std::string, Variable *>::iterator it = method_map.find(s);
    if ( it != method_map.end() )
	return it->second;

    // fallback: search methods vector by variable name
    for ( variable_vec_iter vvi = methods.begin(); vvi != methods.end(); ++vvi )
	if ( !s.compare((*vvi)->name) )
	    return *vvi;

    // search base class chain
    if ( base_class )
	return base_class->findMethod(s);

    return NULL;
}

static bool method_callable_with_arg_count(Variable *mv, size_t argc,
					   size_t *total_out = NULL)
{
    if ( !mv )
	return false;
    FuncDef *fd = dynamic_cast<FuncDef *>(mv->type);
    if ( !fd )
	return false;
    Method *md = (Method *)mv->data;
    size_t hidden = (md && md->owner_class && !(mv->flags & vfSTATIC)) ? 1 : 0;
    size_t total = fd->parameters.size() >= hidden
		 ? fd->parameters.size() - hidden : 0;
    size_t required = fd->required_param_count();
    required = required >= hidden ? required - hidden : 0;
    if ( fd->is_varargs )
    {
	if ( total > 0 )
	    --total;
	if ( total_out )
	    *total_out = total;
	return argc >= required;
    }
    if ( total_out )
	*total_out = total;
    return argc >= required && argc <= total;
}

static Variable *find_method_by_callable_arity(DataDefCLASS *cls,
					       const std::string &name,
					       size_t argc,
					       bool require_static)
{
    if ( !cls )
	return NULL;
    Variable *best = NULL;
    int best_score = -1;
    bool any_named = false;
    for ( variable_vec_iter vvi = cls->methods.begin(); vvi != cls->methods.end(); ++vvi )
    {
	Variable *mv = *vvi;
	if ( !mv )
	    continue;
	FuncDef *fd = dynamic_cast<FuncDef *>(mv->type);
	if ( !fd )
	    continue;
	const std::string &disp = fd->method_display_name.empty()
				? mv->name : fd->method_display_name;
	if ( name.compare(disp) != 0 )
	    continue;
	any_named = true;
	if ( require_static && !(mv->flags & vfSTATIC) )
	    continue;
	size_t total = 0;
	if ( !method_callable_with_arg_count(mv, argc, &total) )
	    continue;
	int score = (argc == total) ? 2 : 1;
	if ( score > best_score )
	{
	    best_score = score;
	    best = mv;
	}
    }
    if ( best )
	return best;
    if ( any_named )
	return NULL;
    for ( size_t i = 0; i < cls->bases.size(); ++i )
	if ( Variable *bv =
		find_method_by_callable_arity(cls->bases[i].base, name, argc,
					      require_static) )
	    return bv;
    if ( cls->base_class )
	return find_method_by_callable_arity(cls->base_class, name, argc,
					     require_static);
    return NULL;
}

static std::string norm_cpp_type_for_overload(const std::string &in)
{
    std::string s = in;
    while (!s.empty() && (s.back() == '&' || s.back() == ' '))
	s.pop_back();
    for (;;)
    {
	size_t i = 0;
	while ( i < s.size() && s[i] == ' ' ) ++i;
	static const char *cv[] = { "const", "volatile" };
	bool stripped = false;
	for ( const char *w : cv )
	{
	    size_t n = strlen(w);
	    if ( s.compare(i, n, w) == 0
	      && (i + n >= s.size() || s[i + n] == ' ') )
	    {
		s.erase(0, i + n);
		stripped = true;
		break;
	    }
	}
	if ( !stripped ) break;
    }
    std::string out;
    for ( char c : s )
	if ( c != ' ' )
	    out += c;
    return out;
}

static bool template_pattern_mentions_param(const std::string &pattern,
					    const std::vector<std::string> &params)
{
    for ( size_t i = 0; i < pattern.size(); )
    {
	unsigned char c = (unsigned char)pattern[i];
	if ( isalpha(c) || pattern[i] == '_' )
	{
	    size_t j = i + 1;
	    while ( j < pattern.size() )
	    {
		unsigned char d = (unsigned char)pattern[j];
		if ( !isalnum(d) && pattern[j] != '_' )
		    break;
		++j;
	    }
	    std::string ident = pattern.substr(i, j - i);
	    for ( const std::string &p : params )
		if ( p == ident )
		    return true;
	    i = j;
	    continue;
	}
	++i;
    }
    return false;
}

// [temp.func.order] tiebreak for member function templates (defined below, after
// the partial-ordering primitives it reuses).
static bool member_tmpl_more_specialized(FuncDef *A, FuncDef *B);

Variable *DataDefCLASS::findMethodOverload(const std::string &name,
					  const std::vector<const DataDef *> &argtypes,
					  int obj_cv)
{
    Variable *best = NULL;
    int best_score = -1;
    bool any_named = false;
    // Scan ALL same-name overloads (the registration pushes each type-differing
    // overload into `methods` under the same display name); rank by arg type.
    for ( variable_vec_iter vvi = methods.begin(); vvi != methods.end(); ++vvi )
    {
	Variable *mv = *vvi;
	if ( !mv )
	    continue;
	FuncDef *fd = dynamic_cast<FuncDef *>(mv->type);
	if ( !fd )
	    continue;
	// Methods are keyed by their MANGLED name (`Box__take`, `Box__take__o2`);
	// match on the unmangled display name when the FuncDef records one, else
	// fall back to the raw name.
	const std::string &disp = fd->method_display_name.empty()
				? mv->name : fd->method_display_name;
	if ( name.compare(disp) != 0 )
	    continue;
	any_named = true;
	Method *md = (Method *)mv->data;
	size_t hidden = (md && md->owner_class && !(mv->flags & vfSTATIC)) ? 1 : 0;
	size_t pn = fd->parameters.size() >= hidden
		  ? fd->parameters.size() - hidden : 0;
	bool varargs = fd->is_varargs && pn > 0;
	size_t fixed = varargs ? pn - 1 : pn;
	// Env-gated probe (MADC_OVL_PROBE=<name substring>). Placed BEFORE the
	// arity gate and before the viability `continue`s below, because a probe
	// downstream of them prints nothing for a REJECTED candidate — and that
	// silence reads as "the candidate does not exist", which is exactly the
	// wrong conclusion to draw about a selection that picked a sibling.
	{
	    static const char *_ovl = ::getenv("MADC_OVL_PROBE");
	    if ( _ovl && *_ovl && name.find(_ovl) != std::string::npos )
		fprintf(stderr, "OVLCAND %s cand=%s disp=%s ret=%s parms=%zu "
			"hidden=%zu pn=%zu varargs=%d fixed=%zu mt=%d "
			"spellings=%zu sp0=%s argc=%zu arity_ok=%d\n",
			name.c_str(), mv->name.c_str(),
			fd->method_display_name.c_str(), fd->returns.name.c_str(),
			fd->parameters.size(), hidden, pn, (int)varargs, fixed,
			(int)fd->is_member_template,
			fd->template_param_spellings.size(),
			fd->template_param_spellings.empty()
			    ? "-" : fd->template_param_spellings[0].c_str(),
			argtypes.size(),
			(int)!((!varargs && pn != argtypes.size())
			    || (varargs && argtypes.size() < fixed)));
	}
	if ( (!varargs && pn != argtypes.size())
	  || (varargs && argtypes.size() < fixed) )
	    continue;
	// [over.match.funcs]/4: a non-static member's implicit object param
	// carries the member's cv, and a CONST object argument cannot
	// initialize a non-const implicit object param ([over.match.viable]).
	// Dtors stay callable on const objects.
	if ( obj_cv == 1 && hidden && !fd->is_const_method && name[0] != '~' )
	    continue;
	int total = 0;
	bool ok = true;
	for ( size_t i = 0; i < fixed; i++ )
	{
	    int s = -1;
	    if ( fd->is_member_template
	      && fd->template_param_spellings.size() == argtypes.size() )
	    {
		const std::string &pat = fd->template_param_spellings[i];
		if ( template_pattern_mentions_param(pat,
						     fd->template_param_names) )
		    s = 1;
		else
		{
		    std::string actual = cpp_spelling_for_mangle(
			const_cast<DataDef *>(argtypes[i]), false);
		    s = (norm_cpp_type_for_overload(pat)
		      == norm_cpp_type_for_overload(actual)) ? 8 : -1;
		}
	    }
	    else
	    {
		size_t pi = i + hidden;
		DataDef *pt = pi < fd->parameters.size() ? fd->parameters[pi] : NULL;
		bool refp = fd->is_ref_param(pi);
		s = score_arg_to_param(argtypes[i], pt, refp);
	    }
	    if ( s < 0 ) { ok = false; break; }
	    total += s;
	}
	if ( ok && varargs )
	{
	    if ( fd->is_member_template
	      && fd->template_param_spellings.size() == argtypes.size() )
	    {
		for ( size_t i = fixed; i < argtypes.size(); ++i )
		{
		    const std::string &pat = fd->template_param_spellings[i];
		    if ( template_pattern_mentions_param(
			     pat, fd->template_param_names) )
		    {
			total += 1;
			continue;
		    }
		    std::string actual = cpp_spelling_for_mangle(
			const_cast<DataDef *>(argtypes[i]), false);
		    if ( norm_cpp_type_for_overload(pat)
		      != norm_cpp_type_for_overload(actual) )
		    {
			ok = false;
			break;
		    }
		    total += 8;
		}
		if ( !ok )
		    continue;
	    }
	    total += 1;
	}
	// Env-gated probe (MADC_OVL_PROBE=<name substring>): every candidate's
	// viability inputs and score, for diagnosing a selection that picks the
	// wrong overload. Prints even for rejected candidates (ok=0), which is
	// the case a score-only dump cannot explain.
	{
	    static const char *_ovl = ::getenv("MADC_OVL_PROBE");
	    if ( _ovl && *_ovl && name.find(_ovl) != std::string::npos )
		fprintf(stderr, "OVLPROBE %s cand=%s disp=%s ret=%s ok=%d "
			"total=%d parms=%zu hidden=%zu pn=%zu varargs=%d "
			"fixed=%zu mt=%d spellings=%zu sp0=%s argc=%zu\n",
			name.c_str(), mv->name.c_str(),
			fd->method_display_name.c_str(),
			fd->returns.name.c_str(), (int)ok, total,
			fd->parameters.size(), hidden, pn, (int)varargs, fixed,
			(int)fd->is_member_template,
			fd->template_param_spellings.size(),
			fd->template_param_spellings.empty()
			    ? "-" : fd->template_param_spellings[0].c_str(),
			argtypes.size());
	}
	if ( ok && total > best_score )
	{
	    best_score = total;
	    best = mv;
	}
	else if ( ok && total == best_score && best )
	{
	    FuncDef *best_fd = dynamic_cast<FuncDef *>(best->type);
	    // Score tie between const/non-const siblings: the implicit object
	    // parameter is the discriminator ([over.match.best] — a non-const
	    // object's exact cv-match beats the qualification conversion).
	    if ( obj_cv >= 0 && best_fd
	      && best_fd->is_const_method != fd->is_const_method )
	    {
		if ( fd->is_const_method == (obj_cv == 1) )
		    best = mv;
	    }
	    // Viability tie: prefer the more-specialized member template
	    // ([temp.func.order]). Without this the first-registered candidate
	    // wins arbitrarily — `take(P)` could shadow the exact `take(U*)`.
	    else if ( best_fd && best_fd->is_member_template && fd->is_member_template
	      && member_tmpl_more_specialized(fd, best_fd) )
		best = mv;
	}
    }
    if ( best )
	return best;
    // C++ name hiding: a same-name method declared in THIS class hides base
    // overloads. Only descend to the base when this class declares none.
    if ( any_named )
    {
	return NULL;
    }
    if ( base_class )
	return base_class->findMethodOverload(name, argtypes, obj_cv);
    return NULL;
}

// === type-domain identity (spec §2.1). Typedefs are already resolved to the
// underlying DataDef before this is called; const/volatile never reach DataDef.
// The DataType tag IS the representation for simple scalars (dtCHAR==dtINT8,
// long and long long are both dtINT64, bool/float/double/ldouble distinct).
bool DataDef::same_representation(DataDef &d)
{
	DataDef *a = this, *b = &d;
	// References compare as their referee (=== reads rvalues).
	while ( a->is_reference() )
		a = static_cast<DataDefPTR *>(a)->base_type;
	while ( b->is_reference() )
		b = static_cast<DataDefPTR *>(b)->base_type;
	if ( a == b )
		return true;
	// Enums are their own domain: only the same enum type matches. Identity is
	// keyed on the bare enum_name — aliasing creates multiple DataDefENUM
	// instances for one source enum, so pointer identity would be wrong;
	// cross-namespace same-name enums are a known approximation.
	DataDefENUM *ae = dynamic_cast<DataDefENUM *>(a);
	DataDefENUM *be = dynamic_cast<DataDefENUM *>(b);
	if ( ae || be )
		return ae && be && ae->enum_name == be->enum_name;
	// Function (pointer) types: identical signature.
	if ( a->is_function() || b->is_function() )
	{
		if ( !a->is_function() || !b->is_function() )
			return false;
		FuncDef *af = dynamic_cast<FuncDef *>(a);
		FuncDef *bf = dynamic_cast<FuncDef *>(b);
		if ( DataDefFPTR *afp = dynamic_cast<DataDefFPTR *>(a) )
			af = afp->target;
		if ( DataDefFPTR *bfp = dynamic_cast<DataDefFPTR *>(b) )
			bf = bfp->target;
		if ( !af || !bf )
			return af == bf;
		if ( af == bf )
			return true;
		if ( !af->return_value_type().same_representation(bf->return_value_type()) )
			return false;
		if ( af->is_varargs != bf->is_varargs )
			return false;
		if ( af->parameters.size() != bf->parameters.size() )
			return false;
		for ( size_t i = 0; i < af->parameters.size(); ++i )
		{
			// A missing (NULL) param slot matches only a missing slot,
			// and a both-NULL slot must not exempt the remaining params.
			if ( !af->parameters[i] && !bf->parameters[i] )
				continue;
			if ( !af->parameters[i] || !bf->parameters[i] )
				return false;
			if ( !af->parameters[i]->same_representation(*bf->parameters[i]) )
				return false;
		}
		return true;
	}
	// C arrays: element domain + count.
	DataDefCArray *aa = dynamic_cast<DataDefCArray *>(a);
	DataDefCArray *ba = dynamic_cast<DataDefCArray *>(b);
	if ( aa || ba )
	{
		if ( !aa || !ba || aa->count != ba->count )
			return false;
		return aa->element_type->same_representation(*ba->element_type);
	}
	// Class/struct/array-object/complex/simd types: identity — the a == b
	// fast path above; different instances are different domains.
	if ( a->basetype() != BaseType::btSimple || b->basetype() != BaseType::btSimple )
		return false;
	// Pointers: recurse on the pointee when both sides carry one. (The
	// builtin dtXXXptr tags encode a simple pointee, and DataDefPTR sets the
	// same tag, so the tag compare below also covers pointer-to-simple.)
	DataDefPTR *ap = dynamic_cast<DataDefPTR *>(a);
	DataDefPTR *bp = dynamic_cast<DataDefPTR *>(b);
	if ( ap && bp )
		return ap->base_type->same_representation(*bp->base_type);
	// Both are btSimple and NOT both DataDefPTR (a pointer pair was handled
	// above); references were already stripped at the top. Pointer-ness must
	// agree — a lone pointer differs from a scalar — then the underlying scalar
	// tags must match exactly. (Structural: the old bare-ref-tag / rtDeRef
	// fallback is dead now that ddVOIDref is a real DataDefREF, stripped above.)
	if ( a->is_pointer() != b->is_pointer() )
		return false;
	return a->type() == b->type();
}

// --- Type table (typeid) identity layer ----------------------------------
// docs/plans/2026-06-12-type-table-value-abi-design.md §2. Slot numbers are
// ABI (pinned in tests/unit/test_datadef.cpp). This switch is the single
// source of truth for slot -> global primitive; the stamping loop and
// Program::type_from_id() both derive from it. Reserved slots (P0 wide
// values: 18-22) return NULL until their DataDefs exist.
DataDef *madc_primitive_for_slot(uint32_t slot)
{
	switch ( slot )
	{
		case MADC_TYPEID_VOID:		return &ddVOID;
		case MADC_TYPEID_VOID_REF:	return &ddVOIDref;
		case MADC_TYPEID_BOOL:		return &ddBOOL;
		case MADC_TYPEID_CHAR:		return &ddCHAR;
		case MADC_TYPEID_INT:		return &ddINT;
		case MADC_TYPEID_INT8:		return &ddINT8;
		case MADC_TYPEID_INT16:		return &ddINT16;
		case MADC_TYPEID_INT24:		return &ddINT24;
		case MADC_TYPEID_INT32:		return &ddINT32;
		case MADC_TYPEID_INT64:		return &ddINT64;
		case MADC_TYPEID_UINT8:		return &ddUINT8;
		case MADC_TYPEID_UINT16:	return &ddUINT16;
		case MADC_TYPEID_UINT24:	return &ddUINT24;
		case MADC_TYPEID_UINT32:	return &ddUINT32;
		case MADC_TYPEID_UINT64:	return &ddUINT64;
		case MADC_TYPEID_FLOAT:		return &ddFLOAT;
		case MADC_TYPEID_DOUBLE:	return &ddDOUBLE;
		case MADC_TYPEID_INT128:	return &ddINT128;
		case MADC_TYPEID_UINT128:	return &ddUINT128;
		case MADC_TYPEID_MAX_ALIGN_T:	return &ddMAX_ALIGN_T;
		case MADC_TYPEID_LPSTR:		return &ddLPSTR;
		case MADC_TYPEID_VOID_PTR:	return &ddVOIDptr;
		case MADC_TYPEID_CHAR_PTR:	return &ddCHARptr;
		case MADC_TYPEID_INT_PTR:	return &ddINTptr;
		case MADC_TYPEID_INT32_PTR:	return &ddINT32ptr;
		case MADC_TYPEID_ARRAY:		return &ddARRAY;
		case MADC_TYPEID_AUTO:		return &ddAUTO;
		case MADC_TYPEID_BUILTIN_VA_LIST:
			return Program::builtin_va_list_type();
		default:			return NULL;
	}
}

void madc_stamp_primitive_type_ids()
{
	for ( uint32_t slot = 1; slot <= MADC_TYPEID_PRIMITIVE_LAST; ++slot )
	{
		DataDef *dd = madc_primitive_for_slot(slot);

		if ( dd )
			dd->type_id = slot;
	}
}

// The ONE typeid policy implementation (declared in datadef.h): the dd->type_id
// lazy-stamp memo + the primitive/system/project segment dispatch, over the
// ACTIVE project table. Statically reachable so cir_node's serializable
// datadef_id accessors resolve without a Program in hand; the Program methods
// below bind their own table and delegate (last binder wins — the
// _active_strpool discipline).
madc::dis::id_table<DataDef> *madc_active_project_types = NULL;

uint32_t madc_type_id_for(DataDef *dd)
{
	if ( !dd )
		return MADC_TYPEID_INVALID;
	if ( dd->type_id )
		return dd->type_id;		// memo: already has an id (any segment)
	if ( !madc_active_project_types )
	{
		// Internal invariant: stamping a project type requires a bound
		// table (production binds at _parser_init; unit tests bind a
		// local id_table). Silently returning 0 would drop type info.
		fprintf(stderr, "madc internal: madc_type_id_for('%s') with no "
			"active project type table\n", dd->name.c_str());
		abort();
	}
	dd->type_id = madc_active_project_types->add(dd);	// project segment owns the storage
	return dd->type_id;
}

DataDef *madc_type_from_id(uint32_t id)
{
	if ( id == MADC_TYPEID_INVALID )
		return NULL;
	if ( id < MADC_TYPEID_PRIMITIVE_END )
		return madc_primitive_for_slot(id);
	if ( id >= MADC_TYPEID_PROJECT_BASE )
		return madc_active_project_types
			? madc_active_project_types->get(id)	// NULL for a foreign / unregistered id
			: NULL;
	return NULL;	// system segment: reserved for the embedded forest
}

uint32_t Program::type_id_for(DataDef *dd)
{
	madc_active_project_types = &project_types;	// this Program is acting
	return madc_type_id_for(dd);
}

DataDef *Program::type_from_id(uint32_t id)
{
	madc_active_project_types = &project_types;	// this Program is acting
	return madc_type_from_id(id);
}

DataDef *DataDefCLASS::binary_operator_return_type(const std::string &opname)
{
    // Prefer a binary (params > 1 incl. __this) overload. Search the source
    // operator name first, then the mangled ClassName__operatorX family, then
    // the base chain.
    FuncDef *any = NULL;
    for ( variable_vec_iter vvi = methods.begin(); vvi != methods.end(); ++vvi )
    {
	Variable *mv = *vvi;
	if ( !mv || opname.compare(mv->name) != 0 ) continue;
	FuncDef *fd = dynamic_cast<FuncDef *>(mv->type);
	if ( !fd ) continue;
	if ( !any ) any = fd;
	if ( fd->parameters.size() > 1 ) return &fd->return_value_type();
    }
    std::string mangled = name + "__" + opname;
    std::string mangled_overload_prefix = mangled + "__o";
    for ( variable_vec_iter vvi = methods.begin(); vvi != methods.end(); ++vvi )
    {
	Variable *mv = *vvi;
	if ( !mv || (mangled.compare(mv->name) != 0
	  && mv->name.compare(0, mangled_overload_prefix.size(),
			      mangled_overload_prefix) != 0) ) continue;
	FuncDef *fd = dynamic_cast<FuncDef *>(mv->type);
	if ( !fd ) continue;
	if ( !any ) any = fd;
	if ( fd->parameters.size() > 1 ) return &fd->return_value_type();
    }
    if ( any ) return &any->return_value_type();
    // Multiple/virtual inheritance: the operator may be inherited from ANY direct
    // base, not only the primary. basic_iostream inherits operator<< from its
    // SECOND base (basic_ostream); the first (basic_istream) has none — so a
    // chained `stringstream << x` lost its basic_ostream result type while the
    // single-base ostringstream worked. `bases` lists every direct base (the
    // primary included), so this subsumes the legacy single-`base_class` walk.
    for ( const BaseSpec &b : bases )
	if ( b.base )
	    if ( DataDef *rt = b.base->binary_operator_return_type(opname) )
		return rt;
    // Legacy single-base path: a class that set base_class without populating
    // bases (then base_class is the sole parent).
    if ( bases.empty() && base_class )
	return base_class->binary_operator_return_type(opname);
    return NULL;
}

bool DataDefCLASS::binary_operator_only_takes_nonclass(const std::string &opname)
{
    bool any = false;
    // The explicit parameter (index 1, after the hidden __this) of a binary
    // member operator. A reference param is stored as DataDefPTR(referee) — unwrap
    // it so `const T&` is judged a class param, not a pointer.
    auto param_is_class = [](FuncDef *fd) -> bool {
	if ( fd->parameters.size() <= 1 ) return false;
	DataDef *p1 = fd->parameters[1];
	bool refp = fd->is_ref_param(1);
	if ( refp && p1 && p1->is_pointer() )
	    p1 = static_cast<DataDefPTR *>(p1)->base_type;
	return p1 && p1->is_object();
    };
    for ( variable_vec_iter vvi = methods.begin(); vvi != methods.end(); ++vvi )
    {
	Variable *mv = *vvi;
	if ( !mv || opname.compare(mv->name) != 0 ) continue;
	FuncDef *fd = dynamic_cast<FuncDef *>(mv->type);
	if ( !fd || fd->parameters.size() <= 1 ) continue;
	any = true;
	if ( param_is_class(fd) ) return false;
    }
    std::string mangled = name + "__" + opname;
    std::string mangled_overload_prefix = mangled + "__o";
    for ( variable_vec_iter vvi = methods.begin(); vvi != methods.end(); ++vvi )
    {
	Variable *mv = *vvi;
	if ( !mv || (mangled.compare(mv->name) != 0
	  && mv->name.compare(0, mangled_overload_prefix.size(),
			      mangled_overload_prefix) != 0) ) continue;
	FuncDef *fd = dynamic_cast<FuncDef *>(mv->type);
	if ( !fd || fd->parameters.size() <= 1 ) continue;
	any = true;
	if ( param_is_class(fd) ) return false;
    }
    if ( any ) return true;
    if ( base_class ) return base_class->binary_operator_only_takes_nonclass(opname);
    return false;
}

DataDef *DataDefCLASS::unary_operator_return_type(const std::string &opname,
						  bool postfix)
{
    FuncDef *fallback = NULL;
    std::string mangled = name + "__" + opname;
    std::string mangled_un = mangled + "_un";
    std::string mangled_overload_prefix = mangled + "__o";
    for ( variable_vec_iter vvi = methods.begin(); vvi != methods.end(); ++vvi )
    {
	Variable *mv = *vvi;
	if ( !mv ) continue;
	FuncDef *fd = dynamic_cast<FuncDef *>(mv->type);
	if ( !fd ) continue;
	const std::string &disp = fd->method_display_name.empty()
				? mv->name : fd->method_display_name;
	if ( opname.compare(disp) != 0
	  && mangled.compare(mv->name) != 0
	  && mangled_un.compare(mv->name) != 0
	  && mv->name.compare(0, mangled_overload_prefix.size(),
			      mangled_overload_prefix) != 0 )
	    continue;
	bool parameterized = fd->parameters.size() > 1;
	if ( postfix == parameterized )
	    return &fd->return_value_type();
	if ( !fallback )
	    fallback = fd;
    }
    if ( fallback )
	return &fallback->return_value_type();
    if ( base_class )
	return base_class->unary_operator_return_type(opname, postfix);
    return NULL;
}

// The operator SYMBOL the object-operator machinery types/lowers for a token,
// NULL when the token is not in that family (comparison/bitwise results are
// already typed correctly). Shared by resolve_object_operator_type and
// lower_free_operator_to_call so the two stay one family.
static const char *object_operator_symbol(TokenID id)
{
    switch ( id )
    {
	case TokenID::tkAdd: return "+";
	case TokenID::tkSub: return "-";
	case TokenID::tkNeg: return "-";
	case TokenID::tkMul: return "*";
	case TokenID::tkDiv: return "/";
	case TokenID::tkMod: return "%";
	case TokenID::tkLnot: return "!";
	case TokenID::tkBnot: return "~";
	case TokenID::tkInc: return "++";
	case TokenID::tkDec: return "--";
	case TokenID::tkBSL: return "<<";
	case TokenID::tkBSR: return ">>";
	case TokenID::tkEquals: return "==";
	case TokenID::tkNotEq: return "!=";
	case TokenID::tkLT: return "<";
	case TokenID::tkGT: return ">";
	case TokenID::tkLE: return "<=";
	case TokenID::tkGE: return ">=";
	case TokenID::tk3Way: return "<=>";
	case TokenID::tk3Eq: return "===";
	case TokenID::tk3NotEq: return "!==";
	default: return NULL;
    }
}


// The class-object DataDef an operand expression DENOTES for operator /
// overload resolution. A reference operand IS the referenced object in every
// expression context (C++ semantics); madc stores both a reference-typed
// expression (DataDefREF) and a reference variable (`const A &p`, vfREFERENCE
// + DataDefPTR(A)) as pointers, so resolution must unwrap them. A plain `A*`
// pointer operand stays NULL — pointer operands keep pointer semantics.
DataDefCLASS *Program::operand_object_class(TokenBase *operand)
{
    if ( !operand )
	return NULL;
    DataDef *dd = operand->datadef();
    if ( DataDefCLASS *c = dynamic_cast<DataDefCLASS *>(dd) )
	return c;
    if ( dd && dd->is_reference() )
	if ( DataDefPTR *rp = dynamic_cast<DataDefPTR *>(dd) )
	    return dynamic_cast<DataDefCLASS *>(rp->base_type);
    TokenVar *tv = dynamic_cast<TokenVar *>(operand);
    if ( tv && (tv->var.is_reference()) )
	if ( DataDefPTR *rp = dynamic_cast<DataDefPTR *>(tv->var.type) )
	    return dynamic_cast<DataDefCLASS *>(rp->base_type);
    return NULL;
}

// The std comparison-category class a builtin `<=>` yields ([expr.spaceship]):
// std::partial_ordering when either operand is floating, else
// std::strong_ordering. These are the STANDARD names of the standard types
// the operator produces — language semantics (like nullptr -> (void*)0), not
// a user-name special case. NULL when <compare> has not been parsed; the
// expression then stays untyped and the CIR lowering rejects loudly.
DataDef *Program::comparison_category_class(TokenOperator *to)
{
    if ( !to ) return NULL;
    bool floating =
	(to->left && to->left->datadef() && to->left->datadef()->is_real())
     || (to->right && to->right->datadef() && to->right->datadef()->is_real());
    namespace_datatype_map_t::iterator ni = namespace_datatype_map.find("std");
    if ( ni == namespace_datatype_map.end() )
	return NULL;
    datatype_map_iter di = ni->find(floating ? "partial_ordering"
						     : "strong_ordering");
    if ( di == ni->end() || !di->second )
	return NULL;
    return &di->second->definition;
}

// Type an operator expression whose left operand is a class object that declares
// the matching operator, using that operator's return type. Without this,
// object operators report the default arithmetic datadef, so copy-init ctor
// selection, chained operator expressions, and `auto` all mis-resolve.
// Array-to-pointer decay ([conv.array]) for an operator operand: a fixed-array
// variable / array member / array-typed expression denotes `element *` in a
// value context. Mirrors the trichotomy in CirBuilder::ctor_arg_datadef.
// TokenMember derives from TokenVar, so it is checked first. Returns NULL when
// the operand is not an array.
DataDef *Program::array_decay_pointer(TokenBase *operand)
{
    if ( !operand ) return NULL;
    if ( TokenMember *tm = dynamic_cast<TokenMember *>(operand) )
    {
	if ( tm->is_fixed_array_member() && tm->var.type )
	    return getPointerType(tm->var.type);
    }
    else if ( TokenVar *tv = dynamic_cast<TokenVar *>(operand) )
    {
	if ( tv->var.is_fixed_array() && tv->var.type )
	    return getPointerType(tv->var.type);
    }
    if ( DataDefCArray *ca = dynamic_cast<DataDefCArray *>(operand->datadef()) )
	if ( ca->element_type )
	    return getPointerType(ca->element_type);
    return NULL;
}

void Program::resolve_object_operator_type(TokenOperator *to)
{
    if ( !to ) return;
    // Builtin `a <=> b` (no class operand): the result IS a comparison-
    // category object ([expr.spaceship]); class-operand <=> resolves through
    // the operator machinery below / the free-operator dispatch like any
    // other operator.
    if ( to->id() == TokenID::tk3Way
      && !operand_object_class(to->left) && !operand_object_class(to->right) )
    {
	if ( DataDef *cat = comparison_category_class(to) )
	    to->set_resolved_type(cat);
	return;
    }
    bool unary = to->argc() == 1;
    bool postfix = unary && to->left != NULL;
    TokenBase *operand = unary ? (postfix ? to->left : to->right) : to->left;
    if ( !operand ) return;
    DataDefCLASS *lc = operand_object_class(operand);
    if ( !lc && unary )
	return;
    // Array-to-pointer decay in additive pointer arithmetic ([conv.array]):
    // `arr + n` / `arr - n` / `n + arr` self-type as `element *`. datadef()'s
    // lazy is_pointer() branch only recognizes real pointers, not arrays, so a
    // self-determined context (ctor-arg / overload-arg typing, with no pointer
    // target to coerce to) wrongly saw `int`. Only when neither operand is a
    // class object.
    if ( !lc && !operand_object_class(to->right)
      && (to->id() == TokenID::tkAdd || to->id() == TokenID::tkSub)
      && to->left && to->right )
    {
	DataDef *ld = to->left->datadef();
	DataDef *rd = to->right->datadef();
	if ( rd && rd->is_numeric() && !rd->is_pointer() )
	    if ( DataDef *dp = array_decay_pointer(to->left) )
	    { to->set_resolved_type(dp); return; }
	if ( to->id() == TokenID::tkAdd
	  && ld && ld->is_numeric() && !ld->is_pointer() )
	    if ( DataDef *dp = array_decay_pointer(to->right) )
	    { to->set_resolved_type(dp); return; }
    }
    if ( !lc && (!to->right || !operand_object_class(to->right)) )
	return;	// neither side is a class object
    const char *opsym = object_operator_symbol(to->id());
    if ( !opsym )
	return;
    std::string opname = std::string("operator") + opsym;
    DataDef *rt = NULL;
    if ( lc )
    {
	rt = unary ? lc->unary_operator_return_type(opname, postfix)
		   : lc->binary_operator_return_type(opname);
	if ( !rt && !unary )
	    rt = free_binary_operator_return_class(lc, opname, to->right);
    }
    else
	// Non-class lhs with a class rhs: let retained free-operator templates
	// decide whether a mixed operand shape applies.
	rt = free_binary_operator_return_class_nonclass_lhs(to->left, opname,
							    to->right);
    if ( rt ) to->set_resolved_type(rt);
}

// Cfront lowering for a retained free-operator template: `a @ b` becomes a
// CALL to the instantiated free operator definition when no exported symbol
// covers that operand shape.
// Fires ONLY when no member operator and no exported free shape covers the
// operand pair; those keep their existing typing + CIR lowerings untouched.
TokenBase *Program::lower_free_operator_to_call(TokenOperator *to,
						bool no_rewrite)
{
    if ( !to || to->argc() != 2 || !to->left || !to->right )
	return NULL;
    const char *opsym = object_operator_symbol(to->id());
    if ( !opsym )
	return NULL;
    DataDefCLASS *lc = operand_object_class(to->left);
    DataDefCLASS *rc = operand_object_class(to->right);
    if ( !lc && !rc )
	return NULL;
    std::string opname = std::string("operator") + opsym;
    // Env-gated probe (MADC_FREEOP_PROBE=<opname substring>): which arm of this
    // lowering claimed the expression. A bail here hands the pair back to the
    // member operator, and when every same-name member takes a scalar that
    // surfaces far away as c2mir's "incompatible argument type for arithmetic
    // type parameter" — with nothing naming the operator that lost.
    {
	static const char *_fop = ::getenv("MADC_FREEOP_PROBE");
	if ( _fop && *_fop && opname.find(_fop) != std::string::npos )
	    fprintf(stderr, "FREEOP enter %s lc=%s rc=%s member_ret=%d"
		    " ovset=%zu\n", opname.c_str(),
		    lc ? lc->name.c_str() : "-", rc ? rc->name.c_str() : "-",
		    (int)(lc && lc->binary_operator_return_type(opname) != NULL),
		    free_operator_overloads.size());
    }
    if ( lc && lc->binary_operator_return_type(opname) )
    {
	// A named member operator normally owns the expression. The ONE exception:
	// the rhs is a class object but every same-name binary member takes a
	// non-class (arithmetic/pointer) parameter — the iterator signature
	// (`operator-(difference_type)` only), where `iter - iter` must instead bind
	// the free cross-type `operator-(const It&, const It&)` retained-template
	// body. Even then we ONLY divert if such a template actually binds; otherwise
	// the member / cir-builder W2 path owns it and we bail exactly as before (so
	// `ostream << string`, whose member operator<< takes scalars but whose free
	// operator<< is an exported reference-returning W2 symbol, is untouched).
	DataDefCLASS *rcls = operand_object_class(to->right);
	if ( !(rcls && lc->binary_operator_only_takes_nonclass(opname)) )
	    return NULL;
	// Only a VALUE/scalar-returning free operator is body-instantiated here.
	// A reference-returning free overload (`std::operator<<(ostream&, ...)` →
	// `ostream&`) is the exported W2 mangled-direct shape bound by the cir
	// builder; diverting `ostream << string` to a body instantiation breaks it.
	for ( const FreeOperatorOverload &ov : free_operator_overloads )
	    if ( ov.opname == opname && !ov.return_spelling.empty()
	      && ov.return_spelling.back() == '&' )
	    {
		static const char *_fop = ::getenv("MADC_FREEOP_PROBE");
		if ( _fop && *_fop && opname.find(_fop) != std::string::npos )
		    fprintf(stderr, "FREEOP bail-refret %s ov.ret=%s\n",
			    opname.c_str(), ov.return_spelling.c_str());
		return NULL;
	    }
	Variable *nv_callee = NULL;
	if ( instantiate_free_operator_template(opname, to->left, to->right,
						&nv_callee) && nv_callee )
	{
	    TokenCallFunc *tc = new TokenCallFunc(*nv_callee);
	    tc->file = to->file;
	    tc->line = to->line;
	    tc->column = to->column;
	    tc->parameters.push_back(to->left);
	    tc->parameters.push_back(to->right);
	    return tc;
	}
	return NULL;	// no free template bound — member / W2 path owns it
    }
    if ( lc && free_binary_operator_return_class(lc, opname, to->right) )
	return NULL;	// exported free shape: mangled-direct (W2) owns it
    if ( !lc && free_binary_operator_return_class_nonclass_lhs(to->left, opname,
							       to->right) )
	return NULL;	// exported literal-lhs mixed shape: same
#ifdef MADC_DBG_QCALL
    fprintf(stderr, "[FREEOP] try %s lc=%s rc=%s\n", opname.c_str(),
	    lc ? lc->name.c_str() : "-", rc ? rc->name.c_str() : "-");
#endif
    // A parsed CONCRETE free operator covering the operand pair (a hoisted
    // hidden friend, a user-written free operator function, or a prior
    // instantiation) is preferred over instantiating a retained template
    // ([over.match.best]: a non-template beats a template specialization).
    {
	std::vector<const DataDef *> at;
	at.push_back(free_operator_arg_datadef(to->left));
	at.push_back(free_operator_arg_datadef(to->right));
	std::vector<bool> zl;
	zl.push_back(is_zero_integer_literal(to->left));
	zl.push_back(is_zero_integer_literal(to->right));
	if ( Variable *win = find_free_operator_function(opname, at, &zl) )
	{
	    TokenCallFunc *tc = new TokenCallFunc(*win);
	    tc->file = to->file;
	    tc->line = to->line;
	    tc->column = to->column;
	    tc->parameters.push_back(to->left);
	    tc->parameters.push_back(to->right);
	    return tc;
	}
    }
    Variable *callee = NULL;
    if ( !instantiate_free_operator_template(opname, to->left, to->right,
					     &callee) || !callee )
	return no_rewrite ? NULL : rewritten_operator_candidate(to);
    TokenCallFunc *tc = new TokenCallFunc(*callee);
    tc->file = to->file;
    tc->line = to->line;
    tc->column = to->column;
    tc->parameters.push_back(to->left);
    tc->parameters.push_back(to->right);
    return tc;
}

// madc strict-equality DOMAIN RULE (spec §2.2): with no user operator===,
// `x === y` strict-compares THROUGH the operand's operator== (a literal enters
// the operand's domain). Reuses the ONE free-operator lowering normal `==`
// uses, so a class whose `operator==` is a free template binds here just as
// `a == b` does. Returns the lowered `x == y` call, or NULL when no
// operator== covers the pair — the caller then keeps the strict-equality token
// for strict_equality_lowering's member-== dispatch or different-domain
// constant. (A class whose == is a MEMBER returns NULL here and is dispatched
// in the CIR builder; only a free/value-returning == is lowered to a call.)
TokenBase *Program::lower_strict_equality_domain_rule(TokenOperator *to)
{
    if ( !to || !to->left || !to->right )
	return NULL;
    TokenEquals *eq = new TokenEquals();
    eq->left = to->left;
    eq->right = to->right;
    eq->file = to->file; eq->line = to->line; eq->column = to->column;
    return lower_free_operator_to_call(eq, /*no_rewrite=*/false);
}

// C++20 REWRITTEN candidates ([over.match.oper]) — consulted only after every
// direct candidate set missed (member/W2 early-outs, parsed free operators,
// retained templates; lower_free_operator_to_call's tail):
//   x != y  ->  !(x == y)      (the == may itself bind reversed)
//   x == y  ->  y == x         (the reversed candidate; == is symmetric)
//   x @ y   ->  (x <=> y) @ 0  (@ in < > <= >=) when an operator<=> covers
//                              the operand pair
//   x === y ->  x == y         (madc domain rule §2.2, no user operator===)
//   x !== y ->  !(x === y), or !(x == y) by the domain rule (§2.4/2.5)
// Synthesized lowerings pass no_rewrite=true wherever re-entry must not
// rewrite again, so the recursion terminates (!= -> == -> reversed == is the
// longest chain). Reached only with a class operand (the caller's lc/rc
// guard), so builtin operators are untouched.
TokenBase *Program::rewritten_operator_candidate(TokenOperator *to)
{
    TokenID idd = (TokenID)to->id();
    if ( idd == TokenID::tkNotEq )
    {
	TokenEquals *eq = new TokenEquals();
	eq->left = to->left;
	eq->right = to->right;
	eq->file = to->file; eq->line = to->line; eq->column = to->column;
	TokenBase *eqexpr = lower_free_operator_to_call(eq);
	if ( !eqexpr )
	{
	    // A MEMBER operator== still serves the rewrite (the CIR
	    // builder's class_operator_call lowers the == token); anything
	    // else keeps the original loud != failure.
	    DataDefCLASS *lc = operand_object_class(to->left);
	    if ( !lc || !lc->binary_operator_return_type("operator==") )
		return NULL;
	    resolve_object_operator_type(eq);
	    eqexpr = eq;
	}
	TokenLnot *neg = new TokenLnot();
	neg->right = eqexpr;
	neg->file = to->file; neg->line = to->line; neg->column = to->column;
	return neg;
    }
    if ( idd == TokenID::tk3NotEq )
    {
	// Strict inequality: `x !== y` is `!(x === y)` — the === may itself
	// dispatch a user operator=== (free or member). It NEVER rewrites to
	// operator!= or operator== (spec §2.4); with no === candidate the
	// token stays for the CIR domain-rule lowering.
	Token3Eq *eq3 = new Token3Eq();
	eq3->left = to->left;
	eq3->right = to->right;
	eq3->file = to->file; eq3->line = to->line; eq3->column = to->column;
	TokenBase *eqexpr = lower_free_operator_to_call(eq3, /*no_rewrite=*/true);
	if ( !eqexpr )
	{
	    DataDefCLASS *lc = operand_object_class(to->left);
	    if ( lc && lc->binary_operator_return_type("operator===") )
	    {
		// A MEMBER operator=== still serves the negation (the CIR
		// builder's class_operator_call lowers the === token).
		resolve_object_operator_type(eq3);
		eqexpr = eq3;
	    }
	    else
	    {
		// Domain rule (spec §2.4/2.5): no user operator===/!== — `x !== y`
		// is `!(x == y)` through the operand's operator==. No == candidate
		// keeps the original token for strict_equality_lowering (member-==
		// dispatch or the different-domain constant).
		eqexpr = lower_strict_equality_domain_rule(to);
		if ( !eqexpr )
		    return NULL;
	    }
	}
	TokenLnot *neg = new TokenLnot();
	neg->right = eqexpr;
	neg->file = to->file; neg->line = to->line; neg->column = to->column;
	return neg;
    }
    if ( idd == TokenID::tk3Eq )
    {
	// Strict equality domain rule (spec §2.2): no user operator=== bound
	// above — strict-compare through operator==. NULL keeps the token for
	// strict_equality_lowering (member-== dispatch / different-domain
	// constant).
	return lower_strict_equality_domain_rule(to);
    }
    if ( idd == TokenID::tkEquals )
    {
	TokenEquals *rev = new TokenEquals();
	rev->left = to->right;
	rev->right = to->left;
	rev->file = to->file; rev->line = to->line; rev->column = to->column;
	return lower_free_operator_to_call(rev, /*no_rewrite=*/true);
    }
    if ( idd == TokenID::tkLT || idd == TokenID::tkGT
      || idd == TokenID::tkLE || idd == TokenID::tkGE )
    {
	Token3Way *t3 = new Token3Way();
	t3->left = to->left;
	t3->right = to->right;
	t3->file = to->file; t3->line = to->line; t3->column = to->column;
	TokenBase *t3expr = lower_free_operator_to_call(t3, /*no_rewrite=*/true);
	if ( !t3expr )
	{
	    // A MEMBER operator<=> serves too (CIR lowers the token); else
	    // there is no three-way candidate — keep the original failure.
	    DataDefCLASS *lc = operand_object_class(to->left);
	    if ( !lc || !lc->binary_operator_return_type("operator<=>") )
		return NULL;
	    resolve_object_operator_type(t3);
	    t3expr = t3;
	}
	TokenOperator *cmp;
	switch ( idd )
	{
	    case TokenID::tkLT: cmp = new TokenLT(); break;
	    case TokenID::tkGT: cmp = new TokenGT(); break;
	    case TokenID::tkLE: cmp = new TokenLE(); break;
	    default:            cmp = new TokenGE(); break;
	}
	cmp->left = t3expr;
	cmp->right = new TokenInt(0);
	cmp->file = to->file; cmp->line = to->line; cmp->column = to->column;
	// The comparison-category friends (operator@(ordering, __unspec))
	// bind this; NULL would leave a half-rewritten tree, so fall back to
	// the raw token only if it carries a class operand CIR can dispatch.
	if ( TokenBase *low = lower_free_operator_to_call(cmp, true) )
	    return low;
	resolve_object_operator_type(cmp);
	return cmp;
    }
    return NULL;
}

// The unqualified template-head component of a C++ type spelling:
// "const ns::Type<Trait,Alloc>&" -> "Type".
// Leading cv-qualifiers, the template-argument list, trailing &/*, and scope
// qualifiers are stripped. Empty when the spelling has no identifier head.
static std::string template_head_component(const std::string &spelling)
{
    size_t h = 0;
    for ( ;; )
    {
	while ( h < spelling.size() && spelling[h] == ' ' ) ++h;
	if ( spelling.compare(h, 6, "const ") == 0 ) { h += 6; continue; }
	if ( spelling.compare(h, 9, "volatile ") == 0 ) { h += 9; continue; }
	break;
    }
    size_t end = spelling.find('<', h);
    if ( end == std::string::npos )
    {
	end = spelling.find_first_of("&*", h);
	if ( end == std::string::npos ) end = spelling.size();
    }
    std::string head = spelling.substr(h, end - h);
    while ( !head.empty() && head.back() == ' ' ) head.pop_back();
    size_t sc = head.rfind("::");
    return sc == std::string::npos ? head : head.substr(sc + 2);
}

DataDef *Program::free_binary_operator_return_class(DataDefCLASS *lc,
	const std::string &opname, TokenBase *right)
{
    if ( !lc || !right || free_operator_overloads.empty() )
	return NULL;
    DataDefCLASS *rc = operand_object_class(right);
    if ( !rc )
	return NULL;     // the exported by-value set is class-by-const-ref both sides
    std::string lhead = template_head_component(lc->canonical_cpp_spelling().empty()
						? lc->name : lc->canonical_cpp_spelling());
    std::string rhead = template_head_component(rc->canonical_cpp_spelling().empty()
						? rc->name : rc->canonical_cpp_spelling());
    if ( lhead.empty() || rhead.empty() )
	return NULL;
    for ( const FreeOperatorOverload &ov : free_operator_overloads )
    {
	if ( ov.opname != opname || ov.param_spellings.size() != 2 )
	    continue;
	const std::string &rspell = ov.return_spelling;
	// By-value class returns only; reference-returning free operators
	// (streams) keep their lowering-time typing.
	if ( rspell.empty() || rspell.back() == '&' || rspell.back() == '*' )
	    continue;
	// A dependent/nested member return (`__normal_iterator<...>::difference_type`)
	// or a deduced return (`auto`/`decltype(...)`) does NOT name an operand class
	// by value — it is a scalar/member type handled by retained-template body
	// instantiation, not the mangled-direct exported shape.
	if ( rspell.find(">::") != std::string::npos
	  || rspell == "auto" || rspell.compare(0, 9, "decltype(") == 0 )
	    continue;
	// Both params lvalue refs (&& overloads never bind mangled-direct).
	const std::string &p0 = ov.param_spellings[0];
	const std::string &p1 = ov.param_spellings[1];
	if ( p0.size() < 2 || p0.back() != '&' || p0[p0.size() - 2] == '&' )
	    continue;
	if ( p1.size() < 2 || p1.back() != '&' || p1[p1.size() - 2] == '&' )
	    continue;
	if ( template_head_component(p0) != lhead
	  || template_head_component(p1) != rhead )
	    continue;
	std::string rethead = template_head_component(rspell);
	if ( rethead == lhead ) return lc;
	if ( rethead == rhead ) return rc;
    }
    return NULL;
}

// Literal-lhs variant: `"pre" + s` — the free set's mixed shape
// (param[0] a non-class pointer/value like `const _CharT*`, param[1] the
// class by const-ref). Returns the operator's by-value return class.
DataDef *Program::free_binary_operator_return_class_nonclass_lhs(
	TokenBase *left, const std::string &opname, TokenBase *right)
{
    if ( !left || !right || free_operator_overloads.empty() )
	return NULL;
    DataDefCLASS *rc = operand_object_class(right);
    DataDef *ld = left->datadef();
    if ( !rc || !ld || operand_object_class(left) )
	return NULL;	// class-lhs rides the main path
    std::string rhead = template_head_component(rc->canonical_cpp_spelling().empty()
						? rc->name : rc->canonical_cpp_spelling());
    if ( rhead.empty() )
	return NULL;
    for ( const FreeOperatorOverload &ov : free_operator_overloads )
    {
	if ( ov.opname != opname || ov.param_spellings.size() != 2 )
	    continue;
	const std::string &rspell = ov.return_spelling;
	if ( rspell.empty() || rspell.back() == '&' || rspell.back() == '*' )
	    continue;	// by-value class returns only
	const std::string &p0 = ov.param_spellings[0];
	const std::string &p1 = ov.param_spellings[1];
	// param[1]: the class, by lvalue reference.
	if ( p1.size() < 2 || p1.back() != '&' || p1[p1.size() - 2] == '&' )
	    continue;
	if ( template_head_component(p1) != rhead )
	    continue;
	// param[0]: NOT an lvalue reference — a pointer shape matches a
	// pointer lhs, a value shape a non-pointer lhs.
	if ( p0.empty() || p0.back() == '&' )
	    continue;
	bool p0_ptr = p0.back() == '*';
	if ( p0_ptr != ld->is_pointer() )
	    continue;
	if ( template_head_component(rspell) == rhead )
	    return rc;
    }
    return NULL;
}

// Normalized text of one token for the namespace-overload identity key —
// identifiers/keywords/datatypes by name, multi-char operators by their string,
// single-char tokens verbatim, anything else by TokenID. Only stability and
// distinctness matter (the key tells overloads apart); it is never emitted.
static std::string overload_token_spelling(TokenBase *t)
{
    if ( !t )
	return "?";
    switch ( t->type() )
    {
	case TokenType::ttIdentifier:
	case TokenType::ttKeyword:
	case TokenType::ttDataType:
	    return ((TokenIdent *)t)->spelling();
	case TokenType::ttMultiOp:
	    return ((TokenMultiOp *)t)->str;
	default:
	    break;
    }
    int64_t c = t->get();
    if ( c > ' ' && c < 127 )
	return std::string(1, (char)c);
    char buf[24];
    snprintf(buf, sizeof(buf), "#%d", (int)t->id());
    return buf;
}

std::string Program::peek_param_list_spelling()
{
    // The parser sits just after the declarator's '('. Walk the balanced
    // parameter-list tokens, then REWIND the cursor (savepos/restore) so the
    // upcoming parseFunction sees the stream untouched. v25: this used to
    // consume-then-pushToken the whole list, which left the param parse
    // draining the pushback LIFO — silently disabling the then-buffer-only
    // forest default-arg cursor tap, so NO C++ namespace free function ever
    // serialized its defaults (stod's `size_t* __idx = 0` — the arity gate
    // then rejected a 1-arg bound call). v26 widened the tap over pushback
    // consumption too, but the rewind stays: it is the honest stream shape.
    TokenStream::Pos peek_saved = tokens.savepos();
    int depth = 1;
    std::string spelling;
    while ( depth > 0 )
    {
	TokenBase *t = nextToken();
	if ( !t )
	    break;
	if ( t->id() == TokenID::tkOpBrk )
	    depth++;
	else if ( t->id() == TokenID::tkClBrk && --depth == 0 )
	    break;
	if ( !spelling.empty() )
	    spelling += ' ';
	// Overload IDENTITY must be by RESOLVED type, not surface text. A
	// parameter named through a class-scope typedef (`_Self`, a nested
	// `iterator`, ...) spells identically across DIFFERENT classes — e.g.
	// `_Rb_tree_iterator`'s and `_Rb_tree_const_iterator`'s hidden-friend
	// `operator!=(const _Self&, const _Self&)` both read `_Self`. Comparing
	// raw spellings then merges the two as one overload (the second reuses
	// the first's symbol), so the const-iterator's `!=` is lost and
	// `s.find(x) != s.end()` falls back to a raw struct `!=`. Canonicalize a
	// current-class-scope alias to its resolved type's unique name so the two
	// stay DISTINCT overloads. Only inside a class scope (friend/member parse);
	// the plain namespace-function path is untouched.
	std::string tok_sp;
	if ( !class_scope_stack.empty()
	  && (t->type() == TokenType::ttIdentifier
	   || t->type() == TokenType::ttDataType) )
	    if ( DataDef *al = resolve_current_class_type_alias(((TokenIdent *)t)->spelling()) )
		tok_sp = al->name;
	spelling += tok_sp.empty() ? overload_token_spelling(t) : tok_sp;
    }
    tokens.restore(peek_saved);
    return spelling;
}

// Rank parsed function-overload candidates against a call's argument types via
// the shared generic score_arg_to_param ranking (the ONE ranking ctor /
// member-operator / namespace-call selection all use). Returns the winning
// Variable, or NULL when no candidate is viable. `zero_args` (optional,
// index-aligned with argtypes) marks arguments that are integer literals of
// value zero — C++ null-pointer constants ([conv.ptr]).
static Variable *rank_fn_overload_candidates(
	const std::vector<Program::NamespaceFnOverload> &cands,
	const std::vector<const DataDef *> &argtypes,
	const std::vector<bool> *zero_args = NULL,
	const std::vector<DataDef *> *explicit_template_args = NULL)
{
    Variable *best = NULL;
    int best_score = -1;
    for ( const Program::NamespaceFnOverload &e : cands )
    {
	FuncDef *fd = e.var ? dynamic_cast<FuncDef *>(e.var->type) : NULL;
	// The body-less template placeholder is seeded ONLY so the set has
	// >= 2 entries and triggers ranking; it is never a real callable. Its
	// 0-param signature is normally arity-filtered out, but a ZERO-ARGUMENT
	// call (`__check_constructible<V,T>()`, explicit template args only) ties
	// its score and — registered first — would win over the real
	// instantiation, emitting an undefined `__ns_<fn>` import. Skip it.
	if ( e.param_spelling == "\x01fn-template-placeholder" )
	    continue;
	if ( explicit_template_args && !explicit_template_args->empty() )
	{
	    if ( e.template_arg_names.size() < explicit_template_args->size() )
		continue;
	    bool explicit_match = true;
	    for ( size_t ti = 0; ti < explicit_template_args->size(); ++ti )
	    {
		DataDef *td = (*explicit_template_args)[ti];
		std::string tn = td ? td->name : std::string();
		if ( e.template_arg_names[ti] != tn )
		{ explicit_match = false; break; }
	    }
	    if ( !explicit_match )
		continue;
	}
	if ( !fd )
	    continue;
	size_t pn = fd->parameters.size();
	// Default arguments make the function callable with
	// [required..total] args (FuncDef::required_param_count).
	if ( argtypes.size() < fd->required_param_count()
	  || argtypes.size() > pn )
	{
#if MADC_DEBUG_FNTPL
	    std::cerr << "FNTPL rank cand=" << e.var->name
		      << " ARITY-SKIP pn=" << pn
		      << " req=" << fd->required_param_count()
		      << " argc=" << argtypes.size() << std::endl;
#endif
	    continue;
	}
	int total = 0;
	bool ok = true;
	for ( size_t i = 0; i < argtypes.size(); i++ )
	{
	    bool refp = fd->is_ref_param(i);
	    bool zlit = zero_args && i < zero_args->size() && (*zero_args)[i];
	    int s = score_arg_to_param(argtypes[i], fd->parameters[i], refp,
				       true, zlit);
#if MADC_DEBUG_FNTPL
	    std::cerr << "FNTPL rank cand=" << e.var->name << " arg" << i
		      << " a=" << (argtypes[i] ? argtypes[i]->name : "?")
		      << " p="
		      << (fd->parameters[i] ? fd->parameters[i]->name : "?")
		      << " refp=" << refp << " s=" << s << std::endl;
#endif
	    if ( s < 0 ) { ok = false; break; }
	    total += s;
	}
	if ( ok && total > best_score )
	{
	    best_score = total;
	    best = e.var;
	}
    }
    return best;
}

Variable *Program::find_namespace_function_overload(const std::string &ns,
		const std::string &name,
		const std::vector<const DataDef *> &argtypes,
		const std::vector<bool> *zero_args,
		const std::vector<DataDef *> *explicit_template_args)
{
    std::map<std::string, std::vector<NamespaceFnOverload>>::iterator oi =
	namespace_fn_overload_sets.find(ns + "::" + name);
    if ( oi == namespace_fn_overload_sets.end() || oi->second.size() < 2 )
    {
#if MADC_DEBUG_FNTPL
	std::cerr << "FNTPL rank-early key=" << ns << "::" << name
		  << " found=" << (oi != namespace_fn_overload_sets.end())
		  << " size=" << (oi != namespace_fn_overload_sets.end()
				  ? oi->second.size() : 0) << std::endl;
#endif
	return NULL;
    }
    Variable *best = rank_fn_overload_candidates(oi->second, argtypes,
						 zero_args,
						 explicit_template_args);
#if MADC_DEBUG_FNTPL
    std::cerr << "FNTPL rank " << ns << "::" << name << " WINNER="
	      << (best ? best->name : "(none)") << std::endl;
#endif
    return best;
}

// A parsed CONCRETE free-operator function viable for the operand types: scan
// every registered overload set whose key ends in "::" + opname — every
// namespace plus the global scope's "" key, the same suffix walk
// instantiate_free_operator_template uses for retained templates — and rank
// all entries together. Hoisted hidden friends, user-written free operators,
// and prior template instantiations all live in these sets.
Variable *Program::find_free_operator_function(const std::string &opname,
		const std::vector<const DataDef *> &argtypes,
		const std::vector<bool> *zero_args)
{
    const std::string suffix = "::" + opname;
    std::vector<NamespaceFnOverload> cands;
    for ( std::map<std::string, std::vector<NamespaceFnOverload>>::iterator mi =
	      namespace_fn_overload_sets.begin();
	  mi != namespace_fn_overload_sets.end(); ++mi )
    {
	const std::string &key = mi->first;
	if ( key.size() < suffix.size()
	  || key.compare(key.size() - suffix.size(), suffix.size(), suffix) )
	    continue;
	cands.insert(cands.end(), mi->second.begin(), mi->second.end());
    }
    if ( cands.empty() )
	return NULL;
    return rank_fn_overload_candidates(cands, argtypes, zero_args);
}

// The DataDef an operand denotes for free-operator overload ranking: a
// reference operand ranks as the referenced class (operand_object_class —
// C++ reference transparency), everything else as its expression datadef.
DataDef *Program::free_operator_arg_datadef(TokenBase *operand)
{
    if ( !operand )
	return NULL;
    if ( DataDefCLASS *oc = operand_object_class(operand) )
	return oc;
    return operand->datadef();
}

int Program::implicit_object_constness(Variable &recv)
{
    if ( recv.name == "__this" )
    {
	TokenCpnd *code = compounds.empty() ? NULL : compounds.top();
	if ( code && code->method )
	    if ( FuncDef *efd = dynamic_cast<FuncDef *>(
			 code->method->returns.type) )
		return efd->is_const_method ? 1 : 0;
	return -1;
    }
    if ( recv.flags & (vfCONSTANT | vfCONSTDECL | vfCONSTBAKED) )
	return 1;
    // A MEMBER receiver read through the implicit `this` joins the implicit
    // object's cv ([expr.ref]): inside a const method a data member is a
    // const object — libc++ set::size() const reads __tree_.size() and must
    // select __tree's PUBLIC const size() overload, never its PRIVATE
    // non-const twin (the cv tiebreak below in findMethodOverload needs
    // obj_cv=1 to do that). A LOCAL that shadows a member keeps its own cv:
    // the compound-chain identity walk exempts block locals.
    {
	TokenCpnd *code = compounds.empty() ? NULL : compounds.top();
	Method *m = code ? code->method : NULL;
	DataDefCLASS *owner = m ? m->owner_class : NULL;
	FuncDef *mfd = m ? dynamic_cast<FuncDef *>(m->returns.type) : NULL;
	if ( owner && mfd && mfd->is_const_method )
	{
	    std::string nm = recv.name;
	    if ( owner->m_offset(nm) != -1 )
	    {
		bool is_block_local = false;
		for ( TokenCpnd *c = code; c && !is_block_local; c = c->parent )
		    for ( size_t i = 0; i < c->variables.size(); ++i )
			if ( c->variables[i] == &recv )
			{
			    is_block_local = true;
			    break;
			}
		if ( !is_block_local )
		    return 1;
	    }
	}
    }
    DataDef *dd = recv.type;
    // Reference transparency: a reference receiver denotes its referent.
    if ( dd && dd->is_reference() )
	if ( DataDefPTR *rp = dynamic_cast<DataDefPTR *>(dd) )
	    dd = rp->base_type;
    if ( dd && dd->is_const() )
	return 1;
    return 0;
}

TokenCallMethod *Program::reselect_method_overload(TokenCallMethod *tc,
		Variable &recv, DataDefCLASS *cls, const std::string &id)
{
    if ( !tc || !cls )
	return tc;
    std::vector<const DataDef *> at;
    // Type each argument by REFERENCE TRANSPARENCY (operand_value_datadef): a
    // reference variable/parameter argument (`const string& __rhs`) denotes the
    // referenced OBJECT, not the raw pointer representation. Without this, inside
    // the instantiated free `operator<(const string&, const string&)` body
    // `lhs.method(rhs)` scored `rhs` as the pointer representation and selected
    // a pointer overload instead of the class-object overload.
    for ( TokenBase *p : tc->parameters )
	at.push_back(p ? operand_value_datadef(p) : NULL);
    Variable *ov = cls->findMethodOverload(id, at,
					   implicit_object_constness(recv));
    TokenCallMethod *selected = tc;
    if ( !ov && unevaluated_operand_depth > 0 )
    {
	// In an unevaluated operand (a decltype/SFINAE probe) a scored MISS —
	// same-name candidates exist (tc->var is the arity pick) but none is
	// viable for these argument types — is [over.match.viable] failure:
	// the call is ill-formed and the probe must SFINAE-reject. Keeping
	// the arity pick typed `declval<Alloc>().destroy(declval<B*>())` as
	// well-formed, so __has_destroy folded TRUE for an argument the
	// member cannot take, and allocator_traits::destroy bound the
	// __a.destroy arm — the __tree:890 tsubst bail (gate testptrviab).
	// An unknown argument shape (a NULL DataDef) keeps the lenient
	// fall-through — reject only what scored as PROVEN non-viable.
	bool all_args_known = true;
	for ( const DataDef *a : at )
	    if ( !a ) { all_args_known = false; break; }
	if ( all_args_known )
	    Throw(tc) << "no viable overload of '" << id << "' in "
		      << cls->name << " for these argument types" << flush;
    }
    if ( ov && ov != &tc->var )
    {
	selected = new TokenCallMethod(recv, *ov);
	selected->parameters = tc->parameters;
	selected->explicit_template_args = tc->explicit_template_args;
	selected->parent_expr = tc->parent_expr;
	selected->file = tc->file;
	selected->line = tc->line;
	selected->column = tc->column;
    }
#if MADC_DEBUG_FNTPL
    {
	const char *dump = ::getenv("MADC_DEBUG_FNTPL_DUMP");
	if ( dump && id.find(dump) != std::string::npos )
	{
	    FuncDef *ofd = dynamic_cast<FuncDef *>(ov ? ov->type : NULL);
	    FuncDef *sfd = dynamic_cast<FuncDef *>(selected->var.type);
	    std::cerr << "FNTPL mcall id=" << id
		      << " cls=" << cls->name
		      << " start=" << tc->var.name
		      << " ov=" << (ov ? ov->name : "(none)")
		      << " selected=" << selected->var.name
		      << " argc=" << selected->parameters.size()
		      << " ov_mt=" << (ofd ? (int)ofd->is_member_template : -1)
		      << " ov_decl=" << (ofd ? ofd->member_template_decl.size() : 0)
		      << " sel_mt=" << (sfd ? (int)sfd->is_member_template : -1)
		      << " sel_decl=" << (sfd ? sfd->member_template_decl.size() : 0)
		      << std::endl;
	}
    }
#endif

    // Instantiate an instance member-template body after overload selection.
    // parseCallMethod sees only the arity-picked placeholder; the retained body
    // lives on the argument-selected overload. Rebind the call to THIS shape's
    // concrete instance (per type-shape — the first-wins local_emit_name alias
    // cannot answer for a member template used at two types), so the emitted
    // symbol AND the real parameters (reference-arg passing) are the instance's.
    if ( unevaluated_operand_depth == 0 )
    {
	Variable *iv = instantiate_member_fn_template_for_call(selected);
	if ( iv && iv != &selected->var )
	{
	    TokenCallMethod *bound = new TokenCallMethod(recv, *iv);
	    bound->parameters = selected->parameters;
	    bound->explicit_template_args = selected->explicit_template_args;
	    bound->parent_expr = selected->parent_expr;
	    bound->file = selected->file;
	    bound->line = selected->line;
	    bound->column = selected->column;
	    selected = bound;
	}
    }
    return selected;
}

// Substitute a retained dependent return-type token range with a positional
// binding + trailing-pack elements (the clang SubstDecl model, return-type
// only — no body instantiation). A pack-expansion `pattern...` naming the
// pack (`declval<_ArgTypes>()...`, `__enable_if_t<!bool(_Bn::value)>...`) is
// repeated once per pack element with the pack name substituted per element;
// the pack name itself is left raw in the forward pass so the just-appended
// pattern still carries it, then lifted out and re-emitted on the `...`.
// The ONE implementation, shared by the member-template resolver
// (resolve_member_template_call_return_type) and the namespace fn-template
// by-key resolver (resolve_fn_template_return_by_key).
static std::vector<TokenBase *> substitute_return_range_tokens(
	const std::vector<TokenBase *> &rtoks,
	const std::map<std::string, DataDef *> &binding,
	const std::string &pack_name,
	const std::vector<DataDef *> &pack_elems)
{
    std::vector<TokenBase *> sub;
    for ( size_t i = 0; i < rtoks.size(); ++i )
    {
	TokenBase *t = rtoks[i];
	// Pack-expansion ellipsis: lift the preceding pattern out of `sub` and
	// re-emit it once per pack element (pack name -> element type).
	if ( !pack_name.empty() && t && t->id() == TokenID::tkDot
	  && i + 2 < rtoks.size()
	  && rtoks[i+1] && rtoks[i+1]->id() == TokenID::tkDot
	  && rtoks[i+2] && rtoks[i+2]->id() == TokenID::tkDot )
	{
	    int depth = 0;
	    size_t start = sub.size();
	    for ( size_t j = sub.size(); j-- > 0; )
	    {
		TokenID jid = sub[j]->id();
		if ( jid == TokenID::tkClBrk || jid == TokenID::tkClSqr
		  || jid == TokenID::tkClBrc )
		    ++depth;
		else if ( jid == TokenID::tkOpBrk || jid == TokenID::tkOpSqr
		       || jid == TokenID::tkOpBrc )
		{ if ( depth == 0 ) { start = j + 1; break; } --depth; }
		else if ( depth == 0 && jid == TokenID::tkComma )
		{ start = j + 1; break; }
		if ( j == 0 ) start = 0;
	    }
	    std::vector<TokenBase *> pat(sub.begin() + start, sub.end());
	    sub.erase(sub.begin() + start, sub.end());
	    for ( size_t e = 0; e < pack_elems.size(); ++e )
	    {
		if ( e )
		    sub.push_back(new TokenComma());
		for ( TokenBase *pt : pat )
		{
		    if ( pt && is_contextual_identifier_token(pt)
		      && contextual_identifier_name(pt) == pack_name )
			sub.push_back(new TokenDataType(pack_elems[e]->name.c_str(),
							*pack_elems[e]));
		    else
			sub.push_back(pt ? pt->clone() : NULL);
		}
	    }
	    for ( TokenBase *pt : pat )
		delete pt;
	    i += 2;
	    continue;
	}
	if ( t && is_contextual_identifier_token(t) )
	{
	    std::string tn = contextual_identifier_name(t);
	    if ( tn == pack_name )   // leave raw for the `...` expansion above
	    {
		sub.push_back(t->clone());
		continue;
	    }
	    std::map<std::string, DataDef *>::const_iterator bi = binding.find(tn);
	    if ( bi != binding.end() && bi->second )
	    {
		sub.push_back(new TokenDataType(bi->second->name.c_str(),
						*bi->second));
		continue;
	    }
	}
	sub.push_back(t ? t->clone() : NULL);
    }
    return sub;
}

DataDef *Program::resolve_member_template_call_return_type(FuncDef *fd,
		const std::vector<DataDef *> &explicit_targs)
{
    if ( vri_debug_enabled() && fd )
	fprintf(stderr, "[vriprobe] MTRT enter %s ret=%zu defs=%zu\n",
		fd->method_display_name.c_str(),
		fd->member_template_return_tokens.size(),
		fd->member_template_param_defaults.size());
    if ( !fd || fd->member_template_return_tokens.empty()
      || fd->template_param_names.empty() )
	return NULL;
    // Bind type parameters from the EXPLICIT template args (the common library
    // shape `_S_test<F, Args...>(0)` is all-explicit). A binding deduced from
    // the call argument types is a follow-up (sub-wall (c)). The trailing
    // parameter may be a PACK (`typename... _Args`): explicit args beyond the
    // leading fixed params all belong to it — bind the fixed params singly and
    // collect the pack's elements (the `__invoke_result`/`__result_of` keystone
    // `_S_test<_Functor, _ArgTypes...>(0)` where _ArgTypes is multi-element).
    std::map<std::string, DataDef *> binding;
    std::string pack_name;
    size_t nfixed = fd->template_param_names.size();
    if ( fd->template_param_is_pack.size() == fd->template_param_names.size()
      && !fd->template_param_is_pack.empty()
      && fd->template_param_is_pack.back() )
    {
	pack_name = fd->template_param_names.back();
	nfixed = fd->template_param_names.size() - 1;
    }
    std::vector<DataDef *> pack_elems;
    for ( size_t i = 0; i < explicit_targs.size(); ++i )
    {
	if ( !explicit_targs[i] )
	    continue;
	if ( i < nfixed )
	    binding[fd->template_param_names[i]] = explicit_targs[i];
	else if ( !pack_name.empty() )
	    pack_elems.push_back(explicit_targs[i]);
    }
    if ( binding.empty() && pack_elems.empty() )
	return NULL;
    DataDefCLASS *owner = dynamic_cast<DataDefCLASS *>(fd->member_template_owner);
    // [temp.deduct]/8 for DEFAULTED type params: an unbound parameter with a
    // captured default must substitute-and-resolve under the binding, or the
    // candidate is NOT viable — gcc13's __is_destructible_impl::__test
    // carries its whole SFINAE in `typename = decltype(declval<_Tp1&>().
    // ~_Tp1())` (plain true_type return). resolve_template_param_default_type
    // is the SFINAE-clean resolver (isolated stream, muted cerr, NULL on
    // failure); a resolved default JOINS the binding so a return naming the
    // defaulted param still substitutes.
    // Enforce only under a CONCRETE binding: during a capture/dependent parse
    // the bound args still name unresolved surfaces and every default would
    // "fail" — rejecting the candidate the capture itself needs (the header's
    // is_destructible chain then never registered). A dependent use keeps the
    // old permissive resolution; the concrete instantiation re-runs here.
    bool binding_concrete = !class_pattern_capture_in_progress
			 && !::getenv("MADC_XTEST_NODEFFILL");
    for ( std::map<std::string, DataDef *>::const_iterator bi = binding.begin();
	  binding_concrete && bi != binding.end(); ++bi )
	if ( !bi->second || datadef_has_unresolved_dependent_surface(bi->second) )
	    binding_concrete = false;
    // [temp.names]: the default's unqualified names (`declval`) bind in the
    // member template's DEFINITION context. The owner's canonical spelling
    // carries that namespace (`std::__do_is_destructible_impl` -> `std`);
    // split before any template args so a nested `::` in an argument list
    // cannot fool the scan. Empty -> global scope, no push.
    std::string def_ns;
    if ( owner )
    {
	std::string ocs = owner->canonical_cpp_spelling().empty()
			? owner->name : owner->canonical_cpp_spelling();
	size_t lt = ocs.find('<');
	if ( lt != std::string::npos )
	    ocs = ocs.substr(0, lt);
	size_t sep = ocs.rfind("::");
	if ( sep != std::string::npos )
	    def_ns = ocs.substr(0, sep);
    }
    Program::NamespaceScope dns_scope(*this, def_ns);
    if ( vri_debug_enabled() && binding_concrete
      && !fd->member_template_param_defaults.empty() )
	fprintf(stderr, "[vriprobe] MT deffill ctx owner=%s canon=%s ns=%s\n",
		owner ? owner->name.c_str() : "(null)",
		owner ? owner->canonical_cpp_spelling().c_str() : "-",
		def_ns.c_str());
    if ( binding_concrete )
	for ( size_t i = 0; i < fd->template_param_names.size()
		    && i < fd->member_template_param_defaults.size(); ++i )
	{
	    if ( binding.count(fd->template_param_names[i])
	      || fd->member_template_param_defaults[i].empty() )
		continue;
	    if ( !pack_name.empty() && fd->template_param_names[i] == pack_name )
		continue;
	    DataDef *rd = resolve_template_param_default_type(
		fd->member_template_param_defaults[i], binding, owner);
	    if ( !rd )
	    {
		if ( vri_debug_enabled() )
		    fprintf(stderr, "[vriprobe] MT deffill REJECT %s param=%s b0=%s\n",
			    fd->method_display_name.c_str(),
			    fd->template_param_names[i].c_str(),
			    binding.empty() ? "-" : binding.begin()->second->name.c_str());
		return NULL;         // substitution failure — not viable
	    }
	    binding[fd->template_param_names[i]] = rd;
	}
    // [temp.deduct]/8 for the FUNCTION parameters: a parameter TYPE that
    // names a bound template param must substitute-and-resolve under the
    // binding, or the candidate is not viable — libc++'s
    // __has_iterator_category __test pair carries its SFINAE in
    // `typename _Up::iterator_category* = nullptr` (a param TYPE, not a
    // defaulted type-param), and without this check the arity-preferred
    // candidate wrongly survived at _Up=int and every false-branch detect
    // read 1. Only runs MENTIONING a bound name are checked (others need no
    // substitution and cannot fail under this binding); the same SFINAE-clean
    // resolver as the deffill above (isolated stream, NULL on failure, a
    // trailing param NAME is a tolerated leftover).
    if ( binding_concrete )
	for ( size_t i = 0; i < fd->member_template_param_type_tokens.size(); ++i )
	{
	    const std::vector<TokenBase *> &run =
		fd->member_template_param_type_tokens[i];
	    if ( run.empty() )
		continue;
	    bool names_bound = false;
	    for ( TokenBase *t : run )
		if ( t && is_contextual_identifier_token(t)
		  && binding.count(contextual_identifier_name(t)) )
		{ names_bound = true; break; }
	    if ( !names_bound )
		continue;
	    if ( !resolve_template_param_default_type(run, binding, owner) )
	    {
		if ( vri_debug_enabled() )
		    fprintf(stderr, "[vriprobe] MT param-subst REJECT %s param[%zu]\n",
			    fd->method_display_name.c_str(), i);
		return NULL;             // substitution failure — not viable
	    }
	}
    // Substitute — the ONE shared implementation (see
    // substitute_return_range_tokens).
    std::vector<TokenBase *> sub = substitute_return_range_tokens(
	fd->member_template_return_tokens, binding, pack_name, pack_elems);
    // Resolve in the owner's class scope (so an owner-scope typedef / member
    // type in the return resolves). resolve_type_token_range carries its own
    // SFINAE trap (returns NULL on substitution failure — a non-viable
    // candidate, not a hard error).
    bool pushed_owner = false;
    if ( owner ) { class_scope_stack.push_back(owner); pushed_owner = true; }
    DataDef *rt = resolve_type_token_range(sub, 0, sub.size());
    if ( pushed_owner && !class_scope_stack.empty()
      && class_scope_stack.back() == owner )
	class_scope_stack.pop_back();
    for ( TokenBase *t : sub )
	delete t;
    // A CAPTURE parse resolving through an UNENFORCEABLE defaulted-param
    // SFINAE — the binding still names placeholders, so the default can
    // neither pass nor fail — must not BAKE a CONSTANT return into the
    // pattern: `decltype(__test<_Tp>(0))` would freeze true_type and every
    // bound is_destructible<X> would answer 1 (the alias-node twin of the
    // [traitfold] baked false_type). A DEPENDENT result stays a
    // re-derivable pattern node (the common_type `_S_test` shape) and
    // captures fine; a concrete one poisons the capture, and the class
    // stays on the legacy re-parse lane, which re-resolves per
    // instantiation in BOTH the live and the forest-bound consumers.
    if ( rt && !binding_concrete && class_pattern_capture_in_progress
      && !datadef_has_unresolved_dependent_surface(rt) )
	for ( size_t i = 0; i < fd->template_param_names.size()
		    && i < fd->member_template_param_defaults.size(); ++i )
	    if ( !fd->member_template_param_defaults[i].empty()
	      && !binding.count(fd->template_param_names[i]) )
	    {
		dependent_parse_poisoned = true;
		Throw << "class-pattern capture cannot bake the constant "
		      << "return of '" << fd->method_display_name
		      << "' past its unenforceable defaulted-param SFINAE"
		      << flush;
	    }
    return rt;
}

TokenCallFunc *Program::reselect_static_member_overload(TokenCallFunc *tc,
		DataDefCLASS *owner, const std::string &member)
{
    if ( !tc || !owner || member.empty() )
	return tc;
    FuncDef *fd = dynamic_cast<FuncDef *>(tc->var.type);
    // Only member TEMPLATES need the post-arg reselection: a non-template static
    // overload set is already disambiguated by find_method_by_callable_arity at
    // resolution time. Narrowing here keeps the change surgical (the part-18
    // partial-ordering lesson: touch selection only on a genuine relationship).
    if ( !fd || !fd->is_member_template )
	return tc;
    std::vector<const DataDef *> at;
    for ( TokenBase *p : tc->parameters )
	at.push_back(p ? p->datadef() : NULL);
    // Selection: a more-specialized overload may win the [temp.func.order]
    // tiebreak (`take(U*)` over `take(P)`). When findMethodOverload can't score
    // a candidate (e.g. a typedef-reference param it doesn't model), keep the
    // already parse-resolved overload (tc->var) — the rebind below still applies.
    Variable *ov = owner->findMethodOverload(member, at);
#if MADC_DEBUG_FNTPL
    {
	const char *dump = ::getenv("MADC_DEBUG_FNTPL_DUMP");
	if ( dump && member.find(dump) != std::string::npos )
	{
	    std::cerr << "FNTPL reselect member=" << member
		      << " owner=" << owner->name
		      << " initial=" << tc->var.name
		      << " ov=" << (ov ? ov->name : "(none)")
		      << " ov_static=" << (ov ? (int)((ov->flags & vfSTATIC) != 0) : -1)
		      << " argc=" << at.size();
	    for ( size_t i = 0; i < at.size(); ++i )
		std::cerr << " a" << i << "="
			  << (at[i] ? at[i]->name : "(null)");
	    std::cerr << std::endl;
	}
    }
#endif
    Variable *selvar = (ov && (ov->flags & vfSTATIC)) ? ov : &tc->var;
    TokenCallFunc *sel = tc;
    if ( selvar != &tc->var )
    {
	sel = new TokenCallFunc(*selvar);
	sel->parameters = tc->parameters;
	sel->explicit_template_args = tc->explicit_template_args;
	sel->auto_scope_context = tc->auto_scope_context;
	sel->file = tc->file;
	sel->line = tc->line;
	sel->column = tc->column;
    }
    // Ensure the selected member template is instantiated (idempotent / memoized
    // when parseCallFunc already ran the hook on the original binding).
    instantiate_namespace_fn_template_for_call(sel);
    Variable *mti_def = instantiate_member_fn_template_for_call(sel);
    // Bind the call to the instantiated DEFINITION (real parameters + ref_params,
    // non-varargs) rather than the varargs placeholder, so REFERENCE arguments
    // are passed by address (the placeholder carries no ref_params, and mutating
    // it would corrupt findMethodOverload's arity gate). The instantiation hook
    // returns THIS type-shape's instance; fall back to the placeholder+alias
    // path (correct for by-value/pointer args) when there is none.
    FuncDef *sfd = dynamic_cast<FuncDef *>(sel->var.type);
    if ( sfd && sfd->is_member_template )
    {
	Variable *idef = mti_def;
	if ( idef && dynamic_cast<FuncDef *>(idef->type) )
	{
	    TokenCallFunc *tc3 = new TokenCallFunc(*idef);
	    tc3->parameters = sel->parameters;
	    tc3->explicit_template_args = sel->explicit_template_args;
	    tc3->auto_scope_context = sel->auto_scope_context;
	    tc3->file = sel->file;
	    tc3->line = sel->line;
	    tc3->column = sel->column;
	    return tc3;
	}
	// No __mti definition — a BODY-LESS member template (the
	// __result_of_other_impl::_S_test shape). Its body can't be instantiated,
	// but a decltype/unevaluated call only needs the concrete RETURN TYPE.
	// Resolve it by substituting the explicit template args into the retained
	// dependent return tokens (clang SubstDecl model, return-type only) and
	// record it as the call's return_override — no synthetic definition, no
	// emission. NULL (substitution failure / no targs) leaves the placeholder.
	if ( DataDef *rt = resolve_member_template_call_return_type(sfd,
		sel->explicit_template_args) )
	{
	    if ( rt != &ddAUTO )
		sel->return_override = rt;
	}
	else
	{
	    // [temp.deduct]/8: the SELECTED candidate's substitution failed
	    // (a defaulted-param SFINAE probe — gcc13's `__test(int)` with
	    // `typename = decltype(declval<_Tp1&>().~_Tp1())`). Overload
	    // resolution falls to the NEXT viable same-name member template —
	    // the ellipsis catch-all `__test(...)` whose return (false_type)
	    // resolves unconditionally. Registration order preserves the
	    // header's declaration order, so the catch-all is tried last.
	    // The overload set lives on the class that REGISTERED the member
	    // templates (`__do_is_destructible_impl` — a BASE of the class
	    // this call resolved through, whose own `methods` is empty for
	    // inherited members). sfd carries it.
	    DataDefCLASS *reg_owner =
		dynamic_cast<DataDefCLASS *>(sfd->member_template_owner);
	    if ( !reg_owner )
		reg_owner = owner;
	    if ( vri_debug_enabled() )
		fprintf(stderr, "[vriprobe] MT fallback member=%s methods=%zu\n",
			member.c_str(), reg_owner->methods.size());
	    for ( Variable *mv : reg_owner->methods )
	    {
		if ( !mv )
		    continue;
		FuncDef *fd2 = dynamic_cast<FuncDef *>(mv->type);
		if ( vri_debug_enabled() && fd2 && fd2->is_member_template )
		    fprintf(stderr, "[vriprobe] MT cand disp=%s same=%d\n",
			    fd2->method_display_name.c_str(),
			    (int)(fd2 == sfd));
		if ( !fd2 || fd2 == sfd || !fd2->is_member_template
		  || fd2->method_display_name != member )
		    continue;
		if ( DataDef *rt2 = resolve_member_template_call_return_type(
			fd2, sel->explicit_template_args) )
		{
		    if ( rt2 != &ddAUTO )
		    {
			TokenCallFunc *tc4 = new TokenCallFunc(*mv);
			tc4->parameters = sel->parameters;
			tc4->explicit_template_args = sel->explicit_template_args;
			tc4->auto_scope_context = sel->auto_scope_context;
			tc4->file = sel->file;
			tc4->line = sel->line;
			tc4->column = sel->column;
			tc4->return_override = rt2;
			return tc4;
		    }
		    break;
		}
	    }
	}
    }
    return sel;
}

// Round `sz` up to alignment `a` (a is a power of two).
static inline size_t mi_align_up(size_t sz, size_t a) { return (sz + a - 1) & ~(a - 1); }

// Itanium-faithful record layout. See
// docs/superpowers/specs/2026-06-03-multiple-inheritance-design.md §2.
// Precondition: `members`/`member_offsets` hold OWN data members from offset 0
// (as addMember produced them); `size`/`max_align` are their packed size and
// strongest own-member alignment; `has_vtable` set iff polymorphic; `bases`
// populated (base, is_virtual). Postcondition: each BaseSpec.offset/is_primary,
// vbase_offset, secondary_vptr_owners, nvsize and size are final; own member
// offsets are shifted to sit after the vptr+non-virtual-bases block.
void DataDefCLASS::compute_layout()
{
    size_t cur = 0;
    // Class alignment accumulator. Starts at the natural minimum (1) and grows to
    // the strongest member / base / vptr alignment — matching gcc/clang. It must
    // NOT floor at the pointer size: a class whose strongest member is a 4-byte
    // int (and which has no vptr and no base) is 4-aligned, so
    // `struct W { int a; ~W(){} };` is sizeof 4, not 8. The vptr/base/vbase bumps
    // below restore pointer alignment where it is genuinely required.
    size_t maxalign = 1;
    // Pointer size/alignment come from the type system (DataDefPTR), NOT a literal
    // 8 — so a future 32-bit target (north-star multi-target) changes them in ONE
    // place. A vptr is a pointer; a (v)base subobject is aligned to its OWN
    // alignment (Itanium ABI), recovered via DataDef::alignment().
    const size_t ptr_size  = ddVOIDptr.size;
    const size_t ptr_align = ddVOIDptr.alignment();

    // 1. vptr: a class carries a vptr if it has virtual methods OR any (transitive)
    //    virtual base (Itanium: virtual inheritance needs a vptr even with no virtual
    //    methods). The vptr sits at offset 0 unless a primary base (non-virtual base
    //    that itself carries a vptr) already provides one.
    std::vector<DataDefCLASS *> all_vbases;
    std::set<DataDefCLASS *> vseen;
    collect_vbases(all_vbases, vseen);
    bool needs_vptr = is_polymorphic() || !all_vbases.empty();
    has_vptr_slot = needs_vptr;
    bool have_primary = false;
    for ( auto &bs : bases )
    {
	if ( !bs.is_virtual && bs.base->has_vptr_slot )
	{
	    bs.is_primary = true; have_primary = true; break;
	}
    }
    bool own_vptr = needs_vptr && !have_primary;
    if ( own_vptr )   // __vptr at 0 — a pointer slot, pointer-aligned
    { cur += ptr_size; if ( ptr_align > maxalign ) maxalign = ptr_align; }

    // 2. non-virtual bases in declaration order (primary first, at 0). A base
    //    contributes its NON-VIRTUAL size (nvsize); its vbases are hoisted.
    for ( auto &bs : bases )
    {
	if ( bs.is_virtual ) continue;
	bool empty_base = trait_is_empty(bs.base);
	// A base subobject is aligned to the base's OWN alignment (Itanium ABI),
	// not an assumed pointer alignment — a non-polymorphic POD base aligns to
	// its strongest member, matching gcc/clang.
	size_t balign = bs.base->alignment();
	if ( !balign ) balign = 1;
	// Itanium empty-base allocation: an EMPTY non-primary base occupies no
	// storage and is PLACED AT OFFSET 0 (dsize contributes nothing), bumped
	// only past a SAME-TYPE empty sibling ([intro.object] distinct-address
	// rule). The old code parked it at the running offset — for libc++'s
	// __compressed_pair<rep, allocator> that put the allocator elem at 24
	// == ONE PAST the 24-byte object, so every __second()/__alloc()
	// accessor read/wrote out of bounds (ASan: get_allocator overflows the
	// string local; under the JIT the writes clobbered ADJACENT locals —
	// the string-concat size corruption).
	if ( empty_base && !bs.is_primary )
	{
	    size_t eoff = 0;
	    for ( auto &prev : bases )
	    {
		if ( &prev == &bs ) break;
		if ( !prev.is_virtual && prev.base == bs.base
		  && prev.offset == eoff )
		    ++eoff;
	    }
	    bs.offset = eoff;
	    if ( bs.base->has_vptr_slot ) secondary_vptr_owners.push_back(bs.base);
	    if ( balign > maxalign ) maxalign = balign;
	    continue;
	}
	cur = mi_align_up(cur, balign);
	bs.offset = bs.is_primary ? 0 : cur;
	if ( bs.is_primary )
	    cur = empty_base ? cur : bs.base->nvsize; // shares vptr@0; empty bases use EBO
	else
	{
	    if ( bs.base->has_vptr_slot ) secondary_vptr_owners.push_back(bs.base);
	    if ( !empty_base )
		cur += bs.base->nvsize;
	}
	if ( balign > maxalign ) maxalign = balign;
    }

    // 3. own data members begin after the non-virtual bases. Record the boundary
    //    only; apply_member_layout() does the member_offsets rewrite (it knows each
    //    member's origin). addMember left `size` = the packed own-members size
    //    (the live flatten resets size to 0 before adding own members; the unit
    //    tests add only own members) and `max_align` = strongest own alignment.
    if ( max_align > maxalign ) maxalign = max_align;
    own_block_off = mi_align_up(cur, max_align ? max_align : 1);
    cur = own_block_off + size;   // size = own packed size on entry

    // 4. nvsize (Itanium) = the non-virtual data size rounded up to the
    //    non-virtual alignment. It is what a DERIVED class adds for this class
    //    when it uses it as a non-virtual base.
    nvsize = mi_align_up(cur, maxalign);
    if ( trait_is_empty(this) && nvsize == 0 )
	nvsize = 1;

    // 5. virtual bases: appended once at the end, in canonical (collected) order.
    //    They begin at this class's DATA SIZE (`cur` — the end of the non-virtual
    //    members, Itanium's dsize), NOT at the maxalign-rounded nvsize: g++ places
    //    the first vbase right after the last non-virtual byte, aligned to the
    //    vbase's own alignment (`struct Left : virtual Mid { int l; }` puts the Mid
    //    subobject at 12 = vptr 8 + l 4, not 16). Starting from nvsize over-pads
    //    every vbase layout (Left 32 vs the correct 24).
    std::vector<DataDefCLASS *> vbs;
    std::set<DataDefCLASS *> seen;
    collect_vbases(vbs, seen);
    size_t end = cur;
    for ( DataDefCLASS *vb : vbs )
    {
	size_t vbalign = vb->alignment();
	if ( !vbalign ) vbalign = 1;
	end = mi_align_up(end, vbalign);
	vbase_offset[vb] = end;
	end += vb->nvsize;        // vbase contributes its non-virtual size
	if ( vbalign > maxalign ) maxalign = vbalign;
    }
    size = mi_align_up(end, maxalign);
    if ( trait_is_empty(this) && size == 0 )
	size = 1;
    class_align = maxalign;   // cache the TRUE class alignment for alignment()
}

// Rewrite each member's final offset from its origin: own members (origin -1, or
// no origin recorded) sit at own_block_off + their own-local offset; an inherited
// member sits at its base subobject offset (vbase_offset for a virtual base, else
// bases[origin].offset) + its offset-within-that-base. Run AFTER compute_layout().
void DataDefCLASS::apply_member_layout()
{
    for ( size_t i = 0; i < member_offsets.size(); i++ )
    {
	// A virtual-base member (direct or transitive) sits at this class's hoisted
	// vbase_offset[base] + its offset WITHIN that base. Checked first: it is
	// shared (one subobject), so it must NOT use a per-path direct-base offset.
	std::map<size_t, DataDefCLASS *>::iterator vbi = member_vbase.find(i);
	if ( vbi != member_vbase.end() )
	{
	    size_t voff = vbase_offset.count(vbi->second) ? vbase_offset[vbi->second] : 0;
	    member_offsets[i] = voff + member_offsets[i];
	    continue;
	}
	int origin = (i < member_origin.size()) ? member_origin[i] : -1;
	if ( origin < 0 )
	    member_offsets[i] = own_block_off + member_offsets[i];
	else
	{
	    size_t boff = 0;
	    if ( origin < (int)bases.size() )
		boff = bases[origin].is_virtual
			 ? vbase_offset[bases[origin].base]
			 : bases[origin].offset;
	    member_offsets[i] = boff + member_offsets[i];
	}
    }
}

// Subobject offset of `target` within this class. A (transitive) virtual base
// lives at this class's hoisted vbase_offset; a non-virtual base at its bs.offset
// (plus the offset within it, transitively). Returns (size_t)-1 if not a base.
// Build the grouped vtable: group 0 = primary (this class's flat vtable_slots,
// already inheritance-merged), then one group per secondary polymorphic base
// (its own slots, at its subobject offset). Run after compute_layout (so
// secondary_vptr_owners + base offsets are known).
void DataDefCLASS::build_vtable_groups()
{
    vtable_groups.clear();
    if ( !has_vtable && !has_vptr_slot ) return;

    // The primary group holds the PRIMARY-chain slots: the primary base's slots
    // (overrides resolved by name at emit time) plus this class's own newly
    // introduced virtuals. Secondary bases' slots live in their own groups, so
    // exclude them from the primary group.
    DataDefCLASS *prim = NULL;
    for ( auto &b : bases ) if ( b.is_primary ) { prim = b.base; break; }
    std::set<std::string> secondary_slots;
    for ( DataDefCLASS *o : secondary_vptr_owners )
	for ( auto &s : o->vtable_slots ) secondary_slots.insert(s);

    VtableGroup primary{this, 0, std::vector<std::string>(), 0};
    if ( prim ) primary.slots = prim->vtable_slots;
    for ( auto &s : vtable_slots )
    {
	bool in_prim = false;
	if ( prim )
	    for ( auto &ps : prim->vtable_slots ) if ( ps == s ) { in_prim = true; break; }
	if ( !in_prim && !secondary_slots.count(s) )
	    primary.slots.push_back(s);
    }
    vtable_groups.push_back(primary);

    for ( DataDefCLASS *o : secondary_vptr_owners )
    {
	size_t off = 0;
	for ( auto &b : bases ) if ( b.base == o ) { off = b.offset; break; }
	vtable_groups.push_back(VtableGroup{o, off, o->vtable_slots, 0});
    }

    // Itanium: the complete-object vtable also carries one group per
    // POLYMORPHIC virtual base — the vbase subobject has its own vptr at its
    // hoisted position, and a V*-typed receiver dispatches through it. Skip a
    // vbase already covered by a group at the same offset (a primary-shared
    // nearly-empty vbase). Appended LAST so find_vslot prefers the primary /
    // secondary groups. (task #36 slice 2)
    std::vector<DataDefCLASS *> gvbases;
    std::set<DataDefCLASS *> gvbseen;
    collect_vbases(gvbases, gvbseen);
    for ( DataDefCLASS *vb : gvbases )
    {
	if ( !vb->has_vptr_slot ) continue;
	size_t voff = vbase_offset.count(vb) ? vbase_offset[vb] : 0;
	bool covered = false;
	for ( auto &g : vtable_groups )
	    if ( g.this_offset == voff ) { covered = true; break; }
	if ( covered ) continue;
	vtable_groups.push_back(VtableGroup{vb, voff, vb->vtable_slots, 0});
    }

    // Address point of each group = the index in the flat Cls__vtable[] array
    // (sub-tables emitted back-to-back) of the group's first FUNCTION slot. Each
    // address point is preceded by the Itanium prologue: one vbase-offset slot
    // per virtual base of the group's OWNER (reverse collect_vbases order in
    // ascending memory — the first collected vbase reads back at vptr[-3]),
    // then [offset_to_top, &_ZTI<cls>] (all emitted in class_vtable_def), so
    // the running index advances by 2 + n_vbases before each group. Computed
    // here so emission / dispatch / vptr-init agree regardless of pass order.
    // (S5a; vbase-offset slots: task #36 slice 2)
    size_t ap = 0;
    for ( auto &g : vtable_groups )
    {
	std::vector<DataDefCLASS *> gvbs;
	std::set<DataDefCLASS *> gvseen;
	g.owner->collect_vbases(gvbs, gvseen);
	ap += 2 + gvbs.size();   // this group's prologue precedes its address point
	g.addr_point = ap;
	ap += g.slots.size();
    }
}

size_t DataDefCLASS::base_offset_of(const DataDefCLASS *target) const
{
    if ( target == this ) return 0;
    // Direct virtual-base hits first: the layout builder records the class's
    // full virtual-base set here, so an (in)direct vbase always resolves from
    // its own entry, never composed through another vbase's local offsets.
    for ( const auto &vb : vbase_offset )
	if ( vb.first == target ) return vb.second;
    // Transitive through a virtual base: a NON-virtual base of a virtual
    // base (ios_base within basic_ios within ostream). Without this arm the
    // walk returned -1 and every consumer (method-call owner adjust,
    // object_arg_addr reference binding) silently skipped the subobject
    // adjustment — cout.setf()/std::hex(cout) wrote flag bits at the
    // stream's own offset 0. Static offsets: correct for a most-derived
    // view (the dynamic-view gap is the vtable vbase-offset-slot work).
    for ( const auto &vb : vbase_offset )
    {
	size_t vinner = vb.first->base_offset_of(target);
	if ( vinner != (size_t)-1 ) return vb.second + vinner;
    }
    for ( const auto &bs : bases )
    {
	if ( bs.is_virtual ) continue; // virtual bases handled via vbase_offset above
	if ( bs.base == target ) return bs.offset;
	size_t inner = bs.base->base_offset_of(target);
	if ( inner != (size_t)-1 ) return bs.offset + inner;
    }
    return (size_t)-1;
}

DataDefCLASS::TypeInfoFlavor DataDefCLASS::typeinfo_flavor() const
{
    if ( bases.empty() )
	return TI_CLASS;
    // __si only when there is exactly one base, public (access 0), non-virtual.
    if ( bases.size() == 1 && !bases[0].is_virtual && bases[0].access == 0 )
	return TI_SI;
    return TI_VMI;
}

bool DataDefCLASS::is_unique_public_nonvirtual_base(DataDefCLASS *b, size_t *off) const
{
    size_t found_off = 0;
    int count = 0;
    for ( const BaseSpec &bs : bases )
    {
	if ( bs.is_virtual || bs.access != 0 ) continue; // public, non-virtual only
	if ( bs.base == b )
	{
	    found_off = bs.offset;
	    count++;
	}
	else
	{
	    size_t sub = 0;
	    if ( bs.base->is_unique_public_nonvirtual_base(b, &sub) )
	    {
		found_off = bs.offset + sub;
		count++;
	    }
	}
    }
    if ( count == 1 )
    {
	if ( off ) *off = found_off;
	return true;
    }
    return false;
}

void DataDefCLASS::collect_vbases(std::vector<DataDefCLASS *> &out,
				  std::set<DataDefCLASS *> &seen) const
{
    for ( const auto &bs : bases )
    {
	// a base's own (transitive) virtual bases come first, then the base if virtual
	bs.base->collect_vbases(out, seen);
	if ( bs.is_virtual && seen.insert(bs.base).second )
	    out.push_back(bs.base);
    }
}

bool DataDefCLASS::is_externally_defined() const
{
    // Only a polymorphic class with a known Itanium spelling can be deferred to
    // libstdc++ (we must be able to name its real _ZTVSt.../_ZTISt... symbols).
    if ( !has_vtable || canonical_cpp_spelling().empty() )
	return false;
    // A polymorphic class DEFINED in a system/toolchain header is owned by that
    // library: libstdc++ explicitly instantiates the standard facets/streams and
    // emits their vtable, typeinfo, AND every member symbol (including inline
    // virtual defaults) as weak symbols. madc must reference the real
    // _ZTVSt.../_ZTISt... and must NOT re-synthesize a parallel vtable — even
    // though the header gives some virtual slots (ctype::do_widen,
    // num_put::do_put, basic_streambuf::imbue, …) an inline body. A USER class
    // that overrides std:: virtuals is NOT from a system header, so it falls
    // through to the slot-body / base analysis below and madc emits its own
    // vtable. Data-driven (path-based), never a namespace==std test.
    if ( from_system_header )
	return true;
    // "madc has a body for this entity" = a real definition parsed in THIS TU
    // (not a bodyless prototype, not an extern-bound declaration, not a pure
    // virtual, not = default/delete).
    auto has_madc_body = [](Variable *v) -> bool {
	FuncDef *fd = v ? dynamic_cast<FuncDef *>(v->type) : NULL;
	return fd && !fd->declaration_only && fd->emit_symbol.empty()
	    && !fd->pure_virtual && !fd->defaulted_or_deleted;
    };
    // madc owns the vtable iff it defines (with a body, in THIS TU) any method
    // that occupies a VTABLE SLOT — a virtual method or virtual destructor.
    // Inline NON-virtual helpers (e.g. ctype::toupper, which forwards to the
    // EXTERNAL virtual do_toupper) carry bodies but are NOT slots, so they must
    // NOT disqualify — otherwise no real libstdc++ class would ever be deferred.
    for ( Variable *m : methods )
    {
	FuncDef *fd = dynamic_cast<FuncDef *>(m ? m->type : NULL);
	if ( fd && has_madc_body(m) && !fd->method_display_name.empty()
	  && virtual_methods.find(fd->method_display_name) != virtual_methods.end() )
	    return false;
    }
    // A destructor with a body (dtors don't carry method_display_name). Any
    // bodied "~..." entry means madc emits this class's dtor slot.
    for ( const auto &kv : method_map )
	if ( !kv.first.empty() && kv.first[0] == '~' && has_madc_body(kv.second) )
	    return false;
    // A madc-defined base owns slots that also appear in this class's vtable
    // (inherited), so it must emit its own vtable/typeinfo too. Recurse.
    for ( const BaseSpec &bs : bases )
	if ( bs.base && !bs.base->is_externally_defined() )
	    return false;
    return true;
}

DataDef *FuncDef::findParameter(const std::string &s)
{
    DBG(cout << "FuncDef[" << name << "]::findParameter(" << s << ')' << endl);
    for ( datadef_vec_iter dvi = parameters.begin(); dvi != parameters.end(); ++dvi )
	if ( !s.compare((*dvi)->name) )
	    return *dvi;

    return NULL;
}

