// recursively search for local variables up the codeblock
// Intern the query name ONCE, then walk the scope chain by the integer sid.
Variable *TokenCpnd::findVariable(const madc::dis::intern_table &sp, const std::string &id)
{
    return findVariable(sp, sp.intern(id), id);
}

void Program::set_token_spelling(TokenIdent *t, const std::string &s)
{
    if ( !t ) return;
    // Step 4: re-spelling an identifier/type token = re-intern -> new spelling_id;
    // spelling() then resolves the new bytes from the pool (no per-token str).
    t->rec.spelling_id = strpool.intern(s);
}

Variable *TokenCpnd::findVariableThisScope(const madc::dis::intern_table &sp, uint32_t qsid,
					   const std::string &id)
{
    // Absorb any newly-appended variables into the O(1) index (first-wins via
    // emplace, matching the old front-to-back linear scan). A shrink (the single
    // erase site) is detected and forces a rebuild. Keys are interned spelling_ids:
    // the variable's name is interned once when it is first absorbed; the query was
    // interned once at the walk entry — no per-level std::string re-hash.
    if ( var_indexed > variables.size() )
    {
	var_index.clear();
	var_indexed = 0;
    }
    for ( ; var_indexed < variables.size(); ++var_indexed )
	if ( Variable *v = variables[var_indexed] )
	{
	    if ( !v->name_sid )		// intern the name ONCE, then reuse the cached id
		v->name_sid = sp.intern(v->name);
	    var_index.emplace(v->name_sid, v);
	}
    std::unordered_map<uint32_t, Variable *>::iterator it = var_index.find(qsid);
    Variable *res = (it != var_index.end()) ? it->second : NULL;
    // A Variable's `name` can be MUTATED after it is appended (operator arity
    // disambiguation renames a same-name overload — via Variable::rename, which
    // zeroes the cached name_sid). The index entry then goes stale: a lookup of
    // the OLD name would falsely hit the renamed var, or a lookup of the NEW
    // name would falsely miss. Detect staleness — a hit whose CURRENT name no
    // longer matches — and REPAIR the index, then re-find. Because rename() is
    // the only post-registration name writer and it zeroes name_sid, a stale
    // entry is exactly one whose key no longer equals its var's name_sid; only
    // those keys (plus the renamed vars' NEW sids, whose first-wins owner may
    // change) can differ from a full rebuild. Repairing just that affected key
    // set replaces the old clear()+re-emplace of the WHOLE scope — 204k
    // unordered_map emplaces (253M Ir) per bound testsubscript run for 28
    // repairs, the surviving half of the task-#14 flood (the re-intern half
    // was fixed there). Repair fires only on a stale hit (rare), so the common
    // path stays O(1) and the result always matches a fresh scan.
    if ( res && res->name != id )
    {
	// The affected key set is tiny (the rename batch that went stale), so a
	// flat vector + linear membership beats hashing per variable in the
	// refill scan below. Raw-pointer walk: at -O0 vector iterators are real
	// function calls, and this test runs once per scope entry per repair.
	std::vector<uint32_t> affected;
	auto affected_has = [&affected](uint32_t sid) -> bool {
	    const uint32_t *p = affected.data();
	    for ( const uint32_t *e = p + affected.size(); p != e; ++p )
		if ( *p == sid )
		    return true;
	    return false;
	};
	// 1. Drop entries whose var no longer carries the key (renamed away).
	for ( std::unordered_map<uint32_t, Variable *>::iterator si = var_index.begin();
	      si != var_index.end(); )
	    if ( !si->second || si->second->name_sid != si->first )
	    {
		if ( !affected_has(si->first) )
		    affected.push_back(si->first);
		si = var_index.erase(si);
	    }
	    else
		++si;
	// 2. Re-intern the renamed vars (name_sid zeroed) and drop any existing
	//    entry at their NEW sid: an earlier-appended renamed var must be able
	//    to win that key from a later var, exactly as a full rebuild would.
	for ( size_t vi = 0; vi < variables.size(); ++vi )
	    if ( Variable *v = variables[vi] )
		if ( !v->name_sid )
		{
		    v->name_sid = sp.intern(v->name);
		    if ( !affected_has(v->name_sid) )
			affected.push_back(v->name_sid);
		    var_index.erase(v->name_sid);
		}
	// 3. Refill ONLY the affected keys, first-wins in append order — the
	//    same winner a full rebuild's front-to-back emplace would pick.
	for ( size_t vi = 0; vi < variables.size(); ++vi )
	    if ( Variable *v = variables[vi] )
		if ( affected_has(v->name_sid) )
		    var_index.emplace(v->name_sid, v);
	it = var_index.find(qsid);
	res = (it != var_index.end()) ? it->second : NULL;
    }
    return res;
}

Variable *TokenCpnd::findVariable(const madc::dis::intern_table &sp, uint32_t qsid, const std::string &id)
{
    DBG(cout << "TokenCpnd::findVariable(" << id << ") method: " << (method ? method->returns.name : "NULL") << endl);
    if ( Variable *res = findVariableThisScope(sp, qsid, id) )
	return res;
    if ( parent )
	return parent->findVariable(sp, qsid, id);

    return NULL;
}

Variable *TokenCpnd::findVariableLocal(const madc::dis::intern_table &sp, const std::string &id)
{
    uint32_t qsid = sp.intern(id);
    // Walk the scope chain but stop at the program/global scope: a hit here is a
    // function parameter or block local, which shadows any namespace member. Block
    // locals live in each compound's `variables`; parameters live in the
    // function-body compound's `method->parameters` (findParameter).
    for ( TokenCpnd *c = this; c && c->type() != TokenType::ttProgram; c = c->parent )
    {
	if ( Variable *res = c->findVariableThisScope(sp, qsid, id) )
	    return res;
	if ( Variable *res = c->findParameter(id) )
	    return res;
    }
    return NULL;
}

Variable *Method::findVariable(const std::string &s)
{
    for ( variable_vec_iter vvi = variables.begin(); vvi != variables.end(); ++vvi )
	if ( !s.compare((*vvi)->name) )
	    return *vvi;

    return NULL;
}

Variable *Method::findParameter(const std::string &s)
{
    for ( variable_vec_iter vvi = parameters.begin(); vvi != parameters.end(); ++vvi )
	if ( !s.compare((*vvi)->name) )
	    return *vvi;

    return NULL;
}

